// Define the record structure
typedef struct {
    int key;
} Record;

// Define the custom serialization function
void serialize(const char* filename, const void* data, size_t size) {
    FILE* fp = fopen(filename, "wb");
    if (fp == NULL) {
        printf("Error: unable to open file for writing\n");
        return;
    }

    // Write the data to the file
    size_t written = fwrite(data, sizeof(Record), size, fp);
    if (written != size) {
        printf("Error: unable to write all data to file\n");
        fclose(fp);
        return;
    }

    // Close the file
    fclose(fp);
}

// Define the function that allocates and initializes the arrays
void allocate_and_initialize_arrays(const char* filename, int num_records, int key_range) {
    // Allocate memory for the offset array
    long* offsets = (long*)malloc(num_records * sizeof(long));
    if (offsets == NULL) {
        printf("Error: unable to allocate memory for offset array\n");
        return;
    }

    // Initialize the offset array with random values within the given range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % key_range;
    }

    // Allocate memory for the key array
    int* keys = (int*)malloc(num_records * sizeof(int));
    if (keys == NULL) {
        printf("Error: unable to allocate memory for key array\n");
        free(offsets);
        return;
    }

    // Initialize the key array with random values within the given range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % key_range;
    }

    // Allocate memory for the record array
    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (records == NULL) {
        printf("Error: unable to allocate memory for record array\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the record array with random values within the given range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % key_range;
    }

    // Serialize the data to a file
    serialize(filename, records, num_records);

    // Free the memory allocated for the arrays
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    allocate_and_initialize_arrays("data.bin", 1000, 100);
    return 0;
}
```
