    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], OPTION_MANPAGE) == 0) {
            args.manpage = 1;
        } else if (strcmp(argv[i], OPTION_CS) == 0) {
            args.cs = 1;
        } else if (strcmp(argv[i], OPTION_O) == 0 && i + 1 < argc) {
            args.output_file = argv[i + 1];
        } else {
            args.input_file = argv[i];
        }
    }

    return args;
}

// Function to read a file line by line and print the number of lines
void process_file(char* input_file, char* output_file) {
    // Open the input file for reading
    FILE* fp = fopen(input_file, "r");
    if (fp == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    // Create a memory-mapped I/O object for the input file
    int fd = fileno(fp);
    void* addr = mmap(NULL, 0, PROT_READ, MAP_PRIVATE, fd, 0);
    if (addr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    // Initialize variables for counting lines and logging
    int line_count = 0;
    time_t start_time, end_time;
    char* log_file = output_file != NULL ? output_file : "stdout";

    // Start the timer for logging
    start_time = time(NULL);

    // Iterate over the lines in the file and count them
    while (fgets(addr, 1024, fp) != NULL) {
        line_count++;
    }

    // Stop the timer for logging
    end_time = time(NULL);

    // Log the start and end times of file processing
    FILE* log_fp = fopen(log_file, "a");
    if (log_fp == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    fprintf(log_fp, "%s: %d lines processed in %ld seconds\n", input_file, line_count, end_time - start_time);
    fclose(log_fp);

    // Close the memory-mapped I/O object and file
    munmap(addr, 0);
    fclose(fp);
}

// Function to handle concurrent access to the log file from multiple instances running simultaneously
