        } else if (strcmp(argv[i], OPTION_O) == 0 && i + 1 < argc) {
            args.output_file = argv[i + 1];
        } else {
            args.input_file = argv[i];
        }
    }

    // Validate and sanitize the command line arguments
    if (args.input_file == NULL) {
