#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

void generate_report(char* input_file, char* output_file, char* rules, bool verbose) {
    // Open the input file and read its contents into a buffer
    FILE* fp = fopen(input_file, "r");
    if (fp == NULL) {
        printf("Error: unable to open input file\n");
        return;
    }
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    rewind(fp);
    char* buffer = (char*)malloc(file_size + 1);
    if (buffer == NULL) {
        printf("Error: unable to allocate memory for input file\n");
        fclose(fp);
        return;
    }
    size_t bytes_read = fread(buffer, sizeof(char), file_size, fp);
    buffer[bytes_read] = '\0';
    fclose(fp);

    // Parse the input file for specific patterns and generate an aggregated report
    char* pattern1 = "pattern1";
    char* pattern2 = "pattern2";
    int count1 = 0;
    int count2 = 0;
    for (int i = 0; i < bytes_read; i++) {
        if (strstr(buffer + i, pattern1) != NULL) {
            count1++;
        } else if (strstr(buffer + i, pattern2) != NULL) {
            count2++;
        }
    }

    // Generate the output report file based on the given rules
    FILE* fp_out = fopen(output_file, "w");
    if (fp_out == NULL) {
        printf("Error: unable to open output file\n");
        free(buffer);
        return;
    }
    fprintf(fp_out, "Total occurrences of pattern1: %d\n", count1);
    fprintf(fp_out, "Total occurrences of pattern2: %d\n", count2);
    if (verbose) {
        for (int i = 0; i < bytes_read; i++) {
            if (strstr(buffer + i, pattern1) != NULL || strstr(buffer + i, pattern2) != NULL) {
                fprintf(fp_out, "%c", buffer[i]);
            }
        }
    }
    fclose(fp_out);

    // Free the memory allocated for the input file buffer
    free(buffer);
}
