#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>

// Structure to represent a cryptographic function and its parameters
typedef struct {
    char *name;
    void (*func)(void);
    void *params;
} CryptFunc;

// Function to return a linked list of available cryptographic hash functions and block ciphers
CryptFunc* get_crypto_funcs(char *dir) {
    // Initialize the head node of the linked list
    CryptFunc *head = NULL;

    // Iterate over the files in the specified directory
    DIR *dp;
    struct dirent *ep;
    if ((dp = opendir(dir)) == NULL) {
        perror("opendir");
        return head;
    }

    while ((ep = readdir(dp)) != NULL) {
        // Check if the file is a shared library
        if (strcmp(ep->d_name, ".") == 0 || strcmp(ep->d_name, "..") == 0) {
            continue;
        }

        // Load the shared library and get its handle
        void *handle = dlopen(ep->d_name, RTLD_LAZY);
        if (handle == NULL) {
            perror("dlopen");
            continue;
        }

        // Get the function pointer for the hash or cipher implementation
        void (*func)(void) = dlsym(handle, "crypt_func");
        if (func == NULL) {
            perror("dlsym");
            dlclose(handle);
            continue;
        }

        // Get the name of the function and its parameters
        char *name = dlsym(handle, "crypt_name");
        void *params = dlsym(handle, "crypt_params");

        // Create a new node for the linked list
        CryptFunc *node = malloc(sizeof(CryptFunc));
        if (node == NULL) {
            perror("malloc");
            continue;
        }

        // Set the function pointer, name, and parameters in the node
        node->func = func;
        node->name = strdup(name);
        node->params = params;

        // Add the node to the linked list
        if (head == NULL) {
            head = node;
        } else {
            CryptFunc *curr = head;
            while (curr->next != NULL) {
                curr = curr->next;
            }
            curr->next = node;
        }
    }

    // Close the directory stream and return the linked list
    closedir(dp);
    return head;
}
```
This function uses the `dlfcn.h` header file to dynamically load shared libraries from a specified directory, and then uses the `dlsym()` function to get the function pointer for the hash or cipher implementation. The function also uses the `malloc()` and `strdup()` functions to allocate memory for the node in the linked list, and the `perror()` function to handle errors gracefully.

The function first opens a directory stream using the `opendir()` function, and then iterates over the files in the directory using the `readdir()` function. For each file, it checks if it is a shared library using the `strcmp()` function, and if so, it loads the shared library using the `dlopen()` function. If the shared library is successfully loaded, the function gets the function pointer for the hash or cipher implementation using the `dlsym()` function, and then gets the name of the function and its parameters using the `dlsym()` function again.

The function then creates a new node in the linked list using the `malloc()` function, and sets the function pointer, name, and parameters in the node. The function then adds the node to the linked list by setting the `next` field of the current node to point to the new node.

Finally, the function closes the directory stream using the `closedir()` function, and returns the linked list of available cryptographic hash functions and block ciphers.']

