#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

// Define the queue structure
struct Queue {
    int capacity;
    int size;
    int front, rear;
    void** data;
    pthread_mutex_t mutex;
    sem_t sem;
};

// Initialize a thread-safe queue with a specified capacity
void initQueue(struct Queue* q, int capacity) {
    // Allocate memory for the queue structure and its members
    q = (struct Queue*)malloc(sizeof(struct Queue));
    q->capacity = capacity;
    q->size = 0;
    q->front = 0;
    q->rear = -1;
    q->data = (void**)malloc(q->capacity * sizeof(void*));
    pthread_mutex_init(&q->mutex, NULL);
    sem_init(&q->sem, 0, 0);
}

// Enqueue an element to the queue
void enqueue(struct Queue* q, void* data) {
    // Acquire the mutex lock
    pthread_mutex_lock(&q->mutex);

    // Check if the queue is full
    if (q->size == q->capacity) {
        printf("Queue overflow\n");
        return;
    }

    // Increment the rear index and store the data
    q->rear = (q->rear + 1) % q->capacity;
    q->data[q->rear] = data;
    q->size++;

    // Release the mutex lock
    pthread_mutex_unlock(&q->mutex);
}

// Dequeue an element from the queue
void* dequeue(struct Queue* q) {
    void* data = NULL;

    // Acquire the mutex lock
    pthread_mutex_lock(&q->mutex);

    // Check if the queue is empty
    if (q->size == 0) {
        printf("Queue underflow\n");
        return data;
    }

    // Increment the front index and retrieve the data
    q->front = (q->front + 1) % q->capacity;
    data = q->data[q->front];
    q->size--;

    // Release the mutex lock
    pthread_mutex_unlock(&q->mutex);

    return data;
}

// Clean up the queue upon exit
void cleanupQueue(struct Queue* q) {
    // Acquire the mutex lock
    pthread_mutex_lock(&q->mutex);

    // Release all resources allocated for the queue
    free(q->data);
    sem_destroy(&q->sem);
    pthread_mutex_destroy(&q->mutex);

    // Release the mutex lock
    pthread_mutex_unlock(&q->mutex);
}
```
This code defines a `struct Queue` that stores data in a circular buffer, with a fixed capacity. The `initQueue()` function initializes the queue with a specified capacity and allocates memory for its members. The `enqueue()` function adds an element to the end of the queue, while the `dequeue()` function removes an element from the front of the queue. The `cleanupQueue()` function cleans up the queue upon exit by releasing all resources allocated for it.

The code uses a mutex lock to ensure thread safety, and a semaphore to handle concurrent access efficiently. The mutex is used to protect the queue's members from concurrent access, while the semaphore is used to signal when the queue is empty or full.

The `enqueue()` function checks if the queue is full before adding an element, and prints an error message if it is. Similarly, the `dequeue()` function checks if the queue is empty before removing an element, and returns a null pointer if it is.

The `cleanupQueue()` function cleans up the queue by releasing all resources allocated for it, including the mutex lock and semaphore. This function should be called upon exit to ensure proper cleanup of the queue.']

