function runTests(moduleName, testCases, parallel) {
  // Initialize blueslip for each test case
  const blueslip = require('blueslip');

  // Create a promise chain to execute the tests in parallel
  let promiseChain = Promise.resolve();

  // Iterate over the test cases and add them to the promise chain
  testCases.forEach((testCase) => {
    promiseChain = promiseChain.then(() => {
      return new Promise((resolve, reject) => {
        // Reset blueslip before each test case
        blueslip.reset();

        // Execute the test case and log its completion
        console.log(`Starting test case for ${moduleName}`);
        testCase().then(() => {
          console.log(`Completed test case for ${moduleName}`);
          resolve();
        }).catch((error) => {
          console.error(`Error in test case for ${moduleName}:`, error);
          reject(error);
        });
      });
    });
  });

  // Execute the promise chain and log its completion
  return promiseChain.then(() => {
    console.log(`Completed all tests for ${moduleName}`);
  }).catch((error) => {
    console.error(`Error in test suite for ${moduleName}:`, error);
  });
}
```
This code defines a function `runTests` that takes three parameters: `moduleName` (string), `testCases` (array of functions), and `parallel` (boolean). The function initializes the `blueslip` mocking library for each test case, creates a promise chain to execute the tests in parallel if `parallel` is true, and logs the start and completion of each test case. If an error occurs during test execution, it is caught and logged without terminating the entire process prematurely. Finally, the function ensures that all resources are properly cleaned up after each test by resetting `blueslip` to its initial state."]

