const oldTestamentBooks = ["Genesis", "Exodus", "Leviticus", "Numbers", "Deuteronomy", "Joshua", "Judges", "Ruth", "1 Samuel", "2 Samuel", "1 Kings", "2 Kings", "1 Chronicles", "2 Chronicles", "Ezra", "Nehemiah", "Esther", "Job", "Psalms", "Proverbs", "Ecclesiastes", "Song of Solomon", "Isaiah", "Jeremiah", "Lamentations", "Ezekiel", "Daniel", "Hosea", "Joel", "Amos", "Obadiah", "Jonah", "Micah", "Nahum", "Habakkuk", "Zephaniah", "Haggai", "Zechariah", "Malachi"];
const punctuationRegex = /[.,\/#!$%\^&\*;:{}=\-_`~()]/g;
const specialCharactersRegex = /[^a-zA-Z0-9 ]/g;
const languageRegex = {
  "en": /[a-zA-Z]+/,
  "es": /[a-zA-Zñáéíóú]+/,
  "fr": /[a-zA-Zàâäèêëîïôœùûüÿç]+/
};
const threshold = 0.7;

function extractBooks(text, language) {
  const books = {};
  for (let book of oldTestamentBooks) {
    let regex = new RegExp(`\\b${book}\\b`, "gi");
    let matches = text.match(regex);
    if (matches) {
      for (let match of matches) {
        let cleanMatch = match.replace(punctuationRegex, "").replace(specialCharactersRegex, "");
        if (cleanMatch.length >= threshold * book.length && languageRegex[language].test(cleanMatch)) {
          books[book] = books[book] ? books[book] + 1 : 1;
        }
      }
    }
  }
  return books;
}

function fetchBookMetadata(books) {
  const metadata = {};
  for (let book of books) {
    let apiResponse = fetch(`https://api.example.com/book/${book}`);
    if (apiResponse.ok) {
      let data = await apiResponse.json();
      metadata[book] = {
        chapterCount: data.chapter_count,
        verseCount: data.verse_count
      };
    } else {
      console.log(`Failed to fetch metadata for book ${book}`);
    }
  }
  return metadata;
}

function getBooksWithMetadata(text, language) {
  const books = extractBooks(text, language);
  const metadata = fetchBookMetadata(books);
  const output = {};
  for (let book of books) {
    output[book] = {
      count: books[book],
      metadata: metadata[book]
    };
  }
  return output;
}
