  switch (action) {
    case 'update':
      result = updateUserAccount(request.id, request.name, request.email, request.password);
      break;
    case 'delete':
      result = deleteUserAccount(request.id);
      break;
    default:
      result = createUserAccount(request.name, request.email, request.password);
  }

  // send response to parent window with updated field name and value
  if (result) {
    return jsonResponse({ success: true, message: 'User account updated successfully' });
