function simulateDataStreaming(data) {
  const graph = {}; // Initialize an empty object to store the graph data
  const vertices = []; // Initialize an empty array to store the vertices
  const edges = []; // Initialize an empty array to store the edges

  // Collect incoming data and add it to the graph
  for (const datum of data) {
    if (!graph[datum.id]) {
      graph[datum.id] = {};
    }
    graph[datum.id][datum.type] = datum;
  }

  // Add random vertices and edges to the graph
  for (let i = 0; i < Math.floor(Math.random() * 10) + 5; i++) {
    const vertexId = Math.floor(Math.random() * data.length);
    const edgeId = Math.floor(Math.random() * data.length);
    vertices.push({ id: vertexId, label: `Vertex ${vertexId}` });
    edges.push({ id: edgeId, source: vertexId, target: edgeId, weight: Math.random() });
  }

  // Set random properties on the vertices and edges
  for (const vertex of vertices) {
    const randProp = `prop${Math.floor(Math.random() * 10)}`;
    graph[vertex.id].properties[randProp] = Math.random();
  }
  for (const edge of edges) {
    const randProp = `prop${Math.floor(Math.random() * 10)}`;
    graph[edge.source][edge.target].properties[randProp] = Math.random();
  }

  // Update the graph database efficiently to accommodate the changes
  for (const vertex of vertices) {
    const id = vertex.id;
    if (!graph[id]) {
      graph[id] = {};
    }
    graph[id].properties = Object.assign(graph[id].properties, vertex.properties);
  }
  for (const edge of edges) {
    const sourceId = edge.source;
    const targetId = edge.target;
    if (!graph[sourceId][targetId]) {
      graph[sourceId][targetId] = {};
    }
    graph[sourceId][targetId].properties = Object.assign(graph[sourceId][targetId].properties, edge.properties);
  }

  return graph;
}
