function traverseDOM(rootElement, userCriteria) {
  // Initialize an empty list to store matching elements
  const matchingElements = [];

  // Define a function to recursively traverse the DOM tree
  const traverse = (element) => {
    // Check if the current element matches the user criteria
    if (userCriteria(element)) {
      // Add the element to the list of matching elements
      matchingElements.push(element);
    }

    // Recursively traverse the child elements
    for (const child of element.children) {
      traverse(child);
    }
  };

  // Start traversing the DOM tree from the root element
  traverse(rootElement);

  // Return the list of matching elements
  return matchingElements;
}
