// Module Loader
const moduleLoader = {
  // Map of loaded modules
  modules: {},

  // Load a module by name
  loadModule(name) {
    return new Promise((resolve, reject) => {
      const url = `modules/${name}.js`;
      fetch(url)
        .then(response => response.text())
        .then(code => {
          try {
            // Execute the module code in a separate context
            const context = {};
            eval(code);
            resolve(context[name]);
          } catch (error) {
            reject(error);
          }
        })
        .catch(error => reject(error));
    });
  },

  // Load multiple modules by name
  loadModules(names) {
    return Promise.all(names.map(name => this.loadModule(name)));
  },

  // Execute a module function with the given arguments
  executeModule(module, args) {
    return new Promise((resolve, reject) => {
      try {
        resolve(module(...args));
      } catch (error) {
        reject(error);
      }
    });
  },

  // Execute a module function with the given arguments and handle errors
  executeModuleWithErrorHandling(module, args) {
    return this.executeModule(module, args).catch(error => {
      console.error(`Error executing module: ${error}`);
      return null;
    });
  },

  // Load and execute a module by name with the given arguments
  loadAndExecuteModule(name, args) {
    return this.loadModule(name).then(module => this.executeModuleWithErrorHandling(module, args));
  },

  // Load and execute multiple modules by name with the given arguments
  loadAndExecuteModules(names, args) {
    return Promise.all(names.map(name => this.loadAndExecuteModule(name, args)));
  }
};

// Example usage:
moduleLoader.loadAndExecuteModules(['module1', 'module2'], ['arg1', 'arg2']).then(results => {
  console.log('Results:', results);
});
```
