import java.util.*;
import java.net.*;

public class SubnetClassifier {
    private static final int DEFAULT_CIDR_SIZE = 24;
    private static final String INVALID_IP_ADDRESS_MESSAGE = "Invalid IP address";
    private static final String NON_OVERLAPPING_CIDR_RANGES_MESSAGE = "Non-overlapping CIDR ranges";

    public Map<String, List<String>> classifySubnets(List<String> networkAddresses, int cidrSize) {
        if (networkAddresses == null || networkAddresses.isEmpty()) {
            return Collections.emptyMap();
        }

        // Initialize the custom data structure to store subnet information
        Map<String, List<String>> subnets = new HashMap<>();

        for (String address : networkAddresses) {
            try {
                InetAddress inetAddress = InetAddress.getByName(address);
                if (!inetAddress.isAnyLocalAddress() && !inetAddress.isLoopbackAddress()) {
                    String subnet = getSubnet(inetAddress, cidrSize);
                    List<String> addresses = subnets.computeIfAbsent(subnet, k -> new ArrayList<>());
                    addresses.add(address);
                }
            } catch (UnknownHostException e) {
                System.out.println(INVALID_IP_ADDRESS_MESSAGE + ": " + address);
            }
        }

        return subnets;
    }

    private String getSubnet(InetAddress inetAddress, int cidrSize) {
        if (cidrSize < 0 || cidrSize > 32) {
            throw new IllegalArgumentException("Invalid CIDR size: " + cidrSize);
        }

        String subnet = null;
        try {
            subnet = inetAddress.getHostAddress().substring(0, cidrSize);
        } catch (IndexOutOfBoundsException e) {
            System.out.println(NON_OVERLAPPING_CIDR_RANGES_MESSAGE + ": " + inetAddress.getHostAddress());
        }

        return subnet;
    }
}
