    public static void optimize(String server1, String server2) throws IOException {
        // Create a pool of threads to handle concurrent connections
        ExecutorService executor = Executors.newFixedThreadPool(5);

        // Create a socket for each connection and start the transfer
        Socket socket1 = new Socket(server1, 80);
        Socket socket2 = new Socket(server2, 80);
        executor.execute(() -> {
            try {
                InputStream inputStream1 = socket1.getInputStream();
                OutputStream outputStream1 = socket1.getOutputStream();
                InputStream inputStream2 = socket2.getInputStream();
                OutputStream outputStream2 = socket2.getOutputStream();
                byte[] buffer = new byte[1024];
                int bytesRead;
                while ((bytesRead = inputStream1.read(buffer)) > 0) {
                    outputStream2.write(buffer, 0, bytesRead);
                }
            } catch (IOException e) {
                // Handle exception
            } finally {
                socket1.close();
                socket2.close();
            }
        });

        executor.execute(() -> {
            try {
                InputStream inputStream1 = socket1.getInputStream();
                OutputStream outputStream1 = socket1.getOutputStream();
                InputStream inputStream2 = socket2.getInputStream();
                OutputStream outputStream2 = socket2.getOutputStream();
                byte[] buffer = new byte[1024];
                int bytesRead;
                while ((bytesRead = inputStream2.read(buffer)) > 0) {
                    outputStream1.write(buffer, 0, bytesRead);
                }
            } catch (IOException e) {
                // Handle exception
            } finally {
                socket1.close();
                socket2.close();
            }
        });

        executor.shutdown();
