// Define the structure to store the metrics
typedef struct {
    long max_weighted_sum;
    char* transaction_id;
    int count;
} Metrics;

// Define the function to process a single transaction
void process_transaction(char* transaction_id, double weight) {
    // Calculate the weighted sum using the dynamic weight factor
    double weighted_sum = weight * DECAY_FACTOR;

    // Update the rolling buffer for this transaction ID
    int index = 0;
    while (index < ROLLING_BUFFER_SIZE && index < MAX_TRANSACTIONS_PER_ID) {
        if (strcmp(transaction_id, rolling_buffer[index].transaction_id) == 0) {
            // Update the weighted sum for this transaction ID in the rolling buffer
            rolling_buffer[index].weighted_sum += weighted_sum;
            break;
        } else {
            index++;
        }
    }

    // If the rolling buffer is full, remove the oldest transaction ID from the buffer
    if (index == ROLLING_BUFFER_SIZE) {
        int oldest_index = 0;
        for (int i = 1; i < ROLLING_BUFFER_SIZE; i++) {
            if (rolling_buffer[i].timestamp < rolling_buffer[oldest_index].timestamp) {
                oldest_index = i;
            }
        }
        strcpy(rolling_buffer[oldest_index].transaction_id, "");
    }

    // Update the metrics for this transaction ID
    Metrics* metrics = get_metrics(transaction_id);
    if (metrics != NULL) {
        metrics->max_weighted_sum = weighted_sum;
        metrics->count++;
    }
}

// Define the function to handle duplicate transaction IDs gracefully
