#include <iostream>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>

using namespace std;

// Global variables
int attack1Cooldown = 9000; // 9 seconds in milliseconds
int attack2Cooldown = 15000; // 15 seconds in milliseconds
mutex mtx;
condition_variable cv;
bool isAttackSelected = false;
int selectedAttack = -1;

void selectAttack() {
    unique_lock<mutex> lock(mtx);
    while (true) {
        // Check if an attack has been selected
        if (isAttackSelected) {
            break;
        }

        // Wait for the cooldown period to end
        this_thread::sleep_for(chrono::milliseconds(attack1Cooldown));

        // Select an attack randomly
        int randomNumber = rand() % 2 + 1;
        if (randomNumber == 1) {
            selectedAttack = 1;
        } else {
            selectedAttack = 2;
        }

        // Notify the game server of the attack selection
        cv.notify_all();

        // Print the selected attack to the console
        cout << "Selected attack: " << selectedAttack << endl;

        // Log the selection along with the current time and latency for future debugging and performance analysis
        chrono::time_point<chrono::system_clock> startTime = chrono::system_clock::now();
        chrono::time_point<chrono::system_clock> endTime = chrono::system_clock::now();
        int latency = chrono::duration_cast<chrono::milliseconds>(endTime - startTime).count();
        cout << "Latency: " << latency << endl;

        // Set the isAttackSelected flag to true
        isAttackSelected = true;
    }
}

void handleNetworkTimeouts() {
    unique_lock<mutex> lock(mtx);
    while (true) {
        // Check if a network timeout has occurred
        if (cv.wait_for(lock, chrono::milliseconds(1000)) == cv_status::timeout) {
            // Handle the network timeout gracefully
            cout << "Network timeout detected" << endl;

            // Reset the isAttackSelected flag to false
            isAttackSelected = false;
        } else {
            break;
        }
    }
}
```
This implementation uses a mutex and condition variable to synchronize access to the `isAttackSelected` flag and the `selectedAttack` variable. The `selectAttack()` function checks if an attack has been selected, waits for the cooldown period to end, selects an attack randomly, notifies the game server of the attack selection, prints the selected attack to the console, logs the selection along with the current time and latency for future debugging and performance analysis, and sets the `isAttackSelected` flag to true. The `handleNetworkTimeouts()` function checks if a network timeout has occurred, handles the timeout gracefully by resetting the `isAttackSelected` flag to false, and waits for the next attack selection or network timeout.']

