namespace RandomValueGenerator
{
    public class RandomValueGenerator
    {
        private Dictionary<int, Random> generators = new Dictionary<int, Random>();

        public void AddRange(int id, int min, int max)
        {
            if (min > max)
                throw new ArgumentException("Minimum value cannot be greater than maximum value.");

            if (!generators.ContainsKey(id))
                generators[id] = new Random();

            generators[id].MinValue = min;
            generators[id].MaxValue = max;
        }

        public int GenerateRandomInteger(int id)
        {
            if (!generators.ContainsKey(id))
                throw new ArgumentException("Invalid generator ID.");

            return generators[id].Next(generators[id].MinValue, generators[id].MaxValue);
        }

        public float GenerateRandomFloat(int id)
        {
            if (!generators.ContainsKey(id))
                throw new ArgumentException("Invalid generator ID.");

            return (float)(generators[id].NextDouble() * (generators[id].MaxValue - generators[id].MinValue) + generators[id].MinValue);
        }

        public void ResetAllGenerators()
        {
            foreach (var generator in generators.Values)
                generator.Reset();
        }

        public override string ToString()
        {
            var sb = new StringBuilder();

            foreach (var generator in generators)
            {
                sb.AppendLine($"{generator.Key}: {generator.Value.MinValue} - {generator.Value.MaxValue}");
            }

            return sb.ToString();
        }
    }
}
```
