#include <openssl/err.h>

struct tiff_info {
    int bits_per_sample;
    int sample_per_pixel;
    int extra_samples;
};

struct tiff_info parseTIFFAndEncrypt(const char* filename, const char* command) {
    // Initialize the struct to store the extracted information
    struct tiff_info info = {0};

    // Open the TIFF file for reading
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        printf("Error: unable to open %s\n", filename);
        return NULL;
    }

    // Read the header of the TIFF file and extract information about the image
    unsigned char header[12];
    fread(header, 1, 12, fp);
    if (header[0] != 'I' || header[1] != 'I') {
        printf("Error: invalid TIFF file\n");
        return NULL;
    }
    info.bits_per_sample = header[14];
    info.sample_per_pixel = header[15];
    if (info.bits_per_sample != 1 && info.bits_per_sample != 2 &&
        info.bits_per_sample != 4 && info.bits_per_sample != 8 &&
        info.bits_per_sample != 16) {
        printf("Error: unsupported bits per sample\n");
        return NULL;
    }
    if (info.sample_per_pixel < 0 || info.sample_per_pixel > 4) {
        printf("Error: invalid number of samples per pixel\n");
        return NULL;
    }

    // Read the extra samples and their information, if any
    int extra_samples = header[16];
    if (extra_samples > 0) {
        info.extra_samples = extra_samples;
        for (int i = 0; i < extra_samples; i++) {
            // Read the sample information and store it in the struct
            unsigned char sample[12];
            fread(sample, 1, 12, fp);
            if (sample[0] != 'I' || sample[1] != 'I') {
                printf("Error: invalid TIFF file\n");
                return NULL;
            }
            info.extra_samples++;
        }
    }

    // Initialize an OpenSSL cipher object and encrypt the extracted data
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        printf("Error: unable to initialize OpenSSL cipher\n");
        return NULL;
    }
    int ret = EVP_EncryptInit(ctx, command);
    if (ret != 1) {
        printf("Error: unable to encrypt data\n");
        return NULL;
    }
    size_t len = fread(info.data, 1, sizeof(info.data), fp);
    ret = EVP_EncryptUpdate(ctx, info.data, &len, info.data, len);
    if (ret != 1) {
        printf("Error: unable to encrypt data\n");
        return NULL;
    }

    // Close the TIFF file and return the cipher object
    fclose(fp);
    return ctx;
}
