        int num_digits = 10;
        while (num_digits--) {
            new_filename[len + 1 + num_digits] = '0' + rand() % 10;
        }
    } else {
        // Replace the current extension with the new format
        sprintf(new_filename + len, "_%d.txt", time(NULL));
    }

    return new_filename;
}
