    // Derive encryption key from password using PBKDF2 with at least 20,000 iterations and a salt size of 16 bytes
    PKCS5_PBKDF2_HMAC_SHA1(password, strlen(password), NULL, 0, 20000, sizeof(key), key);

    // Set IV length to 16 bytes
    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        printf("Error: Failed to allocate memory for cipher context\n");
        return NULL;
    }

    int ret = EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    if (ret != 1) {
        printf("Error: Failed to initialize cipher\n");
        return NULL;
    }

    return ctx;
}

// Function to clean up and disable the cipher when it is no longer needed
void cleanup_aes_cbc(EVP_CIPHER_CTX* ctx) {
    if (ctx == NULL) {
        printf("Error: Invalid cipher context\n");
        return;
    }

    EVP_CIPHER_CTX_free(ctx);
}
