#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <sys/resource.h>

int run_command(char* command, int max_concurrency) {
    // Initialize variables
    int num_commands = 0;
    int num_running = 0;
    int num_completed = 0;
    int num_failed = 0;
    int num_exceeded = 0;
    int status = 1;

    // Create an array to store the process IDs of running commands
    pid_t* pids = malloc(max_concurrency * sizeof(pid_t));

    // Loop until all commands are completed or failed
    while (num_completed < num_commands || num_failed > 0) {
        // Check if there are any running commands that have exceeded the memory or CPU thresholds
        for (int i = 0; i < max_concurrency; i++) {
            if (pids[i] != -1 && resource_exceeded(pids[i])) {
                // Terminate the command and update the status
                kill(pids[i], SIGKILL);
                pids[i] = -1;
                num_failed++;
            }
        }

        // Check if there are any available slots in the array for new commands
        int available_slot = -1;
        for (int i = 0; i < max_concurrency; i++) {
            if (pids[i] == -1) {
                available_slot = i;
                break;
            }
        }

        // If there are no available slots, wait for any running commands to complete or fail
        if (available_slot == -1) {
            wait(NULL);
            continue;
        }

        // Fork a new process to run the next command
        pid_t pid = fork();

        // If the fork was successful, execute the command in the child process
        if (pid > 0) {
            pids[available_slot] = pid;
            num_running++;
            execl("/bin/sh", "sh", "-c", command, NULL);
            perror("execl");
            exit(1);
        } else if (pid == 0) {
            // In the child process, monitor the resource usage and terminate the command if it exceeds the thresholds
            while (1) {
                struct rusage usage;
                getrusage(RUSAGE_SELF, &usage);
                if (usage.ru_maxrss > MAX_MEMORY || usage.ru_utime.tv_sec + usage.ru_stime.tv_sec > MAX_CPU) {
                    kill(getppid(), SIGKILL);
                    exit(1);
                }
            }
        } else {
            perror("fork");
            status = 0;
            break;
        }
    }

    // Free the array of process IDs
    free(pids);

    return status;
}

// Check if a command has exceeded the memory or CPU thresholds
int resource_exceeded(pid_t pid) {
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);
    return (usage.ru_maxrss > MAX_MEMORY || usage.ru_utime.tv_sec + usage.ru_stime.tv_sec > MAX_CPU);
}
```
This code uses the `fork` and `wait` system calls to run multiple commands in parallel, while ensuring that no command exceeds the specified maximum concurrency limit or resource thresholds. The `execl` function is used to execute the commands in a child process, and the `getrusage` function is used to monitor the resource usage of each command. The `resource_exceeded` function checks if a command has exceeded the memory or CPU thresholds, and the `kill` function is used to terminate the command if it does. The `run_command` function returns 1 if all commands are successfully executed within constraints, and 0 otherwise.']

