        process.waitFor();

        // Check if command execution was successful
        if (process.exitValue() != 0) {
            throw new Exception("Command execution failed");
        }

        // Log command output and errors to external logging service
        logOutput(outputFile);
        logErrors(outputFile);

        // Monitor resource usage and terminate process gracefully if necessary
