using System;
using System.Security.Cryptography;
using System.Text;

public static string DecryptTripleDES(string encryptedMessage, string key, string iv)
{
    // Create a new TripleDESCryptoServiceProvider object with the given key and IV
    using (TripleDESCryptoServiceProvider csp = new TripleDESCryptoServiceProvider())
    {
        // Set the key and IV on the csp object
        csp.Key = Encoding.ASCII.GetBytes(key);
        csp.IV = Encoding.ASCII.GetBytes(iv);

        // Create a new MemoryStream to hold the decrypted message
        using (MemoryStream ms = new MemoryStream())
        {
            // Decrypt the encryptedMessage and write it to the MemoryStream
            using (CryptoStream cs = new CryptoStream(ms, csp.CreateDecryptor(), CryptoStreamMode.Write))
            {
                byte[] encryptedBytes = Convert.FromBase64String(encryptedMessage);
                cs.Write(encryptedBytes, 0, encryptedBytes.Length);
            }

            // Return the decrypted message as a string
            return Encoding.ASCII.GetString(ms.ToArray());
        }
    }
}
