using System;
using System.IO;
using System.IO.Compression;
using System.Runtime.Serialization.Formatters.Binary;

public static CustomDataStructure LoadDataFromFile(string filePath)
{
    try
    {
        using (var stream = File.OpenRead(filePath))
        {
            var compressionStream = DetectCompressionFormat(stream);
            if (compressionStream == null)
            {
                throw new Exception("Invalid compression format");
            }

            using (var reader = new BinaryReader(compressionStream))
            {
                return DeserializeDataStructure(reader.ReadBytes(int.MaxValue));
            }
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine("Error loading data from file: " + ex.Message);
        return null;
    }
}

private static Stream DetectCompressionFormat(Stream stream)
{
    if (stream is GZipStream)
    {
        return stream;
    }
    else if (stream is ZipArchive)
    {
        var zip = (ZipArchive)stream;
        foreach (var entry in zip.Entries)
        {
            if (entry.Name == "data")
            {
                return entry.Open();
            }
        }
    }
    return null;
}

private static CustomDataStructure DeserializeDataStructure(byte[] data)
{
    var formatter = new BinaryFormatter();
    using (var stream = new MemoryStream(data))
    {
        return (CustomDataStructure)formatter.Deserialize(stream);
    }
}
```']

