function addRandomVerticesAndEdges(graph) {
  // Generate a random number of vertices between 1 and 5
  const numVertices = Math.floor(Math.random() * 5) + 1;

  // Add the vertices to the graph
  for (let i = 0; i < numVertices; i++) {
    const vertex = {
      id: `vertex-${i}`,
      label: `Vertex ${i}`
    };
    graph.addVertex(vertex);
  }

  // Generate a random number of edges between the vertices
  const numEdges = Math.floor(Math.random() * (numVertices - 1)) + 1;

  // Add the edges to the graph
  for (let i = 0; i < numEdges; i++) {
    const edge = {
      id: `edge-${i}`,
      label: `Edge ${i}`
    };
    graph.addEdge(edge);
  }

  // Set random properties on the vertices and edges
  for (const vertex of graph.getVertices()) {
    const property = `property-${Math.floor(Math.random() * 10)}`;
    vertex.setProperty(property, Math.random());
  }

  for (const edge of graph.getEdges()) {
    const property = `property-${Math.floor(Math.random() * 10)}`;
    edge.setProperty(property, Math.random());
  }

  // Execute a shell command using a child process
  const command = 'ls -l';
  const options = {
    encoding: 'utf8',
    timeout: 5000
  };
  const childProcess = spawn(command, [], options);

  // Handle asynchronous operations properly and manage any potential errors gracefully
  return new Promise((resolve, reject) => {
    childProcess.stdout.on('data', (data) => {
      resolve(data.toString());
    });
    childProcess.stderr.on('data', (error) => {
      reject(error);
    });
  });
}
