use std::env;
use std::fs;
use std::path::PathBuf;

fn manage_dynamic_dir(directories: Vec<String>) -> Result<(), String> {
    let mut env_var = "DYNAMIC_DIR".to_string();
    let mut path = PathBuf::new();

    for directory in directories {
        if !path.is_empty() {
            path.push(directory);
        } else {
            path = PathBuf::from(directory);
        }

        // Check if the directory exists, and create it if not
        if !path.exists() {
            fs::create_dir(&path).map_err(|e| format!("Failed to create directory: {}", e))?;
        }
    }

    // Set the environment variable to the full path of the last created directory
    env::set_var(env_var, path.to_str().unwrap());

    Ok(())
}

fn delete_dynamic_dir() -> Result<(), String> {
    let mut env_var = "DYNAMIC_DIR".to_string();
    let path = PathBuf::from(env::var(&env_var).unwrap());

    // Delete the entire directory structure, including all its subdirectories
    fs::remove_dir_all(&path).map_err(|e| format!("Failed to delete directory: {}", e))?;

    Ok(())
}
```
