// Custom configuration structure
struct config {
    char *ip_address;
    int port_number;
    char *username;
    char *password;
    int logging_level;
};

// Function to parse and validate JSON configuration file
struct config* parse_config(const char *filename) {
    // Load JSON data from file
    json_object *json = json_object_from_file(filename);
    if (!json) {
        fprintf(stderr, "Error: unable to load JSON data from %s\n", filename);
        return NULL;
    }

    // Get IP address field
    const char *ip_address = json_object_get_string(json_object_object_get(json, "ip_address"));
    if (!ip_address) {
        fprintf(stderr, "Error: missing required field 'ip_address' in JSON configuration file\n");
        return NULL;
    }

    // Get port number field
    int port_number = json_object_get_int(json_object_object_get(json, "port_number"));
    if (port_number < 1 || port_number > 65535) {
        fprintf(stderr, "Error: invalid value for 'port_number' in JSON configuration file\n");
        return NULL;
    }

    // Get authentication credentials fields
    const char *username = json_object_get_string(json_object_object_get(json, "username"));
    const char *password = json_object_get_string(json_object_object_get(json, "password"));
    if (!username || !password) {
        fprintf(stderr, "Error: missing required fields 'username' and 'password' in JSON configuration file\n");
        return NULL;
    }

    // Get logging level field
    int logging_level = json_object_get_int(json_object_object_get(json, "logging_level"));
    if (logging_level < 0 || logging_level > 2) {
        fprintf(stderr, "Error: invalid value for 'logging_level' in JSON configuration file\n");
        return NULL;
    }

    // Create custom configuration structure
    struct config *config = malloc(sizeof(struct config));
    if (!config) {
        fprintf(stderr, "Error: unable to allocate memory for custom configuration structure\n");
        return NULL;
    }

