import os
import hashlib
import logging
from concurrent.futures import ProcessPoolExecutor

def calculate_md5_hash(root_path):
    """
    Calculates the MD5 hash of a directory tree given a root path, efficiently traversing the directory structure in chunks to minimize memory usage and optimize performance.

    :param root_path: The root path of the directory tree to calculate the MD5 hash for.
    :return: A dictionary mapping each file path to its hexdigest hash.
    """
    # Set up logging
    logger = logging.getLogger(__name__)
    logger.setLevel(logging.INFO)

    # Create a list of files and directories to process
    files_and_directories = []
    for root, dirs, files in os.walk(root_path):
        for file in files:
            files_and_directories.append(os.path.join(root, file))

    # Create a list of file paths to hash
    file_paths = []
    for file in files_and_directories:
        if os.path.splitext(file)[1] in ['.txt', '.log'] and not file.startswith('.'):
            file_paths.append(file)

    # Create a dictionary to map each file path to its hexdigest hash
    hashes = {}

    # Process the files in chunks using a ProcessPoolExecutor
    with ProcessPoolExecutor() as executor:
        for chunk in chunks(file_paths, 100):
            futures = [executor.submit(hashlib.md5, open(file, 'rb').read()) for file in chunk]
            for future in as_completed(futures):
                hashes[chunk[future.index]] = future.result()

    return hashes

def chunks(lst, n):
    """Yield successive n-sized chunks from lst."""
    for i in range(0, len(lst), n):
        yield lst[i:i + n]
