// Define the record structure
typedef struct {
    int key;
} Record;

// Define the serialization function
void serialize(const char* filename, const Record* records, size_t num_records) {
    // Check if the file exists and is writable
    if (access(filename, W_OK)) {
        perror("Error accessing file");
        return;
    }

    // Open the file for writing in binary mode
    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        perror("Error opening file");
        return;
    }

    // Allocate memory for the offset and key arrays
    long* offsets = malloc(num_records * sizeof(long));
    int* keys = malloc(num_records * sizeof(int));
    if (!offsets || !keys) {
        perror("Error allocating memory");
        return;
    }

    // Initialize the offset and key arrays
    for (size_t i = 0; i < num_records; i++) {
        offsets[i] = records[i].key;
        keys[i] = records[i].key;
    }

    // Serialize the data to the file
    size_t bytes_written = write(fd, offsets, num_records * sizeof(long));
    if (bytes_written != num_records * sizeof(long)) {
        perror("Error writing to file");
        return;
    }
    bytes_written = write(fd, keys, num_records * sizeof(int));
    if (bytes_written != num_records * sizeof(int)) {
        perror("Error writing to file");
        return;
    }

    // Close the file and free memory
    close(fd);
    free(offsets);
    free(keys);
}

// Define the deserialization function
