    int* keys = malloc(*num_records * sizeof(int));
    if (!offsets || !keys) {
        perror("Error allocating memory");
        return;
    }

    // Read the offset and key arrays from the file
    size_t bytes_read = read(fd, offsets, *num_records * sizeof(long));
    if (bytes_read != *num_records * sizeof(long)) {
        perror("Error reading from file");
        return;
    }
    bytes_read = read(fd, keys, *num_records * sizeof(int));
    if (bytes_read != *num_records * sizeof(int)) {
        perror("Error reading from file");
        return;
    }

    // Create the record array and initialize it with the offset and key arrays
    *records = malloc(*num_records * sizeof(Record));
    if (!*records) {
        perror("Error allocating memory");
        return;
    }
    for (size_t i = 0; i < *num_records; i++) {
        (*records)[i].key = keys[i];
    }

    // Close the file and free memory
