// Structure to store sensor data
typedef struct {
    float temperature;
    char identifier[10];
    time_t timestamp;
} sensor_data;

void filterAndSortData(sensor_data* data, int num_records, float min_temp, float max_temp, int interval) {
    // Allocate memory for filtered and sorted data
    int filtered_num_records = 0;
    sensor_data* filtered_data = (sensor_data*)malloc(sizeof(sensor_data) * num_records);
    sensor_data* sorted_data = (sensor_data*)malloc(sizeof(sensor_data) * num_records);

    // Filter data based on temperature range and time interval
    for (int i = 0; i < num_records; i++) {
        if (data[i].temperature >= min_temp && data[i].temperature <= max_temp) {
            filtered_data[filtered_num_records++] = data[i];
        }
    }

    // Sort filtered data by timestamp in ascending order
    qsort(filtered_data, filtered_num_records, sizeof(sensor_data), compareTimestamps);

    // Write filtered and sorted data to file
    FILE* fp = fopen("output.txt", "w");
    if (fp == NULL) {
        printf("Error: Unable to open output file\n");
        return;
    }
    for (int i = 0; i < filtered_num_records; i++) {
        fprintf(fp, "%f %s %ld\n", filtered_data[i].temperature, filtered_data[i].identifier, filtered_data[i].timestamp);
    }
    fclose(fp);

    // Free memory for filtered and sorted data
    free(filtered_data);
    free(sorted_data);
}

int compareTimestamps(const void* a, const void* b) {
    sensor_data* sa = (sensor_data*)a;
    sensor_data* sb = (sensor_data*)b;
    return (sa->timestamp > sb->timestamp) - (sa->timestamp < sb->timestamp);
}
