// Function to extract metadata from a filename
FileMetadata extractMetadata(const char* filename) {
    // Initialize the structure with default values
    FileMetadata metadata = {filename, -1, 0};

    // Extract the user ID and timestamp from the filename
    const char* delim = "_";
    char* token = strtok(filename, delim);
    if (token != NULL) {
        metadata.user_id = atoi(token);
        token = strtok(NULL, delim);
        if (token != NULL) {
            metadata.timestamp = atol(token);
        }
    }

    return metadata;
}

// Function to generate a unique identifier for each file based on its metadata
char* generateIdentifier(const FileMetadata& metadata) {
    // Initialize the buffer with the filename
    char* buffer = (char*)malloc(strlen(metadata.filename) + 1);
    strcpy(buffer, metadata.filename);

    // Append the user ID and timestamp to the buffer
    sprintf(buffer, "%d_%ld", metadata.user_id, metadata.timestamp);

    // Calculate the MD5 hash of the buffer
    unsigned char* hash = md5(buffer, strlen(buffer));

    // Free the buffer and return the hexdigest hash
    free(buffer);
    return hexdigest(hash);
