def calculateHashes(root_path):
    # Initialize the dictionary to store the file paths and their corresponding hashes
    dict = {}

    # Iterate over each file in the directory tree
    for root, dirs, files in os.walk(root_path):
        for filename in files:
            # Calculate the MD5 hash of the file
            with open(os.path.join(root, filename), 'rb') as f:
                hash = hashlib.md5(f.read()).hexdigest()

            # Add the file path and its corresponding hash to the dictionary
