    metadata.unique_identifier = unique_identifier;

    // Print the metadata and unique identifier for this file
    printf("File: %s\n", filename);
    printf("\tUser ID: %d\n", metadata.user_id);
    printf("\tTimestamp: %ld\n", metadata.timestamp);
    printf("\tUnique Identifier: %s\n", unique_identifier);
}

// Define a function to generate a unique identifier for each file based on its metadata
char *generate_unique_identifier(file_metadata_t *metadata) {
    // Initialize the hash context
    MD5_CTX ctx;
    MD5_Init(&ctx);

    // Generate the hash of the user ID and timestamp
    char *user_id_str = malloc(sizeof(char) * 10);
    sprintf(user_id_str, "%d", metadata->user_id);
    MD5_Update(&ctx, user_id_str, strlen(user_id_str));
    free(user_id_str);

    char *timestamp_str = malloc(sizeof(char) * 10);
    sprintf(timestamp_str, "%ld", metadata->timestamp);
    MD5_Update(&ctx, timestamp_str, strlen(timestamp_str));
    free(timestamp_str);

    // Generate the final hash and return it as a string
    unsigned char hash[16];
    MD5_Final(hash, &ctx);
    char *unique_identifier = malloc(sizeof(char) * 32);
    for (int i = 0; i < 16; i++) {
        sprintf(unique_identifier + i*2, "%02x", hash[i]);
    }
    return unique_identifier;
}

// Define a function to validate the extracted metadata and generate a unique identifier
void validate_metadata(char *filename) {
    // Initialize the metadata structure for this file
    file_metadata_t metadata = {0};

