    // Convert the strings to integers and store them in the metadata structure
    metadata.user_id = atoi(user_id_str);
    metadata.timestamp = atol(timestamp_str);

    // Validate the extracted metadata against specified ranges and formats
    if (metadata.user_id < 0 || metadata.user_id > 100) {
        printf("Invalid user ID: %d\n", metadata.user_id);
        return;
    }
    if (metadata.timestamp < 0 || metadata.timestamp > time(NULL)) {
        printf("Invalid timestamp: %ld\n", metadata.timestamp);
        return;
    }

    // Generate a unique identifier for this file based on the validated metadata
    char *unique_identifier = generate_unique_identifier(&metadata);
    metadata.unique_identifier = unique_identifier;

