import os
import hashlib
from concurrent.futures import ProcessPoolExecutor

def calculate_hash(filepath):
    # Open the file and read it in chunks
    with open(filepath, 'rb') as f:
        data = f.read()

    # Calculate the MD5 hash of the file contents
    return hashlib.md5(data).hexdigest()

def calculate_hashes(root_dir):
    # Initialize a dictionary to store the hashes
    hashes = {}

    # Walk the directory tree and calculate the hash for each file
    for root, dirs, files in os.walk(root_dir):
        for filename in files:
            filepath = os.path.join(root, filename)
            hash = calculate_hash(filepath)
            hashes[filepath] = hash

    return hashes

def filter_files(root_dir, extensions=None):
    # Initialize a list to store the filtered files
    filtered_files = []

    # Walk the directory tree and filter the files based on their extensions
    for root, dirs, files in os.walk(root_dir):
        for filename in files:
            filepath = os.path.join(root, filename)
            if extensions is not None and filename.endswith(extensions):
                filtered_files.append(filepath)

    return filtered_files

def main():
    # Define the root directory for the hash calculation
    root_dir = '/path/to/directory'

    # Calculate the hashes for all files in the directory tree
    hashes = calculate_hashes(root_dir)

    # Filter the files based on their extensions
    filtered_files = filter_files(root_dir, ['.txt', '.log'])

    # Print the hashes for the filtered files
    for filepath in filtered_files:
        print(filepath + ': ' + hashes[filepath])
