                    chunk = f.read(1024)
                    if not chunk:
                        break
                    md5.update(chunk)
            # Add file path and hexdigest hash to dictionary
            hashes[os.path.join(dirname, filename)] = md5.hexdigest()

    return hashes

def filter_files(root_path, metadata_attribute):
    # Initialize list of filtered files
    filtered_files = []

    # Loop through each directory in the root path
    for dirname, _, filenames in os.walk(root_path):
        # Loop through each file in the current directory
        for filename in filenames:
            # Check if metadata attribute is present in filename
            if metadata_attribute in filename:
                filtered_files.append(os.path.join(dirname, filename))

    return filtered_files

def store_hashes(root_path, hashes):
    # Initialize list of files to be stored
    files_to_store = []

    # Loop through each directory in the root path
    for dirname, _, filenames in os.walk(root_path):
        # Loop through each file in the current directory
        for filename in filenames:
            # Check if file has a hexdigest hash in dictionary
            if filename in hashes:
                files_to_store.append(os.path.join(dirname, filename))

    return files_to_store

def main():
    # Set up root path for directory tree traversal
    root_path = '/path/to/directory'

    # Calculate MD5 hashes of all files in directory tree
    hashes = calculate_hashes(root_path)

    # Filter files based on custom metadata attribute
    filtered_files = filter_files(root_path, 'author')

    # Store hashes for filtered files in remote database
    store_hashes(root_path, hashes)
