// Enum for categorizing files based on content type
enum ContentType { TEXT, BINARY, EMPTY };

// Struct to store metadata for each file
struct FileMetadata {
    char* filename;
    enum ContentType category;
    size_t size;
    time_t creationTime;
    time_t modificationTime;
};

// Function to process a directory and generate a report
void processDirectory(const char* dirname) {
    // Open the directory
    DIR* dir = opendir(dirname);
    if (dir == NULL) {
        perror("Error opening directory");
        return;
    }

    // Create an array to store metadata for each file
    struct FileMetadata* files = malloc(sizeof(struct FileMetadata) * 1024);
    size_t numFiles = 0;

    // Read the contents of the directory and categorize each file
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        // Get the file's metadata
        struct stat st;
        if (stat(dirname, &st) < 0) {
            perror("Error getting file metadata");
            continue;
        }

        // Determine the category of the file based on its content type
        enum ContentType category = TEXT;
        if (S_ISREG(st.st_mode)) {
            category = BINARY;
        } else if (S_ISDIR(st.st_mode)) {
            category = EMPTY;
        }

        // Add the file's metadata to the array
        files[numFiles].filename = entry->d_name;
        files[numFiles].category = category;
        files[numFiles].size = st.st_size;
        files[numFiles].creationTime = st.st_ctime;
        files[numFiles].modificationTime = st.st_mtime;
        numFiles++;
    }

    // Close the directory
    closedir(dir);

    // Generate a report for each file in the array
    for (size_t i = 0; i < numFiles; i++) {
        printf("%s: %s, size=%zu, creation time=%s, modification time=%s\n",
               files[i].filename,
               categoryToString(files[i].category),
               files[i].size,
               ctime(&files[i].creationTime),
               ctime(&files[i].modificationTime));
    }

    // Free the array of metadata
    free(files);
}

// Convert a content type enum to a string for printing in the report
const char* categoryToString(enum ContentType category) {
    switch (category) {
        case TEXT: return "text";
        case BINARY: return "binary";
        case EMPTY: return "empty";
    }
}
