#define MAX_CACHE_ENTRIES 1024
#define CACHE_EXPIRATION_TIME 3600 // seconds

typedef struct {
    char* hostname;
    u_char ip[INET_ADDRSTRLEN];
    time_t expiration_time;
} cache_entry_t;

cache_entry_t* cache = NULL;
size_t cache_size = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

int resolveHostname(const char* hostname, u_char ip[INET_ADDRSTRLEN]) {
    int ret = -1;
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags = AI_V4MAPPED | AI_ADDRCONFIG;

    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        // Error resolving hostname
        return ret;
    }

    struct in_addr* addr = &((struct sockaddr_in*) res->ai_addr)->sin_addr;
    strcpy(ip, inet_ntoa(*addr));

    pthread_mutex_lock(&cache_lock);
    cache_entry_t* entry = NULL;
    for (size_t i = 0; i < cache_size; i++) {
        if (strcmp(hostname, cache[i].hostname) == 0) {
            entry = &cache[i];
            break;
        }
    }
    if (entry != NULL) {
        // Hostname found in cache
        strcpy(ip, entry->ip);
        ret = 0;
    } else {
        // Hostname not found in cache, add it
        if (cache_size < MAX_CACHE_ENTRIES) {
            cache_entry_t new_entry = {hostname, ip, time(NULL) + CACHE_EXPIRATION_TIME};
            cache[cache_size++] = new_entry;
            ret = 0;
        } else {
            // Cache is full, evict oldest entry
            size_t oldest_index = 0;
            time_t oldest_expiration_time = cache[oldest_index].expiration_time;
            for (size_t i = 1; i < cache_size; i++) {
                if (cache[i].expiration_time < oldest_expiration_time) {
                    oldest_index = i;
                    oldest_expiration_time = cache[oldest_index].expiration_time;
                }
            }
            free(cache[oldest_index].hostname);
            memset(&cache[oldest_index], 0, sizeof(cache_entry_t));
            cache[oldest_index].hostname = strdup(hostname);
            strcpy(cache[oldest_index].ip, ip);
            cache[oldest_index].expiration_time = time(NULL) + CACHE_EXPIRATION_TIME;
            ret = 0;
        }
    }
    pthread_mutex_unlock(&cache_lock);

    return ret;
}
