            transfer_metadata[num_transfers - 1].category = METADATA_ONLY;
            transfer_metadata[num_transfers - 1].size = current_size;
            transfer_metadata[num_transfers - 1].initiation_time = current_initiation_time;
            transfer_metadata[num_transfers - 1].completion_time = current_completion_time;
        } else if (current_size == 0 && current_initiation_time == 0 && current_completion_time == 0) {
            num_transfers++;
            transfer_metadata = realloc(transfer_metadata, sizeof(TransferMetadata) * num_transfers);
            transfer_metadata[num_transfers - 1].original_file_id = strdup(current_file_id);
