using namespace std;

// Custom metadata attribute for filtering strings
struct Metadata {
  string author;
  string projectName;
};

// Hashing mechanism using MD5 functions
class Hasher {
public:
  static string hash(const string& str) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)str.c_str(), str.size(), digest);
    return toHexString(digest, sizeof(digest));
  }

private:
  static string toHexString(const unsigned char* bytes, size_t len) {
    string result;
    for (size_t i = 0; i < len; ++i) {
      result += hexDigit((bytes[i] >> 4) & 0xF);
      result += hexDigit(bytes[i] & 0xF);
    }
    return result;
  }

  static char hexDigit(unsigned char nibble) {
    return (nibble < 10) ? ('0' + nibble) : ('A' + nibble - 10);
  }
};

// Function to insert a string into the forward list after the first occurrence of the first string argument
void insertString(forward_list<string>& list, const string& strToInsert, const string& firstStrArg) {
  auto it = find(list.begin(), list.end(), firstStrArg);
  if (it != list.end()) {
    // Insert the string after the first occurrence of the first string argument
    list.insert_after(it, strToInsert);
  } else {
    // Append the string to the end of the list if the first string argument is not found
    list.push_back(strToInsert);
  }
}

// Function to validate the extracted metadata from each string and generate a unique identifier for each string
void validateMetadataAndGenerateId(const string& str, Metadata& metadata) {
  // Validate the extracted metadata from each string
  if (metadata.author.empty() || metadata.projectName.empty()) {
    throw invalid_argument("Invalid metadata");
  }

  // Generate a unique identifier for each string based on the extracted metadata
  string id = Hasher::hash(metadata.author + ":" + metadata.projectName);

  // Validate the generated identifier before insertion
  if (id.empty()) {
    throw invalid_argument("Invalid identifier");
  }
}

// Function to filter strings based on a custom metadata attribute and generate unique identifiers for each string
void filterStrings(forward_list<string>& list, const string& firstStrArg, const string& secondStrArg) {
  // Create a map to store the extracted metadata from each string
  unordered_map<string, Metadata> metadataMap;

  // Iterate over the forward list and extract the metadata for each string
  for (auto it = list.begin(); it != list.end(); ++it) {
    Metadata metadata;
    size_t pos = it->find(firstStrArg);
    if (pos != string::npos) {
      // Extract the metadata from the first string argument
      metadata.author = it->substr(0, pos);
      metadata.projectName = it->substr(pos + firstStrArg.size());
    } else {
      // If the first string argument is not found, extract the metadata from the second string argument
      metadata.author = secondStrArg;
      metadata.projectName = "";
    }
    metadataMap[*it] = metadata;
  }

  // Iterate over the map and validate the extracted metadata for each string
  for (auto it = metadataMap.begin(); it != metadataMap.end(); ++it) {
    try {
      validateMetadataAndGenerateId(it->first, it->second);
    } catch (const invalid_argument& e) {
      // If the extracted metadata is invalid, remove the corresponding string from the forward list
      list.erase(it->first);
    }
  }
}

// Function to filter files based on their extensions and generate unique identifiers for each file
void filterFiles(forward_list<string>& list, const vector<string>& extensions) {
