    Metadata metadata;
    size_t pos = it->find_last_of(".");
    if (pos != string::npos) {
      // Extract the metadata from the file extension
      metadata.author = "";
      metadata.projectName = it->substr(pos + 1);
    } else {
      // If the file does not have an extension, extract the metadata from the filename
