#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

// Define a struct to represent a node in the queue
struct Node {
    void* data; // Pointer to the data stored in the node
    int priority; // Priority of the task (lower values have higher priority)
    struct Node* next; // Pointer to the next node in the queue
};

// Define a struct to represent the queue
struct Queue {
    struct Node* head; // Pointer to the first node in the queue
    struct Node* tail; // Pointer to the last node in the queue
    int capacity; // Capacity of the queue (maximum number of nodes)
    int size; // Current size of the queue
    pthread_mutex_t mutex; // Mutex for synchronizing access to the queue
    semaphore_t semaphore; // Semaphore for signaling when the queue is empty or full
};

// Function to initialize a new queue with a specified capacity
struct Queue* initQueue(int capacity) {
    struct Queue* queue = malloc(sizeof(struct Queue));
    if (queue == NULL) {
        return NULL;
    }
    queue->head = NULL;
    queue->tail = NULL;
    queue->capacity = capacity;
    queue->size = 0;
    pthread_mutex_init(&queue->mutex, NULL);
    semaphore_init(&queue->semaphore, 0, 1);
    return queue;
}

// Function to enqueue a new task with a specified priority
int enqueue(struct Queue* queue, void* data, int priority) {
    if (queue == NULL || data == NULL) {
        return -1;
    }
    pthread_mutex_lock(&queue->mutex);
    // Check if the queue is full
    if (queue->size >= queue->capacity) {
        pthread_mutex_unlock(&queue->mutex);
        return -2;
    }
    // Create a new node and add it to the end of the queue
    struct Node* newNode = malloc(sizeof(struct Node));
    if (newNode == NULL) {
        pthread_mutex_unlock(&queue->mutex);
        return -3;
    }
    newNode->data = data;
    newNode->priority = priority;
    newNode->next = NULL;
    // If the queue is empty, set the head and tail pointers to the new node
    if (queue->head == NULL) {
        queue->head = newNode;
        queue->tail = newNode;
    } else {
        // Otherwise, add the new node to the end of the queue
        queue->tail->next = newNode;
        queue->tail = newNode;
    }
    queue->size++;
    pthread_mutex_unlock(&queue->mutex);
    return 0;
}

// Function to dequeue a task with the highest priority
void* dequeue(struct Queue* queue) {
    if (queue == NULL) {
        return NULL;
    }
    pthread_mutex_lock(&queue->mutex);
    // Check if the queue is empty
    if (queue->head == NULL) {
        pthread_mutex_unlock(&queue->mutex);
        return NULL;
    }
    // Remove the head node from the queue and return its data
    struct Node* head = queue->head;
    void* data = head->data;
    queue->head = head->next;
    if (queue->head == NULL) {
        queue->tail = NULL;
    }
    free(head);
    queue->size--;
    pthread_mutex_unlock(&queue->mutex);
    return data;
}

// Function to destroy a queue and release its resources
void destroyQueue(struct Queue* queue) {
    if (queue == NULL) {
        return;
    }
    pthread_mutex_lock(&queue->mutex);
    // Free all nodes in the queue
    struct Node* node = queue->head;
    while (node != NULL) {
        struct Node* nextNode = node->next;
        free(node);
        node = nextNode;
    }
    // Destroy the mutex and semaphore
    pthread_mutex_destroy(&queue->mutex);
    semaphore_destroy(&queue->semaphore);
    free(queue);
}
```
This code defines a thread-safe queue data structure that can be used to manage tasks with different priorities in a multi-threaded environment. The `initQueue` function initializes a new queue with a specified capacity, and the `enqueue` function adds a new task to the end of the queue with a specified priority. The `dequeue` function removes the head node from the queue and returns its data, while the `destroyQueue` function destroys the queue and releases its resources.

The queue uses a mutex to synchronize access to the nodes in the queue, and it uses a semaphore to signal when the queue is empty or full. The `enqueue` function checks if the queue is full before adding a new node, and the `dequeue` function checks if the queue is empty before removing a node.

The `destroyQueue` function also destroys the mutex and semaphore used by the queue, which ensures that all resources are released when the queue is destroyed.

This implementation of a thread-safe queue with dynamic task prioritization can handle edge cases like queue overflow, underflow, and dynamic policy changes gracefully. It balances between simplicity and robustness by using appropriate synchronization primitives and optimizing for both time and space complexity.']

