typedef struct {
    char *filename;
    int user_id;
    time_t timestamp;
    off_t filesize;
} file_metadata_t;

// Define a function to extract metadata from a filename
file_metadata_t extract_metadata(const char *filename) {
    // Initialize the structure with default values
    file_metadata_t metadata = {.filename = NULL, .user_id = -1, .timestamp = 0, .filesize = 0};

    // Get the filename and user ID from the path
    char *path = strdup(filename);
    char *user_id_str = strtok(path, "/");
    metadata.user_id = atoi(user_id_str);
    char *timestamp_str = strtok(NULL, "/");
    metadata.timestamp = atol(timestamp_str);
    free(path);

    // Get the file size from the stat structure
    struct stat st;
    if (stat(filename, &st) == 0) {
        metadata.filesize = st.st_size;
    } else {
        perror("Error getting file size");
    }

    return metadata;
}

// Define a function to generate a unique identifier for each file
char *generate_identifier(const char *filename, const file_metadata_t *metadata) {
    // Initialize the buffer for the identifier
    char *identifier = malloc(1024);
    if (identifier == NULL) {
        perror("Error allocating memory for identifier");
        return NULL;
    }

    // Generate the identifier using the metadata
    sprintf(identifier, "%d-%ld-%ld", metadata->user_id, metadata->timestamp, metadata->filesize);

    // Hash the identifier using MD5
    unsigned char hash[16];
    MD5((unsigned char *)identifier, strlen(identifier), hash);

    // Convert the hash to a hex string and return it
    char *hex_hash = malloc(32);
    if (hex_hash == NULL) {
        perror("Error allocating memory for hex hash");
        free(identifier);
        return NULL;
    }
    for (int i = 0; i < 16; i++) {
        sprintf(hex_hash + i * 2, "%02x", hash[i]);
    }
    free(identifier);
    return hex_hash;
}

// Define a function to process a list of filenames and generate unique identifiers for each file
void process_filenames(const char **filenames, int num_filenames) {
    // Initialize the dictionary to store the metadata for each file
    dict *metadata = malloc(sizeof(dict));
    if (metadata == NULL) {
        perror("Error allocating memory for metadata");
        return;
    }

    // Extract metadata from each filename and generate a unique identifier for each file
    for (int i = 0; i < num_filenames; i++) {
        const char *filename = filenames[i];
        file_metadata_t metadata = extract_metadata(filename);
        char *identifier = generate_identifier(filename, &metadata);
        if (identifier == NULL) {
            perror("Error generating identifier");
            continue;
        }
        dict_put(metadata, filename, identifier);
    }

    // Print the metadata and identifiers for each file
    dict_foreach(metadata, key, value) {
        printf("%s: %s\n", key, value);
    }

    // Free the memory allocated for the dictionary
    free(metadata);
}
