from concurrent.futures import ThreadPoolExecutor

def calculate_hashes(root_path):
    # Initialize a list to store the file paths and their corresponding hashes
    file_paths = []
    hashes = {}

    # Walk through the directory tree and read files in chunks
    for root, dirs, files in os.walk(root_path):
        for file in files:
            file_path = os.path.join(root, file)
            with open(file_path, 'rb') as f:
                chunk = f.read(1024)
                while chunk:
                    hashes[file_path] = hashlib.md5(chunk).hexdigest()
                    chunk = f.read(1024)

    # Return the list of file paths and their corresponding hashes
    return file_paths, hashes

def validate_hashes(root_path):
    # Initialize a dictionary to store the metadata for each file
    metadata = {}

    # Walk through the directory tree and extract metadata from each filename
    for root, dirs, files in os.walk(root_path):
        for file in files:
            file_path = os.path.join(root, file)
            metadata[file_path] = extract_metadata(file_path)

    # Generate a unique identifier for each file using the extracted metadata
    identifiers = {}
    for file_path, metadata in metadata.items():
        identifiers[file_path] = generate_identifier(file_path, metadata)

    # Validate the hashes of each file against the expected values
    for file_path, identifier in identifiers.items():
        if hashes[file_path] != identifier:
            print("Hash mismatch for file", file_path)

# Define a function to extract metadata from a filename
def extract_metadata(filename):
    # Initialize the structure with default values
    metadata = {
        'filename': filename,
        'user_id': -1,
        'timestamp': 0,
        'filesize': 0
    }

    # Get the filename and user ID from the path
    path = os.path.split(filename)
    metadata['user_id'] = int(path[0])
    metadata['timestamp'] = int(path[1])

    # Get the file size from the stat structure
    st = os.stat(filename)
    metadata['filesize'] = st.st_size

    return metadata

# Define a function to generate a unique identifier for each file
def generate_identifier(filename, metadata):
    # Initialize the buffer for the identifier
    identifier = b''

    # Generate the identifier using the metadata
    identifier += str(metadata['user_id']).encode()
    identifier += b'-'
    identifier += str(metadata['timestamp']).encode()
    identifier += b'-'
    identifier += str(metadata['filesize']).encode()

    # Hash the identifier using MD5
    hash = hashlib.md5(identifier)

    # Convert the hash to a hex string and return it
    return hash.hexdigest()
