#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <md5.h>

// Custom metadata attribute struct
struct custom_metadata {
    char *user_id;
    time_t timestamp;
    // Additional custom attributes...
};

// Function to extract metadata from filename
void extract_metadata(const char *filename, struct custom_metadata *metadata) {
    // Extract user ID and timestamp from filename
    const char *user_id = strtok(filename, "_");
    time_t timestamp = atoi(strtok(NULL, "_"));

    // Set metadata fields
    metadata->user_id = user_id;
    metadata->timestamp = timestamp;
}

// Function to generate unique identifier for each file based on extracted metadata
void generate_identifier(const char *filename, struct custom_metadata *metadata) {
    // Generate MD5 hash of filename and metadata
    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5((unsigned char *)filename, strlen(filename), hash);
    MD5Update(&hash, (unsigned char *)&metadata->user_id, strlen(metadata->user_id));
    MD5Update(&hash, (unsigned char *)&metadata->timestamp, sizeof(time_t));

    // Convert hash to hexdigest and set as identifier
    char *identifier = malloc(MD5_DIGEST_LENGTH * 2 + 1);
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(identifier + i * 2, "%02x", hash[i]);
    }
}

// Function to traverse directory tree and generate unique identifiers for files
void traverse_directory(const char *root_path, struct custom_metadata *metadata) {
    // Open root directory
    DIR *dir = opendir(root_path);
    if (dir == NULL) {
        perror("Error opening directory");
        return;
    }

    // Traverse directory tree and generate unique identifiers for files
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        const char *filename = entry->d_name;
        if (strcmp(filename, ".") == 0 || strcmp(filename, "..") == 0) {
            continue;
        }

        // Extract metadata from filename and generate unique identifier
        extract_metadata(filename, metadata);
        generate_identifier(filename, metadata);
    }

    // Close directory
    closedir(dir);
}
