```python
import os
import hashlib

def calculate_md5(root_path):
    # Initialize dictionary to map file paths to their MD5 hashes
    md5s = {}

    # Traverse directory tree and calculate MD5 hash for each file
    for root, dirs, files in os.walk(root_path):
        for filename in files:
            # Calculate MD5 hash of file contents
            with open(os.path.join(root, filename), "rb") as f:
                md5 = hashlib.md5()
                while True:
                    chunk = f.read(1024)
                    if not chunk:
                        break
                    md5.update(chunk)

            # Add MD5 hash to dictionary
            md5s[os.path.join(root, filename)] = md5.hexdigest()

    return md5s
