// Define constants for configuration options
#define MAX_LINE_LENGTH 1024
#define PRIORITY_THRESHOLD 5
#define SUMMARY_METRICS "average_response_time"

// Define data structures to store event information
typedef struct Event {
    time_t timestamp;
    char* service_name;
    char* event_details;
} Event;

// Define function prototypes
void parseEvent(char* line, Event* event);
double calculateSummaryMetric(Event* events[], int num_events);
void filterEvents(Event* events[], int num_events);
void logResults(int num_events, Event* events[]);
void handleSignalInterrupt(int signal);

// Main function to read and process the log file
int main(int argc, char** argv) {
    // Initialize variables for configuration options
    int max_line_length = MAX_LINE_LENGTH;
    int priority_threshold = PRIORITY_THRESHOLD;
    char* summary_metrics = SUMMARY_METRICS;

    // Check command-line arguments for configuration options
    if (argc > 1) {
        max_line_length = atoi(argv[1]);
    }
    if (argc > 2) {
        priority_threshold = atoi(argv[2]);
    }
    if (argc > 3) {
        summary_metrics = argv[3];
    }

    // Initialize variables for event processing
    int num_events = 0;
    Event* events[MAX_LINE_LENGTH] = {};

    // Open the log file and read each line
    FILE* fp = fopen("log.txt", "r");
    char line[max_line_length];
    while (fgets(line, max_line_length, fp) != NULL) {
        // Parse the event details and compute a summary metric
        Event* event = malloc(sizeof(Event));
        parseEvent(line, event);
        if (event->timestamp > 0) {
            events[num_events++] = event;
        } else {
            free(event);
        }
    }
    fclose(fp);

    // Filter out non-critical events and compute the summary metric
    filterEvents(events, num_events);
    double average_response_time = calculateSummaryMetric(events, num_events);

    // Log the results to a file
    logResults(num_events, events);

    // Clean up memory and exit
    for (int i = 0; i < num_events; i++) {
        free(events[i]);
    }
    return 0;
}

// Parse an event line and store the details in an Event structure
void parseEvent(char* line, Event* event) {
    // Initialize variables for parsing
    char* token = strtok(line, " ");
    int index = 0;

    // Parse the timestamp
    if (token != NULL) {
        event->timestamp = atoi(token);
        index++;
    }

    // Parse the service name
    if (token != NULL) {
        event->service_name = token;
        index++;
    }

    // Parse the event details
    while (index < MAX_LINE_LENGTH && token != NULL) {
        event->event_details[index++] = token;
        token = strtok(NULL, " ");
    }
}

// Compute a summary metric for the events
double calculateSummaryMetric(Event* events[], int num_events) {
    // Initialize variables for computing the summary metric
    double total_response_time = 0;
    int num_events_processed = 0;

    // Compute the summary metric for each event
    for (int i = 0; i < num_events; i++) {
        Event* event = events[i];
        if (event->timestamp > 0) {
            total_response_time += atoi(event->event_details);
            num_events_processed++;
        }
    }

    // Return the average response time over the last three events
    return total_response_time / num_events_processed;
}

// Filter out non-critical events and compute the summary metric
void filterEvents(Event* events[], int num_events) {
    // Initialize variables for filtering
    int num_events_filtered = 0;

    // Filter out non-critical events
    for (int i = 0; i < num_events; i++) {
        Event* event = events[i];
        if (event->timestamp > 0 && atoi(event->event_details) >= priority_threshold) {
            events[num_events_filtered++] = event;
        } else {
            free(event);
        }
    }
}

// Log the results to a file
void logResults(int num_events, Event* events[]) {
    // Open the log file for writing
    FILE* fp = fopen("log.txt", "a");

    // Write the header line for the log file
    fprintf(fp, "%s %s %s\n", "timestamp", "service_name", summary_metrics);

    // Write each event to the log file
    for (int i = 0; i < num_events; i++) {
        Event* event = events[i];
        fprintf(fp, "%d %s %f\n", event->timestamp, event->service_name, average_response_time);
    }

    // Close the log file
    fclose(fp);
}

// Handle signal interrupts gracefully
void handleSignalInterrupt(int signal) {
    // Save partial results to a temporary file
    FILE* fp = fopen("tmp.txt", "w");
    for (int i = 0; i < num_events; i++) {
        Event* event = events[i];
        fprintf(fp, "%d %s %f\n", event->timestamp, event->service_name, average_response_time);
    }
    fclose(fp);

    // Flush the log file to disk
    fflush(stdout);

    // Exit cleanly
    exit(0);
}
```
