#include <errno.h>

// Function to generate a unique numeric identifier based on the original filename and current timestamp
int generate_unique_id(const char *filename) {
    // Get the current timestamp in milliseconds
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    int ms = (int)(1000 * difftime(now, mktime(tm)));

    // Generate a unique numeric identifier based on the original filename and current timestamp
    char id[256];
    sprintf(id, "%s_%d", filename, ms);

    return atoi(id);
}

// Function to generate a new filename with a unique numeric identifier and standardized file type
char *generate_new_filename(const char *filename) {
    // Get the original filename extension
    const char *ext = strrchr(filename, '.');
    if (ext == NULL) {
        return NULL;
    }

    // Generate a unique numeric identifier based on the original filename and current timestamp
    int id = generate_unique_id(filename);

    // Allocate memory for the new filename
    char *new_filename = malloc(strlen(filename) + strlen(ext) + 10);
    if (new_filename == NULL) {
        return NULL;
    }

    // Generate the new filename with a unique numeric identifier and standardized file type
    sprintf(new_filename, "%s_%d.%s", filename, id, ext + 1);

    return new_filename;
}

// Function to handle potential race conditions when writing to the filesystem
void write_file(const char *filename) {
    // Generate a unique numeric identifier based on the original filename and current timestamp
    int id = generate_unique_id(filename);

    // Allocate memory for the new filename
    char *new_filename = malloc(strlen(filename) + 10);
    if (new_filename == NULL) {
        return;
    }

    // Generate the new filename with a unique numeric identifier and standardized file type
    sprintf(new_filename, "%s_%d", filename, id);

    // Open the file for writing
    FILE *fp = fopen(new_filename, "w");
    if (fp == NULL) {
        free(new_filename);
        return;
    }

    // Write to the file
    fprintf(fp, "Hello, world!\n");

    // Close the file
    fclose(fp);

    // Free memory for the new filename
    free(new_filename);
}
