// Define a structure to hold plugin metadata
typedef struct {
    char *name;
    char *version;
    int required_dependencies[];
    int optional_dependencies[];
    int execution_priority;
} PluginMetadata;

// Define a structure to hold the plugin manager
typedef struct {
    PluginMetadata **plugins;
    int num_plugins;
} PluginManager;

PluginManager *parse_yaml(const char *filename) {
    // Open the YAML file and create a new parser object
    FILE *fp = fopen(filename, "r");
    yaml_parser_t parser;
    yaml_parser_initialize(&parser);
    yaml_parser_set_input_file(&parser, fp);

    // Create an array to hold the plugin metadata
    PluginMetadata **plugins = malloc(sizeof(PluginMetadata *) * 10);
    int num_plugins = 0;

    // Iterate through the YAML file and parse each plugin
    while (yaml_parser_scan(&parser, &event)) {
        if (event.type == YAML_MAPPING_START_EVENT) {
            // Create a new PluginMetadata object for this plugin
            plugins[num_plugins] = malloc(sizeof(PluginMetadata));
            PluginMetadata *plugin = plugins[num_plugins];

            // Parse the plugin name and version
            if (yaml_parser_parse(&parser, &event) && event.type == YAML_SCALAR_EVENT) {
                plugin->name = strdup(event.data.scalar.value);
                yaml_parser_parse(&parser, &event);
                plugin->version = strdup(event.data.scalar.value);
            } else {
                // Handle missing or invalid name and version fields gracefully
                printf("Error: Missing or invalid name and version for plugin %d\n", num_plugins + 1);
                return NULL;
            }

            // Parse the required dependencies
            if (yaml_parser_parse(&parser, &event) && event.type == YAML_SEQUENCE_START_EVENT) {
                int i = 0;
                while (yaml_parser_parse(&parser, &event) && event.type != YAML_SEQUENCE_END_EVENT) {
                    if (event.type == YAML_SCALAR_EVENT) {
                        plugin->required_dependencies[i] = atoi(event.data.scalar.value);
                        i++;
                    } else {
                        // Handle invalid required dependencies gracefully
                        printf("Error: Invalid required dependency for plugin %d\n", num_plugins + 1);
                        return NULL;
                    }
                }
            } else {
                // Handle missing required dependencies gracefully
                printf("Error: Missing required dependencies for plugin %d\n", num_plugins + 1);
                return NULL;
            }

            // Parse the optional dependencies
            if (yaml_parser_parse(&parser, &event) && event.type == YAML_SEQUENCE_START_EVENT) {
                int i = 0;
                while (yaml_parser_parse(&parser, &event) && event.type != YAML_SEQUENCE_END_EVENT) {
                    if (event.type == YAML_SCALAR_EVENT) {
                        plugin->optional_dependencies[i] = atoi(event.data.scalar.value);
                        i++;
                    } else {
                        // Handle invalid optional dependencies gracefully
                        printf("Error: Invalid optional dependency for plugin %d\n", num_plugins + 1);
                        return NULL;
                    }
                }
            }

            // Parse the execution priority
            if (yaml_parser_parse(&parser, &event) && event.type == YAML_SCALAR_EVENT) {
                plugin->execution_priority = atoi(event.data.scalar.value);
            } else {
                // Handle missing or invalid execution priority gracefully
                printf("Error: Missing or invalid execution priority for plugin %d\n", num_plugins + 1);
                return NULL;
            }

            // Increment the number of plugins and continue parsing the YAML file
            num_plugins++;
        }
    }

    // Close the YAML parser and return the plugin manager structure
    yaml_parser_delete(&parser);
    fclose(fp);
    PluginManager *manager = malloc(sizeof(PluginManager));
    manager->plugins = plugins;
    manager->num_plugins = num_plugins;
    return manager;
}
