        // If the new file name is too long, truncate it to the maximum allowed length
        new_filename[max_length] = '\0';
    }

    // Check if a file with the same name already exists in the directory
    struct stat buffer;
    if (stat(new_filename, &buffer) == 0) {
        // If a file with the same name already exists, generate a new unique ID and try again
        id++;
        sprintf(new_filename, "%s-%lu.txt", filename, id);
    }

    // Create an EVP_CIPHER structure for the chosen cipher
    EVP_CIPHER* cipher = NULL;

    // Implement the DES algorithm with ECB mode
