        cipher = EVP_des_ede3();
    }

    // Implement the DES algorithm with CFB mode
    else if (strcmp(filename, "cfb") == 0) {
        cipher = EVP_des_cfb();
    }

    // If no matching cipher was found, return NULL
    if (cipher == NULL) {
        free(new_filename);
        return NULL;
    }

    // Return the pointer to the EVP_CIPHER structure representing the chosen cipher
    return cipher;
}
