Here is the JavaScript function for recursively traversing a DOM tree and returning a list of elements that match a given selector:
```
function getElementsBySelector(selector, element) {
    var elements = [];
    if (element.matches(selector)) {
        elements.push(element);
    }
    element.children.forEach(function(child) {
        elements = elements.concat(getElementsBySelector(selector, child));
    });
    return elements;
}
