    while (i < capacity && packets[i].timestamp != -1) {
        i++;
    }

    // If no empty slots found, double the size of the array
    if (i == capacity) {
        capacity *= 2;
        DataPacket* new_packets = (DataPacket*)realloc(packets, capacity * sizeof(DataPacket));
        for (int j = i; j < capacity; j++) {
            new_packets[j].timestamp = -1;
            new_packets[j].packet_size = 0;
            new_packets[j].packet_data = NULL;
        }
        packets = new_packets;
    }

    // Add the new packet to the array
    packets[i].timestamp = timestamp;
    packets[i].packet_size = packet_size;
    packets[i].packet_data = (char*)malloc(packet_size * sizeof(char));
    memcpy(packets[i].packet_data, packet_data, packet_size);
}

void update_packet(DataPacket* packets, long timestamp, int packet_size, char* packet_data) {
    // Find the packet with the given timestamp in the array
    int i = 0;
    while (i < capacity && packets[i].timestamp != timestamp) {
        i++;
    }

    // If the packet is found, update its data
    if (i < capacity) {
        free(packets[i].packet_data);
        packets[i].packet_size = packet_size;
        packets[i].packet_data = (char*)malloc(packet_size * sizeof(char));
        memcpy(packets[i].packet_data, packet_data, packet_size);
    }
}

DataPacket* get_packet(DataPacket* packets, long timestamp) {
    // Find the packet with the given timestamp in the array
    int i = 0;
    while (i < capacity && packets[i].timestamp != timestamp) {
        i++;
    }

    // If the packet is found, return it
    if (i < capacity) {
        return &packets[i];
    } else {
        return NULL;
    }
}

void free_packet_array(DataPacket* packets) {
    for (int i = 0; i < capacity; i++) {
        if (packets[i].packet_data != NULL) {
            free(packets[i].packet_data);
        }
    }
    free(packets);
}
