    if (config->packet_size < 512 || config->packet_size > 8192) {
        printf("Packet size out of range. Using default value of 1024.\n");
        config->packet_size = 1024;
    }
    if (config->buffer_depth < 1 || config->buffer_depth > 32) {
        printf("Buffer depth out of range. Using default value of 16.\n");
        config->buffer_depth = 16;
    }
    if (config->link_quality_indicator < 0 || config->link_quality_indicator > 10) {
        printf("Link quality indicator out of range. Using default value of 5.\n");
        config->link_quality_indicator = 5;
    }

    // Compute MD5 hash of a provided string parameter using OpenSSL library
    char *string_to_hash = "Hello, world!";
    unsigned char md5_hash[MD5_DIGEST_LENGTH];
    int retval = MD5(string_to_hash, strlen(string_to_hash), md5_hash);
    if (retval != 1) {
        printf("Error computing MD5 hash. Using default value of 0.\n");
        config->md5_hash = 0;
    } else {
        config->md5_hash = md5_hash[0] << 24 | md5_hash[1] << 16 | md5_hash[2] << 8 | md5_hash[3];
    }

    // Log detailed validation steps and final configuration states for debugging and performance tuning
    printf("Final network interface configuration:\n");
    printf("Protocol version: %d\n", config->protocol_version);
    printf("Packet size: %d bytes\n", config->packet_size);
    printf("Buffer depth: %d packets\n", config->buffer_depth);
    printf("Link quality indicator: %d%%\n", config->link_quality_indicator);
    printf("MD5 hash of string 'Hello, world!': 0x%08X\n", config->md5_hash);
}
