    struct cache *cached = NULL;
    pthread_mutex_lock(&cache_mutex);
    for (int i = 0; i < MAX_CACHE_ENTRIES; i++) {
        if (strcmp(hostname, cache[i].hostname) == 0) {
            cached = &cache[i];
            break;
        }
    }
    pthread_mutex_unlock(&cache_mutex);

    // If the hostname is already cached, return the IP address
