    int rc = getaddrinfo(hostname, NULL, &hints, &result);
    if (rc != 0) {
        // Log the error and return an error code
        log_error("Failed to resolve hostname: %s", gai_strerror(rc));
        return NULL;
    }
    struct in_addr *ip = (struct in_addr *)result->ai_addr;
    pthread_mutex_lock(&cache_mutex);
    for (int i = 0; i < MAX_CACHE_ENTRIES; i++) {
        if (cache[i].hostname == NULL) {
            cache[i].hostname = strdup(hostname);
            cache[i].ip_address = *ip;
            cache[i].ttl = time(NULL) + CACHE_TTL;
            break;
        }
    }
    pthread_mutex_unlock(&cache_mutex);

    // Return the IP address
    return (u_char *)&(ip->s_addr);
}

// Function to evict old entries from the cache based on access frequency and time
void cache_eviction() {
    pthread_mutex_lock(&cache_mutex);
    for (int i = 0; i < MAX_CACHE_ENTRIES; i++) {
        if (cache[i].hostname == NULL) {
            continue;
        }
        // Evict entries that are older than the TTL or have not been accessed recently
        if (time(NULL) > cache[i].ttl || cache[i].access_count < QUERIES_PER_MINUTE) {
            free(cache[i].hostname);
            cache[i].hostname = NULL;
        } else {
            // Update the access count and time for this entry
            cache[i].access_count--;
            cache[i].ttl = time(NULL) + CACHE_TTL;
        }
    }
    pthread_mutex_unlock(&cache_mutex);
}

// Function to log successful DNS resolutions and errors
void log_success(const char *hostname, struct in_addr ip_address) {
    if (LOGGING_LEVEL < 1) {
        return;
    }
    printf("DNS resolution succeeded: %s -> %s\n", hostname, inet_ntoa(ip_address));
}

void log_error(const char *message, const char *hostname) {
    if (LOGGING_LEVEL < 2) {
        return;
    }
    printf("DNS resolution failed: %s\n", message);
}
