bool parse_access_token(const char *json_string) {
    json_object *root = json_tokener_parse(json_string);
    if (!root) {
        return false;
    }

    json_object *access_token = json_object_object_get(root, "access_token");
    if (!access_token || !json_object_is_type(access_token, json_type_string)) {
        return false;
    }

    const char *token = json_object_get_string(access_token);
    if (strlen(token) > 256) {
        return false;
    }

    json_object *expires_in = json_object_object_get(root, "expires_in");
    if (!expires_in || !json_object_is_type(expires_in, json_type_int)) {
        return false;
    }

    int expiry = json_object_get_int(expires_in);
    if (expiry <= 0) {
        return false;
    }

    json_object *token_type = json_object_object_get(root, "token_type");
    if (!token_type || !json_object_is_type(token_type, json_type_string)) {
        return false;
    }

    const char *type = json_object_get_string(token_type);
    if (strcmp(type, "Bearer") != 0) {
        return false;
    }

    json_object *refresh_token = json_object_object_get(root, "refresh_token");
    if (refresh_token && !json_object_is_type(refresh_token, json_type_string)) {
        return false;
    }

    return true;
}

bool validate_access_tokens(const char *json_string) {
    bool valid = true;
    json_object *root = json_tokener_parse(json_string);
    if (!root) {
        return false;
    }

    json_object_object_foreach(root, key, val) {
        if (strcmp(key, "access_token") == 0 && !parse_access_token(val)) {
            valid = false;
            break;
        }
    }

    return valid;
}
