    if (expires <= 0) {
        json_object_put(root);
        return false;
    }

    const char *access_token = json_object_get_string(json_object_object_get(root, "access_token"));
    if (strlen(access_token) > 256) {
        json_object_put(root);
        return false;
    }

    json_object_put(root);
    return true;
}

bool *validate_tokens(const char **tokens, int num_tokens) {
    bool *valid = malloc(num_tokens * sizeof(bool));
    for (int i = 0; i < num_tokens; ++i) {
        valid[i] = validate_token(tokens[i]);
    }
    return valid;
}
