            if (!field1 || json_object_get_type(field1) != json_type_string) {
                valid = false;
            }
            // ...
        }
    } else if (strcmp(mode, "xml") == 0) {
        xmlDocPtr doc = xmlReadMemory(buffer, bytes_read, filename, NULL, 0);
        if (!doc || xmlGetLastError() != NULL) {
            valid = false;
        } else {
            // Check for required fields and data types
            xmlNode* node1 = xmlDocGetRootElement(doc);
            if (!node1 || !xmlStrcmp(node1->name, "field1")) {
                valid = false;
            }
            // ...
        }
    } else if (strcmp(mode, "csv") == 0) {
        csv_parser* parser = csv_parse(buffer, bytes_read);
        if (!parser || csv_error(parser)) {
            valid = false;
        } else {
            // Check for required fields and data types
            csv_row* row1 = csv_get_row(parser);
            if (!row1 || !csv_get_field(row1, "field1")) {
                valid = false;
            }
            // ...
        }
    } else {
        valid = false;
    }

    // Clean up and return the result
    free(buffer);
    return valid;
}
