void error_handler(const char* message) {
    // Print an error message and exit the program
    fprintf(stderr, "Error: %s\n", message);
    exit(EXIT_FAILURE);
}

// Define the function to handle concurrent access from multiple threads
void thread_safe(const char* filename) {
    // Open the file in read mode and check for errors
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Error opening file");
        return;
    }

    // Lock the file using flock and check for errors
    struct flock lock;
    lock.l_type = F_WRLCK;
    lock.l_whence = SEEK_SET;
    lock.l_start = 0;
    lock.l_len = 0;
    if (fcntl(fd, F_SETLKW, &lock) == -1) {
        perror("Error locking file");
        close(fd);
        return;
    }

    // Read the data from the file and unlock it using flock
    void* mem = mmap(NULL, sizeof(data), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (mem == MAP_FAILED) {
        perror("Error mapping memory");
        close(fd);
        return;
    }
    msync(mem, sizeof(data), MS_SYNC);
    munmap(mem, sizeof(data));
    lock.l_type = F_UNLCK;
    if (fcntl(fd, F_SETLKW, &lock) == -1) {
        perror("Error unlocking file");
        close(fd);
        return;
    }

    // Close the descriptor and return
    close(fd);
}
