        config->modulation_type = 0;
    }

    // Bandwidth: 20 MHz, 40 MHz, 80 MHz, or 160 MHz
    if (config->bandwidth < 0 || config->bandwidth > 3) {
        printf("Invalid bandwidth. Using default value.\n");
        config->bandwidth = 0;
    }

    // Cell identity: integer between 1 and 256
    if (config->cell_identity < 1 || config->cell_identity > 256) {
        printf("Invalid cell identity. Using default value.\n");
        config->cell_identity = 1;
    }

    // Transmission power: integer between -30 and 30 dBm
    if (config->transmission_power < -30 || config->transmission_power > 30) {
        printf("Invalid transmission power. Using default value.\n");
        config->transmission_power = -30;
    }

    // Signal-to-noise ratio: float between 5 and 40 dB
    if (config->snr < 5 || config->snr > 40) {
        printf("Invalid SNR. Using default value.\n");
        config->snr = 25.0;
    }

    // Frequency offset: float between -100 and 100 Hz
    if (config->frequency_offset < -100 || config->frequency_offset > 100) {
        printf("Invalid frequency offset. Using default value.\n");
        config->frequency_offset = 0.0;
    }
}

