    private readonly PBKDF2 _pbkdf2;

    public HttpPostRequestProcessor(ILogger<HttpPostRequestProcessor> logger, RNGCryptoServiceProvider rngCsp, PBKDF2 pbkdf2)
    {
        _logger = logger;
        _rngCsp = rngCsp;
        _pbkdf2 = pbkdf2;
    }

    public async Task<HttpResponse> ProcessRequestAsync(string userId, string sessionToken, int pageSectionId, int elementId, string htmlContent)
    {
        // Validate the session token and user ID
        if (!ValidateSessionTokenAndUserId(sessionToken, userId))
        {
            return new HttpResponse()
            {
                StatusCode = 401,
                Content = "Invalid session token or user ID"
            };
        }

        // Derive a secure encryption key using PBKDF2 with at least 20,000 iterations and a salt size of 16 bytes
        byte[] derivedKey;
        byte[] iv;
        using (var pbkdf2 = new PBKDF2(_pbkdf2))
        {
            var salt = _rngCsp.GetBytes(16);
            derivedKey = pbkdf2.ComputeDerivedKey(20000, salt, htmlContent, 32);
            iv = pbkdf2.ComputeDerivedKey(20000, salt, htmlContent, 16);
        }

        // Initialize an AES-256-CBC cipher with the derived key and IV
        using (var aes = new AesCbc())
        {
            aes.Key = derivedKey;
            aes.IV = iv;

            // Update the element's HTML content
            var encryptedContent = aes.Encrypt(htmlContent);
            await UpdateElementAsync(pageSectionId, elementId, encryptedContent);
        }

        // Log the update for audit purposes
        _logger.LogInformation($"Updated element {elementId} in page section {pageSectionId} with HTML content");

        return new HttpResponse()
        {
            StatusCode = 200,
            Content = "Page refreshed"
        };
    }

