typedef struct {
    char* filename;
    int version_number;
} file_version_t;

// Define a hash table to store the filenames and their corresponding version numbers
static pthread_mutex_t hash_table_lock = PTHREAD_MUTEX_INITIALIZER;
static hash_table_t* hash_table = NULL;

// Function to process a list of filenames from an external data source, modifying each one to include a timestamp and a version number
void process_filenames(char** filenames, int num_filenames) {
