    if (hash_table == NULL) {
        pthread_mutex_lock(&hash_table_lock);
        if (hash_table == NULL) {
            hash_table = create_hash_table();
        }
        pthread_mutex_unlock(&hash_table_lock);
    }

    // Iterate over the list of filenames and update the version numbers in the hash table
    for (int i = 0; i < num_filenames; i++) {
        char* filename = filenames[i];
        file_version_t* file_version = get_file_version(filename);
        if (file_version == NULL) {
            // If the file version doesn't exist in the hash table, create a new one and add it to the table
            file_version = create_file_version(filename);
            add_file_version(hash_table, filename, file_version);
        } else {
            // If the file version already exists in the hash table, increment its version number
            file_version->version_number++;
        }
    }
}

// Function to create a new file version struct and initialize its fields
file_version_t* create_file_version(char* filename) {
    file_version_t* file_version = malloc(sizeof(file_version_t));
    file_version->filename = strdup(filename);
    file_version->version_number = 1;
    return file_version;
}

// Function to add a new file version struct to the hash table
void add_file_version(hash_table_t* hash_table, char* filename, file_version_t* file_version) {
    pthread_mutex_lock(&hash_table_lock);
    hash_table_put(hash_table, filename, file_version);
    pthread_mutex_unlock(&hash_table_lock);
}

// Function to get the file version struct for a given filename from the hash table
file_version_t* get_file_version(char* filename) {
    pthread_mutex_lock(&hash_table_lock);
    file_version_t* file_version = hash_table_get(hash_table, filename);
    pthread_mutex_unlock(&hash_table_lock);
    return file_version;
}

// Function to create a new hash table for storing the filenames and their corresponding version numbers
hash_table_t* create_hash_table() {
    hash_table_t* hash_table = malloc(sizeof(hash_table_t));
    hash_table->size = 10; // Initial size of the hash table
    hash_table->num_elements = 0;
    hash_table->buckets = calloc(hash_table->size, sizeof(bucket_t*));
    return hash_table;
}

// Function to put a new element in the hash table
void hash_table_put(hash_table_t* hash_table, char* key, file_version_t* value) {
    int index = hash_function(key);
    bucket_t* bucket = hash_table->buckets[index];
    if (bucket == NULL) {
        // If the bucket doesn't exist yet, create a new one and add it to the hash table
        bucket = malloc(sizeof(bucket_t));
        bucket->key = strdup(key);
        bucket->value = value;
        bucket->next = NULL;
        hash_table->buckets[index] = bucket;
    } else {
        // If the bucket already exists, add the new element to the end of the linked list
        while (bucket->next != NULL) {
            bucket = bucket->next;
        }
        bucket->next = malloc(sizeof(bucket_t));
        bucket->next->key = strdup(key);
        bucket->next->value = value;
        bucket->next->next = NULL;
    }
    hash_table->num_elements++;
}

// Function to get an element from the hash table
file_version_t* hash_table_get(hash_table_t* hash_table, char* key) {
    int index = hash_function(key);
    bucket_t* bucket = hash_table->buckets[index];
    while (bucket != NULL && strcmp(bucket->key, key) != 0) {
        bucket = bucket->next;
    }
    if (bucket == NULL) {
        return NULL;
    } else {
        return bucket->value;
    }
}

// Function to calculate the hash value for a given key
int hash_function(char* key) {
    int hash = 0;
    for (int i = 0; i < strlen(key); i++) {
        hash += key[i];
    }
    return hash % hash_table->size;
}
