    struct tm* local_time = localtime(&now);
    char timestamp[20];
    strftime(timestamp, 20, "%Y%m%d-%H%M%S", local_time);

    // Get the length of the original filename
    int orig_len = strlen(filename);

    // Calculate the number of digits to append to the filename
    int num_digits = (orig_len / 2) - 1;

    // Allocate memory for the new filename
    char* new_filename = malloc((orig_len + strlen(timestamp) + num_digits + 1) * sizeof(char));
    if (!new_filename) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Construct the new filename using sprintf and strcat
    sprintf(new_filename, "%s-%0*d.%c", timestamp, num_digits, orig_len - 1, filename[orig_len - 1]);

    // Check if the new filename is at maximum length
    int new_len = strlen(new_filename);
    if (new_len > 256) {
        // If so, append the timestamp and digits without altering the existing extension
        sprintf(new_filename + new_len - 1, "-%s-%0*d", timestamp, num_digits, orig_len - 1);
    }

    // Free the allocated memory
    free(new_filename);

    return new_filename;
}
