    int digits = len / 2;
    for (int i = 0; i < digits; i++) {
        char digit = '0' + i;
        strcat(newFilename, &digit);
    }
    if (lastChar == '.') {
        strcat(newFilename, ".");
    } else {
        strcat(newFilename, &lastChar);
    }

    // Ensure the total length does not exceed 256 characters
    int newLen = strlen(newFilename);
    if (newLen > 256) {
        newFilename[256] = '\0';
    }

    return newFilename;
}
