    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_data);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, filename);
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to download %s: %s\n", url, curl_easy_strerror(res));
        free(filename);
        free(file_hash);
        return NULL;
    }

    // Calculate the hash of the downloaded resource
    FILE* file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open %s for reading\n", filename);
        free(filename);
        free(file_hash);
        return NULL;
    }

    MD5_CTX ctx;
    MD5Init(&ctx);
    char buffer[1024];
    size_t read;
    while ((read = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        MD5Update(&ctx, buffer, read);
    }

    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5Final(hash, &ctx);
    file_hash->filename = filename;
    file_hash->hash = malloc(MD5_DIGEST_LENGTH * 2 + 1);
    if (!file_hash->hash) {
        fprintf(stderr, "Failed to allocate memory for hash\n");
        free(filename);
        free(file_hash);
        return NULL;
    }

    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(file_hash->hash + i * 2, "%02x", hash[i]);
    }

    file_hash->hash[MD5_DIGEST_LENGTH * 2] = '\0';

    fclose(file);

    return file_hash;
}
