import random
from collections import defaultdict

def add_random_vertices(graph):
    """Add a random number of vertices to the graph."""
    num_vertices = random.randint(10, 20)
    for i in range(num_vertices):
        vertex = {
            "id": str(i),
            "label": f"Vertex {i}",
            "properties": {
                "random_property": random.choice(["A", "B", "C"])
            }
        }
        graph.add_vertex(vertex)

def add_random_edges(graph):
    """Add a random number of edges to the graph."""
    num_edges = random.randint(10, 20)
    for i in range(num_edges):
        edge = {
            "id": str(i),
            "label": f"Edge {i}",
            "properties": {
                "random_property": random.choice(["A", "B", "C"])
            }
        }
        graph.add_edge(edge)
```
