    if (i == framework->num_compression_algorithms) {
        fprintf(stderr, "Compression algorithm %s not found\n", algorithm_name);
        return -1;
    }

    // Decompress the data using the specified compression algorithm
    void *data = NULL;
    size_t data_size = 0;
    int status = framework->compression_algorithms[i].decompress(compressed_data, compressed_data_size, &data, &data_size);
    if (status != 0) {
        fprintf(stderr, "Decompression failed with error %d\n", status);
        return -1;
    }

    // Return the decompressed data
    return data_size;
}

// Define a function to get the version of the data from the specified metadata repository
int get_version(data_compression_framework *framework, void *metadata, char *repository_name) {
    assert(framework != NULL);
    assert(metadata != NULL);
    assert(repository_name != NULL);

    // Find the metadata repository with the specified name
    int i;
    for (i = 0; i < framework->num_metadata_repositories; ++i) {
        if (strcmp(framework->metadata_repositories[i].name, repository_name) == 0) {
