    }

    // Get the version of the data from the specified metadata repository
    int version = framework->metadata_repositories[i].get_version(metadata);
    if (version < 0) {
        fprintf(stderr, "Failed to get version from metadata repository %s\n", repository_name);
        return -1;
    }

    // Return the version of the data
    return version;
}

// Define a function to set the version of the data in the specified metadata repository
int set_version(data_compression_framework *framework, void *metadata, int version, char *repository_name) {
    assert(framework != NULL);
    assert(metadata != NULL);
    assert(version >= 0);
    assert(repository_name != NULL);

    // Find the metadata repository with the specified name
    int i;
    for (i = 0; i < framework->num_metadata_repositories; ++i) {
        if (strcmp(framework->metadata_repositories[i].name, repository_name) == 0) {
