        fprintf(stderr, "Caching mechanism %s not found\n", "Memory Cache");
        return NULL;
    }

    // Get the item from the specified caching mechanism
    void *item = framework->caching_mechanisms[i].get(cache, key);
    if (item == NULL) {
        fprintf(stderr, "Failed to get item from caching mechanism %s\n", "Memory Cache");
        return NULL;
    }

    // Return the item
    return item;
}

// Define a function to put an item in the specified caching mechanism
int put(data_compression_framework *framework, void *cache, void *key, void *value) {
    assert(framework != NULL);
    assert(cache != NULL);
    assert(key != NULL);
    assert(value != NULL);

    // Find the caching mechanism with the specified name
    int i;
    for (i = 0; i < framework->num_caching_mechanisms; ++i) {
        if (strcmp(framework->caching_mechanisms[i].name, "Memory Cache") == 0) {
            break;
        }
    }

    // If the caching mechanism was not found, return an error
    if (i == framework->num_caching_mechanisms) {
        fprintf(stderr, "Caching mechanism %s not found\n", "Memory Cache");
        return -1;
    }

    // Put the item in the specified caching mechanism
    int status = framework->caching_mechanisms[i].put(cache, key, value);
    if (status != 0) {
        fprintf(stderr, "Failed to put item in caching mechanism %s\n", "Memory Cache");
        return -1;
    }

    // Return success
    return 0;
}
