Here is a sample C function that performs DNS resolution for a given hostname using the standard library functions and returns the IP address in a u_char array:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>

int dns_resolve(const char *hostname, u_char **ip) {
    struct addrinfo hints;
    struct addrinfo *result, *rp;
    int s;

    // Initialize the addrinfo structure
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET; // IPv4 only for now
    hints.ai_socktype = SOCK_STREAM;

    // Perform DNS resolution
    if ((s = getaddrinfo(hostname, NULL, &hints, &result)) != 0) {
        fprintf(stderr, "getaddrinfo failed: %s\n", gai_strerror(s));
        return -1;
    }

    // Iterate over the results and find the first IPv4 address
    for (rp = result; rp != NULL; rp = rp->ai_next) {
        if (rp->ai_family == AF_INET) {
            *ip = (u_char *)rp->ai_addr;
            break;
        }
    }

    // Free the addrinfo structure
    freeaddrinfo(result);

    return 0;
}
```
