#include <iostream>
#include <random>
#include <vector>

namespace RandomGenerator {
    class MTGenerator {
        private:
            static std::mt19937 mt;

        public:
            MTGenerator() {
                // Initialize the random number generator using a seed
                mt.seed(std::random_device()());
            }

            ~MTGenerator() {}

            void generateRandomNumbers(int numInts) {
                if (numInts > 10000) {
                    std::cerr << "Error: Number of integers exceeds maximum limit" << std::endl;
                    return;
                }

                // Allocate memory for the array of integers
                int* arr = new int[numInts];

                if (arr == nullptr) {
                    std::cerr << "Error: Memory allocation failed" << std::endl;
                    return;
                }

                // Read the list of integers from standard input
                for (int i = 0; i < numInts; ++i) {
                    std::cin >> arr[i];

                    if (!std::cin || arr[i] < -2147483648 || arr[i] > 2147483647) {
                        std::cerr << "Error: Invalid input" << std::endl;
                        delete[] arr;
                        return;
                    }
                }

                // Find the largest integer in the array
                int largest = -2147483648;
                for (int i = 0; i < numInts; ++i) {
                    if (arr[i] > largest) {
                        largest = arr[i];
                    }
                }

                // Print the largest integer
                std::cout << "Largest integer: " << largest << std::endl;

                // Free the allocated memory
                delete[] arr;
            }
    };
}

int main() {
    RandomGenerator::MTGenerator mtGen;
    int numInts = 0;
    std::cin >> numInts;

    if (numInts > 10000) {
        std::cerr << "Error: Number of integers exceeds maximum limit" << std::endl;
        return 1;
    }

    // Allocate memory for the array of integers
    int* arr = new int[numInts];

    if (arr == nullptr) {
        std::cerr << "Error: Memory allocation failed" << std::endl;
        return 1;
    }

    // Read the list of integers from standard input
    for (int i = 0; i < numInts; ++i) {
        std::cin >> arr[i];

        if (!std::cin || arr[i] < -2147483648 || arr[i] > 2147483647) {
            std::cerr << "Error: Invalid input" << std::endl;
            delete[] arr;
            return 1;
        }
    }

    // Find the largest integer in the array
    int largest = -2147483648;
    for (int i = 0; i < numInts; ++i) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }

    // Print the largest integer
    std::cout << "Largest integer: " << largest << std::endl;

    // Free the allocated memory
    delete[] arr;

    return 0;
}
