// Custom serialization function for the device data structure
void serialize_device(const Device* device, char* buffer) {
    // Serialize the name and power consumption values
    strcpy(buffer, device->name);
    memcpy(buffer + strlen(device->name), &device->power_consumption, sizeof(double));

    // Serialize the sensor array
    int num_sensors = device->num_sensors;
    memcpy(buffer + strlen(device->name) + sizeof(double), &num_sensors, sizeof(int));
    for (int i = 0; i < num_sensors; i++) {
        Sensor* sensor = device->sensors[i];
        memcpy(buffer + strlen(device->name) + sizeof(double) + sizeof(int), &sensor->measurement_interval, sizeof(int));
        memcpy(buffer + strlen(device->name) + sizeof(double) + sizeof(int) + sizeof(int), &sensor->status, sizeof(enum SensorStatus));
    }

    // Serialize the observation tree
    int num_observations = device->num_observations;
    memcpy(buffer + strlen(device->name) + sizeof(double) + sizeof(int) * (num_sensors + 1), &num_observations, sizeof(int));
    for (int i = 0; i < num_observations; i++) {
        Observation* observation = device->observations[i];
        memcpy(buffer + strlen(device->name) + sizeof(double) + sizeof(int) * (num_sensors + 1) + sizeof(int), &observation->timestamp, sizeof(time_t));
        memcpy(buffer + strlen(device->name) + sizeof(double) + sizeof(int) * (num_sensors + 1) + sizeof(int) + sizeof(time_t), &observation->sensor, sizeof(Sensor*));
        int num_measurements = observation->num_measurements;
        memcpy(buffer + strlen(device->name) + sizeof(double) + sizeof(int) * (num_sensors + 1) + sizeof(int) + sizeof(time_t) + sizeof(Sensor*), &num_measurements, sizeof(int));
        for (int j = 0; j < num_measurements; j++) {
            memcpy(buffer + strlen(device->name) + sizeof(double) + sizeof(int) * (num_sensors + 1) + sizeof(int) + sizeof(time_t) + sizeof(Sensor*) + sizeof(int), &observation->measurements[j], sizeof(float));
        }
    }
}

// Custom deserialization function for the device data structure
void deserialize_device(Device* device, char* buffer) {
    // Deserialize the name and power consumption values
    strcpy(device->name, buffer);
    memcpy(&device->power_consumption, buffer + strlen(device->name), sizeof(double));

    // Deserialize the sensor array
    int num_sensors;
    memcpy(&num_sensors, buffer + strlen(device->name) + sizeof(double), sizeof(int));
    device->num_sensors = num_sensors;
    for (int i = 0; i < num_sensors; i++) {
        Sensor* sensor = &device->sensors[i];
        memcpy(&sensor->measurement_interval, buffer + strlen(device->name) + sizeof(double) + sizeof(int), sizeof(int));
        memcpy(&sensor->status, buffer + strlen(device->name) + sizeof(double) + sizeof(int) + sizeof(int), sizeof(enum SensorStatus));
    }

    // Deserialize the observation tree
