// Define the maximum number of entries in the cache
#define MAX_CACHE_ENTRIES 1024

// Define the time-to-live for each entry in the cache (in seconds)
#define CACHE_TTL 3600

// Define the maximum query frequency (in queries per second)
#define MAX_QUERY_FREQ 5

// Define the rate limiting factor (in queries per second)
#define RATE_LIMITING_FACTOR 2

// Define the minimum number of vertices to add in a single batch operation
#define MIN_VERTICES_PER_BATCH 100

// Define the maximum number of vertices to add in a single batch operation
#define MAX_VERTICES_PER_BATCH 500

// Define the minimum number of edges to add in a single batch operation
#define MIN_EDGES_PER_BATCH 100

// Define the maximum number of edges to add in a single batch operation
