// Define the cache structure
struct cache {
    char *hostname;
    struct in_addr ip_address;
    time_t ttl;
};

// Define the cache hash table
static struct cache *cache_table[MAX_CACHE_ENTRIES];

// Define the mutex for protecting the cache
static pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the DNS resolution function
int dns_resolve(const char *hostname, struct in_addr *ip_address) {
    // Check if the hostname is already cached
    pthread_mutex_lock(&cache_mutex);
    for (int i = 0; i < MAX_CACHE_ENTRIES; i++) {
        if (cache_table[i] != NULL && strcmp(hostname, cache_table[i]->hostname) == 0) {
            // If the hostname is cached, return the IP address and update the TTL
            *ip_address = cache_table[i]->ip_address;
            cache_table[i]->ttl = time(NULL) + CACHE_TTL;
            pthread_mutex_unlock(&cache_mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&cache_mutex);

    // If the hostname is not cached, perform DNS resolution and cache the result
    struct addrinfo *addr_info = NULL;
    int err = getaddrinfo(hostname, NULL, NULL, &addr_info);
    if (err != 0) {
        return -1;
    }
    *ip_address = ((struct sockaddr_in *)addr_info->ai_addr)->sin_addr;
    freeaddrinfo(addr_info);

    // Add the hostname and IP address to the cache
    pthread_mutex_lock(&cache_mutex);
    for (int i = 0; i < MAX_CACHE_ENTRIES; i++) {
        if (cache_table[i] == NULL) {
            cache_table[i] = malloc(sizeof(struct cache));
            cache_table[i]->hostname = strdup(hostname);
            cache_table[i]->ip_address = *ip_address;
            cache_table[i]->ttl = time(NULL) + CACHE_TTL;
            break;
        }
    }
    pthread_mutex_unlock(&cache_mutex);

    return 0;
}

// Define the MD5 hash function for files
int md5_hash(const char *filepath, unsigned char *md5) {
    // Open the file and calculate its size
    int fd = open(filepath, O_RDONLY);
    if (fd == -1) {
        return -1;
    }
    struct stat st;
    fstat(fd, &st);
    off_t filesize = st.st_size;

    // Allocate memory for the file data and read it in chunks
    char *filedata = malloc(filesize);
    ssize_t bytes_read = 0;
    while (bytes_read < filesize) {
        ssize_t n = read(fd, filedata + bytes_read, filesize - bytes_read);
        if (n == -1) {
            free(filedata);
            close(fd);
            return -1;
        }
        bytes_read += n;
    }
    close(fd);

    // Calculate the MD5 hash of the file data and free the memory
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, filedata, filesize);
    MD5_Final(md5, &ctx);
    free(filedata);

    return 0;
}

