    pthread_mutex_lock(&cache_mutex);
    for (int i = 0; i < MAX_CACHE_ENTRIES; i++) {
        if (cache_table[i] != NULL && strcmp(hostname, cache_table[i]->hostname) == 0) {
            // If the hostname is cached, return the IP address and update the TTL
            struct in_addr ip_address = cache_table[i]->ip_address;
            cache_table[i]->ttl = time(NULL) + CACHE_TTL;
            pthread_mutex_unlock(&cache_mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&cache_mutex);

    // If the hostname is not cached, perform DNS resolution and cache the result
    struct addrinfo *addr_info = NULL;
    int err = getaddrinfo(hostname, NULL, NULL, &addr_info);
    if (err != 0) {
        return -1;
    }
    struct in_addr ip_address = ((struct sockaddr_in *)addr_info->ai_addr)->sin_addr;
    freeaddrinfo(addr_info);

    // Add the hostname and IP address to the cache
    pthread_mutex_lock(&cache_mutex);
    for (int i = 0; i < MAX_CACHE_ENTRIES; i++) {
        if (cache_table[i] == NULL) {
            cache_table[i] = malloc(sizeof(struct cache));
            cache_table[i]->hostname = strdup(hostname);
            cache_table[i]->ip_address = ip_address;
            cache_table[i]->ttl = time(NULL) + CACHE_TTL;
            break;
        }
    }
    pthread_mutex_unlock(&cache_mutex);

    // Add the vertices and edges to the graph database
    int num_added = 0;
    for (int i = 0; i < num_vertices; i++) {
        // Generate a random property value for each vertex
        int prop_value = rand() % (MAX_PROP_VALUE - MIN_PROP_VALUE + 1) + MIN_PROP_VALUE;

        // Add the vertex to the graph database
        err = add_vertex(ip_address, prop_value);
        if (err != 0) {
            return -1;
        }
        num_added++;
    }
    for (int i = 0; i < num_edges; i++) {
        // Generate a random property value for each edge
        int prop_value = rand() % (MAX_EDGE_PROP_VALUE - MIN_EDGE_PROP_VALUE + 1) + MIN_EDGE_PROP_VALUE;

        // Add the edge to the graph database
        err = add_edge(ip_address, prop_value);
        if (err != 0) {
            return -1;
        }
        num_added++;
    }

    return num_added;
}
