// Define the function to handle backpressure from the external data source
void manage_backpressure(NFAPI_CRC_INDICATION_PDU_T* pdu_list, int num_ues) {
    // Check if there is backpressure from the external data source
    if (num_ues > MAX_NUM_UES) {
        // Handle the backpressure by buffering incomplete data and managing it later
        NFAPI_CRC_INDICATION_PDU_T* buffer = buffer_incomplete_data(pdu_list, num_ues);
