        return UNKNOWN_HOST;
    }

    // Create a DNS request structure
    struct DNSRequest req = {.hostname = hostname, .priority = MEDIUM, .sockfd = sockfd};

    // Send the DNS request to the DNS server
    if (sendto(req.sockfd, &req, sizeof(struct DNSRequest), 0, (struct sockaddr *)&req.addr, sizeof(struct sockaddr_in)) < 0) {
        perror("Failed to send DNS request");
        return FAILURE;
    }

    // Receive the DNS response from the DNS server
    struct DNSResponse res = {.sockfd = req.sockfd};
    if (recvfrom(res.sockfd, &res, sizeof(struct DNSResponse), 0, NULL, NULL) < 0) {
        perror("Failed to receive DNS response");
        return FAILURE;
    }

    // Check if the DNS response is valid
    if (res.status != SUCCESS) {
        return res.status;
    }

    // Extract the IP address from the DNS response
    char *ip = inet_ntoa(res.addr.sin_addr);

    // Return the IP address and the DNS request structure
    *addr = res.addr;
    return SUCCESS;
}

// Define a function to manage incoming DNS requests
void handleDNSRequests() {
    // Create a queue for managing incoming DNS requests
    Queue queue = {NULL, NULL};

    // Initialize the DNS resolver
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    initDNSResolver(sockfd);

    // Loop until a shutdown signal is received
    while (1) {
        // Check if there are any incoming DNS requests in the queue
        if (queue.head == NULL) {
            // Wait for an incoming DNS request
            sleep(1);
            continue;
        }

        // Extract the first DNS request from the queue
        struct DNSRequest *req = queue.head;
        queue.head = req->next;

        // Perform DNS resolution for the DNS request
        enum ErrorCode status = resolveDNS(req->hostname, &req->addr);

        // Check if the DNS resolution was successful
        if (status == SUCCESS) {
            // Send the IP address back to the client
            sendto(req->sockfd, &req->addr, sizeof(struct sockaddr_in), 0, (struct sockaddr *)&req->addr, sizeof(struct sockaddr_in));
        } else {
            // Log the error and return an appropriate response to the client
            perror("Failed to resolve DNS");
            sendto(req->sockfd, &status, sizeof(enum ErrorCode), 0, (struct sockaddr *)&req->addr, sizeof(struct sockaddr_in));
        }
    }
}

// Define a function to manage the number of active threads
void manageThreads() {
    // Create a queue for managing incoming DNS requests
    Queue queue = {NULL, NULL};

    // Initialize the DNS resolver
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    initDNSResolver(sockfd);

    // Loop until a shutdown signal is received
    while (1) {
        // Check if there are any incoming DNS requests in the queue
        if (queue.head == NULL) {
            // Wait for an incoming DNS request
            sleep(1);
            continue;
        }

        // Extract the first DNS request from the queue
        struct DNSRequest *req = queue.head;
        queue.head = req->next;

        // Check if there are any active threads
        if (queue.tail == NULL) {
            // Create a new thread to handle the DNS request
            pthread_t thread;
            pthread_create(&thread, NULL, handleDNSRequests, NULL);
        } else {
            // Add the DNS request to the tail of the queue
            struct DNSRequest *req = malloc(sizeof(struct DNSRequest));
            req->hostname = hostname;
            req->priority = priority;
            req->sockfd = sockfd;
            queue.tail->next = req;
            queue.tail = req;
        }
    }
}

