// Caching mechanism for processed data
typedef struct {
    char* key;
    void* value;
    time_t expiration;
} cache_entry_t;

void addCacheEntry(cache_entry_t* entry) {
    // Add cache entry to linked list
    pthread_mutex_lock(&cache_mutex);
    cache_entry_t* head = cache_head;
    if (head == NULL) {
        cache_head = entry;
    } else {
        cache_entry_t* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = entry;
    }
    pthread_mutex_unlock(&cache_mutex);
}

void* getCacheEntry(char* key) {
    // Search for cache entry in linked list
    pthread_mutex_lock(&cache_mutex);
    cache_entry_t* head = cache_head;
    while (head != NULL) {
        if (strcmp(head->key, key) == 0) {
            // Return cached value if not expired
            time_t now = time(NULL);
            if (now < head->expiration) {
                void* value = head->value;
                pthread_mutex_unlock(&cache_mutex);
                return value;
            } else {
                // Remove expired cache entry and continue search
                cache_entry_t* current = head;
                head = head->next;
                free(current->key);
                free(current->value);
                free(current);
            }
        } else {
            head = head->next;
        }
    }
    pthread_mutex_unlock(&cache_mutex);
    return NULL;
}

