        curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
        curl_easy_setopt(curl, CURLOPT_MAXREDIRS, 50L);
        curl_easy_setopt(curl, CURLOPT_TCP_NODELAY, 1L);
        curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 30L);
        curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);
        curl_easy_setopt(curl, CURLOPT_LOW_SPEED_TIME, 60L);
        curl_easy_setopt(curl, CURLOPT_LOW_SPEED_LIMIT, 5L);
        curl_easy_setopt(curl, CURLOPT_FORBID_REUSE, 1L);
        curl_easy_setopt(curl, CURLOPT_FRESH_CONNECT, 1L);
        curl_easy_setopt(curl, CURLOPT_VERBOSE, 0L);

        // Perform API request and handle errors
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "cURL error: %s\n", curl_easy_strerror(res));
        }

        // Clean up cURL handle
        curl_easy_cleanup(curl);
    }

    return json_data;
}

// Parse JSON data and populate configuration structure with values
void parseJSONData(char* json_data, config_t* config) {
    // Initialize JSON parser
    json_object* root = json_tokener_parse(json_data);

    // Extract modulation type from JSON data
    json_object* modulation_type = json_object_object_get(root, "modulationType");
    if (modulation_type) {
        config->modulation_type = json_object_get_int(modulation_type);
    }

    // Extract bandwidth from JSON data
    json_object* bandwidth = json_object_object_get(root, "bandwidth");
    if (bandwidth) {
        config->bandwidth = json_object_get_int(bandwidth);
    }

    // Extract cell identity from JSON data
    json_object* cell_identity = json_object_object_get(root, "cellIdentity");
    if (cell_identity) {
        config->cell_identity = strdup(json_object_get_string(cell_identity));
    }

    // Clean up JSON parser
    json_object_put(root);
}

// Write JSON data to buffer for caching
size_t writeJSONData(void* ptr, size_t size, size_t nmemb, void* userdata) {
    char** json_data = (char**)userdata;
    size_t realsize = size * nmemb;

    // Allocate memory for JSON data and copy buffer contents
    *json_data = malloc(realsize + 1);
    memcpy(*json_data, ptr, realsize);
    (*json_data)[realsize] = '\0';

    return realsize;
}
