    // Compress each transaction record in the CSV file using the specified compression algorithm
    for (int i = 0; i < num_transactions; i++) {
        Transaction *transaction = transactions[i];
        char *compressed_data = compress(transaction->amount, transaction->category, transaction->date);
        fwrite(compressed_data, strlen(compressed_data), 1, output);
    }

    // Encrypt the entire report file using the provided encryption key
    AES_KEY aes_key;
    AES_set_encrypt_key(encryption_key, &aes_key);
    char *encrypted_data = malloc(sizeof(char) * (num_transactions * 1024));
    for (int i = 0; i < num_transactions; i++) {
        Transaction *transaction = transactions[i];
        char *compressed_data = compress(transaction->amount, transaction->category, transaction->date);
        AES_encrypt(compressed_data, encrypted_data + (i * 1024), &aes_key);
    }

    // Write the encrypted data to the output file
    fwrite(encrypted_data, sizeof(char) * num_transactions * 1024, 1, output);

    // Free memory allocated for transactions and compressed data
    free(transactions);
    free(compressed_data);
    free(encrypted_data);

    // Close the input and output files
    fclose(input);
    fclose(output);
}
