void process_file(char *input_file, char *output_file, char *rules, int verbose, char *params) {
    // Open the input file for reading
    int fd = open(input_file, O_RDONLY);
    if (fd == -1) {
        perror("Error opening input file");
        return;
    }

    // Open the output file for writing
    int ofd = open(output_file, O_WRONLY | O_CREAT, 0644);
    if (ofd == -1) {
        perror("Error opening output file");
        close(fd);
        return;
    }

