#define MAX_REQUEST_FREQUENCY 60         // 60 requests per minute
#define MIN_REQUEST_FREQUENCY 1          // 1 request per second
#define DEFAULT_REQUEST_FREQUENCY 30     // 30 requests per minute

typedef struct {
    char *dataSourceURL;
    char *apiKey;
    char *dataFormat;
} StreamingDataConfig;

typedef struct {
    int bufferSize;
    int flushInterval;
    int connectionRetries;
    int requestFrequency;
} StreamingDataPipelineConfig;

StreamingDataPipelineConfig getDefaultStreamingDataPipelineConfig() {
    StreamingDataPipelineConfig config = {
        .bufferSize = DEFAULT_BUFFER_SIZE,
        .flushInterval = DEFAULT_FLUSH_INTERVAL,
        .connectionRetries = DEFAULT_CONNECTION_RETRIES,
        .requestFrequency = DEFAULT_REQUEST_FREQUENCY
    };
    return config;
}

StreamingDataPipelineConfig getCustomizedStreamingDataPipelineConfig(StreamingDataConfig *config) {
    StreamingDataPipelineConfig pipelineConfig = getDefaultStreamingDataPipelineConfig();
    if (config->dataSourceURL != NULL) {
        pipelineConfig.bufferSize = MAX_BUFFER_SIZE;
        pipelineConfig.flushInterval = MAX_FLUSH_INTERVAL;
        pipelineConfig.connectionRetries = MAX_CONNECTION_RETRIES;
        pipelineConfig.requestFrequency = MAX_REQUEST_FREQUENCY;
    } else {
        pipelineConfig.bufferSize = MIN_BUFFER_SIZE;
        pipelineConfig.flushInterval = MIN_FLUSH_INTERVAL;
        pipelineConfig.connectionRetries = MIN_CONNECTION_RETRIES;
        pipelineConfig.requestFrequency = MIN_REQUEST_FREQUENCY;
