#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

// Define the configuration structure
typedef struct {
    int modulation_type;
    int bandwidth;
    int cell_identity;
    int transmission_power;
    float snr;
} wireless_config;

// Define the constraints for each parameter
#define MODULATION_TYPE_MIN 0
#define MODULATION_TYPE_MAX 3
#define BANDWIDTH_MIN 1000
#define BANDWIDTH_MAX 50000
#define CELL_IDENTITY_MIN 1
#define CELL_IDENTITY_MAX 256
#define TRANSMISSION_POWER_MIN -30
#define TRANSMISSION_POWER_MAX 30
#define SNR_MIN 0.0
#define SNR_MAX 10.0

// Define the function to initialize the configuration structure
void init_config(wireless_config *config) {
    // Validate inputs and handle errors
    if (config == NULL) {
        printf("Error: config is null\n");
        return;
    }

    // Populate the configuration structure with default values
    config->modulation_type = 0;
    config->bandwidth = 1000;
    config->cell_identity = 1;
    config->transmission_power = -30;
    config->snr = 0.0;

    // Validate and adjust the configuration parameters to meet constraints
    if (config->modulation_type < MODULATION_TYPE_MIN || config->modulation_type > MODULATION_TYPE_MAX) {
        printf("Error: modulation type is out of range\n");
        return;
    }
    if (config->bandwidth < BANDWIDTH_MIN || config->bandwidth > BANDWIDTH_MAX) {
        printf("Error: bandwidth is out of range\n");
        return;
    }
    if (config->cell_identity < CELL_IDENTITY_MIN || config->cell_identity > CELL_IDENTITY_MAX) {
        printf("Error: cell identity is out of range\n");
        return;
    }
    if (config->transmission_power < TRANSMISSION_POWER_MIN || config->transmission_power > TRANSMISSION_POWER_MAX) {
        printf("Error: transmission power is out of range\n");
        return;
    }
    if (config->snr < SNR_MIN || config->snr > SNR_MAX) {
        printf("Error: signal-to-noise ratio is out of range\n");
        return;
    }

    // Log detailed information for debugging and monitoring
    printf("Initialized configuration structure with modulation type %d, bandwidth %d, cell identity %d, transmission power %d, and signal-to-noise ratio %.2f\n", config->modulation_type, config->bandwidth, config->cell_identity, config->transmission_power, config->snr);
}
