void validate_execution_priorities(URL *url) {
    // Validate that execution priorities are valid and unique
    for (int i = 0; i < url->num_plugins; i++) {
        Plugin *plugin = url->plugins[i];
        if (!plugin) {
            continue;
        }
        int priority = plugin->priority;
        if (priority < MIN_EXECUTION_PRIORITY || priority > MAX_EXECUTION_PRIORITY) {
            printf("Error: plugin %d has invalid execution priority\n", i);
            return;
        }
        for (int j = 0; j < url->num_plugins; j++) {
            if (i == j) {
                continue;
            }
            Plugin *other_plugin = url->plugins[j];
            if (!other_plugin) {
                continue;
            }
            int other_priority = other_plugin->priority;
            if (priority == other_priority) {
                printf("Error: plugins %d and %d have duplicate execution priorities\n", i, j);
                return;
            }
        }
    }
