int findLargestInteger(int *array, int size) {
    if (array == NULL || size <= 0) {
        return -1;
    }

    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    return largest;
}

