    if (file == NULL) {
        printf("Error opening file: %s\n", strerror(errno));
        return;
    }

    // Read the current HTML content from the file
    char *current_html = malloc(1024);
    fread(current_html, 1024, 1, file);

    // Close the file
    fclose(file);

    // Update the HTML content based on the provided input
    if (strcmp(current_html, html_content) != 0) {
        handle_http_post(page_section_id, element_id, html_content);
    }

    // Free the memory allocated for the current HTML content
    free(current_html);
}

// Define the function to dynamically modify a given filename's extension by appending a unique numeric identifier and a standardized file type
void modify_filename(char *filename, char *extension) {
    // Get the current timestamp in milliseconds
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    int millisecs = (int)(1000 * difftime(now, mktime(tm)));

    // Generate a unique numeric identifier based on the current timestamp
    char *unique_id = malloc(16);
    sprintf(unique_id, "%d", millisecs);

    // Append the unique numeric identifier and the standardized file type to the filename
    int len = strlen(filename) + strlen(extension) + strlen(unique_id) + 2;
    char *new_filename = malloc(len);
    sprintf(new_filename, "%s-%s.%s", filename, unique_id, extension);

    // Free the memory allocated for the unique numeric identifier and the new filename
    free(unique_id);
    free(new_filename);
}

