    // Check if the data array is full
    if (is_full()) {
        printf("Error: Data array is full\n");
        return;
    }

    // Find the packet in the data array and update it
    int index = find_packet(packet);
    if (index == -1) {
        printf("Error: Packet not found in data array\n");
        return;
    }
    data[index] = packet;
}

// Retrieve a packet from the data array
