    // Check if the data array is empty
    if (is_empty()) {
        printf("Error: Data array is empty\n");
        return NULL;
    }

    // Find the packet in the data array and retrieve it
    int index = find_packet(timestamp);
    if (index == -1) {
        printf("Error: Packet not found in data array\n");
        return NULL;
    }
    return data[index];
}

// Purge packets older than a specified retention period
void purge_packets(int retention_period) {
    // Check if the data array is empty
    if (is_empty()) {
        printf("Error: Data array is empty\n");
        return;
    }

    // Find the oldest packet in the data array and purge it
    int index = find_oldest_packet();
    if (index == -1) {
        printf("Error: Packet not found in data array\n");
