#include <md5.h>

// Define the structure to hold device information
typedef struct {
    char* name;
    double powerConsumption;
    void* sensorCalibration;
} Device;

// Define the structure to hold sensor information
typedef struct {
    Device* device;
    int measurementInterval;
    bool statusIndicator;
} Sensor;

// Define the structure to hold observation information
typedef struct {
    time_t timestamp;
    Sensor* sensor;
    double measurements[];
} Observation;

// Define the function to compute the MD5 hash of a string
unsigned char* md5(const unsigned char* data, size_t len) {
    // Initialize the MD5 context
    MD5_CTX ctx;
    MD5Init(&ctx);

    // Update the MD5 context with the input data
    MD5Update(&ctx, data, len);

    // Finalize the MD5 hash and return it
    unsigned char* hash = (unsigned char*)malloc(MD5_DIGEST_LENGTH);
    MD5Final(hash, &ctx);
    return hash;
}

// Define the function to process a directory of files
void networkDeviceManager(const char* dirPath) {
    // Initialize the file system and memory management structures
    FILE* fp = NULL;
    size_t fileSize = 0;
    time_t creationTime = 0;
    time_t modificationTime = 0;
    unsigned char* hash = NULL;

    // Iterate over the files in the directory
    DIR* dir = opendir(dirPath);
    struct dirent* entry = NULL;
    while ((entry = readdir(dir)) != NULL) {
        // Skip hidden files and directories
        if (strncmp(entry->d_name, ".", 1) == 0 || strncmp(entry->d_name, "..", 2) == 0) {
            continue;
        }

        // Open the file and compute its MD5 hash
        fp = fopen(entry->d_name, "rb");
        if (fp == NULL) {
            perror("fopen");
            continue;
        }
        fileSize = getFileSize(fp);
        creationTime = getFileCreationTime(fp);
        modificationTime = getFileModificationTime(fp);
        hash = md5(fp, fileSize);

        // Close the file and process its metadata
        fclose(fp);
        printf("Original filename: %s\n", entry->d_name);
        printf("Category: ");
        if (isTextFile(hash)) {
            printf("text");
        } else if (isBinaryFile(hash)) {
            printf("binary");
        } else {
            printf("empty");
        }
        printf("\nSize: %zu\n", fileSize);
        printf("Creation time: %s\n", ctime(&creationTime));
        printf("Modification time: %s\n", ctime(&modificationTime));
        free(hash);
    }
}

