// Define configuration structure for wireless communication system
typedef struct {
    int modulation_type;
    int bandwidth;
    int cell_identity;
    int transmission_power;
    float snr;
} wireless_config_t;

// Initialize configuration structure with default values
void initWirelessConfig(wireless_config_t* config) {
    // Set modulation type to QPSK
    config->modulation_type = 0;

    // Set bandwidth to 20 MHz
    config->bandwidth = 20;

    // Set cell identity to 1
    config->cell_identity = 1;

    // Set transmission power to 15 dBm
    config->transmission_power = 15;

    // Set signal-to-noise ratio (SNR) to 20 dB
    config->snr = 20.0f;
}

// Validate configuration structure against predefined constraints
void validateWirelessConfig(wireless_config_t* config) {
    // Check modulation type is valid
    if (config->modulation_type < 0 || config->modulation_type > 3) {
        printf("Invalid modulation type: %d\n", config->modulation_type);
        return;
    }

    // Check bandwidth is valid
    if (config->bandwidth < 10 || config->bandwidth > 40) {
        printf("Invalid bandwidth: %d MHz\n", config->bandwidth);
        return;
    }

    // Check cell identity is valid
    if (config->cell_identity < 1 || config->cell_identity > 65535) {
        printf("Invalid cell identity: %d\n", config->cell_identity);
        return;
    }

    // Check transmission power is valid
    if (config->transmission_power < -40 || config->transmission_power > 20) {
        printf("Invalid transmission power: %d dBm\n", config->transmission_power);
        return;
    }

    // Check signal-to-noise ratio (SNR) is valid
    if (config->snr < -30 || config->snr > 40) {
        printf("Invalid SNR: %f dB\n", config->snr);
        return;
    }
}

// Search for specific book names in the Old Testament using regex
void searchOldTestamentBooks(const char* text, wireless_config_t* config) {
    // Initialize regex pattern for matching book names
    const char* regex = "\\b(?:Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)\\b";

    // Compile regex pattern for matching book names
    regex_t regex_pattern;
    regcomp(&regex_pattern, regex, REG_EXTENDED);

    // Initialize book name count map
    std::map<std::string, int> book_counts;

    // Iterate through text and match book names using regex
    for (const char* p = text; *p != '\0'; ++p) {
        if (regexec(&regex_pattern, p, 1, NULL, 0) == 0) {
            // Get matched book name
            const char* book_name = p + regex_pattern.rm_so;

            // Ignore punctuation and special characters
            while (*book_name != '\0' && !isalpha(*book_name)) {
                ++book_name;
            }

            // Check if matched book name is in the Old Testament
            bool found = false;
            for (int i = 0; i < sizeof(old_testament_books) / sizeof(const char*); ++i) {
                if (strcasecmp(book_name, old_testament_books[i]) == 0) {
                    found = true;
                    break;
                }
            }

            // Increment book name count if matched and in the Old Testament
            if (found) {
                ++book_counts[book_name];
            }
        }
    }

    // Free regex pattern resources
    regfree(&regex_pattern);

    // Print book name counts
    for (const auto& book : book_counts) {
        printf("%s: %d\n", book.first.c_str(), book.second);
    }
}

// Main function to initialize wireless configuration and search for specific book names in the Old Testament
int main() {
    // Initialize wireless configuration structure with default values
    wireless_config_t config;
    initWirelessConfig(&config);

    // Validate wireless configuration against predefined constraints
    validateWirelessConfig(&config);

    // Search for specific book names in the Old Testament using regex
    searchOldTestamentBooks("The Bible is a collection of religious texts that are considered sacred by Christians and Jews.", &config);

    return 0;
}
