        config->bit_rate = MAX_BIT_RATE;
    } else {
        // Adjust the bit rate based on the client device capabilities
        if (client_device_capabilities & DEVICE_CAPABILITY_HIGH_BITRATE) {
            config->bit_rate = MAX_BIT_RATE;
        } else {
            config->bit_rate = MIN_BIT_RATE;
        }
    }

    // Adjust the buffer capacity based on the network condition
    if (network_condition == 1) {
        config->buffer_capacity = MIN_BUFFER_CAPACITY;
    } else if (network_condition == 2) {
        config->buffer_capacity = MAX_BUFFER_CAPACITY;
    } else {
