        if (client_device_capabilities & DEVICE_CAPABILITY_HIGH_BUFFER) {
            config->buffer_capacity = MAX_BUFFER_CAPACITY;
        } else {
            config->buffer_capacity = MIN_BUFFER_CAPACITY;
        }
