        config->qos_settings = MIN_QOS_SETTINGS;
    } else if (network_condition == 2) {
        config->qos_settings = MAX_QOS_SETTINGS;
    } else {
        // Adjust the QoS settings based on the client device capabilities
        if (client_device_capabilities & DEVICE_CAPABILITY_HIGH_QOS) {
            config->qos_settings = MAX_QOS_SETTINGS;
        } else {
            config->qos_settings = MIN_QOS_SETTINGS;
        }
    }
}

// Define the function to log detailed information about each validation step and the final configuration state for debugging and performance tuning purposes
void log_pipeline_config(pipeline_config *config) {
    printf("Pipeline configuration: codec version = %d, frame rate = %f, bit rate = %d, buffer capacity = %d, QoS settings = %d\n", config->codec_version, config->frame_rate, config->bit_rate, config->buffer_capacity, config->qos_settings);
}
