#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define a structure to represent an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a dynamic array to store the structures
NFAPI_CRC_INDICATION_PDU_T* crcIndicationArray = NULL;
int crcIndicationArraySize = 0;

// Function to add a new element to the array
void addElement(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    // Check if the array is NULL and allocate memory for it if necessary
    if (crcIndicationArray == NULL) {
        crcIndicationArray = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        crcIndicationArraySize = 1;
    } else {
        // Reallocate memory for the array to accommodate a new element
        crcIndicationArray = realloc(crcIndicationArray, (crcIndicationArraySize + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        crcIndicationArraySize++;
    }

    // Initialize the new element with the given values
    crcIndicationArray[crcIndicationArraySize - 1].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    crcIndicationArray[crcIndicationArraySize - 1].RNTI = RNTI;
    crcIndicationArray[crcIndicationArraySize - 1].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    crcIndicationArray[crcIndicationArraySize - 1].CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
}

// Function to remove an element from the array by index
void removeElement(int index) {
    if (index < 0 || index >= crcIndicationArraySize) {
        printf("Error: Invalid index\n");
        return;
    }

    // Shift all elements after the specified index to the left
    for (int i = index + 1; i < crcIndicationArraySize; i++) {
        crcIndicationArray[i - 1] = crcIndicationArray[i];
    }

    // Decrement the size of the array and free the last element
    crcIndicationArraySize--;
    free(crcIndicationArray[crcIndicationArraySize]);
}

// Function to update a specific field within an element in the array
void updateField(int index, int field, int value) {
    if (index < 0 || index >= crcIndicationArraySize) {
        printf("Error: Invalid index\n");
        return;
    }

    // Update the specified field with the given value
    switch (field) {
        case RX_UE_INFORMATION_TAG:
            crcIndicationArray[index].RX_UE_INFORMATION_TAG = value;
            break;
        case RNTI:
            crcIndicationArray[index].RNTI = value;
            break;
        case CRC_INDICATION_REL8_TAG:
            crcIndicationArray[index].CRC_INDICATION_REL8_TAG = value;
            break;
        default:
            printf("Error: Invalid field\n");
            return;
    }
}

// Function to print the contents of the array
void printArray() {
    for (int i = 0; i < crcIndicationArraySize; i++) {
        printf("%d, %d, %d, %d\n", crcIndicationArray[i].RX_UE_INFORMATION_TAG, crcIndicationArray[i].RNTI, crcIndicationArray[i].CRC_INDICATION_REL8_TAG, crcIndicationArray[i].CRCFLAG);
    }
}
