// Define the configuration structure
typedef struct {
    int modulation_type;
    int bandwidth;
    int cell_identity;
    int transmission_power;
    float snr;
} wireless_config;

// Define the constraints for each parameter
#define MODULATION_TYPE_MIN 0
#define MODULATION_TYPE_MAX 3
#define BANDWIDTH_MIN 1000
#define BANDWIDTH_MAX 1000000
#define CELL_IDENTITY_MIN 1
#define CELL_IDENTITY_MAX 256
#define TRANSMISSION_POWER_MIN -100
#define TRANSMISSION_POWER_MAX 100
#define SNR_MIN 0.0
#define SNR_MAX 100.0

// Define the error codes for each parameter
#define PARAM_MODULATION_TYPE_ERROR 1
#define PARAM_BANDWIDTH_ERROR 2
#define PARAM_CELL_IDENTITY_ERROR 3
#define PARAM_TRANSMISSION_POWER_ERROR 4
#define PARAM_SNR_ERROR 5

// Define the function to initialize the configuration structure
void init_wireless_config(wireless_config *config) {
    // Initialize the parameters with default values
    config->modulation_type = MODULATION_TYPE_MIN;
    config->bandwidth = BANDWIDTH_MIN;
    config->cell_identity = CELL_IDENTITY_MIN;
    config->transmission_power = TRANSMISSION_POWER_MIN;
    config->snr = SNR_MIN;

    // Validate the parameters against constraints and log detailed information about validation steps
    if (config->modulation_type < MODULATION_TYPE_MIN || config->modulation_type > MODULATION_TYPE_MAX) {
        printf("Error: Modulation type is out of range. Defaulting to %d.\n", MODULATION_TYPE_MIN);
        config->modulation_type = MODULATION_TYPE_MIN;
    }
    if (config->bandwidth < BANDWIDTH_MIN || config->bandwidth > BANDWIDTH_MAX) {
        printf("Error: Bandwidth is out of range. Defaulting to %d.\n", BANDWIDTH_MIN);
        config->bandwidth = BANDWIDTH_MIN;
    }
    if (config->cell_identity < CELL_IDENTITY_MIN || config->cell_identity > CELL_IDENTITY_MAX) {
        printf("Error: Cell identity is out of range. Defaulting to %d.\n", CELL_IDENTITY_MIN);
        config->cell_identity = CELL_IDENTITY_MIN;
    }
    if (config->transmission_power < TRANSMISSION_POWER_MIN || config->transmission_power > TRANSMISSION_POWER_MAX) {
        printf("Error: Transmission power is out of range. Defaulting to %d.\n", TRANSMISSION_POWER_MIN);
        config->transmission_power = TRANSMISSION_POWER_MIN;
    }
    if (config->snr < SNR_MIN || config->snr > SNR_MAX) {
        printf("Error: Signal-to-noise ratio is out of range. Defaulting to %f.\n", SNR_MIN);
        config->snr = SNR_MIN;
    }
}
