// Function to compute the hash of a line in the log file
void compute_hash(char *line, char *hash_function) {
    // Check if the hash function is valid
    if (strcmp(hash_function, "SHA-256") == 0) {
        SHA256_CTX ctx;
        SHA256_Init(&ctx);
        SHA256_Update(&ctx, line, strlen(line));
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256_Final(hash, &ctx);
        printf("Hash: %s\n", hash);
    } else {
        fprintf(stderr, "Invalid hash function specified\n");
    }
}

