void *process_section(void *thread_data) {
    thread_data_t *td = (thread_data_t *)thread_data;
    report_data_t *report_data = td->report_data;
    // Open the input log file and read it line by line
    FILE *input_file = fopen(report_data->input_file, "r");
    if (input_file == NULL) {
        fprintf(stderr, "Error opening input log file\n");
        return NULL;
    }
    // Open the output report file and write the aggregated report to it
    FILE *output_file = fopen(report_data->output_file, "w");
    if (output_file == NULL) {
        fprintf(stderr, "Error opening output report file\n");
        return NULL;
    }
    // Process the input log file line by line and generate an aggregated report
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, input_file)) != -1) {
        process_line(line, report_data);
    }
    // Close the input and output files
    fclose(input_file);
    fclose(output_file);
    return NULL;
