    if (strlen(report_data.processing_params) == 0) {
        fprintf(stderr, "Invalid processing parameters specified\n");
        return 1;
    }
    // Check if the maximum number of threads is valid
    if (report_data.max_threads < 1 || report_data.max_threads > 8) {
        fprintf(stderr, "Invalid maximum number of threads specified\n");
        return 1;
    }
    // Check if the thread scheduling policy is valid
    if (strcmp(report_data.thread_scheduling_policy, "FIFO") != 0 && strcmp(report_data.thread_scheduling_policy, "RR") != 0) {
        fprintf(stderr, "Invalid thread scheduling policy specified\n");
        return 1;
    }
    // Create a pool of threads to process the input log file
    pthread_t *threads = (pthread_t *)malloc(report_data.max_threads * sizeof(pthread_t));
    if (threads == NULL) {
        fprintf(stderr, "Error allocating memory for thread pool\n");
        return 1;
    }
    // Initialize the thread data structure with the report data and thread ID
    thread_data_t *td = (thread_data_t *)malloc(report_data.max_threads * sizeof(thread_data_t));
    if (td == NULL) {
        fprintf(stderr, "Error allocating memory for thread data\n");
        return 1;
    }
    for (int i = 0; i < report_data.max_threads; i++) {
        td[i].thread_id = i;
        td[i].report_data = &report_data;
    }
    // Create the threads and process the input log file
    for (int i = 0; i < report_data.max_threads; i++) {
        pthread_create(&threads[i], NULL, process_file, (void *)&td[i]);
    }
    // Wait for all threads to complete and handle any errors that may have occurred
    for (int i = 0; i < report_data.max_threads; i++) {
        pthread_join(threads[i], NULL);
    }
    // Clean up the memory allocated for the thread pool and thread data
    free(threads);
    free(td);
    return 0;
}
