    while ((file = readdir(dir)) != NULL) {
        // Check if the file is a regular file and not a directory or special file
        if (file->d_type == DT_REG) {
            strcpy(file_path, input_directory);
            strcat(file_path, "/");
            strcat(file_path, file->d_name);
