// Define function to initialize calibration structure
void init_sensor_calibration(sensor_calibration_t *calibration) {
    // Validate input parameters
    if (calibration == NULL) {
        printf("Error: Invalid input parameter\n");
        return;
    }

    // Populate calibration structure with default values
    calibration->temperature_min = 0.0f;
    calibration->temperature_max = 100.0f;
    calibration->humidity_min = 0.0f;
    calibration->humidity_max = 100.0f;
    calibration->pressure_altitude_min = 0.0f;
    calibration->pressure_altitude_max = 10000.0f;
    calibration->air_quality_index_threshold = 50.0f;

    // Validate and adjust parameters based on system dependencies
    if (is_historical_climate_data_available()) {
        // Use historical climate data to adjust temperature range
        float temperature_range = get_temperature_range();
        calibration->temperature_min = temperature_range.min;
        calibration->temperature_max = temperature_range.max;
    }

    // Validate and adjust parameters based on system dependencies
    if (is_pressure_sensor_available()) {
        // Use pressure sensor to adjust pressure altitude range
        float pressure_altitude_range = get_pressure_altitude_range();
        calibration->pressure_altitude_min = pressure_altitude_range.min;
        calibration->pressure_altitude_max = pressure_altitude_range.max;
    }

    // Log detailed information about each validation step and final calibration state
    printf("Calibration initialized with temperature range: [%.1f, %.1f]\n", calibration->temperature_min, calibration->temperature_max);
    printf("Calibration initialized with humidity range: [%.1f, %.1f]\n", calibration->humidity_min, calibration->humidity_max);
    printf("Calibration initialized with pressure altitude range: [%.1f, %.1f]\n", calibration->pressure_altitude_min, calibration->pressure_altitude_max);
