    // Validate temperature range
    if (temperature < calibration->temperature_min || temperature > calibration->temperature_max) {
        printf("Error: Temperature out of range\n");
        return false;
    }

    // Validate humidity range
    if (humidity < calibration->humidity_min || humidity > calibration->humidity_max) {
        printf("Error: Humidity out of range\n");
        return false;
    }

    // Validate pressure altitude range
    if (pressure_altitude < calibration->pressure_altitude_min || pressure_altitude > calibration->pressure_altitude_max) {
        printf("Error: Pressure altitude out of range\n");
        return false;
    }

    // Validate air quality index threshold
    if (air_quality_index < 0.0f || air_quality_index > 100.0f) {
        printf("Error: Air quality index out of range\n");
        return false;
    }

    return true;
}

// Define function to handle potential delays or failures in data acquisition
void handle_data_acquisition_failure(float temperature, float humidity, float pressure_altitude, float air_quality_index) {
    // Handle failure by using previous calibration values as a fallback
    if (temperature == -1.0f || humidity == -1.0f || pressure_altitude == -1.0f || air_quality_index == -1.0f) {
        printf("Warning: Data acquisition failure, using previous calibration values\n");
        temperature = calibration->temperature_min;
        humidity = calibration->humidity_min;
        pressure_altitude = calibration->pressure_altitude_min;
        air_quality_index = calibration->air_quality_index_threshold;
