    }

    if (config->port_number < 0 || config->port_number > 65535) {
        printf("Error: Invalid port number. Must be between 0 and 65535.\n");
        return;
    }

    if (strcmp(config->authentication_method, "none") != 0 && strcmp(config->authentication_method, "basic") != 0) {
        printf("Error: Invalid authentication method. Must be either 'none' or 'basic'.\n");
        return;
    }

    if (strlen(config->server_address) == 0) {
        printf("Error: Invalid server address. Must not be empty.\n");
        return;
