// Define the structure for the wireless communication system configuration
typedef struct {
    char modulation_type[10]; // QPSK, 16QAM, or 64QAM
    float bandwidth;         // in MHz (5-10 range with increments of 0.5)
    int cell_identity;       // positive integer less than 256
    float signal_strength_threshold; // in dBm (-120 to -50 range with increments of 5)
    int channel_frequency;   // positive integer representing a frequency band (e.g., 2400, 5800)
} wireless_config;

// Function to initialize the configuration structure
void init_configuration(wireless_config *config) {
    // Validate modulation type
    if (strcmp(config->modulation_type, "QPSK") != 0 && strcmp(config->modulation_type, "16QAM") != 0 && strcmp(config->modulation_type, "64QAM") != 0) {
        printf("Invalid modulation type. Must be one of QPSK, 16QAM, or 64QAM.\n");
        return;
    }

    // Validate bandwidth
    if (config->bandwidth < 5 || config->bandwidth > 10 || fmod(config->bandwidth, 0.5) != 0) {
        printf("Invalid bandwidth. Must be a value between 5 and 10 MHz in increments of 0.5.\n");
        return;
    }

    // Validate cell identity
    if (config->cell_identity < 0 || config->cell_identity >= 256) {
        printf("Invalid cell identity. Must be a positive integer less than 256.\n");
        return;
    }

    // Validate signal strength threshold
    if (config->signal_strength_threshold < -120 || config->signal_strength_threshold > -50 || fmod(config->signal_strength_threshold, 5) != 0) {
        printf("Invalid signal strength threshold. Must be a value between -120 dBm and -50 dBm in increments of 5.\n");
        return;
    }

    // Validate channel frequency
    if (config->channel_frequency < 0) {
        printf("Invalid channel frequency. Must be a positive integer representing a frequency band.\n");
        return;
    }

    // Check for overlapping channels
    int i, j;
    for (i = 0; i < config->channel_frequency - 1; i++) {
        for (j = i + 1; j < config->channel_frequency; j++) {
            if (abs(config->channel_frequency[i] - config->channel_frequency[j]) <= 5) {
                printf("Overlapping channels detected. Channel %d overlaps with channel %d.\n", i, j);
                return;
            }
        }
    }

    // Log the final configuration state
    printf("Final configuration state:\n");
    printf("Modulation type: %s\n", config->modulation_type);
    printf("Bandwidth: %.1f MHz\n", config->bandwidth);
    printf("Cell identity: %d\n", config->cell_identity);
    printf("Signal strength threshold: %.1f dBm\n", config->signal_strength_threshold);
    printf("Channel frequency: %d MHz\n", config->channel_frequency);
}
