// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to process a directory and generate a report
void process_directory(const char* dirname) {
    // Open the directory
    DIR *dir = opendir(dirname);
    if (dir == NULL) {
        printf("Error opening directory: %s\n", strerror(errno));
        return;
    }

    // Create a list to store the NFAPI structures
    NFAPI_CRC_INDICATION_PDU_T *nfapi_structures = NULL;

    // Iterate over each file in the directory
    struct dirent *file;
    while ((file = readdir(dir)) != NULL) {
        // Skip hidden files and directories
        if (file->d_name[0] == '.') continue;

        // Get the full path of the file
        char* filename = malloc(strlen(dirname) + strlen(file->d_name) + 2);
        sprintf(filename, "%s/%s", dirname, file->d_name);

        // Open the file
        FILE *fp = fopen(filename, "r");
        if (fp == NULL) {
            printf("Error opening file: %s\n", strerror(errno));
            continue;
        }

        // Read the file contents into a buffer
        char* buffer = malloc(1024);
        size_t bytes_read = fread(buffer, 1, 1024, fp);
        if (bytes_read == 0) {
            printf("Error reading file: %s\n", strerror(errno));
            continue;
        }

        // Close the file
        fclose(fp);

        // Extract metadata from the file
        struct stat st;
        if (stat(filename, &st) == -1) {
            printf("Error getting file metadata: %s\n", strerror(errno));
            continue;
        }

        // Create a new NFAPI structure and populate it with the data
        NFAPI_CRC_INDICATION_PDU_T *nfapi_structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        nfapi_structure->rx_ue_information.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        nfapi_structure->crc_indication_rel8.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        nfapi_structure->rx_ue_information.RNTI = 0x1234; // Randomly set the RNTI
        nfapi_structure->crc_indication_rel8.CRCFLAG = 0x5678; // Randomly set the CRCFLAG
        nfapi_structure->rx_ue_information.size = st.st_size;
        nfapi_structure->rx_ue_information.creation_time = st.st_ctime;
        nfapi_structure->rx_ue_information.modification_time = st.st_mtime;

        // Add the NFAPI structure to the list
        nfapi_structures = realloc(nfapi_structures, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (num_files + 1));
        nfapi_structures[num_files++] = nfapi_structure;
    }

    // Close the directory
    closedir(dir);

    // Generate a report for each file in the list
    for (int i = 0; i < num_files; i++) {
        NFAPI_CRC_INDICATION_PDU_T *nfapi_structure = nfapi_structures[i];
        printf("File %d: %s\n", i, filename);
        printf("\tCategory: %s\n", get_category(nfapi_structure));
        printf("\tSize: %lu\n", nfapi_structure->rx_ue_information.size);
        printf("\tCreation Time: %lu\n", nfapi_structure->rx_ue_information.creation_time);
        printf("\tModification Time: %lu\n", nfapi_structure->rx_ue_information.modification_time);
    }

    // Free the memory allocated for the list and the NFAPI structures
    free(nfapi_structures);
}

// Define a function to get the category of a file based on its content type
char* get_category(NFAPI_CRC_INDICATION_PDU_T *nfapi_structure) {
    if (nfapi_structure->rx_ue_information.size == 0) return "empty";
    else if (nfapi_structure->crc_indication_rel8.CRCFLAG == 1) return "binary";
    else return "text";
}
