    time_t creation_time;
    time_t modification_time;
};

// Define the function to process a directory of files
void process_directory(char *directory) {
    // Open the directory and read its contents
    DIR *dir = opendir(directory);
    if (dir == NULL) {
        perror("Error opening directory");
        return;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip over non-file entries and hidden files
        if (!S_ISREG(entry->d_type) || entry->d_name[0] == '.') {
            continue;
        }

        // Get the file information
        struct stat file_info;
        if (stat(entry->d_name, &file_info) < 0) {
            perror("Error getting file information");
            continue;
        }

        // Determine the file type based on extension and size
        char *extension = strrchr(entry->d_name, '.');
        if (extension != NULL && strlen(extension) > 0) {
            if (strcmp(extension, ".txt") == 0 || strcmp(extension, ".text") == 0) {
                struct TextFileInfo *file = malloc(sizeof(struct TextFileInfo));
                file->filename = entry->d_name;
                file->size = file_info.st_size;
                file->creation_time = file_info.st_ctime;
                file->modification_time = file_info.st_mtime;
            } else if (strcmp(extension, ".bin") == 0 || strcmp(extension, ".binary") == 0) {
                struct BinaryFileInfo *file = malloc(sizeof(struct BinaryFileInfo));
                file->filename = entry->d_name;
                file->size = file_info.st_size;
                file->creation_time = file_info.st_ctime;
                file->modification_time = file_info.st_mtime;
            } else {
                struct EmptyFileInfo *file = malloc(sizeof(struct EmptyFileInfo));
                file->filename = entry->d_name;
                file->size = file_info.st_size;
                file->creation_time = file_info.st_ctime;
                file->modification_time = file_info.st_mtime;
            }
        } else {
            struct EmptyFileInfo *file = malloc(sizeof(struct EmptyFileInfo));
            file->filename = entry->d_name;
            file->size = file_info.st_size;
            file->creation_time = file_info.st_ctime;
            file->modification_time = file_info.st_mtime;
        }

        // Add the file to the list of files
        // ...
    }

    // Close the directory
    closedir(dir);
}

// Define the function to generate a report for each file
void generate_report(struct FileInfo *file) {
    printf("File: %s\n", file->filename);
    printf("Category: ");
    if (file->category == TEXT_FILE) {
        printf("Text");
    } else if (file->category == BINARY_FILE) {
        printf("Binary");
    } else {
        printf("Empty");
    }
    printf("\nSize: %lu\n", file->size);
    printf("Creation Time: %s\n", ctime(&file->creation_time));
    printf("Modification Time: %s\n", ctime(&file->modification_time));
}

// Define the function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void create_crc_indication_pdu(struct FileInfo *file) {
    // ...
}
```
