// Define the structure to hold the log entry data
typedef struct {
    char *message;
    time_t timestamp;
} LogEntry;

// Define the structure to hold the aggregated report data
typedef struct {
    int numEntries;
    double totalDuration;
    double averageDuration;
    double medianDuration;
    double maxDuration;
    double minDuration;
} ReportData;

// Define the function to read the log file and parse its contents
void readLogFile(char *logFileName, char *outputReportFileName, char *rulesString, int thresholdValue, bool verboseFlag) {
    // Open the log file for reading
    FILE *logFile = fopen(logFileName, "r");
    if (logFile == NULL) {
        printf("Error: unable to open log file %s\n", logFileName);
        return;
    }

    // Create a semaphore to synchronize access to the log file by multiple threads
    sem_t *sem = sem_open(logFileName, O_CREAT, 0644, 1);
    if (sem == SEM_FAILED) {
        printf("Error: unable to create semaphore for log file %s\n", logFileName);
        fclose(logFile);
        return;
    }

    // Initialize the report data structure
    ReportData *report = (ReportData *)malloc(sizeof(ReportData));
    memset(report, 0, sizeof(ReportData));

    // Parse the rules string and create a list of rule patterns
    char **rulePatterns = parseRulesString(rulesString);
    int numRulePatterns = strlen(rulePatterns);

    // Read each line of the log file and check for matching rule patterns
    while (fgets(line, sizeof(line), logFile) != NULL) {
        // Acquire the semaphore to prevent concurrent access to the log file by multiple threads
        if (sem_wait(sem) == -1) {
            printf("Error: unable to acquire semaphore for log file %s\n", logFileName);
            fclose(logFile);
            return;
        }

        // Parse the current line and check for matching rule patterns
        char *message = parseLine(line, thresholdValue);
        if (message != NULL) {
            // Add the message to the report data structure
            addMessageToReport(report, message);
        }

        // Release the semaphore
        if (sem_post(sem) == -1) {
            printf("Error: unable to release semaphore for log file %s\n", logFileName);
            fclose(logFile);
            return;
        }
    }

    // Close the log file and free the memory allocated for the report data structure
    fclose(logFile);
    free(report);
}

// Define the function to parse the rules string and create a list of rule patterns
char **parseRulesString(char *rulesString) {
    // Split the rules string into individual rule patterns using whitespace as delimiter
    char **rulePatterns = strtok(rulesString, " ");
    int numRulePatterns = strlen(rulePatterns);

    // Create a list of rule patterns by allocating memory for each pattern and copying it from the input string
    for (int i = 0; i < numRulePatterns; i++) {
        char *pattern = malloc(strlen(rulePatterns[i]) + 1);
        strcpy(pattern, rulePatterns[i]);
        rulePatterns[i] = pattern;
    }

    return rulePatterns;
}

// Define the function to parse a single line of the log file and check for matching rule patterns
char *parseLine(char *line, int thresholdValue) {
    // Split the line into individual fields using whitespace as delimiter
    char **fields = strtok(line, " ");
    if (fields == NULL) {
        return NULL;
    }

    // Check each field for a matching rule pattern
    for (int i = 0; i < numRulePatterns; i++) {
        if (strcmp(rulePatterns[i], fields[i]) == 0) {
            // If a match is found, return the message from the line
            char *message = malloc(strlen(line) + 1);
            strcpy(message, line);
            return message;
        }
    }

    return NULL;
}

// Define the function to add a message to the report data structure
void addMessageToReport(ReportData *report, char *message) {
    // Parse the message and extract the duration field
    int duration = parseDuration(message);

    // Update the report data structure with the new duration value
    report->numEntries++;
    report->totalDuration += duration;
    if (duration > report->maxDuration) {
        report->maxDuration = duration;
    } else if (duration < report->minDuration) {
        report->minDuration = duration;
    }
}

// Define the function to parse a single line of the log file and extract the duration field
int parseDuration(char *line) {
    // Split the line into individual fields using whitespace as delimiter
    char **fields = strtok(line, " ");
    if (fields == NULL) {
        return 0;
    }

    // Extract the duration field from the message
    int duration = atoi(fields[2]);

    return duration;
}

// Define the function to generate an aggregated report file based on the given rules and threshold value
void generateReportFile(char *outputReportFileName, ReportData *report) {
    // Open the output report file for writing
    FILE *reportFile = fopen(outputReportFileName, "w");
    if (reportFile == NULL) {
        printf("Error: unable to open output report file %s\n", outputReportFileName);
        return;
    }

    // Write the aggregated report data to the output report file
    fprintf(reportFile, "Total number of entries: %d\n", report->numEntries);
    fprintf(reportFile, "Total duration: %.2f seconds\n", report->totalDuration);
    fprintf(reportFile, "Average duration: %.2f seconds\n", report->averageDuration);
    fprintf(reportFile, "Median duration: %.2f seconds\n", report->medianDuration);
    fprintf(reportFile, "Maximum duration: %.2f seconds\n", report->maxDuration);
    fprintf(reportFile, "Minimum duration: %.2f seconds\n", report->minDuration);

    // Close the output report file
    fclose(reportFile);
}
