#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

// Define the configuration structure
typedef struct {
    int modulation_type; // QPSK, 16QAM, or 64QAM
    float bandwidth; // in MHz, must be between 5 and 10 MHz in increments of 0.5 MHz
    int cell_identity; // positive integer less than 256
    float signal_strength_threshold; // in dBm, must be between -120 and -50 dBm in increments of 5 dBm
    int channel_frequency; // positive integer representing a frequency band (e.g., 2400, 5800)
    float transmit_power; // in dBm, must be within the range of 0 to 30 dBm
    float noise_figure; // positive floating-point number less than or equal to 10.0
} wireless_configuration;

// Define the frequency range for each channel
#define FREQ_RANGE_MIN 2400
#define FREQ_RANGE_MAX 5800
#define FREQ_RANGE_STEP 0.5

// Define the modulation types
#define MODULATION_TYPE_QPSK 1
#define MODULATION_TYPE_16QAM 2
#define MODULATION_TYPE_64QAM 3

// Define the error codes for invalid inputs
#define ERROR_INVALID_MODULATION_TYPE -1
#define ERROR_INVALID_BANDWIDTH -2
#define ERROR_INVALID_CELL_IDENTITY -3
#define ERROR_INVALID_SIGNAL_STRENGTH_THRESHOLD -4
#define ERROR_INVALID_CHANNEL_FREQUENCY -5
#define ERROR_INVALID_TRANSMIT_POWER -6
#define ERROR_INVALID_NOISE_FIGURE -7
#define ERROR_OVERLAPPING_CHANNELS -8

// Define the synchronization mechanism for concurrent modifications
#define SYNC_MECHANISM pthread_mutex_t mutex;

int initialize_configuration(wireless_configuration *config) {
    // Validate the modulation type
    if (config->modulation_type != MODULATION_TYPE_QPSK && config->modulation_type != MODULATION_TYPE_16QAM && config->modulation_type != MODULATION_TYPE_64QAM) {
        return ERROR_INVALID_MODULATION_TYPE;
    }

    // Validate the bandwidth
    if (config->bandwidth < 5 || config->bandwidth > 10 || fmod(config->bandwidth, FREQ_RANGE_STEP) != 0) {
        return ERROR_INVALID_BANDWIDTH;
    }

    // Validate the cell identity
    if (config->cell_identity < 0 || config->cell_identity >= 256) {
        return ERROR_INVALID_CELL_IDENTITY;
    }

    // Validate the signal strength threshold
    if (config->signal_strength_threshold < -120 || config->signal_strength_threshold > -50 || fmod(config->signal_strength_threshold, 5) != 0) {
        return ERROR_INVALID_SIGNAL_STRENGTH_THRESHOLD;
    }

    // Validate the channel frequency
    if (config->channel_frequency < FREQ_RANGE_MIN || config->channel_frequency > FREQ_RANGE_MAX) {
        return ERROR_INVALID_CHANNEL_FREQUENCY;
    }

    // Validate the transmit power
    if (config->transmit_power < 0 || config->transmit_power > 30) {
        return ERROR_INVALID_TRANSMIT_POWER;
    }

    // Validate the noise figure
    if (config->noise_figure < 0 || config->noise_figure > 10.0) {
        return ERROR_INVALID_NOISE_FIGURE;
    }

    // Check for overlapping channels
    int i, j;
    for (i = 0; i < config->cell_identity - 1; i++) {
        for (j = i + 1; j < config->cell_identity; j++) {
            if (config->channel_frequency[i] == config->channel_frequency[j]) {
                return ERROR_OVERLAPPING_CHANNELS;
            }
        }
    }

    // Initialize the configuration structure
    config->modulation_type = MODULATION_TYPE_QPSK;
    config->bandwidth = 5.0;
    config->cell_identity = 1;
    config->signal_strength_threshold = -90.0;
    config->channel_frequency = FREQ_RANGE_MIN;
    config->transmit_power = 0.0;
    config->noise_figure = 5.0;

    // Return success
    return 0;
}

int main() {
    // Declare the configuration structure
    wireless_configuration config;

    // Initialize the configuration structure
    initialize_configuration(&config);

    // Print the configuration structure
    printf("Modulation type: %d\n", config.modulation_type);
    printf("Bandwidth: %.1f MHz\n", config.bandwidth);
    printf("Cell identity: %d\n", config.cell_identity);
    printf("Signal strength threshold: %.1f dBm\n", config.signal_strength_threshold);
    printf("Channel frequency: %d MHz\n", config.channel_frequency);
    printf("Transmit power: %.1f dBm\n", config.transmit_power);
    printf("Noise figure: %.1f\n", config.noise_figure);

    return 0;
}
