// Define a function to validate the filename input parameter
int validateFilename(const char* filename) {
    // Check if the filename is NULL or empty
    if (filename == NULL || strlen(filename) == 0) {
        return 0;
    }
    // Check if the filename contains spaces or special characters
    for (int i = 0; i < strlen(filename); i++) {
        if (!isalnum(filename[i]) && filename[i] != '.') {
            return 0;
        }
    }
    // Check if the filename ends with a valid file type
    if (strchr(filename, '.') == NULL) {
        return 0;
    }
    return 1;
}

// Define a function to validate the directory path input parameter
int validateDirectoryPath(const char* directoryPath) {
    // Check if the directory path is NULL or empty
    if (directoryPath == NULL || strlen(directoryPath) == 0) {
        return 0;
    }
    // Check if the directory path contains spaces or special characters
    for (int i = 0; i < strlen(directoryPath); i++) {
        if (!isalnum(directoryPath[i]) && directoryPath[i] != '/') {
            return 0;
        }
    }
    // Check if the directory path is a valid directory
    DIR* dir = opendir(directoryPath);
    if (dir == NULL) {
        return 0;
    }
    closedir(dir);
    return 1;
}

// Define a function to construct a new filename with a timestamp, a number of digits based on the length of the original filename, and a file type determined by the last character of the filename
char* constructNewFilename(const char* filename, const char* directoryPath) {
    // Get the current time in milliseconds
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp = (long long)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);

    // Get the length of the original filename and construct a new filename with a timestamp and a number of digits based on the length of the original filename
    int len = strlen(filename);
    char* newFilename = malloc(len + 256);
    if (newFilename == NULL) {
        return NULL;
    }
    sprintf(newFilename, "%s_%lld.txt", filename, timestamp);

    // Ensure that the new filename does not exceed a maximum length of 256 characters and handle cases where the filename contains spaces or special characters
    if (strlen(newFilename) > 256) {
        free(newFilename);
        return NULL;
    }
    for (int i = 0; i < strlen(newFilename); i++) {
        if (!isalnum(newFilename[i]) && newFilename[i] != '.') {
            free(newFilename);
            return NULL;
        }
    }

    // Return the constructed new filename
    return newFilename;
}

