    printf("Configuring wireless communication system with modulation type = %d, bandwidth = %d, cell identity = %d, transmission power = %d, signal-to-noise ratio (SNR) = %.1f\n", config.modulationType, config.bandwidth, config.cellIdentity, config.transmissionPower, config.signalToNoiseRatio);
}
