    printf("Record structures: ");
    for (int i = 0; i < num_offsets; i++) {
        printf("{%d} ", records[i].value);
    }
    printf("\n");

    // Free memory allocated for arrays and structures
    free(offsets);
    free(keys);
    free(records);
}
