#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure to represent a task
typedef struct {
    char* name;
    int priority;
    char* status;
} Task;

// Function to dynamically allocate memory for an array of tasks
Task* createTasks(int numTasks) {
    // Check if the number of tasks is positive and not too large
    if (numTasks <= 0 || numTasks > 100000) {
        printf("Invalid input: %d\n", numTasks);
        return NULL;
    }

    // Dynamically allocate memory for the array of tasks
    Task* tasks = malloc(sizeof(Task) * numTasks);
    if (tasks == NULL) {
        printf("Failed to allocate memory for tasks\n");
        return NULL;
    }

    // Initialize the status strings with predefined states
    for (int i = 0; i < numTasks; i++) {
        tasks[i].status = "Pending";
    }

    return tasks;
}

// Function to update the status of a task
void updateTaskStatus(Task* tasks, int index, char* newStatus) {
    // Check if the index is out-of-bounds
    if (index < 0 || index >= numTasks) {
        printf("Invalid index: %d\n", index);
        return;
    }

    // Update the status of the task
    tasks[index].status = newStatus;
}

// Function to print the details of each task in a formatted manner
void printTasks(Task* tasks, int numTasks) {
    for (int i = 0; i < numTasks; i++) {
        printf("Task %d: %s\n", i + 1, tasks[i].name);
        printf("\tPriority: %d\n", tasks[i].priority);
        printf("\tStatus: %s\n", tasks[i].status);
    }
}

// Function to free the memory allocated for the array of tasks
void freeTasks(Task* tasks) {
    // Check if the pointer is NULL
    if (tasks == NULL) {
        return;
    }

    // Free the memory allocated for each task
    for (int i = 0; i < numTasks; i++) {
        free(tasks[i].name);
        tasks[i].name = NULL;
    }

    // Free the memory allocated for the array of tasks
    free(tasks);
}

// Main function to demonstrate the use of the createTasks and updateTaskStatus functions
int main() {
    int numTasks;
    Task* tasks;

    // Get the number of tasks from the user
    printf("Enter the number of tasks: ");
    scanf("%d", &numTasks);

    // Dynamically allocate memory for an array of tasks
    tasks = createTasks(numTasks);

    // Check if the allocation was successful
    if (tasks == NULL) {
        printf("Failed to allocate memory for tasks\n");
        return 1;
    }

    // Initialize the tasks with predefined values
    for (int i = 0; i < numTasks; i++) {
        tasks[i].name = "Task";
        tasks[i].priority = i + 1;
    }

    // Update the status of a task to "In Progress"
    updateTaskStatus(tasks, 2, "In Progress");

    // Print the details of each task in a formatted manner
    printTasks(tasks, numTasks);

    // Free the memory allocated for the array of tasks
    freeTasks(tasks);

    return 0;
}
```
This code defines a structure to represent a task with a name, priority level, and status. It also defines functions to dynamically allocate memory for an array of tasks, update the status of a task, print the details of each task in a formatted manner, and free the memory allocated for the array of tasks. The main function demonstrates the use of these functions by getting the number of tasks from the user, dynamically allocating memory for an array of tasks, initializing the tasks with predefined values, updating the status of a task to "In Progress", printing the details of each task in a formatted manner, and freeing the memory allocated for the array of tasks. The code includes robust error checking for invalid input, including non-positive numbers and excessively large sizes, and handles edge cases gracefully by providing functionality to update the status of a task to a new state based on user input. It also optimizes memory usage and ensures that all allocated memory is properly freed before the function exits.']

