        printf("Invalid number of projects: %d\n", num_projects);
        return NULL;
    }

    // Allocate memory for the array of projects
    Project** projects = malloc(sizeof(Project*) * num_projects);
    if (projects == NULL) {
        printf("Failed to allocate memory for %d projects\n", num_projects);
        return NULL;
    }

    // Initialize each project in the array
    for (int i = 0; i < num_projects; i++) {
        Project* project = malloc(sizeof(Project));
        if (project == NULL) {
            printf("Failed to allocate memory for project %d\n", i);
            return NULL;
        }
        projects[i] = project;
    }

    // Initialize the status strings and start dates
    for (int i = 0; i < num_projects; i++) {
        Project* project = projects[i];
        project->status = malloc(sizeof(char) * 10);
        if (project->status == NULL) {
            printf("Failed to allocate memory for status string of project %d\n", i);
            return NULL;
        }
        strcpy(project->status, "Pending");
        project->start_date = time(NULL);
    }

    return projects;
}

// Function to update the status of a project
void updateStatus(Project* project, char* new_status) {
    // Check if the new status is valid
    if (new_status == NULL || strlen(new_status) > 10) {
        printf("Invalid new status: %s\n", new_status);
        return;
    }

    // Update the status of the project
    free(project->status);
    project->status = malloc(sizeof(char) * (strlen(new_status) + 1));
    if (project->status == NULL) {
        printf("Failed to allocate memory for new status string\n");
        return;
    }
    strcpy(project->status, new_status);
}

// Function to reschedule a project's start date
void rescheduleStartDate(Project* project, time_t new_start_date) {
    // Check if the new start date is valid
    if (new_start_date < 0 || new_start_date > INT_MAX) {
        printf("Invalid new start date: %ld\n", new_start_date);
        return;
    }

    // Update the start date of the project
    project->start_date = new_start_date;
}

// Function to print the details of a project
void printProject(Project* project) {
    printf("Name: %s\n", project->name);
    printf("Priority: %d\n", project->priority);
    printf("Status: %s\n", project->status);
    printf("Start Date: %ld\n", project->start_date);
}

// Function to print the details of all projects in an array
void printProjects(Project** projects, int num_projects) {
    for (int i = 0; i < num_projects; i++) {
        Project* project = projects[i];
        printf("Project %d:\n", i);
        printProject(project);
    }
}

// Function to free the memory allocated for an array of projects
void freeProjects(Project** projects, int num_projects) {
    // Free the status strings and start dates
    for (int i = 0; i < num_projects; i++) {
        Project* project = projects[i];
        free(project->status);
        project->start_date = time(NULL);
    }

    // Free the array of projects
    free(projects);
}

int main(int argc, char** argv) {
    // Check if the number of command-line arguments is valid
    if (argc != 2) {
        printf("Usage: %s <number_of_projects>\n", argv[0]);
        return 1;
    }

    // Convert the number of projects to an integer
    int num_projects = atoi(argv[1]);
    if (num_projects <= 0) {
        printf("Invalid number of projects: %s\n", argv[1]);
        return 1;
    }

    // Dynamically allocate memory for the array of projects
    Project** projects = createProjects(num_projects);
    if (projects == NULL) {
        printf("Failed to allocate memory for %d projects\n", num_projects);
        return 1;
    }

    // Initialize each project in the array
    for (int i = 0; i < num_projects; i++) {
        Project* project = projects[i];
        printf("Initializing project %d...\n", i);
        project->name = malloc(sizeof(char) * 10);
        if (project->name == NULL) {
            printf("Failed to allocate memory for name of project %d\n", i);
            return 1;
        }
        strcpy(project->name, "Project");
        project->priority = i + 1;
    }

    // Print the details of each project
    printf("Projects:\n");
    printProjects(projects, num_projects);

    // Update the status of a project and reschedule its start date
    Project* project = projects[0];
    updateStatus(project, "In Progress");
    rescheduleStartDate(project, time(NULL) + 10 * 24 * 60 * 60);
    printf("Updated status and rescheduled start date of project %d:\n", 0);
    printProject(project);

    // Free the memory allocated for the array of projects
    freeProjects(projects, num_projects);

    return 0;
}
