    uint8_t crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to construct and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
void construct_populate_list(char* input_log_file, char* output_report_file, char* rules, int threshold, bool verbose) {
    // Open the input log file for reading
    FILE* input_log = fopen(input_log_file, "r");
    if (input_log == NULL) {
        printf("Error: unable to open input log file %s\n", input_log_file);
        return;
    }

    // Open the output report file for writing
    FILE* output_report = fopen(output_report_file, "w");
    if (output_report == NULL) {
        printf("Error: unable to open output report file %s\n", output_report_file);
        return;
    }

    // Define the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;

    // Read the input log file and parse its contents for specific patterns
    while (true) {
        // Read a line from the input log file
        char* line = read_line(input_log);
        if (line == NULL) {
            break;
        }

        // Parse the line for specific patterns
        NFAPI_CRC_INDICATION_PDU_T pdu;
        parse_line(line, &pdu);

        // Add the parsed PDU to the list of NFAPI_CRC_INDICATION_PDU_T structures
        add_to_list(&list, &pdu);
    }

    // Generate an aggregated report file based on a set of configurable rules
    generate_report(list, output_report, rules, threshold, verbose);

    // Close the input log file and output report file
    fclose(input_log);
    fclose(output_report);
}

// Define the function to read a line from the input log file
char* read_line(FILE* input_log) {
    char* line = NULL;
    size_t len = 0;
    ssize_t read;

    // Read a line from the input log file
    while ((read = getline(&line, &len, input_log)) != -1) {
        if (strlen(line) > 0) {
            break;
        }
    }

    return line;
}

// Define the function to parse a line for specific patterns
void parse_line(char* line, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Parse the line for the RX_UE_INFORMATION_TAG
    char* token = strtok(line, " ");
    if (token != NULL) {
        pdu->rx_ue_information_tag = atoi(token);
    }

    // Parse the line for the RNTI
    token = strtok(NULL, " ");
    if (token != NULL) {
        pdu->rnti = atoi(token);
    }

    // Parse the line for the CRC_INDICATION_REL8_TAG
    token = strtok(NULL, " ");
    if (token != NULL) {
        pdu->crc_indication_rel8_tag = atoi(token);
    }

    // Parse the line for the CRCFLAG
    token = strtok(NULL, " ");
    if (token != NULL) {
        pdu->crcflag = atoi(token);
    }
}

// Define the function to add a parsed PDU to the list of NFAPI_CRC_INDICATION_PDU_T structures
void add_to_list(NFAPI_CRC_INDICATION_PDU_T** list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Allocate memory for the new PDU
    NFAPI_CRC_INDICATION_PDU_T* new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_pdu == NULL) {
        printf("Error: unable to allocate memory for the new PDU\n");
        return;
    }

    // Copy the parsed PDU to the new PDU
    memcpy(new_pdu, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Add the new PDU to the list of NFAPI_CRC_INDICATION_PDU_T structures
    if (*list == NULL) {
        *list = new_pdu;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* current = *list;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_pdu;
    }
}

// Define the function to generate an aggregated report file based on a set of configurable rules
void generate_report(NFAPI_CRC_INDICATION_PDU_T* list, FILE* output_report, char* rules, int threshold, bool verbose) {
    // Iterate over the list of NFAPI_CRC_INDICATION_PDU_T structures and generate an aggregated report file based on a set of configurable rules
    while (list != NULL) {
        // Check if the PDU meets the filtering criteria
        bool filter = false;
        if (list->rx_ue_information_tag == threshold) {
            filter = true;
        }

        // Generate a report for the PDU based on the filtering criteria
        if (filter) {
            fprintf(output_report, "RX_UE_INFORMATION_TAG: %d\n", list->rx_ue_information_tag);
            fprintf(output_report, "RNTI: %d\n", list->rnti);
            fprintf(output_report, "CRC_INDICATION_REL8_TAG: %d\n", list->crc_indication_rel8_tag);
            fprintf(output_report, "CRCFLAG: %d\n", list->crcflag);
        }

        // Move to the next PDU in the list
        list = list->next;
    }
}
