// Define the structure for a project
typedef struct {
    char* name;
    int priority;
    char* status;
    time_t start_date;
} Project;

// Function to dynamically allocate memory for an array of projects
Project** createProjects(int num_projects) {
    // Check if the number of projects is positive and not too large
    if (num_projects <= 0 || num_projects > 1000000) {
        printf("Invalid number of projects. Must be between 1 and 1,000,000.\n");
        return NULL;
    }

    // Dynamically allocate memory for the array of projects
    Project** projects = (Project**)malloc(num_projects * sizeof(Project*));
    if (!projects) {
        printf("Failed to allocate memory for projects.\n");
        return NULL;
    }

    // Initialize each project structure with default values
    for (int i = 0; i < num_projects; i++) {
        Project* project = (Project*)malloc(sizeof(Project));
        if (!project) {
            printf("Failed to allocate memory for project %d.\n", i);
            return NULL;
        }
        project->name = "";
        project->priority = 0;
        project->status = "Pending";
        project->start_date = time(NULL);
        projects[i] = project;
    }

    // Return the array of projects
    return projects;
}

// Function to update the status of a project
void updateProjectStatus(Project* project, char* new_status) {
    // Check if the new status is valid
    if (strcmp(new_status, "Pending") && strcmp(new_status, "In Progress") && strcmp(new_status, "Completed")) {
        printf("Invalid status. Must be one of Pending, In Progress, or Completed.\n");
        return;
    }

    // Update the project status and log the change
    project->status = new_status;
    printf("Project %s updated to status %s\n", project->name, new_status);
}

// Function to update the start date of a project
void updateProjectStartDate(Project* project, time_t new_start_date) {
    // Check if the new start date is valid
    if (new_start_date < 0 || new_start_date > time(NULL)) {
        printf("Invalid start date. Must be between 1970 and the current time.\n");
        return;
    }

    // Update the project start date and log the change
    project->start_date = new_start_date;
    printf("Project %s updated to start on %s\n", project->name, ctime(&new_start_date));
}

// Function to rollback changes made to a project
void rollbackProjectChanges(Project* project) {
    // Check if the project has been modified
    if (!project->modified) {
        printf("No changes have been made to this project.\n");
        return;
    }

    // Rollback the project status and start date
    project->status = "Pending";
    project->start_date = time(NULL);
    printf("Project %s rolled back to original state\n", project->name);
}

// Function to free all allocated memory for a project array
void freeProjects(Project** projects, int num_projects) {
    // Check if the number of projects is valid
    if (num_projects <= 0 || num_projects > 1000000) {
        printf("Invalid number of projects. Must be between 1 and 1,000,000.\n");
        return;
    }

    // Free each project structure and the array of projects
    for (int i = 0; i < num_projects; i++) {
        free(projects[i]);
    }
    free(projects);
}
