Here is a sample C# application that dynamically loads and initializes game settings from a JSON configuration file, with support for both development and production environments:
```csharp
using System;
using System.IO;
using Newtonsoft.Json;

namespace GameSettings
{
    public class ConfigurationManager
    {
        private readonly string _configFilePath;
        private readonly string _profileName;
        private readonly bool _isDevelopmentEnvironment;

        public ConfigurationManager(string configFilePath, string profileName)
        {
            _configFilePath = configFilePath;
            _profileName = profileName;
            _isDevelopmentEnvironment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") == "Development";
        }

        public void LoadConfiguration()
        {
            // Load the configuration file and deserialize it into a JSON object
            string configJson = File.ReadAllText(_configFilePath);
            dynamic configObject = JsonConvert.DeserializeObject(configJson);

            // Get the profile settings for the current environment
            dynamic profileSettings = configObject[_profileName];

            // Initialize the game settings based on the profile settings
            GameSettings.Instance.Initialize(profileSettings);
        }

        public void ReloadConfiguration()
        {
            // Load the configuration file and deserialize it into a JSON object
            string configJson = File.ReadAllText(_configFilePath);
            dynamic configObject = JsonConvert.DeserializeObject(configJson);

            // Get the profile settings for the current environment
            dynamic profileSettings = configObject[_profileName];

            // Reload the game settings based on the profile settings
            GameSettings.Instance.Reload(profileSettings);
        }
    }
