#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>

#define MAX_DATA_STREAMS 1024
#define MAX_METADATA_SIZE 1024
#define MAX_DEVICE_ID_LEN 64
#define MAX_DATA_TYPE_LEN 32
#define MAX_TIMESTAMP_LEN 64

typedef struct {
    char device_id[MAX_DEVICE_ID_LEN];
    char data_type[MAX_DATA_TYPE_LEN];
    time_t timestamp;
} metadata_t;

typedef struct {
    int fd;
    pthread_mutex_t mutex;
    metadata_t metadata;
} data_stream_t;

data_stream_t data_streams[MAX_DATA_STREAMS];
int num_data_streams = 0;

void init_data_stream(data_stream_t *ds) {
    ds->fd = -1;
    pthread_mutex_init(&ds->mutex, NULL);
}

void close_data_stream(data_stream_t *ds) {
    if (ds->fd != -1) {
        close(ds->fd);
        ds->fd = -1;
    }
    pthread_mutex_destroy(&ds->mutex);
}

int open_data_stream(char *device_id, char *data_type) {
    int i;
    for (i = 0; i < num_data_streams; i++) {
        if (!strcmp(data_streams[i].device_id, device_id) && !strcmp(data_streams[i].data_type, data_type)) {
            return i;
        }
    }
    if (num_data_streams >= MAX_DATA_STREAMS) {
        return -1;
    }
    data_streams[num_data_streams].fd = socket(AF_INET, SOCK_DGRAM, 0);
    strcpy(data_streams[num_data_streams].device_id, device_id);
    strcpy(data_streams[num_data_streams].data_type, data_type);
    pthread_mutex_init(&data_streams[num_data_streams].mutex, NULL);
    num_data_streams++;
    return num_data_streams - 1;
}

int read_data(char *device_id, char *data_type) {
    int i = open_data_stream(device_id, data_type);
    if (i == -1) {
        return -1;
    }
    pthread_mutex_lock(&data_streams[i].mutex);
    ssize_t n = recvfrom(data_streams[i].fd, &data_streams[i].metadata, MAX_METADATA_SIZE, 0, NULL, NULL);
    if (n == -1) {
        perror("recvfrom");
        pthread_mutex_unlock(&data_streams[i].mutex);
        return -1;
    }
    data_streams[i].metadata.timestamp = time(NULL);
    pthread_mutex_unlock(&data_streams[i].mutex);
    return 0;
}

int write_data(char *device_id, char *data_type) {
    int i = open_data_stream(device_id, data_type);
    if (i == -1) {
        return -1;
    }
    pthread_mutex_lock(&data_streams[i].mutex);
    ssize_t n = sendto(data_streams[i].fd, &data_streams[i].metadata, MAX_METADATA_SIZE, 0, NULL, NULL);
    if (n == -1) {
        perror("sendto");
        pthread_mutex_unlock(&data_streams[i].mutex);
        return -1;
    }
    data_streams[i].metadata.timestamp = time(NULL);
    pthread_mutex_unlock(&data_streams[i].mutex);
    return 0;
}

void generate_report(char *device_id, char *data_type) {
    int i = open_data_stream(device_id, data_type);
    if (i == -1) {
        printf("Device %s with data type %s not found\n", device_id, data_type);
        return;
    }
    pthread_mutex_lock(&data_streams[i].mutex);
    printf("Original Device ID: %s\n", data_streams[i].device_id);
    printf("Category: %s\n", data_type);
    printf("Timestamp: %lu\n", (unsigned long)data_streams[i].metadata.timestamp);
    printf("Data Type: %s\n", data_streams[i].data_type);
    pthread_mutex_unlock(&data_streams[i].mutex);
}

void close_all_data_streams() {
    int i;
    for (i = 0; i < num_data_streams; i++) {
        close_data_stream(&data_streams[i]);
    }
    num_data_streams = 0;
}

int main(int argc, char *argv[]) {
    int c;
    while ((c = getopt(argc, argv, "d:t:")) != -1) {
        switch (c) {
            case 'd':
                read_data(optarg, "operational");
                break;
            case 't':
                write_data(optarg, "diagnostic");
                break;
            default:
                printf("Usage: %s [-d device_id] [-t device_id]\n", argv[0]);
                return 1;
        }
    }
    generate_report("device_id", "operational");
    generate_report("device_id", "diagnostic");
    close_all_data_streams();
    return 0;
}']

