using System;
using System.IO;
using System.Xml;

class Program
{
    static void Main(string[] args)
    {
        // Check if the input file exists and is a binary file
        if (!File.Exists(args[0]) || !File.GetAttributes(args[0]).HasFlag(FileAttributes.Archive))
        {
            Console.WriteLine("Input file does not exist or is not a binary file.");
            return;
        }

        // Check if the output file exists and is a text file
        if (File.Exists(args[1]) && !File.GetAttributes(args[1]).HasFlag(FileAttributes.Archive))
        {
            Console.WriteLine("Output file already exists and is not a text file.");
            return;
        }

        // Load configuration settings from an XML file
        XmlDocument config = new XmlDocument();
        config.Load("config.xml");

        // Get the size of a tile, dimensions of a world, and speed of a camera from the configuration file
        int tileSize = Convert.ToInt32(config.SelectSingleNode("/configuration/tileSize").InnerText);
        int[] worldDimensions = new int[2];
        worldDimensions[0] = Convert.ToInt32(config.SelectSingleNode("/configuration/worldDimensions/width").InnerText);
        worldDimensions[1] = Convert.ToInt32(config.SelectSingleNode("/configuration/worldDimensions/height").InnerText);
        int cameraSpeed = Convert.ToInt32(config.SelectSingleNode("/configuration/cameraSpeed").InnerText);

        // Read the input binary file and parse its contents
        byte[] data = File.ReadAllBytes(args[0]);
        MemoryStream stream = new MemoryStream(data);
        BinaryReader reader = new BinaryReader(stream);

        // Transform the parsed contents based on the set of transformation rules
        string transformedData = "";
        for (int i = 0; i < data.Length; i += tileSize)
        {
            int[] coordinates = new int[2];
            coordinates[0] = i % worldDimensions[0];
            coordinates[1] = i / worldDimensions[0];

            // Apply transformation rules to the current tile
            for (int j = 0; j < cameraSpeed; j++)
            {
                if (coordinates[0] + j >= worldDimensions[0])
                {
                    coordinates[0] -= j;
                }
                else if (coordinates[1] + j >= worldDimensions[1])
                {
                    coordinates[1] -= j;
                }
            }

            // Add the transformed tile to the output file
            transformedData += "Tile at (" + coordinates[0] + ", " + coordinates[1] + ") is: ";
            for (int k = 0; k < tileSize; k++)
            {
                transformedData += reader.ReadByte().ToString() + " ";
            }
            transformedData += "\n";
        }

        // Write the transformed contents to the output file
        File.WriteAllText(args[1], transformedData);
    }
}
