// Function to read a large binary file
int read_file(const char* filename, void** buffer, size_t* size) {
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        printf("Error: Could not open input file %s\n", filename);
        return -1;
    }

    // Get the file size
    fseek(fp, 0, SEEK_END);
    long int file_size = ftell(fp);
    rewind(fp);

    // Check if the file is too large
    if (file_size > 1073741824) { // 1 GB in bytes
        printf("Error: Input file is too large (%ld bytes)\n", file_size);
        fclose(fp);
        return -1;
    }

    // Allocate memory for the buffer
    *buffer = malloc(file_size);
    if (*buffer == NULL) {
        printf("Error: Could not allocate memory for input file\n");
        fclose(fp);
        return -1;
    }

    // Read the entire file into the buffer
    size_t bytes_read = fread(*buffer, 1, file_size, fp);
    if (bytes_read < file_size) {
        printf("Error: Could not read entire input file\n");
        free(*buffer);
        *buffer = NULL;
        fclose(fp);
        return -1;
    }

    // Close the file
    fclose(fp);

    // Set the size of the buffer
    *size = bytes_read;

    return 0;
}

