        }
        if (strcmp(ext, ".txt") == 0) {
            // Text file
            totalSize += st.st_size;
        } else if (strcmp(ext, ".bin") == 0) {
            // Binary file
            totalSize += st.st_size;
        } else {
            // Empty file
            continue;
        }
    }

    // Close the directory
    closedir(dir);

    // Check if the disk space usage is within the predefined threshold
