    if (statvfs(mmFilePath, &fsStat) < 0) {
        perror("Error: Failed to retrieve file system statistics");
        return;
    }
    freeSpace = fsStat.f_bavail * fsStat.f_bsize;
    usedSpace = totalSize - freeSpace;
    if (usedSpace > 0.8 * totalSize) {
        // Prioritize deleting the oldest serialized records or archive less frequently used data
        printf("Warning: Disk space usage is high, prioritizing deletion of older records\n");
