    // Initialize the shared calibration structure
    Calibration* calibration = (Calibration*)mmap(NULL, sizeof(Calibration), PROT_READ | PROT_WRITE, MAP_SHARED, mmFilePath, 0);
    if (calibration == NULL) {
        perror("Error: Failed to initialize shared calibration structure");
        return;
    }

    // Initialize the array of devices and sensors
    Device* devices = (Device*)malloc(sizeof(Device) * 100);
    Sensor* sensors = (Sensor*)malloc(sizeof(Sensor) * 100);
    int numDevices = 0;
    int numSensors = 0;

    // Process each file in the directory
    dir = opendir(dirPath);
    while ((entry = readdir(dir)) != NULL) {
        // Skip hidden files and directories
        if (strncmp(entry->d_name, ".", 1) == 0 || strncmp(entry->d_name, "..", 2) == 0) {
            continue;
        }

        // Process the file metadata
        struct stat st;
        if (stat(entry->d_name, &st) < 0) {
