            continue;
        }

        // Determine the file type based on its extension
        char* ext = strrchr(entry->d_name, '.');
        if (ext == NULL) {
            continue;
        }
        if (strcmp(ext, ".txt") == 0) {
            // Text file
            totalSize += st.st_size;
        } else if (strcmp(ext, ".bin") == 0) {
            // Binary file
            totalSize += st.st_size;
        } else {
            // Empty file
            continue;
        }

        // Open the file and read its contents
        int fd = open(entry->d_name, O_RDONLY);
        if (fd < 0) {
            perror("Error: Failed to open file");
            continue;
        }
        char* buffer = (char*)malloc(st.st_size + 1);
        read(fd, buffer, st.st_size);
        close(fd);

        // Process the file contents based on its type
        if (strcmp(ext, ".txt") == 0) {
            // Text file
            char* line = strtok(buffer, "\n");
            while (line != NULL) {
                // Parse the line and extract the device name and power consumption value
                char* deviceName = strtok(line, " ");
                double powerConsumption = atof(strtok(NULL, " "));
                Device* device = (Device*)malloc(sizeof(Device));
                device->name = deviceName;
                device->powerConsumption = powerConsumption;
                devices[numDevices++] = *device;
            }
        } else if (strcmp(ext, ".bin") == 0) {
            // Binary file
            Observation* observation = (Observation*)malloc(sizeof(Observation));
            observation->timestamp = time(NULL);
            observation->sensorData = buffer;
            calibration->measurementInterval = 10;
            calibration->threshold = 0.5;
        } else {
            // Empty file
            continue;
        }
    }

    // Close the directory
    closedir(dir);

    // Initialize the array of observations and the tree of observation nodes
    Observation* observations = (Observation*)malloc(sizeof(Observation) * 100);
    int numObservations = 0;
    ObservationNode* root = NULL;

    // Process each device and sensor in the array
    for (int i = 0; i < numDevices; i++) {
        Device* device = &devices[i];
        Sensor* sensor = (Sensor*)malloc(sizeof(Sensor));
        sensor->id = i;
        sensor->measurementInterval = calibration->measurementInterval;
        sensor->statusIndicator = 0;
        sensors[numSensors++] = *sensor;

        // Create a new observation node for the device and add it to the tree
        ObservationNode* node = (ObservationNode*)malloc(sizeof(ObservationNode));
        node->timestamp = time(NULL);
        node->sensorData = NULL;
        node->next = root;
        root = node;
    }

    // Serialize the observations and store them in a memory-mapped file
    FILE* mmFile = fopen(mmFilePath, "wb");
    if (mmFile == NULL) {
        perror("Error: Failed to open memory-mapped file for writing");
        return;
    }
    for (int i = 0; i < numObservations; i++) {
        Observation* observation = &observations[i];
        fwrite(observation, sizeof(Observation), 1, mmFile);
    }
    fclose(mmFile);

    // Clean up the memory allocated for the devices and sensors
    free(devices);
    free(sensors);
}
