    if (signal_strength_threshold < -150 || signal_strength_threshold > -30) {
        printf("Invalid signal strength threshold: %d dBm\n", signal_strength_threshold);
        return;
    }

    // Populate configuration structure with given parameters
    config->modulation = modulation;
    config->bandwidth = bandwidth;
    config->cell_id = cell_id;
    config->signal_strength_threshold = signal_strength_threshold;

    // Log detailed information about each validation step and final configuration state for debugging and monitoring purposes
    printf("Initialized wireless configuration:\n");
    printf("  Modulation type: %s\n", get_modulation_string(config->modulation));
    printf("  Bandwidth: %u MHz\n", config->bandwidth);
    printf("  Cell identity: %d\n", config->cell_id);
    printf("  Signal strength threshold: %d dBm\n", config->signal_strength_threshold);
}

// Check if a given value is a power of two
bool is_power_of_two(uint32_t x) {
    return (x != 0) && ((x & (x - 1)) == 0);
}

// Get string representation of modulation type
const char* get_modulation_string(uint8_t modulation) {
    switch (modulation) {
        case QPSK: return "QPSK";
        case 16QAM: return "16QAM";
        case 64QAM: return "64QAM";
        default: return "Unknown";
    }
}
