// Define the structure for network interface configuration
typedef struct {
    int data_rate; // Data rate in Mbps
    int buffer_size; // Buffer size in bytes
    int priority_level; // Priority level (0-10)
} netif_config_t;

// Define the constraints for each parameter
#define DATA_RATE_MIN 100
#define DATA_RATE_MAX 10000
#define BUFFER_SIZE_MIN 1024
#define BUFFER_SIZE_MAX 16777216
#define PRIORITY_LEVEL_MIN 0
#define PRIORITY_LEVEL_MAX 10

// Function to initialize the network interface configuration structure
int init_netif_config(netif_config_t *config) {
    // Check if the input parameters are valid
    if (config == NULL) {
        printf("Error: Invalid input parameter\n");
        return -1;
    }

    // Set default values for each parameter
    config->data_rate = 1000;
    config->buffer_size = 8192;
    config->priority_level = 5;

    // Validate the input parameters and adjust if necessary
    if (config->data_rate < DATA_RATE_MIN || config->data_rate > DATA_RATE_MAX) {
        printf("Warning: Data rate out of range, using default value\n");
        config->data_rate = 1000;
    }
    if (config->buffer_size < BUFFER_SIZE_MIN || config->buffer_size > BUFFER_SIZE_MAX) {
        printf("Warning: Buffer size out of range, using default value\n");
        config->buffer_size = 8192;
    }
    if (config->priority_level < PRIORITY_LEVEL_MIN || config->priority_level > PRIORITY_LEVEL_MAX) {
        printf("Warning: Priority level out of range, using default value\n");
        config->priority_level = 5;
    }

    // Log the final configuration state for debugging and monitoring purposes
    printf("Final network interface configuration:\n");
    printf("Data rate: %d Mbps\n", config->data_rate);
    printf("Buffer size: %d bytes\n", config->buffer_size);
    printf("Priority level: %d\n", config->priority_level);

    return 0;
}
```
