#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

void process_directory(char* directory) {
    DIR *dir;
    struct dirent *ent;
    char* file_name;
    char* new_file_name;
    int file_size;
    int fd;
    int i = 0;
    int j = 0;
    int k = 0;
    int l = 0;
    int m = 0;
    int n = 0;
    char* extension;
    char* mime_type;
    char* size;
    char* error_message;
    FILE *log_file;

    // Open the directory and iterate through its files
    dir = opendir(directory);
    while ((ent = readdir(dir)) != NULL) {
        file_name = ent->d_name;
        fd = open(file_name, O_RDONLY);
        if (fd == -1) {
            error_message = "Error opening file";
            log_file = fopen("error.log", "a");
            fprintf(log_file, "%s: %s\n", file_name, error_message);
            fclose(log_file);
        } else {
            // Read the file and determine its content type
            file_size = lseek(fd, 0, SEEK_END);
            lseek(fd, 0, SEEK_SET);
            extension = strrchr(file_name, '.');
            if (extension != NULL) {
                mime_type = get_mime_type(extension);
            } else {
                mime_type = "application/octet-stream";
            }

            // Rename the file and append its MIME type and size in bytes
            new_file_name = malloc(strlen(file_name) + strlen(mime_type) + 10);
            sprintf(new_file_name, "%s.%s", file_name, mime_type);
            rename(file_name, new_file_name);

            // Check if the file is text or binary based on its content
            for (i = 0; i < file_size; i++) {
                char c = read(fd, &c, 1);
                if (isprint(c)) {
                    j++;
                } else {
                    k++;
                }
            }
            close(fd);
            if (j > k) {
                // File is text
                m = 0;
            } else if (k > j) {
                // File is binary
                m = 1;
            } else {
                // File is unknown
                m = 2;
            }

            // Append the MIME type and size in bytes to the file name
            sprintf(new_file_name, "%s.%s (%d bytes)", new_file_name, mime_type, file_size);

            // Check if the new file name is unique within the directory
            for (l = 0; l < i; l++) {
                if (!strcmp(new_file_name, ent[l].d_name)) {
                    n++;
                }
            }
            if (n > 0) {
                // File name is not unique, append a numeric counter
                sprintf(new_file_name, "%s.%s (%d bytes)", new_file_name, mime_type, file_size);
            }
        }
    }
    closedir(dir);
}

// Get the MIME type of a file based on its extension
char* get_mime_type(char* extension) {
    char* mime_type;
    if (!strcmp(extension, ".txt")) {
        mime_type = "text/plain";
    } else if (!strcmp(extension, ".pdf")) {
        mime_type = "application/pdf";
    } else if (!strcmp(extension, ".jpg")) {
        mime_type = "image/jpeg";
    } else if (!strcmp(extension, ".png")) {
        mime_type = "image/png";
    } else {
        mime_type = "application/octet-stream";
    }
    return mime_type;
}
