// cache structure for storing resolved IP addresses
struct cache {
    char *hostname;
    struct in_addr ip_address;
    time_t expiration_time;
};

// array of cached hostnames and their corresponding IP addresses
static struct cache *cache[MAX_CACHE_SIZE];

// mutex for protecting the cache from concurrent access
static pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;

// function to perform DNS resolution and return the IP address in a u_char array
u_char *dns_resolve(const char *hostname) {
    // check if the hostname is already cached
    struct cache *cached = NULL;
    pthread_mutex_lock(&cache_mutex);
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        if (cache[i] != NULL && strcmp(hostname, cache[i]->hostname) == 0) {
            cached = cache[i];
            break;
        }
    }
    pthread_mutex_unlock(&cache_mutex);

    // if the hostname is already cached, return the IP address
    if (cached != NULL) {
        return (u_char *)&(cached->ip_address.s_addr);
    }

    // otherwise, perform DNS resolution and cache the result
    struct addrinfo hints;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_DGRAM;
    hints.ai_protocol = IPPROTO_UDP;

    struct addrinfo *result;
    int rc = getaddrinfo(hostname, NULL, &hints, &result);
    if (rc != 0) {
        return NULL;
    }

    // cache the resolved IP address and expiration time
    pthread_mutex_lock(&cache_mutex);
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        if (cache[i] == NULL) {
            cache[i] = malloc(sizeof(struct cache));
            cache[i]->hostname = strdup(hostname);
            cache[i]->ip_address.s_addr = ((struct sockaddr_in *)result->ai_addr)->sin_addr.s_addr;
            cache[i]->expiration_time = time(NULL) + CACHE_EXPIRATION_TIME;
            break;
        }
    }
    pthread_mutex_unlock(&cache_mutex);

    freeaddrinfo(result);

    return (u_char *)&(cache[i]->ip_address.s_addr);
}

// function to handle DNSSEC validation failures and return the IP address in a u_char array
u_char *dnssec_validate(const char *hostname) {
    // perform DNS resolution and cache the result
    struct addrinfo hints;
    memset(&hints, 0, sizeof(struct addrinfo));
