// cache management functions
void cache_init(struct cache **cache) {
    // initialize the cache with an empty list of entries
    *cache = malloc(sizeof(struct cache));
    (*cache)->hostname = NULL;
    (*cache)->ip_address.s_addr = 0;
    (*cache)->expiration_time = 0;
}

void cache_add(struct cache **cache, char *hostname, struct in_addr ip_address) {
    // add a new entry to the cache with the given hostname and IP address
    if ((*cache)->hostname == NULL) {
        (*cache)->hostname = malloc(strlen(hostname) + 1);
        strcpy((*cache)->hostname, hostname);
        (*cache)->ip_address.s_addr = ip_address.s_addr;
        (*cache)->expiration_time = time(NULL) + CACHE_EXPIRATION_TIME;
    } else {
        // check if the entry already exists in the cache
        struct cache *entry = (*cache);
        while (entry != NULL) {
            if (strcmp(hostname, entry->hostname) == 0) {
                entry->ip_address.s_addr = ip_address.s_addr;
                entry->expiration_time = time(NULL) + CACHE_EXPIRATION_TIME;
                return;
            }
            entry = entry->next;
        }
        // add a new entry to the cache if it doesn't already exist
        struct cache *new_entry = malloc(sizeof(struct cache));
        new_entry->hostname = malloc(strlen(hostname) + 1);
        strcpy(new_entry->hostname, hostname);
        new_entry->ip_address.s_addr = ip_address.s_addr;
        new_entry->expiration_time = time(NULL) + CACHE_EXPIRATION_TIME;
        new_entry->next = (*cache)->next;
        (*cache)->next = new_entry;
    }
}

void cache_remove(struct cache **cache, char *hostname) {
    // remove an entry from the cache with the given hostname
    if ((*cache)->hostname == NULL) {
        return;
    } else {
        struct cache *entry = (*cache);
        while (entry != NULL) {
            if (strcmp(hostname, entry->hostname) == 0) {
                free(entry->hostname);
                entry->hostname = NULL;
                entry->ip_address.s_addr = 0;
                entry->expiration_time = 0;
                return;
            }
            entry = entry->next;
        }
    }
}

void cache_clear(struct cache **cache) {
    // clear the cache of all entries
    if ((*cache)->hostname == NULL) {
        return;
    } else {
        struct cache *entry = (*cache);
        while (entry != NULL) {
            free(entry->hostname);
            entry->hostname = NULL;
            entry->ip_address.s_addr = 0;
            entry->expiration_time = 0;
            entry = entry->next;
        }
    }
}

// rate limiting functions
void rate_limit(struct cache **cache, char *hostname) {
    // check if the query is within the rate limit threshold
    struct cache *entry = (*cache);
    while (entry != NULL) {
        if (strcmp(hostname, entry->hostname) == 0) {
            time_t current_time = time(NULL);
            if ((current_time - entry->expiration_time) < RATE_LIMIT_THRESHOLD) {
                // rate limit exceeded, return an error code
                return;
            } else {
                // update the expiration time for the entry
                entry->expiration_time = current_time + CACHE_EXPIRATION_TIME;
                break;
            }
        }
        entry = entry->next;
    }
}

