    config->order_book_depth = 5;
    config->trade_execution_priority_levels = 3;
}

// Define the function to validate the network configuration parameters
void validateNetworkConfig(NetworkConfig *config) {
    // Validate market data source
    if (strcmp(config->market_data_source, "NYSE") && strcmp(config->market_data_source, "NASDAQ")) {
        printf("Invalid market data source. Using default value: NYSE\n");
        config->market_data_source = "NYSE";
    }

    // Validate latency tolerance
    if (config->latency_tolerance < 0 || config->latency_tolerance > 1000) {
        printf("Invalid latency tolerance. Using default value: 100\n");
        config->latency_tolerance = 100;
