    // Validate execution strategy
    if (strcmp(config->execution_strategy, "MarketMaker") && strcmp(config->execution_strategy, "HighFrequencyTrader")) {
        printf("Invalid execution strategy. Using default value: MarketMaker\n");
        config->execution_strategy = "MarketMaker";
    }

    // Validate order book depth
    if (config->order_book_depth < 0 || config->order_book_depth > 10) {
        printf("Invalid order book depth. Using default value: 5\n");
        config->order_book_depth = 5;
    }

    // Validate trade execution priority levels
    if (config->trade_execution_priority_levels < 0 || config->trade_execution_priority_levels > 10) {
        printf("Invalid trade execution priority levels. Using default value: 3\n");
        config->trade_execution_priority_levels = 3;
