#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>

struct connection {
    int fd;
    struct sockaddr_in addr;
};

struct connection_pool {
    int size;
    int max_size;
    int idle_timeout;
    pthread_mutex_t mutex;
    struct connection *connections;
};

void init_connection_pool(struct connection_pool *pool, int max_size, int idle_timeout) {
    pool->max_size = max_size;
    pool->idle_timeout = idle_timeout;
    pool->size = 0;
    pool->connections = malloc(sizeof(struct connection) * max_size);
    pthread_mutex_init(&pool->mutex, NULL);
}

void destroy_connection_pool(struct connection_pool *pool) {
    for (int i = 0; i < pool->size; i++) {
        close(pool->connections[i].fd);
    }
    free(pool->connections);
    pthread_mutex_destroy(&pool->mutex);
}

struct connection *get_connection(struct connection_pool *pool) {
    struct connection *conn = NULL;
    pthread_mutex_lock(&pool->mutex);
    if (pool->size > 0) {
        conn = &pool->connections[--pool->size];
    } else {
        int fd = socket(AF_INET, SOCK_STREAM, 0);
        struct sockaddr_in addr;
        memset(&addr, 0, sizeof(struct sockaddr_in));
        addr.sin_family = AF_INET;
        addr.sin_port = htons(80);
        inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);
        if (connect(fd, (struct sockaddr *)&addr, sizeof(struct sockaddr_in)) < 0) {
            perror("connect");
            close(fd);
            return NULL;
        }
        conn = malloc(sizeof(struct connection));
        conn->fd = fd;
        conn->addr = addr;
    }
    pthread_mutex_unlock(&pool->mutex);
    return conn;
}

void release_connection(struct connection_pool *pool, struct connection *conn) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->size < pool->max_size) {
        pool->connections[pool->size++] = conn;
    } else {
        close(conn->fd);
        free(conn);
    }
    pthread_mutex_unlock(&pool->mutex);
}
