u_char* dnsAndEncrypt(const char* hostname, const char* password) {
    // Resolve the hostname using standard library functions
    struct addrinfo hints;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = IPPROTO_TCP;

    struct addrinfo* result;
    if (getaddrinfo(hostname, NULL, &hints, &result) != 0) {
        printf("Failed to resolve hostname\n");
        return NULL;
    }

    // Initialize the AES-256-CBC cipher context using OpenSSL library
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        printf("Failed to initialize cipher context\n");
        return NULL;
    }

    // Set the IV length and key length to fixed values
    int iv_len = 16;
    int key_len = 32;

    // Derive the encryption key from the password using SHA-1 hash function
    unsigned char key[key_len];
    SHA1(password, strlen(password), key);

    // Securely store the derived key and ensure its proper disposal when no longer needed
    EVP_CIPHER_CTX_set_key_length(ctx, key_len);
    EVP_CIPHER_CTX_set_key(ctx, key, key_len);

    // Limit the capabilities of the process by restricting the use of the function to authorized contexts only
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL)) {
        printf("Failed to initialize encryption\n");
        return NULL;
    }

    // Cleanup mechanisms to disable the cipher and release resources when done
    if (!EVP_EncryptFinal_ex(ctx, NULL, NULL)) {
        printf("Failed to finalize encryption\n");
        return NULL;
    }

    EVP_CIPHER_CTX_free(ctx);

    // Return the resolved IP address in a u_char array
    struct addrinfo* current = result;
    while (current != NULL) {
        if (current->ai_family == AF_INET) {
            return (u_char*)&((struct sockaddr_in*)current->ai_addr)->sin_addr.s_addr;
        }
        current = current->ai_next;
    }

    // Return NULL if no IPv4 address is found
    return NULL;
}
