#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

// Define the configuration structure
typedef struct {
    int modulation_type; // Modulation type (e.g., QPSK, OFDM)
    float bandwidth; // Bandwidth in MHz
    char cell_identity[16]; // Cell identity string
    int transmission_power; // Transmission power in dBm
    float snr; // Signal-to-noise ratio (SNR) in dB
} wireless_config_t;

// Define the constraints for each parameter
#define MODULATION_TYPE_MIN 0
#define MODULATION_TYPE_MAX 2
#define BANDWIDTH_MIN 10.0f
#define BANDWIDTH_MAX 80.0f
#define CELL_IDENTITY_LEN 16
#define TRANSMISSION_POWER_MIN -30
#define TRANSMISSION_POWER_MAX 20
#define SNR_MIN -5.0f
#define SNR_MAX 20.0f

// Define the error codes for each validation step
#define VALIDATION_OK 0
#define VALIDATION_ERROR_MODULATION_TYPE 1
#define VALIDATION_ERROR_BANDWIDTH 2
#define VALIDATION_ERROR_CELL_IDENTITY 3
#define VALIDATION_ERROR_TRANSMISSION_POWER 4
#define VALIDATION_ERROR_SNR 5

// Define the logging function for detailed information about each validation step and final configuration state
void log_validation(int validation_result, wireless_config_t *config) {
    if (validation_result == VALIDATION_OK) {
        printf("Validation successful: %d\n", validation_result);
    } else {
        printf("Validation failed: %d\n", validation_result);
    }
    printf("Configuration state:\n");
    printf("  Modulation type: %d\n", config->modulation_type);
    printf("  Bandwidth: %.2f MHz\n", config->bandwidth);
    printf("  Cell identity: %s\n", config->cell_identity);
    printf("  Transmission power: %d dBm\n", config->transmission_power);
    printf("  Signal-to-noise ratio (SNR): %.2f dB\n", config->snr);
}

// Define the function for initializing the configuration structure
int initialize_configuration(wireless_config_t *config, int modulation_type, float bandwidth, char *cell_identity, int transmission_power, float snr) {
    // Validate each parameter against its constraints
    if (modulation_type < MODULATION_TYPE_MIN || modulation_type > MODULATION_TYPE_MAX) {
        log_validation(VALIDATION_ERROR_MODULATION_TYPE, config);
        return -1;
    }
    if (bandwidth < BANDWIDTH_MIN || bandwidth > BANDWIDTH_MAX) {
        log_validation(VALIDATION_ERROR_BANDWIDTH, config);
        return -2;
    }
    if (strlen(cell_identity) > CELL_IDENTITY_LEN) {
        log_validation(VALIDATION_ERROR_CELL_IDENTITY, config);
        return -3;
    }
    if (transmission_power < TRANSMISSION_POWER_MIN || transmission_power > TRANSMISSION_POWER_MAX) {
        log_validation(VALIDATION_ERROR_TRANSMISSION_POWER, config);
        return -4;
    }
    if (snr < SNR_MIN || snr > SNR_MAX) {
        log_validation(VALIDATION_ERROR_SNR, config);
        return -5;
    }

    // Initialize the configuration structure with the validated parameters
    config->modulation_type = modulation_type;
    config->bandwidth = bandwidth;
    strcpy(config->cell_identity, cell_identity);
    config->transmission_power = transmission_power;
    config->snr = snr;

    // Log the final configuration state for debugging and monitoring purposes
    log_validation(VALIDATION_OK, config);

    return 0;
}
