    int idle_timeout; // Idle timeout for connections in seconds
    int connection_timeout; // Connection timeout for connections in seconds
    int max_connection_lifetime; // Maximum lifetime of a connection in seconds
    int current_connections; // Current number of active connections
    int available_connections; // Number of available connections
    int total_connections; // Total number of connections created
    int total_failed_connections; // Total number of failed connections
    int total_closed_connections; // Total number of closed connections
    int total_idle_connections; // Total number of idle connections
    int total_active_connections; // Total number of active connections
    int total_pending_requests; // Total number of pending requests
    int total_completed_requests; // Total number of completed requests
    int total_failed_requests; // Total number of failed requests
    int total_closed_requests; // Total number of closed requests
    int total_idle_requests; // Total number of idle requests
    int total_active_requests; // Total number of active requests
    struct connection *connections; // Array of connections in the pool
} connection_pool;

// Define a connection structure
typedef struct {
    int fd; // File descriptor for the connection
    time_t created_at; // Time when the connection was created
    time_t last_used_at; // Time when the connection was last used
    bool is_available; // Whether the connection is available or not
} connection;

// Define a request structure
typedef struct {
    int fd; // File descriptor for the request
    time_t created_at; // Time when the request was created
    time_t last_used_at; // Time when the request was last used
    bool is_available; // Whether the request is available or not
} request;

// Define a semaphore for synchronizing access to the connection pool
sem_t *connection_pool_sem;

// Initialize the connection pool with the given parameters
void init_connection_pool(int num_connections, int max_connections, int min_connections, int idle_timeout, int connection_timeout, int max_connection_lifetime) {
    // Allocate memory for the connection pool structure
    connection_pool *pool = malloc(sizeof(connection_pool));
    if (pool == NULL) {
        printf("Error: Failed to allocate memory for connection pool\n");
        exit(1);
    }

    // Initialize the connection pool structure
    pool->num_connections = num_connections;
    pool->max_connections = max_connections;
    pool->min_connections = min_connections;
    pool->idle_timeout = idle_timeout;
    pool->connection_timeout = connection_timeout;
    pool->max_connection_lifetime = max_connection_lifetime;
    pool->current_connections = 0;
    pool->available_connections = 0;
    pool->total_connections = 0;
    pool->total_failed_connections = 0;
    pool->total_closed_connections = 0;
    pool->total_idle_connections = 0;
    pool->total_active_connections = 0;
    pool->total_pending_requests = 0;
    pool->total_completed_requests = 0;
    pool->total_failed_requests = 0;
    pool->total_closed_requests = 0;
    pool->total_idle_requests = 0;
    pool->total_active_requests = 0;
    pool->connections = malloc(sizeof(connection) * num_connections);
    if (pool->connections == NULL) {
        printf("Error: Failed to allocate memory for connections\n");
        exit(1);
    }

    // Initialize the semaphore for synchronizing access to the connection pool
    connection_pool_sem = malloc(sizeof(sem_t));
    if (connection_pool_sem == NULL) {
        printf("Error: Failed to allocate memory for connection pool semaphore\n");
        exit(1);
    }
    if (sem_init(connection_pool_sem, 0, 1) != 0) {
        printf("Error: Failed to initialize connection pool semaphore\n");
        exit(1);
    }
}

// Monitor the connection pool and ensure efficient resource utilization
void monitor_connection_pool() {
    // Acquire the semaphore for synchronizing access to the connection pool
    if (sem_wait(connection_pool_sem) != 0) {
        printf("Error: Failed to acquire connection pool semaphore\n");
        exit(1);
    }

    // Check the number of active connections and available connections
    int num_active_connections = 0;
    int num_available_connections = 0;
    for (int i = 0; i < connection_pool->num_connections; i++) {
        if (connection_pool->connections[i].is_available) {
            num_available_connections++;
        } else {
            num_active_connections++;
        }
    }

    // Check the number of pending requests and completed requests
    int num_pending_requests = 0;
    int num_completed_requests = 0;
    for (int i = 0; i < connection_pool->num_connections; i++) {
        if (connection_pool->connections[i].is_available) {
            num_pending_requests++;
        } else {
            num_completed_requests++;
        }
    }

    // Release the semaphore for synchronizing access to the connection pool
    if (sem_post(connection_pool_sem) != 0) {
        printf("Error: Failed to release connection pool semaphore\n");
        exit(1);
    }
}

// Terminate the connection pool and free all resources
void terminate_connection_pool() {
    // Acquire the semaphore for synchronizing access to the connection pool
    if (sem_wait(connection_pool_sem) != 0) {
        printf("Error: Failed to acquire connection pool semaphore\n");
        exit(1);
    }

    // Close all connections in the pool
    for (int i = 0; i < connection_pool->num_connections; i++) {
        if (connection_pool->connections[i].is_available) {
            close(connection_pool->connections[i].fd);
        }
    }

    // Release the semaphore for synchronizing access to the connection pool
    if (sem_post(connection_pool_sem) != 0) {
        printf("Error: Failed to release connection pool semaphore\n");
        exit(1);
    }
}

// Validate a connection against predefined constraints
void validate_connection(int fd) {
    // Acquire the semaphore for synchronizing access to the connection pool
    if (sem_wait(connection_pool_sem) != 0) {
        printf("Error: Failed to acquire connection pool semaphore\n");
        exit(1);
    }

    // Check if the connection is valid
    bool is_valid = true;
    for (int i = 0; i < connection_pool->num_connections; i++) {
        if (connection_pool->connections[i].fd == fd) {
            is_valid = false;
            break;
        }
    }

    // Release the semaphore for synchronizing access to the connection pool
    if (sem_post(connection_pool_sem) != 0) {
        printf("Error: Failed to release connection pool semaphore\n");
        exit(1);
    }
}

// Create a new connection in the pool
int create_connection() {
    // Acquire the semaphore for synchronizing access to the connection pool
    if (sem_wait(connection_pool_sem) != 0) {
        printf("Error: Failed to acquire connection pool semaphore\n");
        exit(1);
    }

    // Check if there are available connections in the pool
    int available_connections = 0;
    for (int i = 0; i < connection_pool->num_connections; i++) {
        if (connection_pool->connections[i].is_available) {
            available_connections++;
        }
    }

    // Create a new connection if there are no available connections in the pool
    int fd = -1;
    if (available_connections == 0) {
        fd = socket(AF_INET, SOCK_STREAM, 0);
        if (fd < 0) {
            printf("Error: Failed to create new connection\n");
            exit(1);
        }
    } else {
        // Find the first available connection in the pool and use it
        for (int i = 0; i < connection_pool->num_connections; i++) {
            if (connection_pool->connections[i].is_available) {
                fd = connection_pool->connections[i].fd;
                break;
            }
        }
    }

    // Release the semaphore for synchronizing access to the connection pool
    if (sem_post(connection_pool_sem) != 0) {
        printf("Error: Failed to release connection pool semaphore\n");
        exit(1);
    }

    return fd;
}

// Close a connection in the pool
void close_connection(int fd) {
    // Acquire the semaphore for synchronizing access to the connection pool
    if (sem_wait(connection_pool_sem) != 0) {
        printf("Error: Failed to acquire connection pool semaphore\n");
        exit(1);
    }

    // Find the connection in the pool and close it
    for (int i = 0; i < connection_pool->num_connections; i++) {
        if (connection_pool->connections[i].fd == fd) {
            close(connection_pool->connections[i].fd);
            break;
        }
    }

    // Release the semaphore for synchronizing access to the connection pool
    if (sem_post(connection_pool_sem) != 0) {
        printf("Error: Failed to release connection pool semaphore\n");
        exit(1);
    }
}

// Acquire a connection from the pool
int acquire_connection() {
    // Acquire the semaphore for synchronizing access to the connection pool
    if (sem_wait(connection_pool_sem) != 0) {
        printf("Error: Failed to acquire connection pool semaphore\n");
        exit(1);
    }

    // Find the first available connection in the pool and use it
    for (int i = 0; i < connection_pool->num_connections; i++) {
        if (connection_pool->connections[i].is_available) {
            connection_pool->connections[i].is_available = false;
            connection_pool->current_connections++;
            connection_pool->total_active_connections++;
            return connection_pool->connections[i].fd;
        }
    }

    // Release the semaphore for synchronizing access to the connection pool
    if (sem_post(connection_pool_sem) != 0) {
        printf("Error: Failed to release connection pool semaphore\n");
        exit(1);
    }

    return -1;
}

// Release a connection back to the pool
void release_connection(int fd) {
    // Acquire the semaphore for synchronizing access to the connection pool
    if (sem_wait(connection_pool_sem) != 0) {
        printf("Error: Failed to acquire connection pool semaphore\n");
        exit(1);
    }

    // Find the connection in the pool and release it
    for (int i = 0; i < connection_pool->num_connections; i++) {
        if (connection_pool->connections[i].fd == fd) {
            connection_pool->connections[i].is_available = true;
            connection_pool->current_connections--;
            connection_pool->total_idle_connections++;
            break;
        }
    }

    // Release the semaphore for synchronizing access to the connection pool
    if (sem_post(connection_pool_sem) != 0) {
        printf("Error: Failed to release connection pool semaphore\n");
        exit(1);
    }
}

