    printf("Testing with valid inputs...\n");
    int result = configureAndFindMax(&config, &list);
    if (result == -1) {
        printf("Error: %s\n", strerror(errno));
    } else {
        printf("The largest integer is: %d\n", find_largest_integer(&list));
    }

    // Test the function with invalid inputs
    printf("Testing with invalid inputs...\n");
    config.modulation_type = 3;
    result = configureAndFindMax(&config, &list);
    if (result == -1) {
        printf("Error: %s\n", strerror(errno));
