    }

    // Test the function with concurrent requests from multiple users
    printf("Testing with concurrent requests...\n");
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, configureAndFindMax, &config);
    }
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    // Test the function with transient network failures
    printf("Testing with transient network failures...\n");
    config.modulation_type = 2;
