// Function to manage file operations for configuration initialization
void init_config_file(char *filename) {
    // Determine unique identifier using original filename and current timestamp
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char *unique_id = malloc(10);
    sprintf(unique_id, "%d", tm->tm_sec);

    // Modify filename's extension to include unique identifier and standardized file type
    char *new_filename = malloc(strlen(filename) + strlen(unique_id) + 5);
    sprintf(new_filename, "%s.%s.conf", filename, unique_id);

    // Open file for writing in append mode
    int fd = open(new_filename, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        printf("Error opening file: %s\n", strerror(errno));
        return;
    }

    // Write configuration parameters to file
    write(fd, "modulation_type = ", 17);
    write(fd, &config->modulation_type, sizeof(int));
    write(fd, "\n", 1);
    write(fd, "bandwidth = ", 10);
    write(fd, &config->bandwidth, sizeof(int));
    write(fd, "\n", 1);
    write(fd, "cell_identity = ", 14);
    write(fd, &config->cell_identity, sizeof(int));
    write(fd, "\n", 1);
    write(fd, "transmission_power = ", 18);
    write(fd, &config->transmission_power, sizeof(int));
    write(fd, "\n", 1);
    write(fd, "snr = ", 6);
    write(fd, &config->snr, sizeof(float));
    write(fd, "\n", 1);
    write(fd, "channel_frequency = ", 17);
    write(fd, &config->channel_frequency, sizeof(float));
    write(fd, "\n", 1);

    // Close file and free memory
    close(fd);
    free(unique_id);
    free(new_filename);
}

// Function to handle concurrent initialization from multiple threads
void init_config_threadsafe(config_t *config) {
    // Use a lock to ensure thread safety and data integrity
    pthread_mutex_lock(&config->lock);

    // Validate configuration parameters against predefined constraints
    validate_config(config);

    // Handle error handling for invalid inputs and unexpected conditions
    if (config->modulation_type < 0 || config->modulation_type > 2) {
        handle_error(config, "Invalid modulation type");
    } else if (config->bandwidth < 64 || config->bandwidth > 1024) {
        handle_error(config, "Invalid bandwidth");
    } else if (config->cell_identity < 1 || config->cell_identity > 32) {
        handle_error(config, "Invalid cell identity");
    } else if (config->transmission_power < 0 || config->transmission_power > 40) {
        handle_error(config, "Invalid transmission power");
    } else if (config->snr < 1.0 || config->snr > 20.0) {
        handle_error(config, "Invalid SNR");
    } else if (config->channel_frequency < 433.9 || config->channel_frequency > 470.0) {
        handle_error(config, "Invalid channel frequency");
    }

    // Unlock the mutex to allow other threads to access the configuration structure
    pthread_mutex_unlock(&config->lock);
}

