    }

    // Check if the transmission power is within the allowed range
    if (config.transmission_power < TRANSMISSION_POWER_CONSTRAINTS[0] || config.transmission_power > TRANSMISSION_POWER_CONSTRAINTS[1]) {
        return false;
    }

    // Check if the frequency band is within the allowed range
    if (config.frequency_band < FREQUENCY_BAND_CONSTRAINTS[0] || config.frequency_band > FREQUENCY_BAND_CONSTRAINTS[1]) {
        return false;
    }

    return true;
}

// Define the function to manage multiple wireless nodes, each with its own independent configuration
void manage_multiple_nodes(wireless_config_t config) {
    // Check if the configuration is valid for all nodes
    if (!validate_configuration_changes(config)) {
        log_error("Invalid configuration changes", 0);
        return;
    }

