typedef struct {
    float temperature;
    int sensor_id;
    long timestamp;
} sensor_data_t;

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to initialize the configuration structure
void init_config(config_t *config) {
    // Validate the modulation type and set it to a default value if invalid
    if (config->modulation_type < 0 || config->modulation_type > 3) {
        printf("Invalid modulation type. Setting to default value.\n");
        config->modulation_type = 2; // Set the modulation type to QPSK
    }

    // Validate the bandwidth and set it to a default value if invalid
    if (config->bandwidth < 0 || config->bandwidth > 10) {
        printf("Invalid bandwidth. Setting to default value.\n");
        config->bandwidth = 5; // Set the bandwidth to 5 MHz
    }

    // Validate the cell identity and set it to a default value if invalid
    if (config->cell_identity < 0 || config->cell_identity > 10) {
        printf("Invalid cell identity. Setting to default value.\n");
        config->cell_identity = 5; // Set the cell identity to 5
    }
}

