    // Validate each temperature reading against a specified range
    for (int i = 0; i < num_sensors; i++) {
        if (sensor_data[i].temperature < 15.0f || sensor_data[i].temperature > 30.0f) {
            printf("Invalid temperature reading at index %d. Setting to default value.\n", i);
            sensor_data[i].temperature = 25.0f; // Set the temperature to a default value
        }
    }

    // Sort the data by timestamp in ascending order
    qsort(sensor_data, num_sensors, sizeof(sensor_data_t), compare_timestamp);
}

