    // Validate each RX_UE_INFORMATION_TAG value against a specified range
    for (int i = 0; i < num_rx_ues; i++) {
        if (rx_ue_info[i].RX_UE_INFORMATION_TAG < 0 || rx_ue_info[i].RX_UE_INFORMATION_TAG > 10) {
            printf("Invalid RX_UE_INFORMATION_TAG value at index %d. Setting to default value.\n", i);
            rx_ue_info[i].RX_UE_INFORMATION_TAG = 5; // Set the RX_UE_INFORMATION_TAG to a default value
        }
    }

    // Validate each CRC_INDICATION_REL8_TAG value against a specified range
    for (int i = 0; i < num_rx_ues; i++) {
        if (rx_ue_info[i].CRC_INDICATION_REL8_TAG < 0 || rx_ue_info[i].CRC_INDICATION_REL8_TAG > 10) {
            printf("Invalid CRC_INDICATION_REL8_TAG value at index %d. Setting to default value.\n", i);
            rx_ue_info[i].CRC_INDICATION_REL8_TAG = 5; // Set the CRC_INDICATION_REL8_TAG to a default value
        }
    }
