    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    crc_indication = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_rx_ues * sizeof(NFAPI_CRC_INDICATION_PDU_T));

