// Define a structure to represent an LTE_EMM_MESSAGE
typedef struct {
    int messageType;
    char* nasMessage;
    time_t timestamp;
} LTE_EMM_MESSAGE;

// Define a linked list node to store the messages in the array
typedef struct {
    LTE_EMM_MESSAGE* message;
    struct Node* next;
} Node;

// Define an array of nodes to store the messages
Node** nodes;

// Define a mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new message to the array
void addMessage(int messageType, char* nasMessage) {
    // Lock the mutex before modifying the array
    pthread_mutex_lock(&mutex);

    // Create a new node for the message
    Node* newNode = malloc(sizeof(Node));
    newNode->message = malloc(sizeof(LTE_EMM_MESSAGE));
    newNode->message->messageType = messageType;
    newNode->message->nasMessage = nasMessage;
    newNode->message->timestamp = time(NULL);

    // Add the node to the end of the array
    nodes[nodesCount++] = newNode;

    // Unlock the mutex after modifying the array
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve a message from the array by its unique ID
LTE_EMM_MESSAGE* getMessage(int messageId) {
    // Lock the mutex before accessing the array
    pthread_mutex_lock(&mutex);

    // Iterate through the nodes in the array to find the matching message
    for (int i = 0; i < nodesCount; i++) {
        if (nodes[i]->message->messageId == messageId) {
            LTE_EMM_MESSAGE* message = nodes[i]->message;
            // Unlock the mutex after accessing the array
            pthread_mutex_unlock(&mutex);
            return message;
        }
    }

    // If no matching message is found, return NULL
    pthread_mutex_unlock(&mutex);
    return NULL;
}

// Function to remove a message from the array safely from multiple concurrent threads
void removeMessage(int messageId) {
    // Lock the mutex before modifying the array
    pthread_mutex_lock(&mutex);

    // Iterate through the nodes in the array to find the matching message
    for (int i = 0; i < nodesCount; i++) {
        if (nodes[i]->message->messageId == messageId) {
            Node* nodeToRemove = nodes[i];
            // Remove the node from the array
            nodes[i] = nodes[--nodesCount];
            free(nodeToRemove);
            break;
        }
    }

    // Unlock the mutex after modifying the array
    pthread_mutex_unlock(&mutex);
}
