#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the structure to store the UE information
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the array to store the UE information
NFAPI_CRC_INDICATION_PDU_T *ue_info_array = NULL;

// Define the mutex for synchronization
pthread_mutex_t ue_info_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate and initialize a new UE information structure
NFAPI_CRC_INDICATION_PDU_T *allocate_ue_info(void) {
    NFAPI_CRC_INDICATION_PDU_T *new_ue_info = NULL;

    // Lock the mutex to prevent race conditions in a multi-threaded environment
    pthread_mutex_lock(&ue_info_mutex);

    // Check if there is enough memory available to allocate a new structure
    if (ue_info_array == NULL || ue_info_array->num_ues >= 1000) {
        // If there is no memory available, return an error indicator
        pthread_mutex_unlock(&ue_info_mutex);
        return NULL;
    }

    // Allocate a new structure and initialize it with random values for the CRC flag
    new_ue_info = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_ue_info == NULL) {
        // If allocation fails, return an error indicator and unlock the mutex
        pthread_mutex_unlock(&ue_info_mutex);
        return NULL;
    }

    new_ue_info->rx_ue_information = RX_UE_INFORMATION_TAG_INIT;
    new_ue_info->rnti = RNTI_INIT;
    new_ue_info->crc_indication_rel8.crflag = (rand() % 2) ? 1 : 0;

    // Increment the number of UEs and unlock the mutex
    ue_info_array->num_ues++;
    pthread_mutex_unlock(&ue_info_mutex);

    return new_ue_info;
}

// Function to deallocate a UE information structure
void deallocate_ue_info(NFAPI_CRC_INDICATION_PDU_T *ue_info) {
    // Lock the mutex to prevent race conditions in a multi-threaded environment
    pthread_mutex_lock(&ue_info_mutex);

    // Decrement the number of UEs and free the structure
    ue_info_array->num_ues--;
    free(ue_info);

    // Unlock the mutex
    pthread_mutex_unlock(&ue_info_mutex);
}

// Function to get a UE information structure by its RNTI
NFAPI_CRC_INDICATION_PDU_T *get_ue_info(RNTI rnti) {
    // Lock the mutex to prevent race conditions in a multi-threaded environment
    pthread_mutex_lock(&ue_info_mutex);

    // Iterate over the UE information structures and find the one with the matching RNTI
    for (int i = 0; i < ue_info_array->num_ues; i++) {
        if (ue_info_array[i].rnti == rnti) {
            // If a match is found, return the structure and unlock the mutex
            pthread_mutex_unlock(&ue_info_mutex);
            return &ue_info_array[i];
        }
    }

    // If no match is found, return an error indicator and unlock the mutex
    pthread_mutex_unlock(&ue_info_mutex);
    return NULL;
}

// Function to update a UE information structure with new CRC indication data
void update_ue_info(NFAPI_CRC_INDICATION_PDU_T *ue_info, RX_UE_INFORMATION_TAG rx_ue_information) {
    // Lock the mutex to prevent race conditions in a multi-threaded environment
    pthread_mutex_lock(&ue_info_mutex);

    // Update the UE information structure with the new data
    ue_info->rx_ue_information = rx_ue_information;

    // Unlock the mutex
    pthread_mutex_unlock(&ue_info_mutex);
}
