        self.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG
        self.RNTI = RNTI
        self.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG
        self.CRCFLAG = CRCFLAG
        self.filename = filename
        self.unique_id = unique_id
        self.md5hash = md5hash

# Function to calculate MD5 hash of directory tree given a root path
def calculate_md5_hash(root_path):
    # Initialize variables
    md5hash = ""
    file_list = []
    dir_list = []
    total_size = 0

    # Recursively traverse directory structure and read files in chunks
    for root, dirs, files in os.walk(root_path):
        for file in files:
            file_path = os.path.join(root, file)
            with open(file_path, "rb") as fp:
                chunk = fp.read(1024)
                while chunk:
                    md5hash += hashlib.md5(chunk).hexdigest()
                    chunk = fp.read(1024)
            total_size += os.path.getsize(file_path)

    # Return MD5 hash of directory tree
    return md5hash

