    if (entry != NULL) {
        return -1;
    }

    // Create a new cache entry
    entry = malloc(sizeof(struct CacheEntry));
    if (!entry) {
        perror("Failed to allocate memory for cache entry");
        return -1;
    }
    entry->cache = manager->cache;
    entry->key = key;
    entry->value = value;
    entry->expiry = time(NULL) + 3600; // Set the expiry time to one hour from now

    // Add the new cache entry to the cache
    pthread_mutex_lock(manager->lock);
    if (sem_wait(manager->sem) == -1) {
        perror("Failed to wait on semaphore");
        free(entry);
        pthread_mutex_unlock(manager->lock);
        return -1;
    }
    // Add the new cache entry to the end of the linked list
    if (manager->cache->size == 0) {
        manager->cache->head = entry;
    } else {
        struct CacheEntry *tail = manager->cache->tail;
        tail->next = entry;
    }
    manager->cache->tail = entry;
    manager->cache->size++;
    pthread_mutex_unlock(manager->lock);
    sem_post(manager->sem);

    return 0;
}

// Define the cache manager function for getting an entry from the cache
struct CacheEntry *cache_manager_get(struct CacheManager *manager, void *key) {
    struct CacheEntry *entry = NULL;

    // Search for the key in the cache
    pthread_mutex_lock(manager->lock);
    if (sem_wait(manager->sem) == -1) {
        perror("Failed to wait on semaphore");
        pthread_mutex_unlock(manager->lock);
        return NULL;
    }
    struct CacheEntry *head = manager->cache->head;
    while (head != NULL) {
        if (head->key == key) {
            entry = head;
            break;
        }
        head = head->next;
    }
    pthread_mutex_unlock(manager->lock);
    sem_post(manager->sem);

    return entry;
}

// Define the cache manager function for updating an existing entry in the cache
int cache_manager_update(struct CacheManager *manager, void *key, void *value) {
    // Check if the key exists in the cache
    struct CacheEntry *entry = cache_manager_get(manager, key);
    if (entry == NULL) {
        return -1;
    }

    // Update the value associated with the key
    entry->value = value;

    return 0;
}

// Define the cache manager function for removing an entry from the cache
int cache_manager_remove(struct CacheManager *manager, void *key) {
    struct CacheEntry *entry = NULL;

    // Search for the key in the cache
    pthread_mutex_lock(manager->lock);
    if (sem_wait(manager->sem) == -1) {
        perror("Failed to wait on semaphore");
        pthread_mutex_unlock(manager->lock);
        return NULL;
    }
    struct CacheEntry *head = manager->cache->head;
    while (head != NULL) {
        if (head->key == key) {
            entry = head;
            break;
        }
        head = head->next;
    }
    // Remove the cache entry from the linked list
    if (entry != NULL) {
        struct CacheEntry *prev = entry->prev;
        struct CacheEntry *next = entry->next;
        if (prev == NULL) {
            manager->cache->head = next;
        } else {
            prev->next = next;
        }
        if (next == NULL) {
            manager->cache->tail = prev;
        } else {
            next->prev = prev;
        }
        manager->cache->size--;
    }
    pthread_mutex_unlock(manager->lock);
    sem_post(manager->sem);

    return 0;
}

// Define the cache manager function for cleaning up the cache
void cache_manager_cleanup(struct CacheManager *manager) {
    // Close the cache file descriptor
    close(manager->cache->fd);

    // Free the memory allocated to the cache structure
    free(manager->cache->data);
    free(manager->cache);

    // Destroy the semaphore and mutex
    sem_destroy(manager->sem);
    pthread_mutex_destroy(manager->lock);

    // Free the memory allocated to the cache manager structure
    free(manager);
}
