        // Free the memory allocated for the current line
        free(line);
    }

    // Compute the statistical summaries for each field
    for (int i = 0; i < report->num_fields; i++) {
        field_stats[i]->mean /= report->num_fields;
        field_stats[i]->median /= report->num_fields;
        field_stats[i]->mode /= report->num_fields;
    }

    // Write the summarized report to the output file
    fprintf(output, "Summary Report\n");
    for (int i = 0; i < report->num_fields; i++) {
        fprintf(output, "%s: mean=%f, median=%f, mode=%f\n", field_stats[i]->field_name, field_stats[i]->mean, field_stats[i]->median, field_stats[i]->mode);
    }

    // Free the memory allocated for the report
    free(report);

    // Close the input and output files
    fclose(input);
    fclose(output);
}

