    // Initialize the data structure to hold the extracted fields
    char **fields = malloc(sizeof(char *) * 10);
    for (int i = 0; i < 10; i++) {
        fields[i] = NULL;
    }

    // Parse the current line and extract the relevant fields based on the rules
    char *token = strtok(line, ",");
    int field_index = 0;
    while (token != NULL) {
        fields[field_index++] = token;
        token = strtok(NULL, ",");
    }

    // Return the extracted fields
    return fields;
}

