// Log processing status
enum class ProcessingStatus {
    INITIALIZING,
    PROCESSING,
    PAUSED,
    FINISHED
};

// Log processing mode
enum class ProcessingMode {
    REALTIME,
    BATCH
};

// Log parsing rule
struct LogParsingRule {
    string field; // Field name
    regex pattern; // Pattern to match
    function<void(const smatch&)> callback; // Callback function for matching logs
};

// Log filtering criteria
