    string field; // Field name
    string value; // Value to filter by
};

// Log aggregation interval
struct LogAggregationInterval {
    int milliseconds; // Aggregation interval in milliseconds
    function<void(const vector<string>&)> callback; // Callback function for aggregated logs
};

// Log processing configuration
struct LogProcessingConfiguration {
    ProcessingMode mode; // Processing mode (realtime or batch)
    int logInterval; // Log interval in milliseconds
    int logCount; // Number of logs to process per iteration
    int cacheSize; // Cache size in bytes
    int threadCount; // Number of threads to use for processing logs
};

// Log processing context
struct LogProcessingContext {
    ProcessingStatus status; // Processing status
    LogProcessingConfiguration configuration; // Processing configuration
    vector<LogParsingRule> parsingRules; // Parsing rules
    vector<LogFilterCriteria> filterCriteria; // Filter criteria
    vector<LogAggregationInterval> aggregationIntervals; // Aggregation intervals
