void updateLogProcessingConfiguration(LogProcessingContext& context, const LogProcessingConfiguration& configuration) {
    if (configuration.mode != ProcessingMode::REALTIME && configuration.mode != ProcessingMode::BATCH) {
        throw invalid_argument("Invalid processing mode");
    }
    if (configuration.logInterval < MIN_LOG_INTERVAL || configuration.logInterval > MAX_LOG_INTERVAL) {
        throw invalid_argument("Invalid log interval");
    }
    if (configuration.logCount < MIN_LOG_COUNT || configuration.logCount > MAX_LOG_COUNT) {
        throw invalid_argument("Invalid log count");
    }
    if (configuration.cacheSize < MIN_CACHE_SIZE || configuration.cacheSize > MAX_CACHE_SIZE) {
        throw invalid_argument("Invalid cache size");
    }
    if (configuration.threadCount < MIN_THREAD_COUNT || configuration.threadCount > MAX_THREAD_COUNT) {
        throw invalid_argument("Invalid thread count");
    }
    context.configuration = configuration;
}

