        if (regex_search(log, matches, rule.pattern)) {
            rule.callback(matches);
        }
    }
    for (const LogAggregationInterval& interval : context.aggregationIntervals) {
        if (interval.milliseconds == 0 || interval.callback == nullptr) {
            continue;
        }
        int milliseconds = getLogTimestamp(log);
        if (milliseconds > 0 && milliseconds % interval.milliseconds == 0) {
            vector<string> logsToAggregate;
            for (const string& log : context.logs) {
                int timestamp = getLogTimestamp(log);
                if (timestamp > 0 && timestamp >= milliseconds - interval.milliseconds) {
                    logsToAggregate.push_back(log);
                }
            }
            interval.callback(logsToAggregate);
        }
    }
}

// Process multiple logs in the log processing context
void processLogs(LogProcessingContext& context, const vector<string>& logs) {
    if (logs.empty()) {
        throw invalid_argument("Invalid logs");
    }
    for (const string& log : logs) {
        processLog(context, log);
    }
}

