void generate_report(char* input_file, char* output_file, char* rules, bool verbose, char* hash_function, int max_line_length) {
    // Open the input file and check for errors
    FILE* input = fopen(input_file, "r");
    if (input == NULL) {
        printf("Error opening input file: %s\n", strerror(errno));
        return;
    }

    // Open the output file and check for errors
    FILE* output = fopen(output_file, "w");
    if (output == NULL) {
        printf("Error opening output file: %s\n", strerror(errno));
        fclose(input);
        return;
    }

    // Initialize the hash function and check for errors
    MD5_CTX ctx;
    int ret = MD5_Init(&ctx);
    if (ret != 1) {
        printf("Error initializing hash function: %s\n", strerror(errno));
        fclose(input);
        fclose(output);
        return;
    }

    // Read the input file in chunks and process each line
    char* buffer = malloc(max_line_length + 1);
    while (fgets(buffer, max_line_length, input) != NULL) {
        // Compute the hash of the current line
        ret = MD5_Update(&ctx, buffer, strlen(buffer));
        if (ret != 1) {
            printf("Error computing hash: %s\n", strerror(errno));
            fclose(input);
            fclose(output);
            return;
        }

        // Parse the current line and extract relevant information
        char* token = strtok(buffer, " ");
        while (token != NULL) {
            if (strcmp(token, rules) == 0) {
                // Extract the key metrics from the current line
                int metric1 = atoi(strtok(NULL, " "));
                int metric2 = atoi(strtok(NULL, " "));
                int metric3 = atoi(strtok(NULL, " "));

                // Print the aggregated report for the current line
                fprintf(output, "%s %d %d %d\n", token, metric1, metric2, metric3);
            } else {
                // Print the detailed logs if verbose flag is set
                if (verbose) {
                    fprintf(output, "%s\n", buffer);
                }
            }

            // Get the next token
            token = strtok(NULL, " ");
        }

        // Reset the hash function for the next line
        ret = MD5_Init(&ctx);
        if (ret != 1) {
            printf("Error resetting hash function: %s\n", strerror(errno));
            fclose(input);
            fclose(output);
            return;
        }
    }

    // Close the input and output files
    fclose(input);
    fclose(output);

    // Free the memory allocated for the buffer
    free(buffer);
}
