    for (uint32_t i = 0; i < n; ++i) {
        if (!validateCRCIndicationPDU(&crc_indications[i])) {
            LOG_ERROR("Invalid CRC indication PDU at index %d.", i);
            free(crc_indications);
            return NULL;
        }
    }

    // Integrate with an existing data processing pipeline to allow seamless transfer of the structures to subsequent functions
    return crc_indications;
}

// Define a function to validate each CRC indication PDU
bool validateCRCIndicationPDU(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Validate the RX UE information tag
    if (pdu->rx_ue_information_tag > UINT16_MAX) {
        return false;
    }

    // Validate the RNTI
    if (pdu->rnti > UINT32_MAX) {
        return false;
    }

    // Validate the CRC indication REL8 tag
    if (pdu->crc_indication_rel8_tag > UINT8_MAX) {
        return false;
    }

    // Validate the CRCFLAG
    if (!(pdu->crcflag == true || pdu->crcflag == false)) {
        return false;
    }

    return true;
}
