            // Unlock the mutex and return if the user already exists in the cache
            pthread_mutex_unlock(&cache->mutex);
            return;
        }
    }

    // Allocate memory for the new user
    struct user_cache *new_user = malloc(sizeof(struct user_cache));
    if (new_user == NULL) {
        // Unlock the mutex and return if memory allocation fails
        pthread_mutex_unlock(&cache->mutex);
        return;
    }

    // Initialize the new user's username and email
    new_user->username = strdup(username);
    new_user->email = strdup(email);

    // Add the new user to the cache
    for (int i = 0; i < MAX_USERS; i++) {
        if (cache->users[i] == NULL) {
            cache->users[i] = new_user;
            break;
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&cache->mutex);
}

