// Define the function to handle caching of frequently used configurations
void cache_wireless_config(wireless_config *config) {
    // Lock the cache structure to prevent concurrent modifications
    pthread_mutex_lock(&cache.mutex);

    // Add the configuration to the cache if it is not already present
    if (cache.count < CACHE_SIZE) {
        cache.config[cache.count] = config;
        cache.count++;
    } else {
        // Replace the least recently used configuration with the new one
        int lru_index = 0;
        for (int i = 1; i < CACHE_SIZE; i++) {
            if (cache.timestamp[i] < cache.timestamp[lru_index]) {
                lru_index = i;
            }
        }
        cache.config[lru_index] = config;
    }

    // Update the timestamp for the cached configuration
    cache.timestamp[cache.count - 1] = time(NULL);

    // Unlock the cache structure to allow other threads to modify it
    pthread_mutex_unlock(&cache.mutex);
}

