// Function to generate a new filename based on the original filename's characteristics
char *generate_filename(const char *original_filename) {
    // Get the current timestamp
    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);

    // Create a new filename with the same file type as the original filename
    char *new_filename = malloc(strlen(original_filename) + 10);
    sprintf(new_filename, "%d-%02d-%02d-%s", time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday, original_filename + strlen(original_filename) - 4);

    // Add a timestamp and a number of digits equal to half the length of the original filename (rounded down)
    int num_digits = strlen(new_filename) / 2;
    sprintf(new_filename + strlen(new_filename), "-%d", rand() % num_digits);

    return new_filename;
}
