namespace NumberOperations {
    class RandomNumberManager {
    private:
        std::vector<int> numbers;
        int totalCount = 0;

    public:
        RandomNumberManager() {
            srand(time(NULL));
        }

        void addNumber(int number) {
            if (number > 0) {
                numbers.push_back(number);
                totalCount++;
            } else {
                std::cout << "Invalid input: Number must be greater than 0." << std::endl;
            }
        }

        int getTotalCount() {
            return totalCount;
        }

        int findLargestNumber() {
            if (totalCount == 0) {
                std::cout << "No numbers in the collection." << std::endl;
                return -1;
            } else {
                return *std::max_element(numbers.begin(), numbers.end());
            }
        }

        void clear() {
            numbers.clear();
            totalCount = 0;
        }
    };
}
