#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

// Define the memory pool structure
struct MemoryPool {
    void* data; // Pointer to the start of the memory pool
    size_t size; // Size of the memory pool in bytes
    size_t used; // Amount of memory currently in use
    size_t alignment; // Alignment requirement for memory blocks
};

// Define a function to allocate memory from the pool
void* mempool_alloc(struct MemoryPool* pool, size_t size) {
    // Check if the requested size is within the bounds of the pool
    assert(size <= pool->size);

    // Calculate the aligned size and alignment requirements
    size_t aligned_size = (size + pool->alignment - 1) / pool->alignment * pool->alignment;
    size_t alignment = aligned_size - size;

    // Check if there is enough memory available in the pool
    if (pool->used + aligned_size > pool->size) {
        return NULL;
    }

    // Allocate the memory block from the pool
    void* data = pool->data + pool->used;
    pool->used += aligned_size;

    // Return a pointer to the allocated memory block
    return data;
}

// Define a function to deallocate memory from the pool
void mempool_free(struct MemoryPool* pool, void* data) {
    // Check if the data pointer is within the bounds of the pool
    assert(data >= pool->data && data < pool->data + pool->size);

    // Calculate the offset of the memory block from the start of the pool
    size_t offset = (char*)data - (char*)pool->data;

    // Check if the memory block is still in use
    if (offset >= pool->used) {
        return;
    }

    // Update the used memory counter and return
    pool->used -= offset;
}

// Define a function to adjust the size of the memory pool
void mempool_resize(struct MemoryPool* pool, size_t new_size) {
    // Check if the new size is within the bounds of the pool
    assert(new_size <= pool->size);

    // Update the used memory counter and return
    pool->used = new_size;
}
```
