// Define the configuration structure for the wireless communication system
typedef struct {
    int modulation_type;
    int bandwidth;
    int cell_identity;
    int transmission_power;
    float signal_to_noise_ratio;
    char* frequency_hopping_sequence;
    bool power_amplification_control_settings;
} wireless_configuration_t;

// Define the NFAPI_CRC_INDICATION_PDU_T structure for storing RX UE information
typedef struct {
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
} nfapi_crc_indication_pdu_t;

