#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <md5.h>

// Custom memory pool for efficient allocation and deallocation of NFAPI_CRC_INDICATION_PDU_T structures
struct MemoryPool {
    struct MemoryPool* next;
    size_t size;
    void* data;
};

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate a list of NFAPI_CRC_INDICATION_PDU_T structures with unique identifiers
void generate_crc_indication_pdu_list(const char* root_path, const char* log_file) {
    // Initialize memory pool for efficient allocation and deallocation of NFAPI_CRC_INDICATION_PDU_T structures
    struct MemoryPool* mempool = NULL;

    // Open log file for writing
    FILE* log_fp = fopen(log_file, "w");
    if (log_fp == NULL) {
        printf("Error: Failed to open log file %s\n", log_file);
        return;
    }

    // Iterate over all files in the directory tree rooted at root_path
    DIR* dir = opendir(root_path);
    if (dir == NULL) {
        printf("Error: Failed to open directory %s\n", root_path);
        fclose(log_fp);
        return;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip directories and files that start with a dot (hidden files)
        if (entry->d_type == DT_DIR || entry->d_name[0] == '.') {
            continue;
        }

        // Construct unique identifier for each file based on user ID, timestamp, and file size
        char* filename = entry->d_name;
        char* user_id = strtok(filename, "_");
        char* timestamp = strtok(NULL, "_");
        char* filesize = strtok(NULL, "_");
        char unique_id[1024];
        sprintf(unique_id, "%s_%s_%s", user_id, timestamp, filesize);

        // Calculate MD5 hash of the unique identifier to ensure no duplicate RNTIs within the list
        uint8_t md5_hash[16];
        MD5((unsigned char*)unique_id, strlen(unique_id), md5_hash);

        // Allocate memory for NFAPI_CRC_INDICATION_PDU_T structure and populate fields
        struct MemoryPool* mempool_entry = malloc(sizeof(struct MemoryPool));
        if (mempool_entry == NULL) {
            printf("Error: Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T structure\n");
            fclose(log_fp);
            return;
        }
        mempool_entry->next = mempool;
        mempool_entry->size = sizeof(struct MemoryPool);
        mempool_entry->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (mempool_entry->data == NULL) {
            printf("Error: Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T structure\n");
            fclose(log_fp);
            return;
        }
        memcpy(mempool_entry->data, &NFAPI_CRC_INDICATION_PDU_T, sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        mempool = mempool_entry;

        // Log creation process for each file
        fprintf(log_fp, "Creating NFAPI_CRC_INDICATION_PDU_T structure for file %s\n", filename);
        fprintf(log_fp, "Unique identifier: %s\n", unique_id);
        fprintf(log_fp, "MD5 hash: ");
        for (int i = 0; i < 16; i++) {
            fprintf(log_fp, "%02x", md5_hash[i]);
        }
        fprintf(log_fp, "\n");
    }

    // Close log file and free memory pool
    fclose(log_fp);
    struct MemoryPool* current = mempool;
    while (current != NULL) {
        struct MemoryPool* next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
}
