import hashlib
import os
import time

# Custom memory pool for efficient allocation and deallocation of NFAPI_CRC_INDICATION_PDU_T structures
class MemoryPool:
    def __init__(self):
        self.next = None
        self.size = 0
        self.data = None

# Function to generate a list of NFAPI_CRC_INDICATION_PDU_T structures with unique identifiers
def generate_crc_indication_pdu_list(root_path, log_file):
    # Initialize memory pool for efficient allocation and deallocation of NFAPI_CRC_INDICATION_PDU_T structures
    mempool = MemoryPool()

    # Open log file for writing
    with open(log_file, "w") as log_fp:
        # Iterate over all files in the directory tree rooted at root_path
        for dirname, subdirs, files in os.walk(root_path):
            for filename in files:
                # Skip directories and files that start with a dot (hidden files)
                if filename[0] == ".":
                    continue

                # Construct unique identifier for each file based on user ID, timestamp, and file size
                user_id = os.path.basename(dirname)
                timestamp = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime())
                filesize = os.path.getsize(os.path.join(dirname, filename))
                unique_id = f"{user_id}_{timestamp}_{filesize}"

                # Calculate MD5 hash of the unique identifier to ensure no duplicate RNTIs within the list
                md5_hash = hashlib.md5(unique_id.encode()).hexdigest()

                # Allocate memory for NFAPI_CRC_INDICATION_PDU_T structure and populate fields
                mempool_entry = MemoryPool()
                mempool_entry.next = mempool
                mempool_entry.size = sizeof(struct NFAPI_CRC_INDICATION_PDU_T)
                mempool_entry.data = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T))
                if mempool_entry.data == NULL:
                    print("Error: Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T structure")
                    return
                memcpy(mempool_entry.data, &NFAPI_CRC_INDICATION_PDU_T, sizeof(struct NFAPI_CRC_INDICATION_PDU_T))
                mempool = mempool_entry

                # Log creation process for each file
                log_fp.write("Creating NFAPI_CRC_INDICATION_PDU_T structure for file {}\n".format(filename))
                log_fp.write("Unique identifier: {}\n".format(unique_id))
                log_fp.write("MD5 hash: {}\n".format(md5_hash))
