// Define the function to allocate and validate the array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocateAndValidateCRCIndications(uint32_t N, uint32_t randomSeed) {
    // Initialize the array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* crcIndications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    if (!crcIndications) {
        // Handle out-of-memory condition
        fprintf(stderr, "Error: Failed to allocate memory for CRC indications (%s)\n", strerror(errno));
        return NULL;
    }

    // Initialize the random seed for generating random values
    srand(randomSeed);

    // Loop through each structure in the array and initialize its fields
    for (uint32_t i = 0; i < N; i++) {
        crcIndications[i].RX_UE_INFORMATION_TAG = rand() % 1000000;
        crcIndications[i].RNTI = rand() % 65536;
        crcIndications[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        crcIndications[i].CRCFLAG = (rand() % 2) == 0 ? true : false;
    }

    // Validate the integrity of each structure before returning the array
    for (uint32_t i = 0; i < N; i++) {
        if (!validateCRCIndication(&crcIndications[i])) {
            fprintf(stderr, "Error: CRC indication %d is invalid\n", i);
            free(crcIndications);
            return NULL;
        }
    }

    // Return the array of NFAPI_CRC_INDICATION_PDU_T structures
    return crcIndications;
}

// Define the function to validate a single NFAPI_CRC_INDICATION_PDU_T structure
bool validateCRCIndication(NFAPI_CRC_INDICATION_PDU_T* crcIndication) {
    // Check if the RX_UE_INFORMATION_TAG is valid
    if (crcIndication->RX_UE_INFORMATION_TAG < 0 || crcIndication->RX_UE_INFORMATION_TAG > 1000000) {
        return false;
    }

    // Check if the RNTI is valid
    if (crcIndication->RNTI < 0 || crcIndication->RNTI > 65536) {
        return false;
    }

    // Check if the CRC_INDICATION_REL8_TAG is valid
    if (crcIndication->CRC_INDICATION_REL8_TAG < 0 || crcIndication->CRC_INDICATION_REL8_TAG > 256) {
        return false;
    }

    // Check if the CRCFLAG is valid
    if (crcIndication->CRCFLAG != true && crcIndication->CRCFLAG != false) {
        return false;
    }

    // If all checks pass, return true
    return true;
}

// Define the function to handle periodic re-allocation of memory as NFAPI_CRC_INDICATION_PDU_T structures are processed
void reallocateMemory(NFAPI_CRC_INDICATION_PDU_T** crcIndications, uint32_t* size) {
    // Check if the current allocation size is sufficient for the next iteration
    if (*size < *crcIndications + 1) {
        // Reallocate memory with a new size that is twice the current size
        *crcIndications = (NFAPI_CRC_INDICATION_PDU_T*)realloc(*crcIndications, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (*size * 2));
        if (!*crcIndications) {
            // Handle out-of-memory condition
            fprintf(stderr, "Error: Failed to reallocate memory for CRC indications (%s)\n", strerror(errno));
            return;
        }
    }
}
