// function to handle rate limiting adaptively based on network conditions and server responsiveness
void rate_limiting_adaptive(struct rate_limiting *rate_limiting) {
    // check if the current query is within the rate limit window
    time_t now = time(NULL);
    if (now - rate_limiting->last_query_time < rate_limiting->window_size) {
        return;
    }

    // update the last query time and check if the current query is within the rate limit threshold
    rate_limiting->last_query_time = now;
    if (rate_limiting->queries_per_second <= 0 || now - rate_limiting->last_query_time < rate_limiting->window_size) {
        return;
    }

    // sleep for the remaining time in the rate limit window
    int seconds = (int) (rate_limiting->window_size - (now - rate_limiting->last_query_time));
    if (seconds > 0) {
        usleep(seconds * 1000000);
    }
}

