// Define the function to calculate the MD5 hash of a file given its path
void md5_hash(char *path) {
    // Open the file for reading
    FILE *fp = fopen(path, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", path);
        return;
    }

    // Read the file in chunks to minimize memory usage and optimize performance for large files
    char buffer[BUFFER_SIZE];
    while (!feof(fp)) {
        size_t bytes_read = fread(buffer, 1, BUFFER_SIZE, fp);
        if (bytes_read == 0) {
            break;
        }

        // Calculate the MD5 hash of the buffer
        unsigned char md5[MD5_DIGEST_LENGTH];
        MD5(buffer, bytes_read, md5);

        // Print the hexadecimal representation of the hash
        printf("MD5 hash: ");
        for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
            printf("%02x", md5[i]);
        }
        printf("\n");
    }

    // Close the file and return
    fclose(fp);
}
