#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

// Define the graph structure
typedef struct {
    int num_vertices;
    int *vertices;
} graph_t;

// Define the function to add a random number of vertices to the graph
void add_random_vertices(graph_t *graph, int num_vertices) {
    // Generate a random number of vertices to add
    int num_to_add = rand() % (num_vertices + 1);

    // Allocate memory for the new vertices
    graph->vertices = realloc(graph->vertices, sizeof(int) * (graph->num_vertices + num_to_add));

    // Add the new vertices to the graph
    for (int i = 0; i < num_to_add; i++) {
        int vertex = rand() % (graph->num_vertices + 1);
        graph->vertices[graph->num_vertices++] = vertex;
    }
}
