};

// Define the cache entry structure
struct CacheEntry {
    std::string key;
    std::string value;
    std::chrono::time_point<std::chrono::system_clock> lastAccessed;
};

// Define the caching mechanism class
class CachingMechanism {
public:
    // Constructor
    CachingMechanism(const ConfigSettings& config) : config_(config), cacheSize_(0) {}

    // Add a new entry to the cache
    void addEntry(const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (cacheSize_ >= config_.maxCacheSize) {
            // Evict the least recently used entry
            evictEntry();
        }
        cache_.push_back({key, value, std::chrono::system_clock::now()});
        ++cacheSize_;
    }

    // Get an existing entry from the cache
    std::string getEntry(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = cache_.begin(); it != cache_.end(); ++it) {
            if (it->key == key) {
                // Update the last accessed time
                it->lastAccessed = std::chrono::system_clock::now();
                return it->value;
            }
        }
        return "";
    }

    // Evict an entry from the cache
    void evictEntry() {
        if (cacheSize_ == 0) {
            return;
        }
        auto it = std::max_element(cache_.begin(), cache_.end(), [](const CacheEntry& a, const CacheEntry& b) {
            return a.lastAccessed < b.lastAccessed;
        });
        cache_.erase(it);
        --cacheSize_;
    }

private:
    // Configuration settings
    ConfigSettings config_;

    // Cache size
    int cacheSize_;

    // Cache entries
    std::vector<CacheEntry> cache_;

    // Mutex for thread safety
    std::mutex mutex_;
};

// Define the configuration manager class
class ConfigurationManager {
public:
