    // Load the configuration settings from multiple sources
    void loadConfiguration() {
        // Load JSON file
        if (!config_.jsonFilePath.empty()) {
            std::ifstream jsonFile(config_.jsonFilePath);
            if (jsonFile.is_open()) {
                std::string line;
                while (std::getline(jsonFile, line)) {
                    // Parse the JSON file and add each key-value pair to the cache
                    cachingMechanism_.addEntry(line);
                }
            } else {
                throw std::runtime_error("Failed to open JSON configuration file");
            }
        }

        // Load environment variables
        for (const auto& envVar : config_.envVars) {
            cachingMechanism_.addEntry(envVar.first, envVar.second);
        }

        // Load command line flags
        for (const auto& cmdLineFlag : config_.cmdLineFlags) {
            cachingMechanism_.addEntry(cmdLineFlag);
        }
    }

    // Get a configuration setting from the cache
    std::string getConfigurationSetting(const std::string& key) {
        return cachingMechanism_.getEntry(key);
