        std::lock_guard<std::mutex> lock(mutex_);
        logLevel_ = logLevel;
    }

    // Log a message
    void logMessage(const std::string& message, int logLevel) {
        if (logLevel >= logLevel_) {
            std::lock_guard<std::mutex> lock(mutex_);
            // Write the message to the log file
            std::ofstream logFile(config_.logFilePath, std::ios::app);
            if (logFile.is_open()) {
