typedef struct {
    char* device_id;
    int ip_address;
    char* config_state;
    time_t last_seen;
} networkDevice;

// Define the function to manage the list of network devices
void manageNetworkDevices(int num_devices, int* ip_addresses, char** device_ids, char** config_states) {
    // Initialize the list of network devices
    networkDevice* devices = (networkDevice*)malloc(num_devices * sizeof(networkDevice));
    if (!devices) {
        printf("Error: Failed to allocate memory for the list of network devices\n");
        return;
    }

    // Loop through each device and validate its IP address and configuration state
    for (int i = 0; i < num_devices; i++) {
        if (!validateIPAddress(ip_addresses[i])) {
            printf("Error: Invalid IP address %d\n", ip_addresses[i]);
            continue;
        }
        if (!validateConfigState(config_states[i])) {
            printf("Error: Invalid configuration state for device %s\n", device_ids[i]);
            continue;
        }
    }

    // Loop through each device and update its last seen timestamp
    for (int i = 0; i < num_devices; i++) {
        devices[i].last_seen = time(NULL);
    }

    // Free the memory allocated for the list of network devices
    free(devices);
}

// Validate an IP address
int validateIPAddress(int ip_address) {
    if (ip_address < 0 || ip_address > 255) {
        return 0;
    }
    return 1;
}

// Validate a configuration state
int validateConfigState(char* config_state) {
    if (!config_state) {
        return 0;
    }
    if (strcmp(config_state, "Active") == 0 || strcmp(config_state, "Offline") == 0 || strcmp(config_state, "Standby") == 0) {
        return 1;
    }
    return 0;
}
