void update_wireless_config(wireless_config *config, int modulation_type, int bandwidth, int cell_identity, int transmission_power, float snr, float channel_occupancy_level) {
    // Update the parameters in the configuration structure
    config->modulation_type = modulation_type;
    config->bandwidth = bandwidth;
    config->cell_identity = cell_identity;
    config->transmission_power = transmission_power;
    config->snr = snr;
    config->channel_occupancy_level = channel_occupancy_level;
