    printf("Validation steps:\n");
    printf("\tModulation type: %d\n", config->modulation_type);
    printf("\tBandwidth: %d\n", config->bandwidth);
    printf("\tCell identity: %d\n", config->cell_identity);
    printf("\tTransmission power: %d\n", config->transmission_power);
    printf("\tSNR: %.2f\n", config->snr);
    printf("\tChannel occupancy level: %.2f\n", config->channel_occupancy_level);
}

