// Define the structure to hold the CRC indication data
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    RX_UE_INFORMATION_TAG rx_ue_info;
    CRCFLAG crcflag;
} CrcIndicationData;

// Define the pool of structures to manage
static CrcIndicationData *pool = NULL;

// Define the maximum number of structures that can be allocated at once
#define MAX_STRUCTURES 1000

// Define the mutex for thread-safe access to the pool
static pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the condition variable for signaling when a structure is available
static pthread_cond_t structure_available = PTHREAD_COND_INITIALIZER;

// Define the current number of structures in use
static int num_structures = 0;

// Define the maximum allowed limit for the number of structures
#define MAX_LIMIT 10000

// Define the external logging library to record detailed information about each structure's creation
extern void log_crc_indication(CrcIndicationData *data);

// Function to dynamically manage a pool of CRC indication structures
void manage_crc_indications(NFAPI_CRC_INDICATION_PDU_T *pdu, RX_UE_INFORMATION_TAG rx_ue_info, CRCFLAG crcflag) {
    // Lock the mutex to ensure thread-safe access to the pool
    pthread_mutex_lock(&pool_mutex);

    // Check if there is a structure available in the pool
    while (num_structures >= MAX_LIMIT) {
        // If not, wait for a signal that a structure is available
        pthread_cond_wait(&structure_available, &pool_mutex);
    }

    // Allocate memory for a new structure
    CrcIndicationData *data = malloc(sizeof(CrcIndicationData));

    // Initialize the structure with the given data
    memcpy(&data->pdu, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    data->rx_ue_info = rx_ue_info;
    data->crcflag = crcflag;

    // Log the creation of the structure using the external logging library
    log_crc_indication(data);

    // Increment the number of structures in use
    num_structures++;

    // Unlock the mutex to allow other threads to access the pool
    pthread_mutex_unlock(&pool_mutex);
}

// Function to release a structure from the pool
void release_crc_indication(CrcIndicationData *data) {
    // Lock the mutex to ensure thread-safe access to the pool
    pthread_mutex_lock(&pool_mutex);

    // Decrement the number of structures in use
    num_structures--;

    // Free the memory for the structure
    free(data);

    // Signal that a structure is available to other threads
    pthread_cond_signal(&structure_available);

    // Unlock the mutex to allow other threads to access the pool
    pthread_mutex_unlock(&pool_mutex);
}

// Function to monitor the current number of structures in use
int get_num_structures() {
    return num_structures;
}

// Function to dynamically adjust the maximum allowed limit for the number of structures
void set_max_limit(int new_limit) {
    // Lock the mutex to ensure thread-safe access to the pool
    pthread_mutex_lock(&pool_mutex);

    // Set the new maximum limit
    MAX_LIMIT = new_limit;

    // Unlock the mutex to allow other threads to access the pool
    pthread_mutex_unlock(&pool_mutex);
}
