#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

// Define a struct to represent a sensor reading
struct SensorReading {
    int timestamp;
    float temperature;
    float humidity;
};

// Define a function to read and process a batch of sensor readings from a file
void processBatch(char* filename, char* outputFilename, char* rules, bool verbose, char* statFuncId, int maxRecordSize, int batchInterval) {
    // Open the input file and allocate memory for the batch of sensor readings
    FILE* fp = fopen(filename, "r");
    struct SensorReading* batch = (struct SensorReading*)malloc(batchInterval * sizeof(struct SensorReading));

    // Read and process each record in the batch
    for (int i = 0; i < batchInterval; i++) {
        fscanf(fp, "%d %f %f", &batch[i].timestamp, &batch[i].temperature, &batch[i].humidity);

        // Apply filtering and aggregation rules to the current record
        if (strcmp(rules, "filter") == 0) {
            // Filter out records with temperature or humidity values outside of the specified range
            if (batch[i].temperature < 20 || batch[i].temperature > 30 || batch[i].humidity < 40 || batch[i].humidity > 60) {
                continue;
            }
        } else if (strcmp(rules, "aggregate") == 0) {
            // Aggregate the temperature and humidity values for each record
            float avgTemp = 0.0f;
            float avgHum = 0.0f;
            int count = 0;
            for (int j = i - batchInterval + 1; j <= i; j++) {
                avgTemp += batch[j].temperature;
                avgHum += batch[j].humidity;
                count++;
            }
            batch[i].temperature = avgTemp / count;
            batch[i].humidity = avgHum / count;
        }

        // Check if the record exceeds the maximum size constraint and resize it if necessary
        if (sizeof(struct SensorReading) > maxRecordSize) {
            struct SensorReading* newBatch = (struct SensorReading*)realloc(batch, batchInterval * sizeof(struct SensorReading));
            if (newBatch == NULL) {
                printf("Error: Failed to resize batch of sensor readings\n");
                return;
            }
            batch = newBatch;
        }
    }

    // Compute the specified statistical measure for each batch of records
    float* stats = (float*)malloc(batchInterval * sizeof(float));
    for (int i = 0; i < batchInterval; i++) {
        if (strcmp(statFuncId, "mean") == 0) {
            stats[i] = (batch[i].temperature + batch[i].humidity) / 2.0f;
        } else if (strcmp(statFuncId, "median") == 0) {
            // Compute the median of the temperature and humidity values for each record
            float tempMedian = 0.0f;
            float humMedian = 0.0f;
            int count = 0;
            for (int j = i - batchInterval + 1; j <= i; j++) {
                tempMedian += batch[j].temperature;
                humMedian += batch[j].humidity;
                count++;
            }
            stats[i] = (tempMedian / count) + (humMedian / count);
        } else if (strcmp(statFuncId, "mode") == 0) {
            // Compute the mode of the temperature and humidity values for each record
            float tempMode = 0.0f;
            float humMode = 0.0f;
            int count = 0;
            for (int j = i - batchInterval + 1; j <= i; j++) {
                if (batch[j].temperature == tempMode) {
                    count++;
                } else if (count > 0) {
                    tempMode = batch[j].temperature;
                    count = 1;
                }
                if (batch[j].humidity == humMode) {
                    count++;
                } else if (count > 0) {
                    humMode = batch[j].humidity;
                    count = 1;
                }
            }
            stats[i] = (tempMode + humMode) / 2.0f;
        }
    }

    // Write the processed batch of sensor readings to a file
    FILE* outFile = fopen(outputFilename, "a");
    for (int i = 0; i < batchInterval; i++) {
        fprintf(outFile, "%d %f %f\n", batch[i].timestamp, batch[i].temperature, batch[i].humidity);
    }
    fclose(outFile);

    // Write the statistical measures to a separate section of the report file
    FILE* statsFile = fopen("stats.txt", "a");
    for (int i = 0; i < batchInterval; i++) {
        fprintf(statsFile, "%d %f\n", batch[i].timestamp, stats[i]);
    }
    fclose(statsFile);

    // Free memory allocated for the batch of sensor readings and statistical measures
    free(batch);
    free(stats);
}

// Define a function to process a large dataset of sensor readings
void processDataset(char* filename, char* outputFilename, char* rules, bool verbose, char* statFuncId, int maxRecordSize, int batchInterval) {
    // Open the input file and allocate memory for the entire dataset
    FILE* fp = fopen(filename, "r");
    struct SensorReading* dataset = (struct SensorReading*)malloc(sizeof(struct SensorReading));

    // Read and process each record in the dataset
    while (!feof(fp)) {
        fscanf(fp, "%d %f %f", &dataset[i].timestamp, &dataset[i].temperature, &dataset[i].humidity);

        // Apply filtering and aggregation rules to the current record
        if (strcmp(rules, "filter") == 0) {
            // Filter out records with temperature or humidity values outside of the specified range
            if (dataset[i].temperature < 20 || dataset[i].temperature > 30 || dataset[i].humidity < 40 || dataset[i].humidity > 60) {
                continue;
            }
        } else if (strcmp(rules, "aggregate") == 0) {
            // Aggregate the temperature and humidity values for each record
            float avgTemp = 0.0f;
            float avgHum = 0.0f;
            int count = 0;
            for (int j = i - batchInterval + 1; j <= i; j++) {
                avgTemp += dataset[j].temperature;
                avgHum += dataset[j].humidity;
                count++;
            }
            dataset[i].temperature = avgTemp / count;
            dataset[i].humidity = avgHum / count;
        }

        // Check if the record exceeds the maximum size constraint and resize it if necessary
        if (sizeof(struct SensorReading) > maxRecordSize) {
            struct SensorReading* newDataset = (struct SensorReading*)realloc(dataset, batchInterval * sizeof(struct SensorReading));
            if (newDataset == NULL) {
                printf("Error: Failed to resize dataset of sensor readings\n");
                return;
            }
            dataset = newDataset;
        }
    }

    // Process the dataset in batches, writing each batch to a separate file and computing statistical measures for each batch
    int i = 0;
    while (i < batchInterval) {
        processBatch(filename, outputFilename, rules, verbose, statFuncId, maxRecordSize, batchInterval);
        i += batchInterval;
    }

    // Free memory allocated for the entire dataset
    free(dataset);
}

// Define a function to compute statistical measures for a given set of sensor readings
void computeStats(char* filename, char* statFuncId) {
    // Open the input file and allocate memory for the entire dataset
    FILE* fp = fopen(filename, "r");
    struct SensorReading* dataset = (struct SensorReading*)malloc(sizeof(struct SensorReading));

    // Read each record in the dataset and compute the specified statistical measure
    while (!feof(fp)) {
        fscanf(fp, "%d %f %f", &dataset[i].timestamp, &dataset[i].temperature, &dataset[i].humidity);
        if (strcmp(statFuncId, "mean") == 0) {
            // Compute the mean of the temperature and humidity values for each record
            float tempMean = 0.0f;
            float humMean = 0.0f;
            int count = 0;
            for (int j = i - batchInterval + 1; j <= i; j++) {
                tempMean += dataset[j].temperature;
                humMean += dataset[j].humidity;
                count++;
            }
            printf("%d %f\n", dataset[i].timestamp, (tempMean / count) + (humMean / count));
        } else if (strcmp(statFuncId, "median") == 0) {
            // Compute the median of the temperature and humidity values for each record
            float tempMedian = 0.0f;
            float humMedian = 0.0f;
            int count = 0;
            for (int j = i - batchInterval + 1; j <= i; j++) {
                tempMedian += dataset[j].temperature;
                humMedian += dataset[j].humidity;
                count++;
            }
            printf("%d %f\n", dataset[i].timestamp, (tempMedian / count) + (humMedian / count));
        } else if (strcmp(statFuncId, "mode") == 0) {
            // Compute the mode of the temperature and humidity values for each record
            float tempMode = 0.0f;
            float humMode = 0.0f;
            int count = 0;
            for (int j = i - batchInterval + 1; j <= i; j++) {
                if (dataset[j].temperature == tempMode) {
                    count++;
                } else if (count > 0) {
                    tempMode = dataset[j].temperature;
                    count = 1;
                }
                if (dataset[j].humidity == humMode) {
                    count++;
                } else if (count > 0) {
                    humMode = dataset[j].humidity;
                    count = 1;
                }
            }
            printf("%d %f\n", dataset[i].timestamp, (tempMode + humMode) / 2.0f);
        }
    }

    // Free memory allocated for the entire dataset
    free(dataset);
