#include <pthread.h>
#include <syslog.h>

// Define the log levels
#define LOG_LEVEL_INFO 0
#define LOG_LEVEL_WARNING 1
#define LOG_LEVEL_ERROR 2

// Define the environment variables for logging configuration
#define ENV_LOG_LEVEL "LOG_LEVEL"
#define ENV_LOG_FILENAME "LOG_FILENAME"
#define ENV_LOG_MAX_SIZE "LOG_MAX_SIZE"
#define ENV_LOG_FLUSH_INTERVAL "LOG_FLUSH_INTERVAL"

// Define the default log level and file name if not set in environment variables
#define DEFAULT_LOG_LEVEL LOG_LEVEL_INFO
#define DEFAULT_LOG_FILENAME "/var/log/error.log"
#define DEFAULT_LOG_MAX_SIZE 1024 * 1024 * 5 // 5 MB
#define DEFAULT_LOG_FLUSH_INTERVAL 60 // flush every minute

// Define the buffer size for logging
#define LOG_BUFFER_SIZE 1024

// Define the structure to hold the log message and its metadata
typedef struct {
    char *message;
    int level;
    time_t timestamp;
} LogMessage;

// Define the buffer for logging messages
static LogMessage *log_buffer = NULL;
static size_t log_buffer_size = 0;
static size_t log_buffer_count = 0;

// Define the mutex for thread-safe logging
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the function to log a message with a given level and format string
void log(int level, const char *format, ...) {
    // Acquire the mutex for thread-safe logging
    pthread_mutex_lock(&log_mutex);

    // Check if the buffer is full and needs to be flushed
    if (log_buffer_count >= log_buffer_size) {
        flush_log();
    }

    // Allocate memory for the new message
    LogMessage *message = malloc(sizeof(LogMessage));
    message->level = level;
    message->timestamp = time(NULL);

    // Format the message using snprintf
    va_list args;
    va_start(args, format);
    vsnprintf(message->message, LOG_BUFFER_SIZE, format, args);
    va_end(args);

    // Add the new message to the buffer
    log_buffer[log_buffer_count++] = message;

    // Release the mutex for thread-safe logging
    pthread_mutex_unlock(&log_mutex);
}

// Define the function to flush the log buffer to disk
void flush_log() {
    // Open the log file in append mode
    FILE *file = fopen(getenv(ENV_LOG_FILENAME), "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    // Write each message in the buffer to the log file
    for (size_t i = 0; i < log_buffer_count; i++) {
        LogMessage *message = log_buffer[i];
        fprintf(file, "%s %d %ld\n", message->message, message->level, message->timestamp);
    }

    // Close the log file
    fclose(file);
}

// Define the function to query logged messages within a specified time range
void query_log(time_t start, time_t end) {
    // Open the log file in read mode
    FILE *file = fopen(getenv(ENV_LOG_FILENAME), "r");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    // Read each line of the log file and check if it falls within the specified time range
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        // Parse the message level and timestamp from the line
        int level;
        time_t timestamp;
        sscanf(line, "%d %ld", &level, &timestamp);

        // Check if the message falls within the specified time range
        if (start <= timestamp && timestamp <= end) {
            printf("%s\n", line);
        }
    }

    // Close the log file
    fclose(file);
}

// Define the function to start and stop a Java service with a random delay between operations
void manage_service() {
    // Generate a random delay between 0 and 10 seconds
    int delay = rand() % 10;

    // Start the service after the delay
    printf("Starting service...\n");
    sleep(delay);

    // Stop the service after another random delay between 0 and 10 seconds
    delay = rand() % 10;
    printf("Stopping service...\n");
    sleep(delay);
}
