        printf("Error: Invalid bandwidth. Using default value.\n");
        config->bandwidth = 20; // MHz
    }

    // Validate cell identity against predefined constraints
    if (config->cell_identity < CELL_IDENTITY_MIN || config->cell_identity > CELL_IDENTITY_MAX) {
        printf("Error: Invalid cell identity. Using default value.\n");
        config->cell_identity = 0; // unique identifier for each cell
    }

    // Validate signal strength threshold against predefined constraints
    if (config->signal_strength_threshold < SIGNAL_STRENGTH_THRESHOLD_MIN || config->signal_strength_threshold > SIGNAL_STRENGTH_THRESHOLD_MAX) {
        printf("Error: Invalid signal strength threshold. Using default value.\n");
        config->signal_strength_threshold = -80.0f; // dBm
