// Define the function for calculating the MD5 checksum of a binary asset
unsigned char* calculateMD5Checksum(char* filename) {
    // Open the file and read its contents into a buffer
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) return NULL;
    fseek(fp, 0, SEEK_END);
    long filesize = ftell(fp);
    rewind(fp);
    unsigned char* buffer = malloc(filesize);
    if (buffer == NULL) {
        printf("Error allocating memory for file %s\n", filename);
        fclose(fp);
        return NULL;
    }
    size_t bytes_read = fread(buffer, 1, filesize, fp);
    if (bytes_read < filesize) {
        printf("Error reading file %s\n", filename);
        free(buffer);
        fclose(fp);
        return NULL;
    }
    fclose(fp);

    // Calculate the MD5 checksum of the buffer using a standard library function
    unsigned char* md5sum = malloc(16);
    if (md5sum == NULL) {
        printf("Error allocating memory for MD5 checksum\n");
        free(buffer);
        return NULL;
    }
    MD5_CTX ctx;
    MD5Init(&ctx);
    MD5Update(&ctx, buffer, filesize);
    MD5Final(md5sum, &ctx);

    // Free the memory allocated for the buffer and return the MD5 checksum
    free(buffer);
    return md5sum;
}

