int dns_resolve(const char *hostname, u_char *ip) {
    int ret = 0;
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_DGRAM;
    hints.ai_protocol = IPPROTO_UDP;
    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        return -1;
    }
    struct in_addr *addr = (struct in_addr *) res->ai_addr;
    memcpy(ip, addr->s_addr, 4);
    freeaddrinfo(res);
    return ret;
}

int dns_cache_get(const char *hostname, u_char *ip) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        if (cache[i].hostname == NULL) {
            continue;
        }
        if (strcmp(cache[i].hostname, hostname) == 0) {
            memcpy(ip, cache[i].ip, 4);
            pthread_mutex_unlock(&cache_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return -1;
}

int dns_cache_set(const char *hostname, u_char *ip) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        if (cache[i].hostname == NULL) {
            cache[i].hostname = strdup(hostname);
            memcpy(cache[i].ip, ip, 4);
            pthread_mutex_unlock(&cache_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return -1;
}

int dns_cache_expire(const char *hostname) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        if (cache[i].hostname == NULL) {
            continue;
        }
        if (strcmp(cache[i].hostname, hostname) == 0) {
            free(cache[i].hostname);
            cache[i].hostname = NULL;
            pthread_mutex_unlock(&cache_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return -1;
}

