#define INVALID_BIT_RATE -2
#define INVALID_VIDEO_RESOLUTION -3
#define INVALID_FRAME_RATE -4
#define INVALID_AUDIO_SAMPLE_RATE -5
#define UNEXPECTED_ERROR -6

// Define the function to initialize the media processing pipeline configuration structure
int initMediaPipelineConfig(MediaPipelineConfig *config, int codec_type, int bit_rate, int video_resolution, float frame_rate, int audio_sample_rate) {
    // Validate the input parameters against the constraints
    if (codec_type < 0 || codec_type > 2) {
        printf("Invalid codec type: %d\n", codec_type);
        return INVALID_CODEC_TYPE;
    }
    if (bit_rate < MIN_BIT_RATE || bit_rate > MAX_BIT_RATE) {
        printf("Invalid bit rate: %d\n", bit_rate);
        return INVALID_BIT_RATE;
    }
    if (video_resolution < MIN_VIDEO_RESOLUTION || video_resolution > MAX_VIDEO_RESOLUTION) {
        printf("Invalid video resolution: %dx%d\n", video_resolution.width, video_resolution.height);
        return INVALID_VIDEO_RESOLUTION;
    }
    if (frame_rate < MIN_FRAME_RATE || frame_rate > MAX_FRAME_RATE) {
        printf("Invalid frame rate: %f\n", frame_rate);
        return INVALID_FRAME_RATE;
    }
    if (audio_sample_rate < MIN_AUDIO_SAMPLE_RATE || audio_sample_rate > MAX_AUDIO_SAMPLE_RATE) {
        printf("Invalid audio sample rate: %d\n", audio_sample_rate);
        return INVALID_AUDIO_SAMPLE_RATE;
    }

    // Initialize the configuration structure with the validated parameters
    config->codec_type = codec_type;
    config->bit_rate = bit_rate;
    config->video_resolution = video_resolution;
    config->frame_rate = frame_rate;
    config->audio_sample_rate = audio_sample_rate;

    // Log the final configuration state for debugging and monitoring purposes
    printf("Media pipeline configuration initialized with:\n");
    printf("\tCodec type: %d\n", config->codec_type);
    printf("\tBit rate: %d\n", config->bit_rate);
    printf("\tVideo resolution: %dx%d\n", config->video_resolution.width, config->video_resolution.height);
    printf("\tFrame rate: %f\n", config->frame_rate);
    printf("\tAudio sample rate: %d\n", config->audio_sample_rate);

    return 0;
}

// Define the function to validate the input parameters against the constraints
int validateInputParameters(int codec_type, int bit_rate, int video_resolution, float frame_rate, int audio_sample_rate) {
    // Validate the input parameters against the constraints
    if (codec_type < 0 || codec_type > 2) {
        printf("Invalid codec type: %d\n", codec_type);
        return INVALID_CODEC_TYPE;
    }
