    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the maximum size of the array
#define MAX_ARRAY_SIZE 1024

// Define a mutex for concurrent access to the array
pthread_mutex_t array_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a variable to keep track of the number of elements in the array
size_t num_elements = 0;

// Define a variable to keep track of the total allocated capacity of the array
size_t total_capacity = MAX_ARRAY_SIZE;

// Define a function to add an element to the array
void add_element(NFAPI_CRC_INDICATION_PDU_T *element) {
    // Acquire the mutex for concurrent access to the array
    pthread_mutex_lock(&array_mutex);

    // Check if the array is full and needs to be resized
    if (num_elements == total_capacity) {
        // Resize the array by half
        total_capacity = total_capacity / 2;

        // Reallocate memory for the new size of the array
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(NULL, sizeof(NFAPI_CRC_INDICATION_PDU_T) * total_capacity);

        // Check if the reallocation was successful
        if (new_array == NULL) {
            // Release the mutex and return
            pthread_mutex_unlock(&array_mutex);
            return;
        }

        // Copy the elements from the old array to the new one
        memcpy(new_array, element, sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_elements);

        // Free the memory for the old array
        free(element);

        // Update the pointer to the new array
        element = new_array;
    }

    // Add the new element to the end of the array
    memcpy(&element[num_elements], element, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Increment the number of elements in the array
    num_elements++;

    // Release the mutex
    pthread_mutex_unlock(&array_mutex);
}

// Define a function to update an element in the array
void update_element(NFAPI_CRC_INDICATION_PDU_T *element) {
    // Acquire the mutex for concurrent access to the array
    pthread_mutex_lock(&array_mutex);

    // Check if the element exists in the array
    if (num_elements == 0 || element->RX_UE_INFORMATION_TAG != element[num_elements - 1].RX_UE_INFORMATION_TAG) {
        // Release the mutex and return
        pthread_mutex_unlock(&array_mutex);
        return;
    }

    // Update the element in the array
    memcpy(&element[num_elements - 1], element, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Release the mutex
    pthread_mutex_unlock(&array_mutex);
}

// Define a function to retrieve an element from the array by index
NFAPI_CRC_INDICATION_PDU_T *get_element(size_t index) {
    // Acquire the mutex for concurrent access to the array
    pthread_mutex_lock(&array_mutex);

    // Check if the element exists in the array
    if (index >= num_elements) {
        // Release the mutex and return NULL
        pthread_mutex_unlock(&array_mutex);
        return NULL;
    }

    // Return a pointer to the element at the specified index
    NFAPI_CRC_INDICATION_PDU_T *element = &element[index];

    // Release the mutex
    pthread_mutex_unlock(&array_mutex);

    return element;
}

// Define a function to clear all elements from the array and reset its capacity
void clear_array() {
    // Acquire the mutex for concurrent access to the array
    pthread_mutex_lock(&array_mutex);

    // Free the memory for the old array
    free(element);

    // Reset the number of elements in the array and its capacity
    num_elements = 0;
    total_capacity = MAX_ARRAY_SIZE;

    // Release the mutex
    pthread_mutex_unlock(&array_mutex);
}
