#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define a structure to represent an element in the dynamic array
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
} Element;

// Define a structure to represent the dynamic array
typedef struct {
    Element *elements; // Pointer to the elements in the array
    size_t capacity; // The maximum number of elements that can be stored in the array
    size_t count; // The current number of elements in the array
    pthread_mutex_t mutex; // A mutex for synchronizing access to the array
} DynamicArray;

// Define a function to create a new dynamic array with a specified capacity
DynamicArray *create_dynamic_array(size_t capacity) {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (array == NULL) {
        return NULL;
    }
    array->elements = malloc(capacity * sizeof(Element));
    if (array->elements == NULL) {
        free(array);
        return NULL;
    }
    array->capacity = capacity;
    array->count = 0;
