    // Acquire the mutex for synchronizing access to the array
    pthread_mutex_lock(&array->mutex);

    // Check if the index is valid
    if (index >= array->count) {
        pthread_mutex_unlock(&array->mutex);
        return -1;
    }

    // Update the element in the array
    array->elements[index].pdu = pdu;

    // Release the mutex for synchronizing access to the array
    pthread_mutex_unlock(&array->mutex);

