import java.util.concurrent.BlockingQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;

public class TaskExecutor {
    private final BlockingQueue<Runnable> taskQueue;
    private final ExecutorService executorService;
    private final int maxThreads;
    private final long minIdleTime;
    private final long maxIdleTime;

    public TaskExecutor(int capacity, int maxThreads, long minIdleTime, long maxIdleTime) {
        this.taskQueue = new LinkedBlockingQueue<>(capacity);
        this.executorService = Executors.newFixedThreadPool(maxThreads);
        this.maxThreads = maxThreads;
        this.minIdleTime = minIdleTime;
        this.maxIdleTime = maxIdleTime;
    }

    public void execute(Runnable task) {
        if (taskQueue.offer(task)) {
            executorService.execute(task);
        } else {
            System.out.println("Task queue is full, dropping task");
        }
    }

    public void shutdown() {
        executorService.shutdown();
    }

    public boolean awaitTermination(long timeout, TimeUnit unit) throws InterruptedException {
        return executorService.awaitTermination(timeout, unit);
    }

    private class TaskRunner implements Runnable {
        @Override
        public void run() {
            while (true) {
                try {
                    Runnable task = taskQueue.take();
                    if (task != null) {
                        task.run();
                    } else {
                        break;
                    }
                } catch (InterruptedException e) {
                    System.out.println("Task runner interrupted, exiting");
                    break;
                }
            }
        }
    }
}
