import java.util.concurrent.BlockingQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class TaskExecutor {
    private static final int DEFAULT_CAPACITY = 1000;
    private static final int MIN_THREADS = 2;
    private static final int MAX_THREADS = 5;
    private static final long SHUTDOWN_TIMEOUT = 30L;
    private static final TimeUnit SHUTDOWN_UNIT = TimeUnit.SECONDS;

    private BlockingQueue<Runnable> taskQueue;
    private ExecutorService executorService;

    public TaskExecutor() {
        this(DEFAULT_CAPACITY);
    }

    public TaskExecutor(int capacity) {
        this.taskQueue = new LinkedBlockingQueue<>(capacity);
        this.executorService = Executors.newFixedThreadPool(MIN_THREADS, MAX_THREADS);
    }

    public void execute(Runnable task) throws InterruptedException {
        if (task == null) {
            throw new IllegalArgumentException("Task cannot be null");
        }
        this.taskQueue.put(task);
    }

    public void shutdown() throws InterruptedException {
        this.executorService.shutdown();
        if (!this.executorService.awaitTermination(SHUTDOWN_TIMEOUT, SHUTDOWN_UNIT)) {
            this.executorService.shutdownNow();
        }
    }

    public void pause() {
        this.executorService.pause();
    }

    public void resume() {
        this.executorService.resume();
    }
}
