class NFAPI_CRC_INDICATION_PDU_T:
    def __init__(self, rx_ue_information_tag: int, rnti: int, crc_indication_rel8_tag: int):
        self.rx_ue_information_tag = rx_ue_information_tag
        self.rnti = rnti
        self.crc_indication_rel8_tag = crc_indication_rel8_tag

class NFAPI_CRC_INDICATION_PDU_T_Factory:
    def __init__(self):
        self.factory_functions = {}

    def add_factory_function(self, id: int, factory_function):
