    def create_instance(self, id: int):
        if id in self.factory_functions:
            return self.factory_functions[id]()
        else:
            raise ValueError("Invalid ID")

class NFAPI_CRC_INDICATION_PDU_T_Manager:
    def __init__(self, num_structures: int):
        self.num_structures = num_structures
        self.structures = [None] * num_structures
        self.factory = NFAPI_CRC_INDICATION_PDU_T_Factory()
        self.factory.add_factory_function(1, self._create_structure)

