// Function to create a new device tree structure
device_config* create_device_tree(int size) {
    // Allocate memory for the device tree structure
    device_config* root = (device_config*)malloc(sizeof(device_config));
    if (!root) {
        printf("Error: Failed to allocate memory for device tree\n");
        return NULL;
    }

    // Initialize the device tree structure
    root->device_id = NULL;
    root->power_consumption = 0.0f;
    root->operational_state = "Online";
    root->last_online = time(NULL);
    root->parent = NULL;
    root->left = NULL;
    root->right = NULL;

    // Create a new device config structure for each node in the tree
    for (int i = 0; i < size; i++) {
        device_config* new_device = create_device_config(NULL, 0.0f, "Online");
        if (!new_device) {
            printf("Error: Failed to allocate memory for device config\n");
            return NULL;
        }

        // Add the new device config structure to the tree
        add_node(root, new_device);
    }

    return root;
}

// Function to add a new node to the device tree
void add_node(device_config* parent, device_config* child) {
    // Check if the parent and child nodes are valid
    if (!parent || !child) {
        printf("Error: Invalid parent or child node provided\n");
        return;
    }

    // Add the new node to the tree
    if (parent->left == NULL) {
        parent->left = child;
    } else if (parent->right == NULL) {
        parent->right = child;
    } else {
        printf("Error: Device tree is full\n");
    }
}

// Function to update the device operational state in the tree
void update_device_state(device_config* root, char* device_id, char* new_state) {
    // Check if the device ID and new state are valid
    if (!root || !device_id || !new_state) {
        printf("Error: Invalid device ID or new state provided\n");
        return;
    }

    // Update the operational state of the device in the tree
    device_config* current = root;
    while (current != NULL) {
        if (strcmp(current->device_id, device_id) == 0) {
            update_operational_state(current, new_state);
            break;
        } else {
            current = current->left ? current->left : current->right;
        }
    }
}

// Function to update the device power consumption in the tree
void update_device_power(device_config* root, char* device_id, float new_power) {
    // Check if the device ID and new power are valid
    if (!root || !device_id || new_power <= 0.0f) {
        printf("Error: Invalid device ID or new power provided\n");
        return;
    }

    // Update the power consumption of the device in the tree
    device_config* current = root;
    while (current != NULL) {
        if (strcmp(current->device_id, device_id) == 0) {
            update_power_consumption(current, new_power);
            break;
        } else {
            current = current->left ? current->left : current->right;
        }
    }
}

// Function to update the device last online timestamp in the tree
void update_device_last_online(device_config* root, char* device_id, time_t new_timestamp) {
    // Check if the device ID and new timestamp are valid
    if (!root || !device_id || new_timestamp <= 0) {
        printf("Error: Invalid device ID or new timestamp provided\n");
        return;
    }

    // Update the last online timestamp of the device in the tree
    device_config* current = root;
    while (current != NULL) {
        if (strcmp(current->device_id, device_id) == 0) {
            update_last_online(current, new_timestamp);
            break;
        } else {
            current = current->left ? current->left : current->right;
        }
    }
}

// Function to free the memory allocated for the device tree structure
void free_device_tree(device_config* root) {
    // Check if the root node is valid
    if (!root) {
        printf("Error: Invalid root node provided\n");
        return;
    }

    // Free the memory allocated for each node in the tree
    device_config* current = root;
    while (current != NULL) {
        device_config* temp = current;
        if (temp->left != NULL) {
            free_device_tree(temp->left);
        }
        if (temp->right != NULL) {
            free_device_tree(temp->right);
        }
        free(temp);
        current = current->parent;
    }
}
