    if (locationCoordinates.first < -90.0 || locationCoordinates.first > 90.0 || locationCoordinates.second < -180.0 || locationCoordinates.second > 180.0) {
        throw std::invalid_argument("Invalid location coordinates");
    }
    if (measurementRange <= 0.0) {
        throw std::invalid_argument("Measurement range must be positive");
    }
    if (calibrationFactor < 0.0 || calibrationFactor > 1.0) {
        throw std::invalid_argument("Calibration factor must be between 0 and 1");
    }

    // Initialize the sensor configuration structure
    SensorConfiguration config;
    config.type = type;
    config.samplingFrequency = samplingFrequency;
    config.locationCoordinates = locationCoordinates;
    config.measurementRange = measurementRange;
    config.calibrationFactor = calibrationFactor;

