const BibleBooks = {
  "Genesis": {
    "chapters": 50,
    "verses": 31539
  },
  "Exodus": {
    "chapters": 40,
    "verses": 18270
  },
  // ... (additional books)
};

const BibleRegex = /(?:^|\s)(?:the|a|an)?\s*(?<book>Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)(?:\s|$)/gi;

function getBibleBooks(text) {
  const books = {};
  let match;
  while ((match = BibleRegex.exec(text)) !== null) {
    const bookName = match[1].toLowerCase();
    if (bookName in BibleBooks) {
      books[bookName] = (books[bookName] || 0) + 1;
    }
  }
  return Object.entries(books).map(([book, count]) => ({
    book: book.charAt(0).toUpperCase() + book.slice(1),
    frequency: count,
    chapterCount: BibleBooks[book].chapters,
    verseCount: BibleBooks[book].verses
  }));
}

// Example usage:
const text = "The book of Genesis is the first book of the Bible and contains the account of creation.";
console.log(getBibleBooks(text)); // Output: [{ book: 'Genesis', frequency: 1, chapterCount: 50, verseCount: 31539 }]
