// Define the project structure
typedef struct {
    char* name;
    int priority_level;
    char* status;
    time_t start_date;
} Project;

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to generate an array of projects
Project* generate_projects(int num_projects) {
    // Check if the number of projects is valid
    if (num_projects <= 0) {
        fprintf(stderr, "Invalid number of projects: %d\n", num_projects);
        return NULL;
    }

    // Allocate memory for the array of projects
    Project* projects = malloc(sizeof(Project) * num_projects);
    if (projects == NULL) {
        fprintf(stderr, "Failed to allocate memory for %d projects\n", num_projects);
        return NULL;
    }

    // Initialize the array of projects
    for (int i = 0; i < num_projects; i++) {
        Project* project = &projects[i];
        project->name = malloc(sizeof(char) * 256);
        if (project->name == NULL) {
            fprintf(stderr, "Failed to allocate memory for project name\n");
            return NULL;
        }
        project->priority_level = i + 1;
        project->status = malloc(sizeof(char) * 256);
        if (project->status == NULL) {
            fprintf(stderr, "Failed to allocate memory for project status\n");
            return NULL;
        }
        project->start_date = time(NULL);
    }

    // Return the array of projects
    return projects;
}

// Define the function to generate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* generate_nfapi_crc_indication_pdus(int num_ues) {
    // Check if the number of UEs is valid
    if (num_ues <= 0) {
        fprintf(stderr, "Invalid number of UEs: %d\n", num_ues);
        return NULL;
    }

    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_pdus = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_ues);
    if (nfapi_crc_indication_pdus == NULL) {
        fprintf(stderr, "Failed to allocate memory for %d NFAPI_CRC_INDICATION_PDU_T structures\n", num_ues);
        return NULL;
    }

    // Initialize the array of NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < num_ues; i++) {
        NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_pdu = &nfapi_crc_indication_pdus[i];
        nfapi_crc_indication_pdu->rx_ue_information_tag.rnti = i + 1;
        nfapi_crc_indication_pdu->crc_indication_rel8_tag.crc_flag = rand() % 2;
    }

    // Return the array of NFAPI_CRC_INDICATION_PDU_T structures
    return nfapi_crc_indication_pdus;
}

