    if (!validateTopologySpecs(topology_specs)) {
        invalid_config.topology_specs = topology_specs;
        printf("Invalid topology specs: %s\n", topology_specs);
    }

    // If any of the parameters failed validation, return NULL and store the invalid configuration
    if (invalid_config.cell_identity || invalid_config.modulation_type || invalid_config.bandwidth || invalid_config.signal_threshold || invalid_config.topology_specs) {
        printf("Invalid configuration detected\n");
        return NULL;
    }

    // Initialize the network configuration structure
    NetworkConfig* config = (NetworkConfig*)malloc(sizeof(NetworkConfig));
    if (!config) {
        printf("Failed to allocate memory for network configuration\n");
        return NULL;
    }

    // Set the active configuration index and store the configuration in memory
    config->active_config_index = active_config_index;
    strcpy(config->modulation_type, modulation_type);
    config->bandwidth = bandwidth;
    config->cell_identity = cell_identity;
    config->signal_threshold = signal_threshold;
    strcpy(config->topology_specs, topology_specs);

