import java.security.MessageDigest;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class StringHasher {
    private static final int MAX_BATCH_SIZE = 10000; // maximum number of strings processed in a single call

    public Map<String, String> hashStrings(List<String> strings) throws Exception {
        if (strings == null || strings.isEmpty()) {
            return new HashMap<>();
        }

        int batchSize = Math.min(MAX_BATCH_SIZE, strings.size()); // limit the maximum number of strings processed in a single call
        Map<String, String> hashes = new HashMap<>(batchSize);

        for (int i = 0; i < batchSize; i++) {
            String string = strings.get(i);
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] bytes = md.digest(string.getBytes());
            String hash = bytesToHexString(bytes);
            hashes.put(string, hash);
        }

        return hashes;
    }

    private static String bytesToHexString(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < bytes.length; i++) {
            sb.append(Integer.toString((bytes[i] & 0xff) + 0x100, 16).substring(1));
        }
        return sb.toString();
    }
}
```
