    char* parameter;
    char* value;
};

// Define the structure to store network reliability settings
struct ReliabilitySettings {
    int redundancy_level;
    enum SensingProtocol backup_protocol;
    bool fault_tolerance_enabled;
};

// Define the function to initialize the sensor network configuration
void initializeSensorNetwork(int active_config_index, struct SensorConfig* config) {
    // Validate the input parameters
    if (active_config_index < 0 || active_config_index >= MAX_CONFIG_COUNT) {
        printf("Invalid active configuration index: %d\n", active_config_index);
        return;
    }

    struct SensorConfig* current_config = &config[active_config_index];

    // Validate the sensing protocol
    if (current_config->sensing_protocol < SIMPLE_POLLING || current_config->sensing_protocol > MQTT_PUBSUB) {
        printf("Invalid sensing protocol: %d\n", current_config->sensing_protocol);
        return;
    }

    // Validate the sampling frequency
    if (current_config->sampling_frequency < 1 || current_config->sampling_frequency > 10) {
        printf("Invalid sampling frequency: %d\n", current_config->sampling_frequency);
        return;
    }

    // Validate the sensor ID
    if (current_config->sensor_id < 1 || current_config->sensor_id > 512) {
        printf("Invalid sensor ID: %d\n", current_config->sensor_id);
        return;
    }

    // Validate the environmental thresholds
    if (current_config->thresholds.temperature < -273 || current_config->thresholds.temperature > 500) {
        printf("Invalid temperature threshold: %f\n", current_config->thresholds.temperature);
        return;
    }

    if (current_config->thresholds.humidity < 0 || current_config->thresholds.humidity > 100) {
        printf("Invalid humidity threshold: %f\n", current_config->thresholds.humidity);
        return;
    }

    // Validate the network reliability settings
    if (current_config->reliability_settings.redundancy_level < 1 || current_config->reliability_settings.redundancy_level > 3) {
        printf("Invalid redundancy level: %d\n", current_config->reliability_settings.redundancy_level);
        return;
    }

    if (current_config->reliability_settings.backup_protocol < SIMPLE_POLLING || current_config->reliability_settings.backup_protocol > MQTT_PUBSUB) {
        printf("Invalid backup protocol: %d\n", current_config->reliability_settings.backup_protocol);
        return;
    }

    if (current_config->reliability_settings.fault_tolerance_enabled != true && current_config->reliability_settings.fault_tolerance_enabled != false) {
        printf("Invalid fault tolerance setting: %d\n", current_config->reliability_settings.fault_tolerance_enabled);
        return;
    }

    // Store the invalid configurations in a separate structure
    struct InvalidConfig* invalid_configs = NULL;
    int num_invalid_configs = 0;

    for (int i = 0; i < MAX_CONFIG_COUNT; i++) {
        if (i != active_config_index) {
            struct SensorConfig* config = &config[i];
            if (config->sensing_protocol < SIMPLE_POLLING || config->sensing_protocol > MQTT_PUBSUB) {
                invalid_configs[num_invalid_configs].sensor_id = i;
                invalid_configs[num_invalid_configs].parameter = "sensing_protocol";
                invalid_configs[num_invalid_configs].value = config->sensing_protocol;
                num_invalid_configs++;
            }

            if (config->sampling_frequency < 1 || config->sampling_frequency > 10) {
                invalid_configs[num_invalid_configs].sensor_id = i;
                invalid_configs[num_invalid_configs].parameter = "sampling_frequency";
                invalid_configs[num_invalid_configs].value = config->sampling_frequency;
                num_invalid_configs++;
            }

            if (config->sensor_id < 1 || config->sensor_id > 512) {
                invalid_configs[num_invalid_configs].sensor_id = i;
                invalid_configs[num_invalid_configs].parameter = "sensor_id";
                invalid_configs[num_invalid_configs].value = config->sensor_id;
                num_invalid_configs++;
            }

            if (config->thresholds.temperature < -273 || config->thresholds.temperature > 500) {
                invalid_configs[num_invalid_configs].sensor_id = i;
                invalid_configs[num_invalid_configs].parameter = "temperature";
                invalid_configs[num_invalid_configs].value = config->thresholds.temperature;
                num_invalid_configs++;
            }

            if (config->thresholds.humidity < 0 || config->thresholds.humidity > 100) {
                invalid_configs[num_invalid_configs].sensor_id = i;
                invalid_configs[num_invalid_configs].parameter = "humidity";
                invalid_configs[num_invalid_configs].value = config->thresholds.humidity;
                num_invalid_configs++;
            }

            if (config->reliability_settings.redundancy_level < 1 || config->reliability_settings.redundancy_level > 3) {
                invalid_configs[num_invalid_configs].sensor_id = i;
                invalid_configs[num_invalid_configs].parameter = "redundancy_level";
                invalid_configs[num_invalid_configs].value = config->reliability_settings.redundancy_level;
                num_invalid_configs++;
            }

            if (config->reliability_settings.backup_protocol < SIMPLE_POLLING || config->reliability_settings.backup_protocol > MQTT_PUBSUB) {
                invalid_configs[num_invalid_configs].sensor_id = i;
                invalid_configs[num_invalid_configs].parameter = "backup_protocol";
                invalid_configs[num_invalid_configs].value = config->reliability_settings.backup_protocol;
                num_invalid_configs++;
            }

            if (config->reliability_settings.fault_tolerance_enabled != true && config->reliability_settings.fault_tolerance_enabled != false) {
                invalid_configs[num_invalid_configs].sensor_id = i;
                invalid_configs[num_invalid_configs].parameter = "fault_tolerance_enabled";
                invalid_configs[num_invalid_configs].value = config->reliability_settings.fault_tolerance_enabled;
                num_invalid_configs++;
            }
        }
    }

    // Handle unexpected conditions gracefully
    if (num_invalid_configs > 0) {
        printf("Invalid configuration detected, please correct the following parameters:\n");
        for (int i = 0; i < num_invalid_configs; i++) {
            struct InvalidConfig* invalid_config = &invalid_configs[i];
            printf("Sensor ID: %d, Parameter: %s, Value: %f\n", invalid_config->sensor_id, invalid_config->parameter, invalid_config->value);
        }
    } else {
        // Setup the sensor network configuration
        for (int i = 0; i < MAX_CONFIG_COUNT; i++) {
            struct SensorConfig* config = &config[i];
            if (i == active_config_index) {
                // Activate the current configuration
                printf("Activating sensor network configuration %d\n", active_config_index);
                setupSensorNetwork(config);
            } else {
                // Deactivate all other configurations
                printf("Deactivating sensor network configuration %d\n", i);
                deactivateSensorNetwork(config);
            }
        }
    }
}

// Define the function to setup the sensor network
void setupSensorNetwork(struct SensorConfig* config) {
    // Setup the sensing protocol
    switch (config->sensing_protocol) {
        case SIMPLE_POLLING:
            printf("Setting up simple polling for sensor ID %d\n", config->sensor_id);
            break;
        case UDP_STREAMING:
            printf("Setting up UDP streaming for sensor ID %d\n", config->sensor_id);
            break;
        case MQTT_PUBSUB:
            printf("Setting up MQTT pub/sub for sensor ID %d\n", config->sensor_id);
            break;
    }

    // Setup the sampling frequency
    printf("Setting sampling frequency to %d Hz for sensor ID %d\n", config->sampling_frequency, config->sensor_id);

    // Setup the environmental thresholds
    printf("Setting temperature threshold to %f for sensor ID %d\n", config->thresholds.temperature, config->sensor_id);
    printf("Setting humidity threshold to %f for sensor ID %d\n", config->thresholds.humidity, config->sensor_id);

    // Setup the network reliability settings
    printf("Setting redundancy level to %d for sensor ID %d\n", config->reliability_settings.redundancy_level, config->sensor_id);
    printf("Setting backup protocol to %d for sensor ID %d\n", config->reliability_settings.backup_protocol, config->sensor_id);
    printf("Setting fault tolerance enabled to %d for sensor ID %d\n", config->reliability_settings.fault_tolerance_enabled, config->sensor_id);
}

// Define the function to deactivate a sensor network configuration
void deactivateSensorNetwork(struct SensorConfig* config) {
    // Deactivate the sensing protocol
    switch (config->sensing_protocol) {
        case SIMPLE_POLLING:
            printf("Deactivating simple polling for sensor ID %d\n", config->sensor_id);
            break;
        case UDP_STREAMING:
            printf("Deactivating UDP streaming for sensor ID %d\n", config->sensor_id);
            break;
        case MQTT_PUBSUB:
            printf("Deactivating MQTT pub/sub for sensor ID %d\n", config->sensor_id);
            break;
    }

    // Deactivate the sampling frequency
    printf("Deactivating sampling frequency for sensor ID %d\n", config->sensor_id);

    // Deactivate the environmental thresholds
    printf("Deactivating temperature threshold for sensor ID %d\n", config->sensor_id);
    printf("Deactivating humidity threshold for sensor ID %d\n", config->sensor_id);

    // Deactivate the network reliability settings
    printf("Deactivating redundancy level for sensor ID %d\n", config->sensor_id);
    printf("Deactivating backup protocol for sensor ID %d\n", config->sensor_id);
    printf("Deactivating fault tolerance enabled for sensor ID %d\n", config->sensor_id);
}
```
