void process_directory(const char *dir) {
    DIR *dp;
    struct dirent *ep;
    struct stat sb;
    int i = 0;
    char new_filename[MAX_FILENAME_LEN];
    file_type type;

    if ((dp = opendir(dir)) == NULL) {
        perror("opendir");
        return;
    }

    while ((ep = readdir(dp)) != NULL) {
        snprintf(new_filename, MAX_FILENAME_LEN, "%s/%s", dir, ep->d_name);
        if (stat(new_filename, &sb) == -1) {
            perror("stat");
            continue;
        }

        type = classify_file(ep->d_name, sb.st_size);
        switch (type) {
            case TEXT:
                snprintf(new_filename, MAX_FILENAME_LEN, "%s/%s.txt", dir, ep->d_name);
                break;
            case BINARY:
                snprintf(new_filename, MAX_FILENAME_LEN, "%s/%s.bin", dir, ep->d_name);
                break;
            default:
                snprintf(new_filename, MAX_FILENAME_LEN, "%s/%s.%s", dir, ep->d_name, DEFAULT_EXTENSION);
        }

        if (rename(new_filename, ep->d_name) == -1) {
            perror("rename");
            continue;
        }
    }

    closedir(dp);
}

file_type classify_file(const char *filename, size_t size) {
    FILE *fp;
    int c;
    int count = 0;
    int percent_nonprintable = 0;

    if ((fp = fopen(filename, "r")) == NULL) {
        perror("fopen");
        return UNKNOWN;
    }

    while ((c = fgetc(fp)) != EOF) {
        if (!isprint(c)) {
            percent_nonprintable++;
        }
        count++;
    }

    fclose(fp);

    if (percent_nonprintable > 0.5 * count) {
        return BINARY;
    } else {
        return TEXT;
    }
}
