#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <errno.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>
#include <json-c/json.h>

// Define the structure for a device configuration
typedef struct {
    char* name;
    uint32_t version;
    void* settings;
    setting* settings_array;
} device_config;

// Define the structure for a setting
typedef struct {
    device* device;
    char* key;
    enum value_type {string, integer, float};
    union value {
        char* string;
        int32_t integer;
        float float;
    } value;
} setting;

// Define the shared settings structure
typedef struct {
    uint32_t num_settings;
    setting** settings;
} shared_settings;

// Define the function to serialize a device configuration to JSON format
void serialize_device_config(const device_config* config, json_object* root) {
    // Add the name of the device to the JSON object
    json_object_object_add(root, "name", json_object_new_string(config->name));

    // Add the version number of the configuration to the JSON object
    json_object_object_add(root, "version", json_object_new_int(config->version));

    // Add the settings array to the JSON object
    json_object* settings = json_object_new_array();
    for (uint32_t i = 0; i < config->num_settings; i++) {
        setting* setting = &config->settings[i];
        json_object* setting_obj = json_object_new_object();
        json_object_object_add(setting_obj, "device", json_object_new_string(setting->device->name));
        json_object_object_add(setting_obj, "key", json_object_new_string(setting->key));
        switch (setting->value_type) {
            case string:
                json_object_object_add(setting_obj, "value", json_object_new_string(setting->value.string));
                break;
            case integer:
                json_object_object_add(setting_obj, "value", json_object_new_int(setting->value.integer));
                break;
            case float:
                json_object_object_add(setting_obj, "value", json_object_new_double(setting->value.float));
                break;
        }
        json_object_array_add(settings, setting_obj);
    }
    json_object_object_add(root, "settings", settings);
}

// Define the function to deserialize a device configuration from JSON format
void deserialize_device_config(const json_object* root, device_config* config) {
    // Get the name of the device from the JSON object
    const char* name = json_object_get_string(json_object_object_get(root, "name"));
    if (name == NULL) {
        printf("Error: Could not find 'name' field in JSON object\n");
        return;
    }
    config->name = strdup(name);

    // Get the version number of the configuration from the JSON object
    int32_t version = json_object_get_int(json_object_object_get(root, "version"));
    if (version == -1) {
        printf("Error: Could not find 'version' field in JSON object\n");
        return;
    }
    config->version = version;

    // Get the settings array from the JSON object
    json_object* settings = json_object_object_get(root, "settings");
    if (settings == NULL) {
        printf("Error: Could not find 'settings' field in JSON object\n");
        return;
    }
    config->num_settings = json_object_array_length(settings);
    config->settings = malloc(sizeof(setting*) * config->num_settings);
    for (uint32_t i = 0; i < config->num_settings; i++) {
        json_object* setting = json_object_array_get_idx(settings, i);
        if (setting == NULL) {
            printf("Error: Could not find setting %d in JSON object\n", i);
            return;
        }
        setting* new_setting = malloc(sizeof(setting));
        config->settings[i] = new_setting;
        // Get the device name from the JSON object
        const char* device_name = json_object_get_string(json_object_object_get(setting, "device"));
        if (device_name == NULL) {
            printf("Error: Could not find 'device' field in setting %d\n", i);
            return;
        }
        new_setting->device = strdup(device_name);
