        const char* key = json_object_get_string(json_object_object_get(setting, "key"));
        if (key == NULL) {
            printf("Error: Could not find 'key' field in setting %d\n", i);
            return;
        }
        new_setting->key = strdup(key);
        // Get the value type from the JSON object
        enum value_type value_type = json_object_get_int(json_object_object_get(setting, "value"));
        if (value_type == -1) {
            printf("Error: Could not find 'value' field in setting %d\n", i);
            return;
        }
        new_setting->value_type = value_type;
        // Get the value from the JSON object
        switch (new_setting->value_type) {
            case string:
                const char* string_value = json_object_get_string(json_object_object_get(setting, "value"));
                if (string_value == NULL) {
                    printf("Error: Could not find 'value' field in setting %d\n", i);
                    return;
                }
                new_setting->value.string = strdup(string_value);
                break;
            case integer:
                int32_t integer_value = json_object_get_int(json_object_object_get(setting, "value"));
                if (integer_value == -1) {
                    printf("Error: Could not find 'value' field in setting %d\n", i);
                    return;
                }
                new_setting->value.integer = integer_value;
                break;
            case float:
                double float_value = json_object_get_double(json_object_object_get(setting, "value"));
                if (float_value == -1) {
                    printf("Error: Could not find 'value' field in setting %d\n", i);
                    return;
                }
                new_setting->value.float = float_value;
                break;
        }
    }
