// Define the function to store a device configuration in a memory-mapped file
void store_device_config(const device_config* config, const char* filename) {
    // Open the memory-mapped file for writing
    int fd = open(filename, O_RDWR | O_CREAT, 0644);
    if (fd == -1) {
        printf("Error: Could not open file %s\n", filename);
        return;
    }

    // Serialize the device configuration to JSON format
    json_object* root = json_object_new();
    serialize_device_config(config, root);

    // Write the JSON data to the memory-mapped file
    char* json_data = json_object_to_json_string(root);
    write(fd, json_data, strlen(json_data));

    // Close the memory-mapped file
    close(fd);
}

// Define the function to load a device configuration from a memory-mapped file
void load_device_config(const char* filename, device_config* config) {
    // Open the memory-mapped file for reading
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        printf("Error: Could not open file %s\n", filename);
        return;
    }

    // Read the JSON data from the memory-mapped file
    char* json_data = malloc(sizeof(char) * 4096);
    read(fd, json_data, 4096);

    // Deserialize the JSON data to a device configuration
    json_object* root = json_tokener_parse(json_data);
    deserialize_device_config(root, config);

    // Close the memory-mapped file
    close(fd);
}

// Define the function to update a device configuration based on new settings
void update_device_config(device_config* config, const char* key, void* value) {
    // Find the setting with the specified key in the configuration
    for (uint32_t i = 0; i < config->num_settings; i++) {
        if (strcmp(config->settings[i]->key, key) == 0) {
            // Update the value of the setting
            switch (config->settings[i]->value_type) {
                case string:
                    free(config->settings[i]->value.string);
                    config->settings[i]->value.string = strdup((char*)value);
                    break;
                case integer:
                    config->settings[i]->value.integer = (int32_t)value;
                    break;
                case float:
                    config->settings[i]->value.float = (double)value;
                    break;
            }
            return;
        }
    }
}

// Define the function to update a device configuration based on new settings
void update_shared_settings(const char* key, void* value) {
    // Find the setting with the specified key in the shared settings structure
    for (uint32_t i = 0; i < shared_settings->num_settings; i++) {
        if (strcmp(shared_settings->settings[i]->key, key) == 0) {
            // Update the value of the setting
            switch (shared_settings->settings[i]->value_type) {
                case string:
                    free(shared_settings->settings[i]->value.string);
                    shared_settings->settings[i]->value.string = strdup((char*)value);
                    break;
                case integer:
                    shared_settings->settings[i]->value.integer = (int32_t)value;
                    break;
                case float:
                    shared_settings->settings[i]->value.float = (double)value;
                    break;
            }
            return;
        }
    }
}

