#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <resolv.h>

#define MAX_HOSTNAME_LEN 256
#define DNS_SERVER "8.8.8.8" // Google's public DNS server
#define DNS_PORT 53
#define DNS_TIMEOUT 10 // seconds

// Structure to hold the DNS query data
struct dns_query {
    char hostname[MAX_HOSTNAME_LEN];
    struct sockaddr_in addr;
};

// Function to resolve a given hostname to its IP address using standard library functions
int resolve_hostname(const char *hostname, struct in_addr *ip) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    // Set up the DNS query data structure
    struct dns_query *query = malloc(sizeof(struct dns_query));
    strncpy(query->hostname, hostname, MAX_HOSTNAME_LEN);
    query->addr.sin_family = AF_INET;
    query->addr.sin_port = htons(DNS_PORT);
    inet_pton(AF_INET, DNS_SERVER, &query->addr.sin_addr);

    // Send the DNS query and receive the response
    int ret = sendto(sockfd, query, sizeof(*query), 0, (struct sockaddr *)&query->addr, sizeof(query->addr));
    if (ret < 0) {
        perror("sendto");
        return -1;
    }

    // Read the DNS response and extract the IP address
    char buf[MAX_HOSTNAME_LEN];
    ret = recvfrom(sockfd, buf, MAX_HOSTNAME_LEN, 0, NULL, NULL);
    if (ret < 0) {
        perror("recvfrom");
        return -1;
    }
    *ip = inet_addr(buf);

    // Close the socket and free the query data structure
    close(sockfd);
    free(query);

    return 0;
}
