use std::net::TcpStream;
use std::io::{Read, Write};
use std::error::Error;

// Structure to hold the HTTP request data
struct HttpRequest {
    url: String,
    method: String,
    headers: Vec<(String, String)>,
    body: Option<Vec<u8>>,
}

// Function to create an HTTP client capable of returning a `RequestBuilder` for a given URL
fn http_client(url: &str) -> Result<HttpRequest, Box<dyn Error>> {
    // Create a new TCP stream and connect to the server
    let mut stream = TcpStream::connect(url)?;

    // Read the HTTP request from the stream
    let mut buf = [0u8; 1024];
    let bytes_read = stream.read(&mut buf)?;
    if bytes_read == 0 {
        return Err("Failed to read HTTP request".into());
    }

    // Parse the HTTP request and extract the URL, method, headers, and body
    let mut url = String::new();
    let mut method = String::new();
    let mut headers = Vec::new();
    let mut body = None;
    for line in buf.split(|&b| b == b'\n') {
        if line.starts_with(b"GET ") || line.starts_with(b"POST ") {
            method = String::from_utf8(line[4..].to_vec())?;
        } else if line.starts_with(b"Host:") {
            url = String::from_utf8(line[6..].to_vec())?;
        } else if line.starts_with(b"Content-Length:") {
            let content_length = String::from_utf8(line[14..].to_vec())?;
            body = Some(stream.read(&mut buf)?);
        }
    }

    // Create a new `HttpRequest` object and return it
    Ok(HttpRequest {
        url,
        method,
        headers,
        body,
    })
}
