        printf("Invalid cell ID: %d\n", cell_id);
        return ERROR_FAILURE;
    }
    if (signal_threshold < SIGNAL_THRESHOLD_MIN || signal_threshold > SIGNAL_THRESHOLD_MAX) {
        printf("Invalid signal threshold: %d\n", signal_threshold);
        return ERROR_FAILURE;
    }
    if (channel_alloc < CHANNEL_ALLOC_MIN || channel_alloc > CHANNEL_ALLOC_MAX) {
        printf("Invalid channel allocation strategy: %d\n", channel_alloc);
        return ERROR_FAILURE;
    }

    // Initialize the configuration structure
    config->modulation = modulation;
    config->bandwidth = bandwidth;
    config->cell_id = cell_id;
    config->signal_threshold = signal_threshold;
    config->channel_alloc = channel_alloc;

