    if (config_file == NULL) {
        printf("Failed to open configuration file: %s\n", strerror(errno));
        return ERROR_FAILURE;
    }
    fprintf(config_file, "%d,%d,%d,%d,%d\n", config->modulation, config->bandwidth, config->cell_id, config->signal_threshold, config->channel_alloc);
    fclose(config_file);

    // Log the configuration details for debugging and monitoring purposes
    printf("Configuration initialized successfully:\n");
    printf("\tModulation: %d\n", config->modulation);
    printf("\tBandwidth: %d MHz\n", config->bandwidth);
    printf("\tCell ID: %d\n", config->cell_id);
    printf("\tSignal Threshold: %d dBm\n", config->signal_threshold);
    printf("\tChannel Allocation Strategy: %s\n", channel_alloc_str(config->channel_alloc));

    return ERROR_SUCCESS;
}

// Implement the dynamic update mechanism
int update_config(struct wireless_config *config, int modulation, int bandwidth, int cell_id, int signal_threshold, int channel_alloc) {
