#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

// Define the data structure for storing monitoring parameters
typedef struct {
    int sampling_rate;
    float threshold_values[3];
    int window_size;
    char* data_aggregation_method;
} MonitoringParams;

// Define the data structure for storing the processed data
typedef struct {
    double* data;
    int size;
} ProcessedData;

// Define the function to process and analyze the data stream
void processAndAnalyzeData(MonitoringParams params, ProcessedData* processed_data) {
    // Initialize the data processing structure with the given parameters
    MonitoringParams monitoring_params = params;
    ProcessedData processed_data_struct = *processed_data;

    // Validate the inputs and handle any errors
    if (monitoring_params.sampling_rate <= 0 || monitoring_params.threshold_values[0] < 0 || monitoring_params.window_size <= 0) {
        printf("Invalid input parameters\n");
        return;
    }

    // Initialize the data aggregation method and window size
    char* data_aggregation_method = monitoring_params.data_aggregation_method;
    int window_size = monitoring_params.window_size;

    // Read the data stream from standard input
    double* data = (double*) malloc(sizeof(double) * window_size);
    for (int i = 0; i < window_size; i++) {
        scanf("%lf", &data[i]);
    }

    // Process the data and identify statistical outliers
    double* outliers = (double*) malloc(sizeof(double) * window_size);
    int num_outliers = 0;
    for (int i = 0; i < window_size; i++) {
        if (fabs(data[i]) > monitoring_params.threshold_values[0] || fabs(data[i]) < monitoring_params.threshold_values[1]) {
            outliers[num_outliers++] = data[i];
        }
    }

    // Print the identified outliers along with their timestamps and magnitude
    printf("Identified %d statistical outliers:\n", num_outliers);
    for (int i = 0; i < num_outliers; i++) {
        printf("%.2f at time %.2f\n", outliers[i], data[i]);
    }

    // Free the memory allocated for the data and outliers
    free(data);
    free(outliers);
}

// Define the unit tests for validating the function's behavior under various conditions
void testProcessAndAnalyzeData() {
    MonitoringParams params = {10, {0.5, 0.25, 0.1}, 10};
    ProcessedData processed_data;
    processAndAnalyzeData(params, &processed_data);
}

// Define the integration tests for validating the function's behavior under high-load scenarios
void testProcessAndAnalyzeDataHighLoad() {
    MonitoringParams params = {100, {0.5, 0.25, 0.1}, 100};
    ProcessedData processed_data;
    processAndAnalyzeData(params, &processed_data);
}

// Define the integration tests for validating the function's behavior under varying load conditions
void testProcessAndAnalyzeDataVaryingLoad() {
    MonitoringParams params = {100, {0.5, 0.25, 0.1}, 100};
    ProcessedData processed_data;
    processAndAnalyzeData(params, &processed_data);
}
