#include <errno.h>
#include <stdbool.h>

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for project
typedef struct {
    char* name;
    int priority;
    char* status;
    time_t start_date;
} PROJECT;

// Define the array of projects
PROJECT* projects = NULL;

// Define the number of projects
int num_projects = 0;

// Define the mutex for protecting the projects array
pthread_mutex_t projects_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the semaphore for signaling when a project is added or removed
sem_t project_sem;

// Define the function to add a new project
void add_project(char* name, int priority) {
    // Lock the mutex
    pthread_mutex_lock(&projects_mutex);

    // Allocate memory for the new project
    PROJECT* new_project = (PROJECT*)malloc(sizeof(PROJECT));
    if (!new_project) {
        perror("Failed to allocate memory for new project");
        return;
    }

    // Initialize the fields of the new project
    new_project->name = name;
    new_project->priority = priority;
    new_project->status = "Pending";
    new_project->start_date = time(NULL);

    // Add the new project to the array
    projects[num_projects++] = new_project;

    // Unlock the mutex
    pthread_mutex_unlock(&projects_mutex);

    // Signal that a new project has been added
    sem_post(&project_sem);
}

// Define the function to remove a project
void remove_project(int index) {
    // Lock the mutex
    pthread_mutex_lock(&projects_mutex);

    // Free the memory of the removed project
    free(projects[index]);

    // Shift the remaining projects down by one index
    for (int i = index; i < num_projects - 1; i++) {
        projects[i] = projects[i + 1];
    }

    // Decrement the number of projects
    num_projects--;

    // Unlock the mutex
    pthread_mutex_unlock(&projects_mutex);
}

// Define the function to update a project's status
void update_project_status(int index, char* new_status) {
    // Lock the mutex
    pthread_mutex_lock(&projects_mutex);

    // Update the status of the project
    projects[index]->status = new_status;

    // Unlock the mutex
    pthread_mutex_unlock(&projects_mutex);
}

// Define the function to update a project's start date
void update_project_start_date(int index, time_t new_start_date) {
    // Lock the mutex
    pthread_mutex_lock(&projects_mutex);

    // Update the start date of the project
    projects[index]->start_date = new_start_date;

    // Unlock the mutex
    pthread_mutex_unlock(&projects_mutex);
}

// Define the function to get a project's status
