    for (int i = 0; i < num_projects; i++) {
        if (projects[i]->rnti == rnti && !strcmp(projects[i]->name, name)) {
            start_date = projects[i]->start_date;
            break;
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&projects_mutex);

    return start_date;
}
