u_char *dns_resolve(const char *hostname) {
    // Check if hostname is in cache
    dns_cache_entry_t *cache_entry = dns_cache_get(hostname);
    if (cache_entry != NULL && time(NULL) < cache_entry->ttl) {
        return cache_entry->ip;
    }

    // Check rate limiting
    dns_rate_limit_t *rate_limit = dns_rate_limit_get(hostname);
    if (rate_limit != NULL && rate_limit->queries >= DNS_RATE_LIMIT_THRESHOLD) {
        return NULL;
    }

    // Perform DNS resolution and caching
    u_char *ip = dns_resolve_internal(hostname);
    if (ip == NULL) {
        return NULL;
    }
    dns_cache_set(hostname, ip);

    // Update rate limiting
    if (rate_limit != NULL) {
        rate_limit->queries++;
        time_t now = time(NULL);
        if (now - rate_limit->last_query >= DNS_MIN_QUERY_INTERVAL) {
            rate_limit->last_query = now;
        }
    } else {
        dns_rate_limit_set(hostname, 1, time(NULL));
    }

    return ip;
}

u_char *dns_resolve_internal(const char *hostname) {
    // Perform DNS resolution using standard library functions
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_DGRAM;
    hints.ai_protocol = IPPROTO_UDP;
    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        return NULL;
    }
    struct sockaddr_in *sa = (struct sockaddr_in *) res->ai_addr;
    u_char *ip = malloc(sizeof(u_char) * 4);
    memcpy(ip, &sa->sin_addr.s_addr, sizeof(u_char) * 4);
    freeaddrinfo(res);

    return ip;
}

void dns_cache_set(const char *hostname, u_char *ip) {
    // Add entry to DNS cache
    dns_cache_entry_t *cache_entry = malloc(sizeof(dns_cache_entry_t));
    cache_entry->hostname = strdup(hostname);
    memcpy(cache_entry->ip, ip, sizeof(u_char) * 4);
    cache_entry->ttl = time(NULL) + DNS_CACHE_TTL;
    pthread_mutex_lock(&dns_cache_mutex);
    dns_cache[hostname] = cache_entry;
    pthread_mutex_unlock(&dns_cache_mutex);
}

void dns_cache_get(const char *hostname) {
    // Get entry from DNS cache
    pthread_mutex_lock(&dns_cache_mutex);
    dns_cache_entry_t *cache_entry = dns_cache[hostname];
    if (cache_entry != NULL && time(NULL) < cache_entry->ttl) {
        memcpy(ip, cache_entry->ip, sizeof(u_char) * 4);
    } else {
        freeaddrinfo(res);
    }
    pthread_mutex_unlock(&dns_cache_mutex);
}

void dns_rate_limit_set(const char *hostname, int queries, time_t last_query) {
    // Add entry to DNS rate limiting cache
    dns_rate_limit_t *rate_limit = malloc(sizeof(dns_rate_limit_t));
    rate_limit->queries = queries;
    rate_limit->last_query = last_query;
    pthread_mutex_lock(&dns_rate_limit_mutex);
    dns_rate_limit[hostname] = rate_limit;
    pthread_mutex_unlock(&dns_rate_limit_mutex);
}

void dns_rate_limit_get(const char *hostname) {
    // Get entry from DNS rate limiting cache
    pthread_mutex_lock(&dns_rate_limit_mutex);
    dns_rate_limit_t *rate_limit = dns_rate_limit[hostname];
    if (rate_limit != NULL) {
        int queries = rate_limit->queries;
        time_t last_query = rate_limit->last_query;
        pthread_mutex_unlock(&dns_rate_limit_mutex);
        return queries, last_query;
    } else {
        pthread_mutex_unlock(&dns_rate_limit_mutex);
        return 0, time(NULL);
    }
}

