#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <resolv.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>
#include <errno.h>

#define MAX_LINE_LENGTH 1024
#define MAX_HOSTNAME_LENGTH 256
#define MAX_RULES_LENGTH 1024
#define MAX_CACHE_SIZE 10000
#define DNS_TIMEOUT 3 // seconds
#define DNS_RETRY_COUNT 3
#define MIN_THREADS 5
#define MAX_THREADS 10
#define THREAD_JOIN_TIMEOUT 10 // seconds

typedef struct {
    char hostname[MAX_HOSTNAME_LENGTH];
    u_char ip_address[4];
} Host;

typedef struct {
    char *hostname;
    u_char *ip_address;
} HostCacheEntry;

typedef struct {
    int count;
    time_t last_accessed;
} HostCacheEntryMetadata;

typedef struct {
    HostCacheEntry *entries[MAX_CACHE_SIZE];
    HostCacheEntryMetadata metadata[MAX_CACHE_SIZE];
} HostCache;

void initializeHostCache(HostCache *cache) {
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        cache->entries[i] = NULL;
        cache->metadata[i].count = 0;
        cache->metadata[i].last_accessed = time(NULL);
    }
}

void addHostToCache(HostCache *cache, char *hostname, u_char *ip_address) {
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        if (cache->entries[i] == NULL) {
            cache->entries[i] = malloc(sizeof(HostCacheEntry));
            cache->metadata[i].count++;
            strcpy(cache->entries[i]->hostname, hostname);
            memcpy(cache->entries[i]->ip_address, ip_address, 4);
            break;
        } else if (strcmp(cache->entries[i]->hostname, hostname) == 0) {
            cache->metadata[i].count++;
            memcpy(cache->entries[i]->ip_address, ip_address, 4);
            break;
        }
    }
}

void removeHostFromCache(HostCache *cache, char *hostname) {
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        if (cache->entries[i] != NULL && strcmp(cache->entries[i]->hostname, hostname) == 0) {
            cache->metadata[i].count--;
            free(cache->entries[i]);
            cache->entries[i] = NULL;
            break;
        }
    }
}

void updateHostCacheMetadata(HostCache *cache, char *hostname) {
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        if (cache->entries[i] != NULL && strcmp(cache->entries[i]->hostname, hostname) == 0) {
            cache->metadata[i].last_accessed = time(NULL);
            break;
        }
    }
}

void resolveHostname(char *hostname, u_char *ip_address) {
    struct addrinfo hints, *res;
    int err;

    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if ((err = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(err));
        return;
    }

    memcpy(ip_address, res->ai_addr, 4);
}

void generateReportAndResolveHostnames(char *input_log_file, char *output_report_file, char *rules, bool verbose, char *custom_hash_function_identifier, char *hostname, int session_id, int max_concurrent_dns_queries) {
    FILE *input_log = fopen(input_log_file, "r");
    FILE *output_report = fopen(output_report_file, "w");

    if (input_log == NULL || output_report == NULL) {
        fprintf(stderr, "Error opening files\n");
        return;
    }

    HostCache cache;
    initializeHostCache(&cache);

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, input_log) != NULL) {
        // Compute hash and store in report file
        u_char hash[16];
        computeHash(line, custom_hash_function_identifier, hash);
        fprintf(output_report, "%s\n", hash);

        // Resolve hostname and add to cache if not already present
        char hostname[MAX_HOSTNAME_LENGTH];
        u_char ip_address[4];
        resolveHostname(line, ip_address);
        addHostToCache(&cache, line, ip_address);

        // Update cache metadata
        updateHostCacheMetadata(&cache, line);
    }

    fclose(input_log);
    fclose(output_report);
}
