// Subroutine to compute and return the MD5 hash of a provided string parameter
char* getMD5Hash(const char* str) {
    unsigned char md5_hash[MD5_DIGEST_LENGTH];
    if (MD5((unsigned char*)str, strlen(str), md5_hash)) {
        perror("Error computing MD5 hash");
        return NULL;
    }
    char* hash = (char*)malloc(32);
    if (!hash) {
        perror("Error allocating memory for MD5 hash");
        return NULL;
    }
    sprintf(hash, "%08x%08x", md5_hash[0], md5_hash[1]);
    return hash;
}

// Function to get the file type of a given filename
int getFileType(const char* filename) {
    // Check if the filename ends with a valid file extension
    const char* extensions[] = {"txt", "bin", "empty"};
    for (int i = 0; i < sizeof(extensions) / sizeof(extensions[0]); i++) {
        if (strcmp(filename + strlen(filename) - strlen(extensions[i]), extensions[i]) == 0) {
            return i;
        }
    }
    // If the filename does not end with a valid file extension, assume it is an empty file
    return EMPTY_FILE;
}

// Function to get the current time in milliseconds
long getCurrentTime() {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("Error getting current time");
        return 0;
    }
    return ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
