    json_object_set_uint32(root, "timeout", config->timeout);
    json_object_set_uint32(root, "encryption_key_length", config->encryption_key_length);
    json_object_set_float(root, "compression_ratio", config->compression_ratio);
    json_object_set_uint32(root, "update_interval", config->update_interval);

    // Add the settings array to the JSON object
    json_object_set_array(root, "settings", config->settings_array);

    // Serialize the JSON object into a string
    char* json_string = json_serialize_to_string(root);

    // Write the serialized JSON string to a file
