            rx_ue_information_array.data = realloc(rx_ue_information_array.data, (rx_ue_information_array.size + 1) * sizeof(nfapi_crc_indication_pdu_t));
            rx_ue_information_array.data[rx_ue_information_array.size++] = pdu;
        } else if (strncmp(line, "NETWORK_DIRECTORY_SERVICE", 23) == 0) {
            // Allocate memory for the network directory service API and populate it with the data from the line
            network_directory_service_api_t* api = malloc(sizeof(network_directory_service_api_t));
