            // Add the network directory service API to the dynamic array of APIs
            network_directory_service_apis = realloc(network_directory_service_apis, (network_directory_service_apis.size + 1) * sizeof(network_directory_service_api_t));
            network_directory_service_apis[network_directory_service_apis.size++] = api;
        } else {
            // Ignore any other lines in the file
        }
    }

    // Process each RX UE information PDU in the dynamic array
    process_rx_ue_information_pdu_array(&rx_ue_information_array);

    // Process each network directory service API in the dynamic array
    process_network_directory_service_api_array(network_directory_service_apis);

    // Close the file and free any allocated memory
    fclose(file);
    free(line);
    for (int i = 0; i < rx_ue_information_array.size; i++) {
        free(rx_ue_information_array.data[i]);
    }
    free(rx_ue_information_array.data);
    for (int i = 0; i < network_directory_service_apis.size; i++) {
        free(network_directory_service_apis[i]->content_type);
        free(network_directory_service_apis[i]);
    }
    free(network_directory_service_apis);
}
