    int buffer_depth;
    int link_quality_indicator;
} network_interface_config;

// Function to generate and configure network files report
void generateAndConfigureNetworkFilesReport(const char* directory) {
    // Initialize network interface configuration structure
    network_interface_config config = {0};

    // Process each file's metadata, including size, creation time, and last modification time
    for (int i = 0; i < num_files; i++) {
        const char* filename = files[i];
        struct stat file_stat;
        if (stat(filename, &file_stat) == -1) {
            perror("Error getting file metadata");
            continue;
        }

        // Generate a report for each file
        printf("File: %s\n", filename);
        printf("  Size: %ld bytes\n", file_stat.st_size);
        printf("  Creation time: %s\n", ctime(&file_stat.st_ctime));
        printf("  Modification time: %s\n", ctime(&file_stat.st_mtime));

        // Compute and return the MD5 hash of a provided string parameter using a standard library function
        char* md5_hash = computeMD5Hash(filename);
        if (md5_hash == NULL) {
            perror("Error computing MD5 hash");
            continue;
        }
        printf("  MD5 hash: %s\n", md5_hash);
        free(md5_hash);

        // Construct a new filename based on the original filename's characteristics
        char* new_filename = constructNewFilename(filename);
        if (new_filename == NULL) {
            perror("Error constructing new filename");
            continue;
        }
        printf("  New filename: %s\n", new_filename);
        free(new_filename);
    }
}

// Subroutine to compute and return the MD5 hash of a provided string parameter using a standard library function
char* computeMD5Hash(const char* str) {
    // Initialize the MD5 context
    MD5_CTX ctx;
    MD5_Init(&ctx);

    // Update the MD5 context with the input string
    MD5_Update(&ctx, str, strlen(str));

    // Finalize the MD5 hash and return it as a hexadecimal string
    unsigned char md5_hash[MD5_DIGEST_LENGTH];
    MD5_Final(md5_hash, &ctx);
    char* hex_hash = malloc(2 * MD5_DIGEST_LENGTH + 1);
    if (hex_hash == NULL) {
        perror("Error allocating memory for hexadecimal hash");
        return NULL;
    }
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(hex_hash + 2 * i, "%02x", md5_hash[i]);
    }
    hex_hash[2 * MD5_DIGEST_LENGTH] = '\0';
    return hex_hash;
}

// Subroutine to construct a new filename based on the original filename's characteristics
char* constructNewFilename(const char* filename) {
    // Initialize the new filename with the original filename
    int len = strlen(filename);
    char* new_filename = malloc(256);
    if (new_filename == NULL) {
        perror("Error allocating memory for new filename");
        return NULL;
    }
    strcpy(new_filename, filename);

    // Add a timestamp to the new filename
    time_t current_time = time(NULL);
    struct tm* time_info = localtime(&current_time);
    char* timestamp = asctime(time_info);
    strcat(new_filename, timestamp);

    // Add a number of digits equal to half the length of the original filename (rounded down) to the new filename
    int num_digits = len / 2;
    char* digits = malloc(num_digits + 1);
    if (digits == NULL) {
        perror("Error allocating memory for digits");
        return NULL;
    }
    sprintf(digits, "%0*d", num_digits, rand() % 10000);
    strcat(new_filename, digits);

    // Add a file type determined by the last character of the original filename to the new filename
    char last_char = filename[len - 1];
    if (last_char == 't') {
        strcat(new_filename, ".txt");
    } else if (last_char == 'b') {
        strcat(new_filename, ".bin");
    } else if (last_char == 'e') {
        strcat(new_filename, ".empty");
    } else {
        perror("Error determining file type");
        return NULL;
    }

    // Ensure the new filename fits within 256 characters, even when including spaces and special characters
    int new_len = strlen(new_filename);
    if (new_len > 256) {
        perror("Error: new filename exceeds maximum length");
        return NULL;
    }

    // Allocate memory dynamically for the new filename, freeing it after successful construction
    char* new_filename_copy = malloc(new_len + 1);
    if (new_filename_copy == NULL) {
        perror("Error allocating memory for new filename copy");
        return NULL;
    }
    strcpy(new_filename_copy, new_filename);
    free(new_filename);
    return new_filename_copy;
}
