#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

void extendAndOptimizeDataProcessingPipeline(char* data, int size) {
    // Initialize variables for tracking packet processing stats
    int numPackets = 0;
    int numErrors = 0;

    // Iterate over each packet in the data buffer
    for (int i = 0; i < size; i += sizeof(struct Packet)) {
        struct Packet* packet = (struct Packet*)&data[i];

        // Check if the packet is malformed or has a priority level that exceeds the maximum allowed value
        if (!isValidPacket(packet) || packet->priority > MAX_PRIORITY) {
            numErrors++;
            continue;
        }

        // Lock the pipeline to ensure thread safety
        pthread_mutex_lock(&pipelineMutex);

        // Process the packet according to its priority level
        switch (packet->priority) {
            case LOW_PRIORITY:
                processLowPriorityPacket(packet);
                break;
            case MEDIUM_PRIORITY:
                processMediumPriorityPacket(packet);
                break;
            case HIGH_PRIORITY:
                processHighPriorityPacket(packet);
                break;
        }

        // Unlock the pipeline to allow other threads to access it
        pthread_mutex_unlock(&pipelineMutex);

        numPackets++;
    }

    // Log the number of packets successfully processed and any errors encountered
    printf("Processed %d packets, with %d errors\n", numPackets, numErrors);
}

// Check if a packet is valid by verifying its metadata
bool isValidPacket(struct Packet* packet) {
    // Verify the packet timestamp and source IP are within acceptable ranges
    if (packet->timestamp < MIN_TIMESTAMP || packet->timestamp > MAX_TIMESTAMP ||
        packet->sourceIP < MIN_SOURCE_IP || packet->sourceIP > MAX_SOURCE_IP) {
        return false;
    }

    // Verify the payload size is within acceptable limits
    if (packet->payloadSize < MIN_PAYLOAD_SIZE || packet->payloadSize > MAX_PAYLOAD_SIZE) {
        return false;
    }

    return true;
}

// Process a low-priority packet by simply copying it to the output buffer
void processLowPriorityPacket(struct Packet* packet) {
    // Copy the packet to the output buffer
    memcpy(&outputBuffer[outputIndex], packet, sizeof(struct Packet));
    outputIndex += sizeof(struct Packet);
}

// Process a medium-priority packet by copying it to the output buffer and then processing its payload
void processMediumPriorityPacket(struct Packet* packet) {
    // Copy the packet to the output buffer
    memcpy(&outputBuffer[outputIndex], packet, sizeof(struct Packet));
    outputIndex += sizeof(struct Packet);

    // Process the payload of the packet
    processPayload(packet->payload, packet->payloadSize);
}

// Process a high-priority packet by copying it to the output buffer and then processing its payload
void processHighPriorityPacket(struct Packet* packet) {
    // Copy the packet to the output buffer
    memcpy(&outputBuffer[outputIndex], packet, sizeof(struct Packet));
    outputIndex += sizeof(struct Packet);

    // Process the payload of the packet
    processPayload(packet->payload, packet->payloadSize);
}

// Process the payload of a packet by verifying its integrity and then copying it to the output buffer
void processPayload(char* payload, int size) {
    // Verify the payload is within acceptable limits
    if (size < MIN_PAYLOAD_SIZE || size > MAX_PAYLOAD_SIZE) {
        return;
    }

    // Copy the payload to the output buffer
    memcpy(&outputBuffer[outputIndex], payload, size);
    outputIndex += size;
}
