// Define the configuration structure for the wireless communication system
typedef struct {
    int modulation_type; // 0: OFDM, 1: QPSK, 2: PSK
    int bandwidth; // in MHz
    int cell_identity; // unique identifier for each cell
    int transmission_power; // in dBm
    float channel_frequency; // in Hz
} wireless_config;

// Define the constraints for each parameter
#define MODULATION_TYPE_MIN 0
#define MODULATION_TYPE_MAX 2
