    int new_transmission_power = config->transmission_power + (signal_strength - interference);

    // Validate the new transmission power against the constraints
    if (new_transmission_power < TRANSMISSION_POWER_MIN || new_transmission_power > TRANSMISSION_POWER_MAX) {
        printf("Error: Invalid new transmission power\n");
        return ERROR_INVALID_TRANSMISSION_POWER;
    }

    // Update the configuration structure with the new transmission power
    config->transmission_power = new_transmission_power;

    // Return success
    return 0;
}

