// Define the configuration structure for the wireless communication system
typedef struct {
    int modulation_type; // Modulation type (e.g., QPSK, OFDM)
    int bandwidth; // Bandwidth in MHz
    int cell_identity; // Cell identity
    int transmission_power; // Transmission power in dBm
    float snr; // Signal-to-noise ratio in dB
    float antenna_gain; // Antenna gain in dBi
} wireless_config_t;

// Define the NFAPI_CRC_INDICATION_PDU_T structure for CRC indication
