#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

struct Transaction {
    int id;
    string type;
    double amount;
    string date;
};

bool filterTransaction(const Transaction& transaction, const vector<int>& criteria) {
    // Check if the transaction meets the specified criteria
    for (auto criterion : criteria) {
        switch (criterion) {
            case 1: // Age
                if (transaction.id < 30) {
                    return true;
                }
                break;
            case 2: // Amount
                if (transaction.amount > 500) {
                    return true;
                }
                break;
            case 3: // Date
                if (transaction.date < "2022-01-01") {
                    return true;
                }
                break;
        }
    }
    return false;
}

int main() {
    vector<Transaction> transactions = {
        {1, "deposit", 100.0, "2022-01-01"},
        {2, "withdrawal", 500.0, "2022-01-02"},
        {3, "transfer", 200.0, "2022-01-03"},
        {4, "deposit", 300.0, "2022-01-04"},
        {5, "withdrawal", 600.0, "2022-01-05"}
    };

    vector<int> criteria = {1, 2}; // Filter transactions based on age and amount

    // Apply filter to transactions
    vector<Transaction> filteredTransactions;
    for (auto transaction : transactions) {
        if (filterTransaction(transaction, criteria)) {
            filteredTransactions.push_back(transaction);
        }
    }

    // Print filtered transactions
    cout << "Filtered Transactions:" << endl;
    for (auto transaction : filteredTransactions) {
        cout << transaction.id << ", " << transaction.type << ", " << transaction.amount << ", " << transaction.date << endl;
    }

    return 0;
}']

