        // Compute the hash of the line using the specified hash function
        unsigned long hash = compute_hash(resolved_hostname, config.modulation_type, config.bandwidth, config.cell_identity, config.transmit_power);

        // Store the hash and key metrics in the output report file
        fprintf(output_report, "%lu\t%s\n", hash, resolved_hostname);
    }

    // Close the input log file and output report file
    fclose(input_log);
    fclose(output_report);

    // Free the DNS resolution cache
    free(dns_cache);
}

// Define the function for resolving hostnames in the input log file
char* resolve_hostname(char* line, char* dns_cache) {
    // Split the line into tokens using whitespace as a delimiter
    char* token = strtok(line, " ");
    while (token != NULL) {
        if (strncmp(token, "Hostname", 8) == 0) {
            // Resolve the hostname using DNS resolution
            struct in_addr addr;
            int result = inet_pton(AF_INET, token + 9, &addr);
            if (result != 1) {
                printf("Error: unable to resolve hostname\n");
                return NULL;
            }

            // Store the resolved IP address in the DNS resolution cache
            char* ip_address = inet_ntoa(addr);
            strcpy(dns_cache, ip_address);

            // Return the resolved hostname
            return token + 9;
        }

        // Move on to the next token
        token = strtok(NULL, " ");
    }

    // If no hostname is found, return NULL
    return NULL;
}

// Define the function for computing the hash of a line in the input log file
unsigned long compute_hash(char* line, int modulation_type, int bandwidth, int cell_identity, int transmit_power) {
    // Initialize the hash value with the specified parameters
    unsigned long hash = 0;
    hash += (modulation_type << 24);
    hash += (bandwidth << 16);
    hash += (cell_identity << 8);
    hash += transmit_power;

    // Compute the hash of each token in the line using the specified hash function
    char* token = strtok(line, " ");
    while (token != NULL) {
        unsigned long token_hash = compute_hash(token, 0, 0, 0, 0);
        hash += token_hash;

        // Move on to the next token
        token = strtok(NULL, " ");
    }

    return hash;
}
