#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <curl/curl.h>
#include <pthread.h>
#include <time.h>

// Define the structure to hold the authentication token and its expiration time
typedef struct {
    char* token;
    time_t expires;
} auth_token_t;

// Define the function to retrieve the authentication token from the external identity provider
auth_token_t* get_auth_token(const char* api_endpoint, const char* client_id, const char* client_secret) {
    // Initialize the CURL handle and set the URL for the API endpoint
    CURL* curl = curl_easy_init();
    curl_easy_setopt(curl, CURLOPT_URL, api_endpoint);

    // Set the HTTP method to POST and add the client ID and secret as headers
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, "client_id=" + client_id + "&client_secret=" + client_secret);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, "Content-Type: application/x-www-form-urlencoded");

    // Perform the HTTP request and check for errors
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to retrieve authentication token: %s\n", curl_easy_strerror(res));
        return NULL;
