        fprintf(stderr, "Failed to retrieve authentication token: HTTP status code %ld\n", http_code);
        return NULL;
    }

    // Create a new auth_token_t structure and populate it with the access token and expiration time
    auth_token_t* token = malloc(sizeof(auth_token_t));
    token->token = strdup(curl_easy_strerror(res));
    token->expires = time(NULL) + 3600; // Expire the token in one hour

    // Clean up and return the auth_token_t structure
    curl_easy_cleanup(curl);
    return token;
}

