    key_array = (int*)malloc(sizeof(int) * 10);
    records = (Record*)malloc(sizeof(Record) * 10);

    // Initialize the arrays and records
    for (i = 0; i < 10; i++) {
        offset_array[i] = i * 10;
        key_array[i] = i + 1;
        records[i].key = i + 1;
    }

    // Serialize the records into a binary format using the custom serialization function
    serialize(records, 10, &data);

    // Encrypt the serialized data using AES-CBC with the provided encryption key, IV, and padding
    encrypt(data, sizeof(Record) * 10, key, iv, padding, &ciphertext);

    // Write the encrypted data to a file specified by the user-provided filename
    FILE* fp = fopen(filename, "wb");
    if (fp == NULL) {
        printf("Error: Failed to open file for writing\n");
        return;
    }
    fwrite(ciphertext, sizeof(unsigned char), strlen((char*)ciphertext), fp);
    fclose(fp);

    // Set the value of each record's int field to a random value within a given range
