    // Decrypt the serialized data using AES-CBC with the provided encryption key, IV, and padding
    decrypt(data, sizeof(Record) * 10, key, iv, padding, &plaintext);

    // Deserialize the decrypted plaintext into an array of records using the custom deserialization function
    deserialize(plaintext, sizeof(Record) * 10, &records);

    // Print the values of each record's int field
    for (i = 0; i < 10; i++) {
        printf("Record %d: %d\n", i + 1, records[i].key);
