using namespace std;

// Define the structure for a communication project
struct CommunicationProject {
    char* name;
    int priority;
    string status;
    chrono::time_point<chrono::system_clock> start_date;
};

// Define the cache class
class Cache {
public:
    // Constructor
    Cache(int size) : size_(size), data_(new CommunicationProject[size]) {}

    // Destructor
    ~Cache() { delete[] data_; }

    // Add a new project to the cache
    void add(const CommunicationProject& project) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (size_ == 0) return;
        data_[head_] = project;
        head_ = (head_ + 1) % size_;
        size_--;
    }

    // Get a project from the cache
    CommunicationProject get(const string& name) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (int i = head_; i != tail_; i = (i + 1) % size_) {
            if (data_[i].name == name) return data_[i];
        }
        return CommunicationProject();
    }

private:
    int size_;
    int head_;
    int tail_;
    CommunicationProject* data_;
    std::mutex mutex_;
};

