// Define a function to compute and return the MD5 hash of a provided string parameter
char* md5Hash(char* input) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)input, strlen(input), digest);
    char* output = (char*)malloc(sizeof(char) * 32);
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(output + i * 2, "%02x", digest[i]);
    }
    return output;
}

// Define a function to decrypt a given ciphertext using AES-CBC with a provided encryption key, initialization vector (IV), and padding
void* decrypt(char* ciphertext, char* encryptionKey, char* initializationVector) {
    // Initialize the OpenSSL library
    ERR_load_crypto_strings();
    OPENSSL_add_all_algorithms_conf();
    OPENSSL_add_all_ciphers();
    OPENSSL_add_all_digests();

    // Create an AES-CBC decryption context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();

    // Set the encryption key and initialization vector (IV) for the decryption context
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, (unsigned char*)encryptionKey, (unsigned char*)initializationVector);

    // Decrypt the ciphertext using AES-CBC with padding
    int len = strlen(ciphertext);
    unsigned char* plaintext = (unsigned char*)malloc(sizeof(char) * len);
    EVP_DecryptUpdate(ctx, plaintext, &len, (unsigned char*)ciphertext, len);

    // Free the memory allocated for the decrypted plaintext
    free(plaintext);

    // Close the AES-CBC decryption context
    EVP_CIPHER_CTX_free(ctx);
}

// Define a function to serialize records into a binary format using a custom serialization function
void* serializeRecords(long* offsets, int* keys, NetworkInterfaceConfig config) {
    // Allocate memory for the serialized data
    void* serializedData = malloc(sizeof(char) * 1024);

    // Serialize the network interface configuration parameters into the serialized data
    memcpy(serializedData, &config, sizeof(NetworkInterfaceConfig));

    // Serialize the offset values and key values into the serialized data
    for (int i = 0; i < 10; i++) {
        memcpy(serializedData + sizeof(NetworkInterfaceConfig) + i * sizeof(long), &offsets[i], sizeof(long));
        memcpy(serializedData + sizeof(NetworkInterfaceConfig) + 10 * sizeof(long) + i * sizeof(int), &keys[i], sizeof(int));
    }

    // Return the serialized data
    return serializedData;
}

// Define a function to generate a report for each file in a directory, detailing its original filename, category, size, creation time, and modification time
void generateReportForEachFileInDirectory(char* directoryPath) {
    // Open the directory specified by the user-provided path
    DIR* dir = opendir(directoryPath);
    if (dir == NULL) {
        printf("Error: unable to open directory %s\n", directoryPath);
        return;
    }

    // Iterate over each file in the directory and generate a report for it
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        char* filename = entry->d_name;
        printf("Generating report for file %s\n", filename);

        // Determine the category of the file based on its extension
        int category = 0;
        if (strcmp(filename, ".txt") == 0) {
            category = TEXT_FILE;
        } else if (strcmp(filename, ".bin") == 0) {
            category = BINARY_FILE;
        } else {
            category = EMPTY_FILE;
        }

        // Open the file and determine its size and creation/modification times
        FILE* fp = fopen(filename, "rb");
        if (fp == NULL) {
            printf("Error: unable to open file %s for reading\n", filename);
            continue;
        }
        fseek(fp, 0, SEEK_END);
        long size = ftell(fp);
        fclose(fp);

        struct stat st;
        if (stat(filename, &st) == -1) {
            printf("Error: unable to determine creation/modification times for file %s\n", filename);
            continue;
        }

        // Generate a report for the file based on its category, size, creation time, and modification time
        char* report = (char*)malloc(sizeof(char) * 1024);
        sprintf(report, "Original filename: %s\nCategory: %d\nSize: %ld bytes\nCreation time: %s\nModification time: %s", filename, category, size, ctime(&st.st_ctime), ctime(&st.st_mtime));
        printf("%s\n", report);
    }

    // Close the directory
    closedir(dir);
}

// Define a function to construct a new filename based on the original filename's characteristics, ensuring it includes a timestamp, a number of digits equal to half the length of the original filename (rounded down), and a file type determined by the last character
char* constructNewFilename(char* originalFilename) {
    // Determine the length of the original filename
    int len = strlen(originalFilename);

    // Construct a new filename based on the original filename's characteristics, ensuring it includes a timestamp, a number of digits equal to half the length of the original filename (rounded down), and a file type determined by the last character
    char* newFilename = (char*)malloc(sizeof(char) * 1024);
    sprintf(newFilename, "%s_%d.%c", originalFilename, len / 2, originalFilename[len - 1]);

    // Return the constructed filename
    return newFilename;
}
