// Custom serialization function for the record structure
void serialize_record(const Record* record, char* buffer) {
    // Serialize the string, integer, and floating-point value in the record
    size_t offset = 0;
    memcpy(buffer + offset, record->string, strlen(record->string));
    offset += strlen(record->string);
    memcpy(buffer + offset, &record->integer, sizeof(int));
    offset += sizeof(int);
    memcpy(buffer + offset, &record->float_value, sizeof(float));
    offset += sizeof(float);
}

// Custom deserialization function for the record structure
void deserialize_record(const char* buffer, Record* record) {
    // Deserialize the string, integer, and floating-point value in the record
    size_t offset = 0;
    memcpy(record->string, buffer + offset, strlen(buffer));
    offset += strlen(buffer);
    memcpy(&record->integer, buffer + offset, sizeof(int));
    offset += sizeof(int);
    memcpy(&record->float_value, buffer + offset, sizeof(float));
    offset += sizeof(float);
}

// Custom serialization function for the log structure
void serialize_log(const Log* log, char* buffer) {
    // Serialize the timestamp, reference to a record, and status indicator in the log
    size_t offset = 0;
    memcpy(buffer + offset, &log->timestamp, sizeof(time_t));
    offset += sizeof(time_t);
    memcpy(buffer + offset, &log->record, sizeof(Record*));
    offset += sizeof(Record*);
    memcpy(buffer + offset, &log->status, sizeof(enum {active, inactive}));
    offset += sizeof(enum {active, inactive});
}

// Custom deserialization function for the log structure
void deserialize_log(const char* buffer, Log* log) {
    // Deserialize the timestamp, reference to a record, and status indicator in the log
    size_t offset = 0;
    memcpy(&log->timestamp, buffer + offset, sizeof(time_t));
    offset += sizeof(time_t);
    memcpy(&log->record, buffer + offset, sizeof(Record*));
    offset += sizeof(Record*);
    memcpy(&log->status, buffer + offset, sizeof(enum {active, inactive}));
    offset += sizeof(enum {active, inactive});
}

