#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <errno.h>

// Define the MIME types for text, binary, and unknown content
#define TEXT_MIME "text/plain"
#define BINARY_MIME "application/octet-stream"
#define UNKNOWN_MIME "application/unknown"

// Define the maximum file size in bytes
#define MAX_FILE_SIZE 1024 * 1024 * 5 // 5 MB

// Define the directory path and file extension metadata
char* dir_path = "/path/to/directory";
char* ext_metadata = "application/octet-stream";

// Function to check if a file is text or binary based on its MIME type, size, and metadata
int is_text(const char* filename) {
    // Get the file extension from the filename
    const char* ext = strrchr(filename, '.');
    if (ext == NULL) {
        return 0;
    }

    // Check if the file extension matches any of the known MIME types
    if (strcmp(ext, ".txt") == 0 || strcmp(ext, ".csv") == 0 || strcmp(ext, ".json") == 0) {
        return 1;
    }

    // Check if the file size is greater than the maximum allowed size
    struct stat st;
    if (stat(filename, &st) != 0) {
        perror("Error getting file size");
        return -1;
    }

    if (st.st_size > MAX_FILE_SIZE) {
        return 0;
    }

    // Check if the file contains more than 50% non-printable characters
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening file");
        return -1;
    }

    int c;
    int count = 0;
    while ((c = fgetc(fp)) != EOF) {
        if (!isprint(c)) {
            count++;
        }
    }

    fclose(fp);

    return (count / st.st_size) > 0.5;
}

// Function to rename a file based on its MIME type, size, and metadata
int rename_file(const char* filename, const char* new_filename) {
    // Get the file extension from the filename
    const char* ext = strrchr(filename, '.');
    if (ext == NULL) {
        return 0;
    }

    // Check if the file extension matches any of the known MIME types
    if (strcmp(ext, ".txt") == 0 || strcmp(ext, ".csv") == 0 || strcmp(ext, ".json") == 0) {
        return rename(filename, new_filename);
    }

    // Check if the file size is greater than the maximum allowed size
    struct stat st;
    if (stat(filename, &st) != 0) {
        perror("Error getting file size");
        return -1;
    }

    if (st.st_size > MAX_FILE_SIZE) {
        return 0;
    }

    // Check if the file contains more than 50% non-printable characters
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening file");
        return -1;
    }

    int c;
    int count = 0;
    while ((c = fgetc(fp)) != EOF) {
        if (!isprint(c)) {
            count++;
        }
    }

    fclose(fp);

    // Rename the file based on its MIME type, size, and metadata
    char* mime_type = is_text(filename) ? TEXT_MIME : BINARY_MIME;
    char* size_str = malloc(10);
    sprintf(size_str, "%d", st.st_size);
    char* id_str = malloc(10);
    sprintf(id_str, "%d", rand());
    char* new_file_name = malloc(strlen(filename) + strlen(mime_type) + strlen(size_str) + strlen(id_str) + 3);
    sprintf(new_file_name, "%s.%s.%s.%s", filename, mime_type, size_str, id_str);
    int ret = rename(filename, new_file_name);
    free(size_str);
    free(id_str);
    free(new_file_name);
    return ret;
}

// Function to process a directory containing multiple files and categorize them based on their MIME type, size, and metadata
int process_directory(const char* dir_path) {
    // Get the list of files in the directory
    struct dirent** file_list = NULL;
    int num_files = scandir(dir_path, &file_list, NULL, alphasort);
    if (num_files < 0) {
        perror("Error getting file list");
        return -1;
    }

    // Iterate over the files and categorize them based on their MIME type, size, and metadata
    for (int i = 0; i < num_files; i++) {
        char* filename = file_list[i]->d_name;
        if (is_text(filename)) {
            // Rename the file as text
            char* new_file_name = malloc(strlen(filename) + strlen(TEXT_MIME) + 3);
            sprintf(new_file_name, "%s.%s", filename, TEXT_MIME);
            int ret = rename_file(filename, new_file_name);
            free(new_file_name);
            if (ret < 0) {
                perror("Error renaming file");
                return -1;
            }
        } else if (is_binary(filename)) {
            // Rename the file as binary
            char* new_file_name = malloc(strlen(filename) + strlen(BINARY_MIME) + 3);
            sprintf(new_file_name, "%s.%s", filename, BINARY_MIME);
            int ret = rename_file(filename, new_file_name);
            free(new_file_name);
            if (ret < 0) {
                perror("Error renaming file");
                return -1;
            }
        } else {
            // Rename the file as unknown
            char* new_file_name = malloc(strlen(filename) + strlen(UNKNOWN_MIME) + 3);
            sprintf(new_file_name, "%s.%s", filename, UNKNOWN_MIME);
            int ret = rename_file(filename, new_file_name);
            free(new_file_name);
            if (ret < 0) {
                perror("Error renaming file");
                return -1;
            }
        }
    }

    // Free the memory allocated for the file list
    for (int i = 0; i < num_files; i++) {
        free(file_list[i]);
    }
    free(file_list);

    return 0;
}
