#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>
#include <errno.h>

// Custom memory pool for efficient allocation and deallocation of TCP connection records
struct MemoryPool {
    struct ConnectionRecord* records;
    size_t capacity;
    size_t count;
};

// Function to dynamically allocate memory for a new TCP connection record
struct ConnectionRecord* createConnectionRecord(const char* ip, int port, enum ConnectionState state) {
    struct ConnectionRecord* record = malloc(sizeof(struct ConnectionRecord));
    if (!record) {
        return NULL;
    }
    record->ip = strdup(ip);
    record->port = port;
    record->state = state;
    return record;
}

// Function to dynamically deallocate memory for a TCP connection record
void destroyConnectionRecord(struct ConnectionRecord* record) {
    free(record->ip);
    free(record);
}

// Function to manage a list of TCP connection records, each containing an IP address, port number, and connection state
struct ConnectionList {
    struct MemoryPool* pool;
    size_t count;
};

// Function to create a new empty connection list with a specified capacity
struct ConnectionList* createConnectionList(size_t capacity) {
    struct ConnectionList* list = malloc(sizeof(struct ConnectionList));
    if (!list) {
        return NULL;
    }
    list->pool = createMemoryPool(capacity);
    list->count = 0;
    return list;
}

// Function to destroy a connection list and all its associated records
void destroyConnectionList(struct ConnectionList* list) {
    for (size_t i = 0; i < list->count; i++) {
        destroyConnectionRecord(list->pool->records[i]);
    }
    free(list->pool);
    free(list);
}

// Function to add a new TCP connection record to the list, dynamically allocating memory as needed
int addConnectionRecord(struct ConnectionList* list, const char* ip, int port, enum ConnectionState state) {
    if (list->count >= list->pool->capacity) {
        return -1;
    }
    struct ConnectionRecord* record = createConnectionRecord(ip, port, state);
    if (!record) {
        return -2;
    }
    list->pool->records[list->count++] = record;
    return 0;
}

// Function to remove a TCP connection record from the list by its index
void removeConnectionRecord(struct ConnectionList* list, size_t index) {
    if (index >= list->count) {
        return;
    }
    destroyConnectionRecord(list->pool->records[index]);
    for (size_t i = index + 1; i < list->count; i++) {
        list->pool->records[i - 1] = list->pool->records[i];
    }
    list->count--;
}

// Function to retrieve a TCP connection record from the list by its index
struct ConnectionRecord* getConnectionRecord(struct ConnectionList* list, size_t index) {
    if (index >= list->count) {
        return NULL;
    }
    return list->pool->records[index];
}

