    // Check if the new status is valid
    if (strcmp(new_status, "Pending") == 0 || strcmp(new_status, "In Progress") == 0 || strcmp(new_status, "Completed") == 0 || strcmp(new_status, "Failed") == 0) {
        // Update the status of the project
        project->status = new_status;
    } else {
