        printf("Invalid start date update for project %s\n", project->name);
    }
}

// Define a function to handle concurrency control when updating project statuses and start dates
void handleConcurrency(struct Project* project) {
    // Check if the project is currently being updated by another thread
    if (project->status == "In Progress" || project->start_date > 0) {
        // If the project is currently being updated, wait for the update to complete before proceeding
        while (project->status == "In Progress" || project->start_date > 0) {
            sleep(1);
        }
    }
}

