<?php

function handleUserRequest($_REQUEST) {
    // Validate and save the user request
    $validationResult = validateUserRequest($_REQUEST);
    if ($validationResult['status'] === 'error') {
        return json_encode(['message' => 'error', 'errors' => $validationResult['errors']]);
    }

    $saveResult = saveUserRequest($validationResult['data']);
    if ($saveResult['status'] === 'error') {
        return json_encode(['message' => 'error', 'errors' => $saveResult['errors']]);
    }

    // Handle the user request based on the sub-action
    switch ($_REQUEST['sub_action']) {
        case 'create':
            createUserAccount($validationResult['data']);
            break;
        case 'update':
            updateUserAccount($validationResult['data']);
            break;
        case 'delete':
            deleteUserAccount($_REQUEST['id']);
            break;
    }

    // Return a JSON response with the result of the request
    return json_encode(['message' => 'success']);
}

function validateUserRequest($request) {
    $errors = [];

    // Validate the user ID if present
    if (isset($_REQUEST['id'])) {
        if (!is_numeric($_REQUEST['id']) || $_REQUEST['id'] < 1) {
            $errors[] = 'Invalid user ID';
        }
    }

    // Validate the name and email
    if (!filter_var($_REQUEST['email'], FILTER_VALIDATE_EMAIL)) {
        $errors[] = 'Invalid email address';
    }

    // Validate the password
    if (strlen($_REQUEST['password']) < 8) {
        $errors[] = 'Password must be at least 8 characters long';
    }

    return [
        'status' => count($errors) > 0 ? 'error' : 'success',
        'data' => $request,
        'errors' => $errors
    ];
}

function saveUserRequest($request) {
    // Save the user request to the database
    try {
        $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
        $stmt = $db->prepare("INSERT INTO users (id, name, email, password) VALUES (:id, :name, :email, :password)");
        $stmt->execute([
            ':id' => isset($_REQUEST['id']) ? $_REQUEST['id'] : null,
            ':name' => $_REQUEST['name'],
            ':email' => $_REQUEST['email'],
            ':password' => password_hash($_REQUEST['password'], PASSWORD_DEFAULT)
        ]);
    } catch (PDOException $e) {
        return [
            'status' => 'error',
            'errors' => ['Error saving user request to database']
        ];
    }

    return [
        'status' => 'success',
        'data' => $request
    ];
}

function createUserAccount($request) {
    // Create a new user account with the provided data
    try {
        $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
        $stmt = $db->prepare("INSERT INTO users (name, email, password) VALUES (:name, :email, :password)");
        $stmt->execute([
            ':name' => $_REQUEST['name'],
            ':email' => $_REQUEST['email'],
            ':password' => password_hash($_REQUEST['password'], PASSWORD_DEFAULT)
        ]);
    } catch (PDOException $e) {
        return [
            'status' => 'error',
            'errors' => ['Error creating user account']
        ];
    }
}

function updateUserAccount($request) {
    // Update the user account with the provided ID
    try {
        $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
        $stmt = $db->prepare("UPDATE users SET name = :name, email = :email, password = :password WHERE id = :id");
        $stmt->execute([
            ':id' => $_REQUEST['id'],
            ':name' => $_REQUEST['name'],
            ':email' => $_REQUEST['email'],
            ':password' => password_hash($_REQUEST['password'], PASSWORD_DEFAULT)
        ]);
    } catch (PDOException $e) {
        return [
            'status' => 'error',
            'errors' => ['Error updating user account']
        ];
    }
}

function deleteUserAccount($id) {
    // Delete the user account with the provided ID
    try {
        $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
        $stmt = $db->prepare("DELETE FROM users WHERE id = :id");
        $stmt->execute([
            ':id' => $id
        ]);
    } catch (PDOException $e) {
        return [
            'status' => 'error',
            'errors' => ['Error deleting user account']
        ];
    }
}
