// Define the SessionManager class
class SessionManager {
public:
    // Constructor
    SessionManager(int numThreads) : numThreads_(numThreads), ioService_(numThreads) {}

    // Destructor
    ~SessionManager() {
        for (auto& thread : threads_) {
            thread.join();
        }
    }

    // Start the session manager
    void start() {
        for (int i = 0; i < numThreads_; ++i) {
            threads_.emplace_back(std::thread([this] { ioService_.run(); }));
        }
    }

    // Stop the session manager
    void stop() {
        ioService_.stop();
    }

    // Add a new session to the manager
    void addSession(const std::string& sessionId, const std::string& userId) {
        std::lock_guard<std::mutex> lock(sessionsMutex_);
        sessions_.emplace(sessionId, userId);
    }

    // Remove a session from the manager
    void removeSession(const std::string& sessionId) {
        std::lock_guard<std::mutex> lock(sessionsMutex_);
        sessions_.erase(sessionId);
    }

    // Get the user ID associated with a given session
    std::string getUserId(const std::string& sessionId) {
        std::lock_guard<std::mutex> lock(sessionsMutex_);
        auto it = sessions_.find(sessionId);
        if (it != sessions_.end()) {
            return it->second;
        } else {
            return "";
        }
    }

private:
    // Number of threads to use for the session manager
    int numThreads_;

    // IO service used for asynchronous operations
    io_service ioService_;

    // Map of sessions and their associated user IDs
    std::map<std::string, std::string> sessions_;

    // Mutex to protect access to the session map
    std::mutex sessionsMutex_;

    // Vector of threads used for asynchronous operations
    std::vector<std::thread> threads_;
};
```
