        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = sessions_.begin(); it != sessions_.end(); ++it) {
            if ((*it)->getName() == name) {
                delete *it;
                sessions_.erase(it);
                --numSessions_;
                break;
            }
        }
    }

    // Get the number of session data sources in the pool
    int getNumSessions() {
        std::lock_guard<std::mutex> lock(mutex_);
        return numSessions_;
    }

private:
