// function to perform DNS resolution for a given hostname and return the IP address in a u_char array
int dns_resolve(const char *hostname, u_char *ip) {
    // initialize variables
    struct addrinfo hints, *res;
    int err, i = 0;
    char ip_str[INET6_ADDRSTRLEN];

    // check if hostname is null or empty
    if (hostname == NULL || strlen(hostname) == 0) {
        return -1;
    }

    // initialize addrinfo structure for DNS resolution
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags = AI_V4MAPPED | AI_ADDRCONFIG;

    // perform DNS resolution using getaddrinfo()
    err = getaddrinfo(hostname, NULL, &hints, &res);
    if (err != 0) {
        return -1;
    }

    // iterate through addrinfo structure to find IPv4 or IPv6 address
    for (i = 0; res[i] != NULL; i++) {
        if (res[i]->ai_family == AF_INET || res[i]->ai_family == AF_INET6) {
            break;
        }
    }

    // check if IP address was found
    if (res[i] == NULL) {
        return -1;
    }

    // convert IP address to string and store in u_char array
    inet_ntop(res[i]->ai_family, res[i]->ai_addr->sa_data, ip_str, INET6_ADDRSTRLEN);
    strncpy((char *)ip, ip_str, MAX_IP_LENGTH - 1);

