// Configuration structure for wireless communication system
typedef struct {
    int modulation_type; // 0: OFDM, 1: QPSK, 2: PSK
    int bandwidth; // 0: 20 MHz, 1: 40 MHz, 2: 80 MHz
    int cell_identity; // Unique identifier for the cell
    int transmission_power; // Power in dBm
    float snr; // Signal-to-noise ratio in dB
} wireless_config;

// Initialize configuration structure with default values
void init_config(wireless_config *config) {
    config->modulation_type = 0;
    config->bandwidth = 0;
    config->cell_identity = 1;
    config->transmission_power = 20;
    config->snr = 5.0;
}

// Validate configuration parameters against predefined constraints
int validate_config(wireless_config *config) {
    // Modulation type must be 0 (OFDM), 1 (QPSK), or 2 (PSK)
    if (config->modulation_type != 0 && config->modulation_type != 1 && config->modulation_type != 2) {
        return -1;
    }

    // Bandwidth must be 0 (20 MHz), 1 (40 MHz), or 2 (80 MHz)
    if (config->bandwidth != 0 && config->bandwidth != 1 && config->bandwidth != 2) {
        return -2;
    }

    // Cell identity must be a positive integer
    if (config->cell_identity < 1) {
        return -3;
    }

    // Transmission power must be within the range of [0, 40] dBm
    if (config->transmission_power < 0 || config->transmission_power > 40) {
        return -4;
    }

    // Signal-to-noise ratio must be within the range of [5.0, 15.0] dB
    if (config->snr < 5.0 || config->snr > 15.0) {
        return -5;
    }

    return 0;
}

