// Define the maximum size of the array in bytes
#define MAX_ARRAY_SIZE 1024

// Define the structure for the network service configuration
typedef struct {
    int protocol_version;
    int port_number;
    int authentication_method;
    char* server_address;
} NetworkServiceConfig;

// Define the structure for the CRC indication PDU
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to initialize the network service configuration structure
NetworkServiceConfig* initNetworkServiceConfig(int protocol_version, int port_number, int authentication_method, char* server_address) {
    // Validate the inputs against constraints
    if (protocol_version < 0 || protocol_version > 255) {
        printf("Error: Invalid protocol version\n");
        return NULL;
    }
    if (port_number < 1 || port_number > 65535) {
        printf("Error: Invalid port number\n");
        return NULL;
    }
    if (authentication_method != 0 && authentication_method != 1) {
        printf("Error: Invalid authentication method\n");
        return NULL;
    }
    if (server_address == NULL || strlen(server_address) > MAX_SERVER_ADDRESS_LENGTH) {
        printf("Error: Invalid server address\n");
        return NULL;
    }

    // Allocate memory for the network service configuration structure
    NetworkServiceConfig* config = (NetworkServiceConfig*)malloc(sizeof(NetworkServiceConfig));
    if (config == NULL) {
        printf("Error: Failed to allocate memory for the network service configuration\n");
        return NULL;
    }

    // Populate the network service configuration structure with the given inputs
    config->protocol_version = protocol_version;
    config->port_number = port_number;
    config->authentication_method = authentication_method;
    config->server_address = server_address;

    // Allocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
    int num_structures = 10; // Replace with a more appropriate value
    NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (crc_indication_pdu == NULL) {
        printf("Error: Failed to allocate memory for the CRC indication PDU array\n");
        free(config);
        return NULL;
    }

    // Populate each structure with a unique RX_UE_INFORMATION_TAG, valid RNTI, and CRC_INDICATION_REL8_TAG
    for (int i = 0; i < num_structures; i++) {
        crc_indication_pdu[i].RX_UE_INFORMATION_TAG = i + 1;
        crc_indication_pdu[i].RNTI = i + 1;
        crc_indication_pdu[i].CRC_INDICATION_REL8_TAG = i + 1;
        crc_indication_pdu[i].CRCFLAG = true;
    }

    // Verify that the total length of all structures does not exceed the specified limit
    int total_length = num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (total_length > MAX_ARRAY_SIZE) {
        printf("Error: Total length of CRC indication PDU array exceeds the specified limit\n");
        free(config);
        free(crc_indication_pdu);
        return NULL;
    }

    // Set the CRC indication PDU array in the network service configuration structure
    config->crc_indication_pdu = crc_indication_pdu;

    // Return the initialized network service configuration structure
    return config;
}
