#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define structure for LTE UE Context
typedef struct {
    int ue_id;
    char *active_bearers[10];
    int handover_params[2];
} lte_ue_context_t;

// Define a dynamic array to store the contexts
lte_ue_context_t **contexts = NULL;
int num_contexts = 0;

// Function to add new context
void add_context(int ue_id, char *active_bearers[], int handover_params[]) {
    // Check if the array is full
    if (num_contexts == SIZE) {
        printf("Error: Array is full\n");
        return;
    }

    // Allocate memory for the new context
    lte_ue_context_t *new_context = malloc(sizeof(lte_ue_context_t));
    if (new_context == NULL) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Initialize the new context
    new_context->ue_id = ue_id;
    memcpy(new_context->active_bearers, active_bearers, sizeof(char *) * 10);
    memcpy(new_context->handover_params, handover_params, sizeof(int) * 2);

    // Add the new context to the array
    contexts[num_contexts++] = new_context;
}

// Function to update an existing context
void update_context(int ue_id, char *active_bearers[], int handover_params[]) {
    // Find the index of the context to be updated
    int i;
    for (i = 0; i < num_contexts; i++) {
        if (contexts[i]->ue_id == ue_id) {
            break;
        }
    }

    // Check if the context was found
    if (i == num_contexts) {
        printf("Error: Context not found\n");
        return;
    }

    // Update the active bearers and handover parameters
    memcpy(contexts[i]->active_bearers, active_bearers, sizeof(char *) * 10);
    memcpy(contexts[i]->handover_params, handover_params, sizeof(int) * 2);
}

// Function to retrieve a specific context by UE ID
lte_ue_context_t *get_context(int ue_id) {
    // Find the index of the context to be retrieved
    int i;
    for (i = 0; i < num_contexts; i++) {
        if (contexts[i]->ue_id == ue_id) {
            break;
        }
    }

    // Check if the context was found
    if (i == num_contexts) {
        printf("Error: Context not found\n");
        return NULL;
    }

    // Return the retrieved context
    return contexts[i];
}

// Function to free memory for all contexts
void free_contexts() {
    int i;
    for (i = 0; i < num_contexts; i++) {
        free(contexts[i]);
    }
    free(contexts);
}
