    if (configs == NULL) {
        fprintf(stderr, "Failed to allocate memory for %d wireless communication system configurations\n", num_projects);
        return NULL;
    }

    // Initialize each configuration structure with default values
    for (int i = 0; i < num_projects; i++) {
        configs[i].modulation_type = malloc(1024 * sizeof(char));
        if (configs[i].modulation_type == NULL) {
            fprintf(stderr, "Failed to allocate memory for modulation type\n");
            return NULL;
        }
        strcpy(configs[i].modulation_type, "");
        configs[i].bandwidth = 0;
        configs[i].cell_identity = 0;
        configs[i].transmission_power = 0;
        configs[i].snr = 0.0f;
        configs[i].frequency_offset = 0;
    }

    // Return the array of wireless communication system configurations
    return configs;
}

// Define the function to update the status of a project to a new state based on user input
void updateProjectStatus(communicationProject* project, char* new_status) {
    // Check if the project is valid
    if (project == NULL) {
        fprintf(stderr, "Invalid project\n");
        return;
    }

    // Check if the new status is valid
    if (new_status == NULL || strlen(new_status) == 0) {
        fprintf(stderr, "Invalid new status\n");
        return;
    }

    // Update the project status
    free(project->status);
    project->status = malloc(strlen(new_status) + 1);
    if (project->status == NULL) {
        fprintf(stderr, "Failed to allocate memory for new status\n");
        return;
    }
    strcpy(project->status, new_status);
}

// Define the function to rollback changes made to a project's status if the update fails due to resource constraints or invalid state transitions
void rollbackProjectStatusUpdate(communicationProject* project) {
    // Check if the project is valid
    if (project == NULL) {
        fprintf(stderr, "Invalid project\n");
        return;
    }

    // Rollback the project status update
    free(project->status);
    project->status = malloc(strlen("Pending") + 1);
    if (project->status == NULL) {
        fprintf(stderr, "Failed to allocate memory for rollback status\n");
        return;
    }
    strcpy(project->status, "Pending");
}

// Define the function to process a directory containing multiple files and categorize them into three groups based on their content type (text, binary, or empty)
void processDirectory(char* directory_path) {
    // Check if the directory path is valid
    if (directory_path == NULL || strlen(directory_path) == 0) {
        fprintf(stderr, "Invalid directory path\n");
        return;
    }

    // Open the directory
    DIR* dir = opendir(directory_path);
    if (dir == NULL) {
        fprintf(stderr, "Failed to open directory: %s\n", strerror(errno));
        return;
    }

    // Iterate over the files in the directory
    struct dirent* entry = readdir(dir);
    while (entry != NULL) {
        // Check if the file is a regular file
        if (entry->d_type == DT_REG) {
            // Get the file size and last modification time
            struct stat stats;
            int result = fstatat(dirfd(dir), entry->d_name, &stats, AT_SYMLINK_NOFOLLOW);
            if (result != 0) {
                fprintf(stderr, "Failed to get file information: %s\n", strerror(errno));
                return;
            }

            // Categorize the file based on its content type
            if (S_ISREG(stats.st_mode)) {
                // Text file
                printf("File: %s, Type: Text, Size: %ld bytes, Creation Time: %s, Modification Time: %s\n", entry->d_name, stats.st_size, ctime(&stats.st_ctime), ctime(&stats.st_mtime));
            } else if (S_ISDIR(stats.st_mode)) {
                // Directory
                printf("File: %s, Type: Directory\n", entry->d_name);
            } else {
                // Other file type
                printf("File: %s, Type: Other\n", entry->d_name);
            }
        }

        // Get the next file in the directory
        entry = readdir(dir);
    }

    // Close the directory
    closedir(dir);
}

// Define the function to generate a report that includes the original filename, category, size, creation time, and modification time for each file
void generateReport(char* directory_path) {
    // Check if the directory path is valid
    if (directory_path == NULL || strlen(directory_path) == 0) {
        fprintf(stderr, "Invalid directory path\n");
        return;
    }

    // Open the directory
    DIR* dir = opendir(directory_path);
    if (dir == NULL) {
        fprintf(stderr, "Failed to open directory: %s\n", strerror(errno));
        return;
    }

    // Iterate over the files in the directory
    struct dirent* entry = readdir(dir);
    while (entry != NULL) {
        // Check if the file is a regular file
        if (entry->d_type == DT_REG) {
            // Get the file size and last modification time
            struct stat stats;
            int result = fstatat(dirfd(dir), entry->d_name, &stats, AT_SYMLINK_NOFOLLOW);
            if (result != 0) {
                fprintf(stderr, "Failed to get file information: %s\n", strerror(errno));
                return;
            }

            // Generate the report for the file
            printf("File: %s, Size: %ld bytes, Creation Time: %s, Modification Time: %s\n", entry->d_name, stats.st_size, ctime(&stats.st_ctime), ctime(&stats.st_mtime));
        }

        // Get the next file in the directory
        entry = readdir(dir);
    }

    // Close the directory
    closedir(dir);
}
