// Define struct for sensor event data
struct SensorEvent {
    int id;
    long timestamp;
    float intensity;
};

// Define struct for operational metrics
struct Metrics {
    int max_intensity;
    int max_id;
    int num_events;
    long last_timestamp;
};

// Function to process sensor data streams
void process_sensor_data(struct SensorEvent *event, struct Metrics *metrics) {
    // Check if event is within the last minute
    if (event->timestamp > metrics->last_timestamp - 60) {
        // Increment number of events and update maximum intensity
        metrics->num_events++;
        if (event->intensity > metrics->max_intensity) {
            metrics->max_intensity = event->intensity;
            metrics->max_id = event->id;
        }
    } else {
        // Reset operational metrics if event is older than 1 minute
        metrics->num_events = 0;
        metrics->max_intensity = 0;
        metrics->max_id = -1;
    }
}

// Function to handle high-frequency data streams efficiently and minimize memory usage
void process_sensor_data_efficient(struct SensorEvent *event, struct Metrics *metrics) {
    // Check if event is within the last minute
    if (event->timestamp > metrics->last_timestamp - 60) {
        // Increment number of events and update maximum intensity
        metrics->num_events++;
        if (event->intensity > metrics->max_intensity) {
            metrics->max_intensity = event->intensity;
            metrics->max_id = event->id;
        }
    } else {
        // Reset operational metrics if event is older than 1 minute
        metrics->num_events = 0;
        metrics->max_intensity = 0;
        metrics->max_id = -1;
    }
}
