    unsigned short port;
    bool is_active;
} Stream;

// Define the structure for QoS settings
typedef struct {
    int level;
    int priority;
} QoSSettings;

// Define the function to add a new connection
int addConnection(Connection *conn) {
    // Check if the connection ID is already in use
    if (isConnectionIdInUse(conn->id)) {
        return -1;
    }

    // Add the connection to the list of connections
    conn->sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (conn->sockfd < 0) {
        perror("socket");
        return -1;
    }

    // Set up the connection metadata
    conn->ip_addr = malloc(sizeof(char) * INET_ADDRSTRLEN);
    if (!conn->ip_addr) {
        perror("malloc");
        close(conn->sockfd);
        return -1;
    }
    strcpy(conn->ip_addr, "0.0.0.0");
    conn->port = 0;
    conn->is_active = true;
    conn->num_streams = 0;
    conn->qos_level = 0;

    // Add the connection to the list of connections
    pthread_mutex_lock(&conn_list_mutex);
    conn_list = realloc(conn_list, (num_connections + 1) * sizeof(Connection));
    if (!conn_list) {
        perror("realloc");
        close(conn->sockfd);
        free(conn->ip_addr);
        return -1;
    }
    conn_list[num_connections++] = *conn;
    pthread_mutex_unlock(&conn_list_mutex);

    // Return the connection ID
    return conn->id;
}

// Define the function to update an existing connection
int updateConnection(Connection *conn) {
    // Check if the connection ID is in use
    if (!isConnectionIdInUse(conn->id)) {
        return -1;
    }

    // Update the connection metadata
    pthread_mutex_lock(&conn_list_mutex);
    for (int i = 0; i < num_connections; i++) {
        if (conn_list[i].id == conn->id) {
            conn_list[i] = *conn;
            break;
        }
    }
    pthread_mutex_unlock(&conn_list_mutex);

    // Return the connection ID
    return conn->id;
}

// Define the function to retrieve a specific connection by ID
Connection* getConnectionById(int id) {
    // Check if the connection ID is in use
    if (!isConnectionIdInUse(id)) {
        return NULL;
    }

    // Find the connection with the specified ID
    pthread_mutex_lock(&conn_list_mutex);
    for (int i = 0; i < num_connections; i++) {
        if (conn_list[i].id == id) {
            Connection *conn = &conn_list[i];
            pthread_mutex_unlock(&conn_list_mutex);
            return conn;
        }
    }
    pthread_mutex_unlock(&conn_list_mutex);

    // Return NULL if the connection is not found
    return NULL;
}

// Define the function to add a new data stream within a connection
int addStream(Connection *conn, Stream *stream) {
    // Check if the connection ID is in use
    if (!isConnectionIdInUse(conn->id)) {
        return -1;
    }

    // Add the data stream to the list of streams within the connection
    pthread_mutex_lock(&conn->streams_list_mutex);
    conn->num_streams++;
    conn->streams = realloc(conn->streams, (conn->num_streams + 1) * sizeof(Stream));
    if (!conn->streams) {
        perror("realloc");
        pthread_mutex_unlock(&conn->streams_list_mutex);
        return -1;
    }
    conn->streams[conn->num_streams] = *stream;
    pthread_mutex_unlock(&conn->streams_list_mutex);

    // Return the data stream ID
    return stream->id;
}

// Define the function to update an existing data stream within a connection
int updateStream(Connection *conn, Stream *stream) {
    // Check if the connection ID is in use
    if (!isConnectionIdInUse(conn->id)) {
        return -1;
    }

    // Update the data stream metadata
    pthread_mutex_lock(&conn->streams_list_mutex);
    for (int i = 0; i < conn->num_streams; i++) {
        if (conn->streams[i].id == stream->id) {
            conn->streams[i] = *stream;
            break;
        }
    }
    pthread_mutex_unlock(&conn->streams_list_mutex);

    // Return the data stream ID
    return stream->id;
}

// Define the function to retrieve a specific data stream within a connection by ID
Stream* getStreamById(Connection *conn, int id) {
    // Check if the connection ID is in use
    if (!isConnectionIdInUse(conn->id)) {
        return NULL;
    }

    // Find the data stream with the specified ID within the connection
    pthread_mutex_lock(&conn->streams_list_mutex);
    for (int i = 0; i < conn->num_streams; i++) {
        if (conn->streams[i].id == id) {
            Stream *stream = &conn->streams[i];
            pthread_mutex_unlock(&conn->streams_list_mutex);
            return stream;
        }
    }
    pthread_mutex_unlock(&conn->streams_list_mutex);

    // Return NULL if the data stream is not found
    return NULL;
}

// Define the function to check if a connection ID is in use
bool isConnectionIdInUse(int id) {
    pthread_mutex_lock(&conn_list_mutex);
    for (int i = 0; i < num_connections; i++) {
        if (conn_list[i].id == id) {
            pthread_mutex_unlock(&conn_list_mutex);
            return true;
        }
    }
    pthread_mutex_unlock(&conn_list_mutex);

    // Return false if the connection ID is not in use
    return false;
}

// Define the function to check if a data stream within a connection is active
bool isStreamActive(Connection *conn, int id) {
    pthread_mutex_lock(&conn->streams_list_mutex);
    for (int i = 0; i < conn->num_streams; i++) {
        if (conn->streams[i].id == id) {
            bool is_active = conn->streams[i].is_active;
            pthread_mutex_unlock(&conn->streams_list_mutex);
            return is_active;
        }
    }
    pthread_mutex_unlock(&conn->streams_list_mutex);

    // Return false if the data stream is not active
    return false;
}

// Define the function to check if a connection is healthy
bool isConnectionHealthy(Connection *conn) {
    // Check if the connection is active and has any active streams
    if (!conn->is_active || conn->num_streams == 0) {
        return false;
    }

    // Check if any of the data streams within the connection are not active
    pthread_mutex_lock(&conn->streams_list_mutex);
    for (int i = 0; i < conn->num_streams; i++) {
        if (!conn->streams[i].is_active) {
            pthread_mutex_unlock(&conn->streams_list_mutex);
            return false;
        }
    }
    pthread_mutex_unlock(&conn->streams_list_mutex);

    // Return true if the connection is healthy
    return true;
}

// Define the function to prioritize data streams based on QoS requirements
void prioritizeStreams(Connection *conn) {
    // Sort the data streams within the connection by QoS level and priority
    pthread_mutex_lock(&conn->streams_list_mutex);
    qsort(conn->streams, conn->num_streams, sizeof(Stream), compareStreams);
    pthread_mutex_unlock(&conn->streams_list_mutex);
}

// Define the function to compare data streams based on QoS requirements
int compareStreams(const void *a, const void *b) {
    Stream *sa = (Stream *)a;
    Stream *sb = (Stream *)b;
    if (sa->qos_level > sb->qos_level) {
        return 1;
    } else if (sa->qos_level < sb->qos_level) {
        return -1;
    } else {
        if (sa->priority > sb->priority) {
            return 1;
        } else if (sa->priority < sb->priority) {
            return -1;
        } else {
            return 0;
        }
    }
}

// Define the function to serialize and deserialize connection states for persistence and backup purposes
void serializeConnectionState(Connection *conn, char **state_str) {
    // Serialize the connection metadata
    pthread_mutex_lock(&conn->streams_list_mutex);
    int state_len = 0;
    for (int i = 0; i < conn->num_streams; i++) {
        state_len += strlen(conn->streams[i].ip_addr) + 1;
    }
    char *state = malloc(sizeof(char) * state_len);
    if (!state) {
        perror("malloc");
        pthread_mutex_unlock(&conn->streams_list_mutex);
        return;
    }
    int offset = 0;
    for (int i = 0; i < conn->num_streams; i++) {
        strcpy(state + offset, conn->streams[i].ip_addr);
        offset += strlen(conn->streams[i].ip_addr) + 1;
    }
    pthread_mutex_unlock(&conn->streams_list_mutex);

    // Serialize the connection QoS settings
    int qos_settings_len = sizeof(QoSSettings);
    char *qos_settings = malloc(sizeof(char) * qos_settings_len);
    if (!qos_settings) {
        perror("malloc");
        free(state);
        return;
    }
    memcpy(qos_settings, &conn->qos_level, qos_settings_len);

    // Serialize the connection state string
    int total_len = strlen(state) + qos_settings_len + 1;
    *state_str = malloc(sizeof(char) * total_len);
    if (!*state_str) {
        perror("malloc");
        free(state);
        free(qos_settings);
        return;
    }
    strcpy(*state_str, state);
    memcpy((*state_str) + strlen(state), qos_settings, qos_settings_len);
    (*state_str)[total_len - 1] = '\0';

    // Free the memory allocated for the connection metadata and QoS settings
    free(state);
    free(qos_settings);
}

void deserializeConnectionState(char *state_str, Connection *conn) {
    // Deserialize the connection metadata
    int offset = 0;
    while (offset < strlen(state_str)) {
        Stream *stream = malloc(sizeof(Stream));
        if (!stream) {
            perror("malloc");
            return;
        }
        stream->ip_addr = malloc(sizeof(char) * INET_ADDRSTRLEN);
        if (!stream->ip_addr) {
            perror("malloc");
            free(stream);
            return;
        }
        strcpy(stream->ip_addr, state_str + offset);
        offset += strlen(state_str + offset) + 1;
        stream->port = 0;
        stream->is_active = true;
        conn->num_streams++;
        conn->streams = realloc(conn->streams, (conn->num_streams + 1) * sizeof(Stream));
        if (!conn->streams) {
            perror("realloc");
            free(stream->ip_addr);
            free(stream);
            return;
        }
        conn->streams[conn->num_streams] = *stream;
    }

    // Deserialize the connection QoS settings
    int qos_settings_len = sizeof(QoSSettings);
    memcpy(&conn->qos_level, state_str + offset, qos_settings_len);
    offset += qos_settings_len;

    // Deserialize the connection state string
