#include <sys/types.h>
#include <pthread.h>

// Logging library
#include "logging.h"

// Function to generate a random number of digits between 1 and 5
int rand_digits(void) {
    return (rand() % 5) + 1;
}

// Function to modify the filename's extension to include a timestamp, a random number of digits, and a file type
char* modify_filename(const char* filename) {
    // Get the current time in YYYYMMDDHHMMSS format
    time_t now = time(NULL);
    struct tm* tm_now = localtime(&now);
    char timestamp[14];
    strftime(timestamp, 14, "%Y%m%d%H%M%S", tm_now);

    // Generate a random number of digits between 1 and 5
    int rand_num = rand_digits();

    // Determine the new file type based on the original filename's extension
    char* ext = strrchr(filename, '.');
    if (ext == NULL) {
        return NULL;
    }
    char* new_ext = NULL;
    if (strcmp(ext, ".txt") == 0) {
        new_ext = ".txt";
    } else if (strcmp(ext, ".csv") == 0) {
        new_ext = ".csv";
    } else if (strcmp(ext, ".log") == 0) {
        new_ext = ".log";
    } else if (strcmp(ext, ".xml") == 0) {
        new_ext = ".xml";
    } else {
        return NULL;
    }

    // Create a new filename with the modified extension
    char* new_filename = malloc(256);
    if (new_filename == NULL) {
        return NULL;
    }
    sprintf(new_filename, "%s%s%04d%s", filename, timestamp, rand_num, new_ext);

    // Check if the new filename already exists in the current directory
    struct stat st;
    if (stat(new_filename, &st) == 0) {
        LOG("File %s already exists, generating a new name", new_filename);
        free(new_filename);
        return modify_filename(filename);
    }

    // Return the modified filename
    return new_filename;
}

// Thread-safe function to generate a unique filename for a given input filename
char* generate_unique_filename(const char* filename) {
    pthread_mutex_lock(&mutex);
    char* new_filename = modify_filename(filename);
    pthread_mutex_unlock(&mutex);
    return new_filename;
}
