#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>

#define MAX_DATA_STREAMS 1024
#define MAX_DEVICE_ID_LEN 64
#define MAX_METADATA_LEN 128
#define MAX_DATA_TYPE_LEN 32
#define MAX_TIMESTAMP_LEN 64

typedef struct {
    char device_id[MAX_DEVICE_ID_LEN];
    char data_type[MAX_DATA_TYPE_LEN];
    char timestamp[MAX_TIMESTAMP_LEN];
} metadata_t;

typedef enum {
    OPERATIONAL,
    ALERT,
    DIAGNOSTIC
} data_category_t;

typedef struct {
    int fd;
    char device_id[MAX_DEVICE_ID_LEN];
    metadata_t metadata;
    pthread_mutex_t mutex;
} data_stream_t;

void *data_stream_handler(void *arg) {
    data_stream_t *stream = (data_stream_t *) arg;
    char buffer[MAX_METADATA_LEN];
    ssize_t nread;
    while ((nread = read(stream->fd, buffer, MAX_METADATA_LEN)) > 0) {
        // Process data stream
        printf("Received %ld bytes from device %s\n", nread, stream->device_id);
        // Extract metadata and report
        metadata_t *metadata = (metadata_t *) buffer;
        printf("Metadata: timestamp=%s, device_id=%s, data_type=%s\n", metadata->timestamp, metadata->device_id, metadata->data_type);
    }
    if (nread < 0) {
        perror("Error reading from socket");
    } else {
        printf("Connection closed by device %s\n", stream->device_id);
    }
    close(stream->fd);
    pthread_mutex_destroy(&stream->mutex);
    free(stream);
    return NULL;
}

int main() {
    int i, j;
    data_stream_t *data_streams[MAX_DATA_STREAMS];
    for (i = 0; i < MAX_DATA_STREAMS; i++) {
        data_streams[i] = malloc(sizeof(data_stream_t));
        if (!data_streams[i]) {
            perror("Error allocating memory for data stream");
            return 1;
        }
    }
    // Initialize data streams
    for (i = 0; i < MAX_DATA_STREAMS; i++) {
        data_streams[i]->fd = socket(AF_INET, SOCK_STREAM, 0);
        if (data_streams[i]->fd == -1) {
            perror("Error creating socket");
            return 1;
        }
        struct sockaddr_in server_address;
        memset(&server_address, 0, sizeof(server_address));
        server_address.sin_family = AF_INET;
        server_address.sin_port = htons(8080);
        if (inet_pton(AF_INET, "127.0.0.1", &server_address.sin_addr) <= 0) {
            perror("Error setting address");
            return 1;
        }
        if (connect(data_streams[i]->fd, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
            perror("Error connecting to socket");
            return 1;
        }
        data_streams[i]->device_id[0] = '\0';
        pthread_mutex_init(&data_streams[i]->mutex, NULL);
    }
    // Start data stream handlers
    for (i = 0; i < MAX_DATA_STREAMS; i++) {
        if (pthread_create(&data_streams[i]->tid, NULL, data_stream_handler, data_streams[i]) != 0) {
            perror("Error creating thread");
            return 1;
        }
    }
    // Handle incoming data streams
    while (1) {
        for (i = 0; i < MAX_DATA_STREAMS; i++) {
            if (data_streams[i]->device_id[0] == '\0') {
                continue;
            }
            // Read metadata from data stream
            char buffer[MAX_METADATA_LEN];
            ssize_t nread = read(data_streams[i]->fd, buffer, MAX_METADATA_LEN);
            if (nread > 0) {
                // Extract metadata and report
                metadata_t *metadata = (metadata_t *) buffer;
                printf("Metadata: timestamp=%s, device_id=%s, data_type=%s\n", metadata->timestamp, metadata->device_id, metadata->data_type);
            } else if (nread == 0) {
                // Connection closed by device
                close(data_streams[i]->fd);
                data_streams[i]->device_id[0] = '\0';
            } else {
                perror("Error reading from socket");
            }
        }
    }
    return 0;
}']

