    RX_UE_INFORMATION_TAG rxUeInformationTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to initialize the network service configuration
NetworkServiceConfig* initNetworkServiceConfig(const char* filename, int protocolVersion, int portNumber, const char* authenticationMethod, const char* serverAddress) {
    // Validate the input parameters
    if (filename == NULL || protocolVersion < 0 || portNumber < 0 || authenticationMethod == NULL || serverAddress == NULL) {
        printf("Invalid input parameters\n");
        return NULL;
    }

    // Dynamically allocate memory for the network service configuration structure
    NetworkServiceConfig* config = (NetworkServiceConfig*)malloc(sizeof(NetworkServiceConfig));
    if (config == NULL) {
        printf("Failed to allocate memory for the network service configuration\n");
        return NULL;
    }

    // Initialize the network service configuration structure
    config->protocolVersion = protocolVersion;
    config->portNumber = portNumber;
    config->authenticationMethod = authenticationMethod;
    config->serverAddress = serverAddress;

    // Dynamically allocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
    int numPdus = 10; // Set the number of PDUs to 10
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numPdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdus == NULL) {
        printf("Failed to allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures\n");
        free(config);
        return NULL;
    }

    // Populate each structure with a unique RX_UE_INFORMATION_TAG, valid RNTI, and CRC_INDICATION_REL8_TAG
    for (int i = 0; i < numPdus; i++) {
        pdus[i].rxUeInformationTag = (RX_UE_INFORMATION_TAG)i;
        pdus[i].rnti = (RNTI)(i + 1);
        pdus[i].crcIndicationRel8Tag.crcflag = (CRCFLAG)rand();
    }

    // Verify that the total length of all structures does not exceed the specified limit
    int totalLength = numPdus * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (totalLength > MAX_NFAPI_CRC_INDICATION_PDU_SIZE) {
        printf("The total length of all structures exceeds the specified limit\n");
        free(config);
        free(pdus);
        return NULL;
    }

    // Apply performance optimizations
    config->numPdus = numPdus;
    config->pdus = pdus;

    // Calculate the MD5 hash of the file
    char* md5Hash = generateEnhancedFilename(filename);
    if (md5Hash == NULL) {
        printf("Failed to calculate the MD5 hash of the file\n");
        free(config);
        free(pdus);
        return NULL;
    }

    // Set the enhanced filename
    config->enhancedFilename = md5Hash;

    // Return the initialized network service configuration structure
    return config;
}

// Define the function to generate an enhanced filename based on the original filename's characteristics
char* generateEnhancedFilename(const char* filename) {
    // Validate the input parameters
    if (filename == NULL) {
        printf("Invalid input parameters\n");
        return NULL;
    }

    // Get the file extension and strip it from the original filename
    const char* extension = strrchr(filename, '.');
    if (extension == NULL) {
        printf("Failed to get the file extension\n");
        return NULL;
    }
    int extensionLength = strlen(extension);
    char* strippedFilename = (char*)malloc((strlen(filename) - extensionLength + 1) * sizeof(char));
    if (strippedFilename == NULL) {
        printf("Failed to allocate memory for the stripped filename\n");
        return NULL;
    }
    strncpy(strippedFilename, filename, strlen(filename) - extensionLength);
    strippedFilename[strlen(filename) - extensionLength] = '\0';

    // Construct the new filename using sprintf and strcat
    char* enhancedFilename = (char*)malloc((MAX_ENHANCED_FILENAME_LENGTH + 1) * sizeof(char));
    if (enhancedFilename == NULL) {
        printf("Failed to allocate memory for the enhanced filename\n");
        free(strippedFilename);
        return NULL;
    }
    sprintf(enhancedFilename, "%s_%d.%s", strippedFilename, (int)(time(NULL) % 10000), extension + 1);
    strcat(enhancedFilename, strippedFilename);

    // Free the memory allocated for the stripped filename and return the enhanced filename
    free(strippedFilename);
    return enhancedFilename;
}
