// Define the structure for a data packet
typedef struct {
    time_t timestamp;
    size_t packet_size;
    unsigned char *packet_data;
} DataPacket;

// Define the configuration structure for the wireless communication system
typedef struct {
    int modulation_type;
    int bandwidth;
    int cell_identity;
    int transmission_power;
    float snr;
} WirelessCommunicationConfig;

// Function to initialize and manage a dynamic array of DataPacket structures
void init_data_packets(DataPacket **packets, size_t capacity) {
    // Allocate memory for the array of packets
    *packets = (DataPacket *)malloc(capacity * sizeof(DataPacket));
    if (*packets == NULL) {
        printf("Error: Failed to allocate memory for data packets\n");
        return;
    }

    // Initialize each packet in the array with a timestamp and an empty byte array
    for (size_t i = 0; i < capacity; i++) {
        (*packets)[i].timestamp = time(NULL);
        (*packets)[i].packet_size = 0;
        (*packets)[i].packet_data = NULL;
    }
}

// Function to add a new packet to the dynamic array of DataPacket structures
void add_packet(DataPacket **packets, size_t capacity, const unsigned char *packet_data, size_t packet_size) {
    // Check if the array is full and needs to be resized
    if (capacity == 0 || (*packets)[capacity - 1].timestamp < time(NULL)) {
        // Resize the array by doubling its capacity
        DataPacket *new_packets = (DataPacket *)realloc(*packets, 2 * capacity * sizeof(DataPacket));
        if (new_packets == NULL) {
            printf("Error: Failed to resize data packets array\n");
            return;
        }
        *packets = new_packets;
        capacity *= 2;
    }

    // Add the new packet to the end of the array
    (*packets)[capacity - 1].timestamp = time(NULL);
    (*packets)[capacity - 1].packet_size = packet_size;
    (*packets)[capacity - 1].packet_data = (unsigned char *)malloc(packet_size * sizeof(unsigned char));
    if ((*packets)[capacity - 1].packet_data == NULL) {
        printf("Error: Failed to allocate memory for new packet\n");
        return;
    }
    memcpy((*packets)[capacity - 1].packet_data, packet_data, packet_size);
}

// Function to update an existing packet in the dynamic array of DataPacket structures
void update_packet(DataPacket **packets, size_t capacity, time_t timestamp, const unsigned char *packet_data, size_t packet_size) {
    // Find the index of the packet with the specified timestamp
    size_t i;
    for (i = 0; i < capacity && (*packets)[i].timestamp != timestamp; i++);

    // Check if a matching packet was found
    if (i == capacity) {
        printf("Error: No packet with the specified timestamp was found\n");
        return;
    }

    // Update the packet data and size
    (*packets)[i].packet_size = packet_size;
    memcpy((*packets)[i].packet_data, packet_data, packet_size);
}

// Function to retrieve a packet from the dynamic array of DataPacket structures by timestamp
DataPacket *get_packet(DataPacket **packets, size_t capacity, time_t timestamp) {
    // Find the index of the packet with the specified timestamp
    size_t i;
    for (i = 0; i < capacity && (*packets)[i].timestamp != timestamp; i++);

    // Check if a matching packet was found
    if (i == capacity) {
        return NULL;
    }

    // Return the packet at the specified index
    return &(*packets)[i];
}

