            } else if (strcmp(token, "transmission_power") == 0) {
                token = strtok(NULL, ",");
                transmission_power = atoi(token);
                if (transmission_power < 0 || transmission_power > 100) {
                    printf("Error: Invalid transmission power\n");
                    return;
                }
            } else if (strcmp(token, "snr") == 0) {
                token = strtok(NULL, ",");
                snr = atof(token);
                if (snr < 0.0f || snr > 10.0f) {
                    printf("Error: Invalid SNR\n");
                    return;
                }
            } else {
                printf("Error: Unknown parameter '%s'\n", token);
                return;
            }
        }
    }

    // Update the configuration structure with the validated parameters
    config->modulation_type = modulation_type;
    config->bandwidth = bandwidth;
    config->cell_identity = cell_identity;
    config->transmission_power = transmission_power;
    config->snr = snr;
}
