void add_packet(time_t timestamp, size_t packet_size, unsigned char *packet_data) {
    // Check if there is enough memory available to store the new packet
    if (num_data_packets >= SIZE_MAX / sizeof(DataPacket)) {
        fprintf(stderr, "Error: not enough memory to add a new packet\n");
        return;
    }

    // Allocate memory for the new packet
    DataPacket *new_packet = malloc(sizeof(DataPacket));
    if (new_packet == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for a new packet\n");
        return;
    }

    // Initialize the new packet with the given timestamp and data
    new_packet->timestamp = timestamp;
    new_packet->packet_size = packet_size;
    new_packet->packet_data = malloc(packet_size);
    if (new_packet->packet_data == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for the packet data\n");
        free(new_packet);
        return;
    }
    memcpy(new_packet->packet_data, packet_data, packet_size);

    // Add the new packet to the dynamic array
    data_packets = realloc(data_packets, (num_data_packets + 1) * sizeof(DataPacket));
    if (data_packets == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for the new packet\n");
        free(new_packet->packet_data);
        free(new_packet);
        return;
    }
    data_packets[num_data_packets++] = *new_packet;
}

