    // Update the existing packet with the new data
    DataPacket *existing_packet = &data_packets[i];
    free(existing_packet->packet_data);
    existing_packet->packet_size = packet_size;
    existing_packet->packet_data = malloc(packet_size);
    if (existing_packet->packet_data == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for the new packet data\n");
        return;
    }
    memcpy(existing_packet->packet_data, packet_data, packet_size);
}

