    if (temperature_range[1] < -273.15 || temperature_range[1] > 550) {
        throw invalid_argument("Invalid maximum temperature value: " + to_string(temperature_range[1]));
    }
    if (humidity_threshold < 0 || humidity_threshold > 100) {
