    config.sampling_interval = sampling_interval;
    config.geographic_coordinates[0] = geographic_coordinates[0];
    config.geographic_coordinates[1] = geographic_coordinates[1];
    config.temperature_range[0] = temperature_range[0];
    config.temperature_range[1] = temperature_range[1];
    config.humidity_threshold = humidity_threshold;
    config.battery_level = battery_level;

    // Log detailed information about the configuration state for debugging and monitoring purposes
    cout << "Sensor configuration initialized with the following parameters:" << endl;
    cout << "  Sensor type: " << config.sensor_type << endl;
    cout << "  Sampling interval: " << config.sampling_interval << " seconds" << endl;
