// Function to load a cryptographic module from a specified directory
int load_cryptographic_module(const char* directory, const char* module_name) {
    // Check if the directory and module name are valid
    if (!directory || !module_name) {
        return -1;
    }

    // Open the shared library file
    int fd = open(directory, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open shared library");
        return -1;
    }

    // Get the size of the shared library
    struct stat sb;
    if (fstat(fd, &sb) < 0) {
        perror("Failed to get file size");
        close(fd);
        return -1;
    }

    // Read the contents of the shared library into memory
    void* buffer = malloc(sb.st_size);
    if (!buffer) {
        perror("Failed to allocate memory for shared library");
        close(fd);
        return -1;
    }
    ssize_t bytes_read = read(fd, buffer, sb.st_size);
    if (bytes_read < 0) {
        perror("Failed to read from shared library");
        free(buffer);
        close(fd);
        return -1;
    }

    // Close the file descriptor
    close(fd);

    // Load the shared library into memory
    void* handle = dlopen(directory, RTLD_LAZY | RTLD_GLOBAL);
    if (!handle) {
        perror("Failed to load shared library");
        free(buffer);
        return -1;
    }

    // Get the address of the function in the shared library
    void* (*function)(void) = dlsym(handle, module_name);
    if (!function) {
        perror("Failed to get function address");
        dlclose(handle);
        free(buffer);
        return -1;
    }

    // Free the memory allocated for the shared library
    free(buffer);

    // Return the address of the function
    return (int)function;
}

