    // Initialize the new device
    new_device->device_id = strdup(device_id);
    new_device->cryptographic_function = cryptographic_function;
    new_device->function_parameters = function_parameters;

    // Add the new device to the list of devices
    list->devices[list->size++] = new_device;

    return 0;
}

