public static async Task<SummaryResult> ProcessLargeDataset(SqlConnection connection, string commandText, int batchSize, TimeSpan timeout)
{
    var summary = new SummaryResult();
    using (var cursor = await connection.BeginTransactionAsync())
    {
        try
        {
            while (true)
            {
                var rows = await cursor.ExecuteReaderAsync(commandText, batchSize);
                if (!rows.HasRows) break;

                summary.TotalRows += rows.RecordsAffected;
                while (rows.Read())
                {
                    try
                    {
                        var transformedRow = TransformRow(rows);
                        summary.TransformedRows++;
                    }
                    catch (Exception ex)
                    {
                        summary.Errors.Add(ex);
                    }
                }
            }

            await cursor.CommitAsync();
        }
        catch (Exception ex)
        {
            await cursor.RollbackAsync();
            throw;
        }
    }

    return summary;
}

public class SummaryResult
