            }

            var element = elements[0];

            // Use XPath to find the first child node of the element and return its text content
            xpath = $"{xpath}/*[local-name()='{namespaceUri}']";
            var childNodes = element.SelectNodes(xpath);

            if (childNodes == null || childNodes.Count == 0)
