                var childNodeNames = string.Join(", ", childNodes.Cast<XmlElement>().Select(e => e.Name));
                throw new MultipleElementsFoundException($"Multiple child nodes found with name '{namespaceUri}': {childNodeNames}");
            }

            var childNode = childNodes[0];
