const express = require('express');
const app = express();
const bodyParser = require('body-parser');
const cors = require('cors');
const jwt = require('jsonwebtoken');
const { Validate, LogMessage, UpdatePresence } = require('./helpers');

app.use(bodyParser.urlencoded({ extended: true }));
app.use(bodyParser.json());
app.use(cors());

// Define the route for the chat application
app.post('/chat', (req, res) => {
  // Validate the request object
  const validationResult = Validate(req);
  if (!validationResult.success) {
    return res.status(400).json({ message: 'Invalid request' });
  }

  // Extract the user ID and event type from the request object
  const userId = req.body.user_id;
  const eventType = req.body.event_type;

  // Check if the user is authorized to perform this action
  if (!ValidateUser(userId)) {
    return res.status(403).json({ message: 'Forbidden' });
  }

  // Handle the event type based on its value
  switch (eventType) {
    case 'send_message':
      // Log the message to the chat history
      const message = req.body.message;
      LogMessage(userId, message);
      break;
    case 'update_presence':
      // Update the user's online status
      const presenceStatus = req.body.presence_status;
      UpdatePresence(userId, presenceStatus);
      break;
    default:
      return res.status(400).json({ message: 'Invalid event type' });
  }

  // Send a response back to the client with the updated event type and payload
  const response = {
    success: true,
    event_type: eventType,
    payload: req.body.payload,
  };
  return res.json(response);
});

// Define helper methods for data integrity and accurate logging
function ValidateUser(userId) {
  // Check if the user is authenticated and has the necessary permissions
  const token = req.headers['x-auth-token'];
  if (!token) return false;
  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    if (decoded.user_id !== userId) return false;
  } catch (error) {
    console.log(error);
    return false;
  }
  return true;
