const fs = require('fs');
const path = require('path');
const util = require('util');
const readFileAsync = util.promisify(fs.readFile);
const execFileAsync = util.promisify(require('child_process').execFile);

// Load the files from a local directory
const filePaths = fs.readdirSync('./files/').filter(file => path.extname(file) === '.js');

// Create an object to store the loaded files and their dependencies
const loadedFiles = {};

// Function to load a file and its dependencies
async function loadFile(filePath, dependencies) {
  // Check if the file has already been loaded
  if (loadedFiles[filePath]) {
    return;
  }

  // Load the file and its dependencies
  const fileContent = await readFileAsync(filePath);
  const dependencies = [];
  for (const dependency of dependencies) {
    dependencies.push(await loadFile(dependency));
  }

  // Execute the file with its dependencies
  try {
    await execFileAsync('node', [filePath, ...dependencies]);
  } catch (error) {
    console.log(`Error loading ${filePath}: ${error}`);
  }
}

// Function to load and execute all files in the specified order
async function loadAndExecuteFiles(filePaths) {
  // Load each file and its dependencies
  for (const filePath of filePaths) {
    await loadFile(filePath);
  }

  // Execute each file in the specified order
  for (const filePath of filePaths) {
    const fileContent = await readFileAsync(filePath);
    try {
      await execFileAsync('node', [filePath]);
    } catch (error) {
      console.log(`Error executing ${filePath}: ${error}`);
    }
  }
}

// Function to interrupt the loading process
async function interruptLoading() {
  // TODO: Implement interrupting the loading process
}

// Load and execute all files in the specified order
loadAndExecuteFiles(filePaths).catch(error => console.log(`Error loading files: ${error}`));
