import os
import logging
from datetime import timedelta
from typing import Optional

class AvatarCache:
    def __init__(self, default_avatar_dir: str = None):
        self.default_avatar_dir = default_avatar_dir or "path/to/default/avatar/directory"
        self.cache = {}
        self.access_counts = {}
        self.max_age = timedelta(days=30)

    def get_avatar(self, user_id: int) -> Optional[str]:
        if user_id in self.cache:
            self.access_counts[user_id] += 1
            return self.cache[user_id]
        else:
            return None

    def set_avatar(self, user_id: int, avatar_path: str):
        self.cache[user_id] = avatar_path
        self.access_counts[user_id] = 1

    def clear_avatar(self, user_id: int):
        if user_id in self.cache:
            del self.cache[user_id]
            del self.access_counts[user_id]

    def prune_cache(self):
        for user_id, avatar_path in self.cache.items():
            if self.access_counts[user_id] == 0:
                try:
                    os.remove(avatar_path)
                except OSError as e:
                    logging.error(f"Failed to remove avatar {avatar_path}: {e}")
                finally:
                    del self.cache[user_id]
                    del self.access_counts[user_id]

    def get_cached_avatar(self, user_id: int) -> Optional[str]:
        if user_id in self.cache:
            return self.cache[user_id]
        else:
            return None

    def set_cached_avatar(self, user_id: int, avatar_path: str):
        self.cache[user_id] = avatar_path

    def clear_cached_avatar(self, user_id: int):
        if user_id in self.cache:
            del self.cache[user_id]

class AvatarLoader:
    def __init__(self, cache: AvatarCache, default_avatar_dir: str = None):
        self.cache = cache
        self.default_avatar_dir = default_avatar_dir or "path/to/default/avatar/directory"

    def load_avatar(self, user_id: int) -> Optional[str]:
        avatar_path = self.cache.get_avatar(user_id)
        if avatar_path is None:
            try:
                response = requests.get(f"https://example.com/users/{user_id}/avatar")
                if response.status_code == 200:
                    avatar_path = self.cache.set_avatar(user_id, response.content)
            except requests.exceptions.RequestException as e:
                logging.error(f"Failed to load avatar for user {user_id}: {e}")
        return avatar_path

    def get_cached_avatar(self, user_id: int) -> Optional[str]:
        return self.cache.get_cached_avatar(user_id)

    def set_cached_avatar(self, user_id: int, avatar_path: str):
        self.cache.set_cached_avatar(user_id, avatar_path)

    def clear_cached_avatar(self, user_id: int):
