<?php

namespace App\Services;

use App\DAO\UserDAO;
use App\Models\User;
use App\Utils\PasswordUtil;
use App\Utils\RateLimiter;
use App\Utils\AuditLogger;
use App\Exceptions\InvalidArgumentException;
use App\Exceptions\DatabaseConnectionException;
use App\Exceptions\PasswordUpdateFailedException;

class PasswordUpdater {
    private $userDAO;
    private $passwordUtil;
    private $rateLimiter;
    private $auditLogger;

    public function __construct(UserDAO $userDAO, PasswordUtil $passwordUtil, RateLimiter $rateLimiter, AuditLogger $auditLogger) {
        $this->userDAO = $userDAO;
        $this->passwordUtil = $passwordUtil;
        $this->rateLimiter = $rateLimiter;
        $this->auditLogger = $auditLogger;
    }

    public function updatePassword(User $user, string $newPassword): void {
        if (!$this->validatePassword($newPassword)) {
            throw new InvalidArgumentException('Invalid password');
        }

        try {
            $this->rateLimiter->checkRateLimit($user);
            $this->userDAO->updateUserPassword($user, $newPassword);
            $this->auditLogger->logPasswordUpdate($user, $newPassword);
        } catch (DatabaseConnectionException $e) {
            throw new PasswordUpdateFailedException('Failed to update password', 0, $e);
        }
    }

    private function validatePassword(string $password): bool {
        return $this->passwordUtil->validatePassword($password);
    }
}
