#include <iostream>
#include <vector>
#include <map>
#include <string>
#include <memory>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <future>

class Octree {
public:
    // Constructor
    Octree(int featureSize, int leafNodes) : featureSize_(featureSize), leafNodes_(leafNodes) {}

    // Destructor
    ~Octree() {
        for (auto& node : nodes_) {
            delete node;
        }
    }

    // Insert data into the octree
    void insert(const std::vector<double>& data, const std::string& projectStatus, const std::string& startDate) {
        // Calculate the hash value for the data
        size_t hash = calculateHash(data);

        // Find the node that corresponds to the hash value
        OctreeNode* node = findNode(hash);

        // If the node is not found, create a new one
        if (node == nullptr) {
            node = createNode(hash);
        }

        // Insert the data into the node
        node->insert(data, projectStatus, startDate);
    }

    // Retrieve data from the octree
    std::vector<std::vector<double>> retrieve(const std::string& projectStatus, const std::string& startDate) {
        // Calculate the hash value for the query
        size_t hash = calculateHash(projectStatus, startDate);

        // Find the node that corresponds to the hash value
        OctreeNode* node = findNode(hash);

        // If the node is not found, return an empty vector
        if (node == nullptr) {
            return {};
        }

        // Retrieve the data from the node
        return node->retrieve();
    }

private:
    // Calculate the hash value for the given data
    size_t calculateHash(const std::vector<double>& data) {
        // Implement a simple hash function that takes the first few elements of the vector as input
        return (size_t)(data[0] * 100 + data[1]) % nodes_.size();
    }

    // Find the node that corresponds to the given hash value
    OctreeNode* findNode(size_t hash) {
        for (auto& node : nodes_) {
            if (node->hash == hash) {
                return node.get();
            }
        }
        return nullptr;
    }

    // Create a new node with the given hash value
    OctreeNode* createNode(size_t hash) {
        nodes_.emplace_back(new OctreeNode(hash));
        return nodes_.back().get();
    }

    // The size of the feature vector
    int featureSize_;

    // The number of leaf nodes in the octree
    int leafNodes_;

    // A vector of shared pointers to the nodes in the octree
    std::vector<std::shared_ptr<OctreeNode>> nodes_;
};

class OctreeNode {
public:
    // Constructor
    OctreeNode(size_t hash) : hash(hash), data_(featureSize_, 0.0), children_(leafNodes_) {}

    // Destructor
    ~OctreeNode() {
        for (auto& child : children_) {
            delete child;
        }
    }

    // Insert data into the node
    void insert(const std::vector<double>& data, const std::string& projectStatus, const std::string& startDate) {
        // If the node is a leaf node, store the data and return
        if (children_.empty()) {
            data_ = data;
            return;
        }

        // Calculate the hash value for the data
        size_t hash = calculateHash(data);

        // Find the child that corresponds to the hash value
        OctreeNode* child = findChild(hash);

        // If the child is not found, create a new one
        if (child == nullptr) {
            child = createChild(hash);
        }

        // Insert the data into the child node
        child->insert(data, projectStatus, startDate);
    }

    // Retrieve data from the node
    std::vector<std::vector<double>> retrieve() {
        // If the node is a leaf node, return the stored data
        if (children_.empty()) {
            return {data_};
        }

        // Retrieve the data from all child nodes
        std::vector<std::vector<double>> data;
        for (auto& child : children_) {
            auto childData = child->retrieve();
            data.insert(data.end(), childData.begin(), childData.end());
        }
        return data;
    }

private:
    // The hash value of the node
    size_t hash;

    // The feature vector stored in the node
    std::vector<double> data_;

    // A vector of shared pointers to the child nodes
    std::vector<std::shared_ptr<OctreeNode>> children_;
};
```
