using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

namespace WirelessConfigManager
{
    public class WirelessConfigManager
    {
        private readonly Dictionary<string, Random> _randomNumberGenerators = new Dictionary<string, Random>();
        private readonly object _lock = new object();

        public void AddRange(string rangeName, int minValue, int maxValue)
        {
            if (rangeName == null)
                throw new ArgumentNullException(nameof(rangeName));

            if (minValue > maxValue)
                throw new ArgumentOutOfRangeException(nameof(minValue), "Min value must be less than or equal to max value.");

            lock (_lock)
            {
                _randomNumberGenerators[rangeName] = new Random();
            }
        }

        public int GenerateRandomInt(string rangeName)
        {
            if (rangeName == null)
                throw new ArgumentNullException(nameof(rangeName));

            lock (_lock)
            {
                var randomNumberGenerator = _randomNumberGenerators[rangeName];
                return randomNumberGenerator.Next(minValue: 0, maxValue);
            }
        }

        public float GenerateRandomFloat(string rangeName)
        {
            if (rangeName == null)
                throw new ArgumentNullException(nameof(rangeName));

            lock (_lock)
            {
                var randomNumberGenerator = _randomNumberGenerators[rangeName];
                return (float)randomNumberGenerator.NextDouble();
            }
        }

        public override string ToString()
        {
            lock (_lock)
            {
                var builder = new StringBuilder();
                foreach (var range in _randomNumberGenerators)
                {
                    builder.AppendLine($"{range.Key}: {range.Value}");
                }
                return builder.ToString();
            }
        }

        public void Reset()
        {
            lock (_lock)
            {
                _randomNumberGenerators.Clear();
            }
        }
    }
}
```
