} handover_params_t;

// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
    bool crcflag;
} nfapi_crc_indication_pdu_t;

// Define the hash table for fast lookups
typedef struct {
    ue_context_t *ue_contexts[10000];
    int num_ue_contexts;
} ue_context_hash_table_t;

// Define the doubly linked list for efficient insertion and deletion operations
typedef struct {
    ue_context_t *ue_context;
    struct node *next;
    struct node *prev;
} ue_context_doubly_linked_list_t;

// Define the custom memory allocator for managing UE contexts
typedef struct {
    ue_context_t *ue_contexts[10000];
    int num_ue_contexts;
} ue_context_memory_allocator_t;

// Define the function to add a new UE context
void add_new_ue_context(int ue_id, char *active_radio_bearers[10], struct handover_params *handover_params) {
    // Create a new UE context
    ue_context_t *new_ue_context = (ue_context_t *)malloc(sizeof(ue_context_t));
    if (!new_ue_context) {
        printf("Error: Failed to allocate memory for the new UE context\n");
        return;
    }

    // Initialize the fields of the new UE context
    new_ue_context->ue_id = ue_id;
    memcpy(new_ue_context->active_radio_bearers, active_radio_bearers, sizeof(char *) * 10);
    new_ue_context->handover_params = handover_params;

    // Add the new UE context to the hash table and doubly linked list
    ue_context_hash_table_t *hash_table = (ue_context_hash_table_t *)malloc(sizeof(ue_context_hash_table_t));
    if (!hash_table) {
        printf("Error: Failed to allocate memory for the hash table\n");
        return;
    }
    ue_context_doubly_linked_list_t *doubly_linked_list = (ue_context_doubly_linked_list_t *)malloc(sizeof(ue_context_doubly_linked_list_t));
    if (!doubly_linked_list) {
        printf("Error: Failed to allocate memory for the doubly linked list\n");
        return;
    }
    hash_table->num_ue_contexts++;
    doubly_linked_list->ue_context = new_ue_context;
    doubly_linked_list->next = NULL;
    doubly_linked_list->prev = NULL;
    hash_table->ue_contexts[new_ue_context->ue_id] = doubly_linked_list;
