// Define the caching mechanism with a configurable eviction policy
class Cache {
public:
    Cache(int capacity) : capacity_(capacity), size_(0) {}

    void insert(const string& key, const string& value) {
        if (size_ >= capacity_) {
            // Evict the least recently used item
            auto it = cache_.begin();
            cache_.erase(it);
            --size_;
        }
        cache_[key] = value;
        ++size_;
    }

    string get(const string& key) {
        if (cache_.find(key) != cache_.end()) {
            return cache_[key];
        } else {
            return "";
        }
    }

private:
    int capacity_;
    int size_;
    map<string, string> cache_;
};

