        projects[i].name = malloc(100 * sizeof(char));
        if (projects[i].name == NULL) {
            printf("Failed to allocate memory for project name\n");
            return;
        }
        projects[i].deadline.month = 0;
        projects[i].deadline.day = 0;
        projects[i].priority = 0;
        projects[i].status = malloc(10 * sizeof(char));
        if (projects[i].status == NULL) {
            printf("Failed to allocate memory for project status\n");
            return;
        }
    }

    // Print the details of each project in a formatted manner
    for (int i = 0; i < num_projects; i++) {
        printf("%d. Project %s\n", i + 1, projects[i].name);
        printf("Deadline: %d/%d\n", projects[i].deadline.month, projects[i].deadline.day);
        printf("Priority: %d\n", projects[i].priority);
        printf("Status: %s\n", projects[i].status);
    }

    // Free the memory allocated for each project
    for (int i = 0; i < num_projects; i++) {
        free(projects[i].name);
        free(projects[i].status);
    }

    // Free the memory allocated for the array of projects
    free(projects);
}

