// Function to update the status of a project
void update_project_status(project* project, char* new_status) {
    // Check if the project is valid
    if (project == NULL) {
        printf("Invalid project\n");
        return;
    }

    // Update the status of the project
    free(project->status);
    project->status = malloc(strlen(new_status) + 1);
    strcpy(project->status, new_status);
}

