int selectAndEncryptAttack(const vector<int>& attacks, int cooldownPeriod, int bitsPerSample) {
    // Initialize OpenSSL cipher object
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        cerr << "Error initializing OpenSSL cipher context" << endl;
        return -1;
    }

    // Set encryption parameters
    int encryptResult = EVP_EncryptInit(ctx, EVP_aes_256_cbc(), NULL, NULL);
    if (encryptResult != 1) {
        cerr << "Error initializing OpenSSL cipher" << endl;
        return -1;
    }

    // Select attack based on cooldown period and latency
    int selectedAttack = -1;
    for (int i = 0; i < attacks.size(); ++i) {
        if (attacks[i].cooldownPeriod <= cooldownPeriod && attacks[i].latency >= 5 && attacks[i].latency <= 15) {
            selectedAttack = i;
            break;
        }
    }

    // Encrypt attack information
    if (selectedAttack != -1) {
        int encryptResult = EVP_EncryptUpdate(ctx, NULL, &encryptedDataLength, attacks[selectedAttack].data, attacks[selectedAttack].dataLength);
        if (encryptResult != 1) {
            cerr << "Error encrypting attack data" << endl;
            return -1;
        }
    }

    // Print selected attack number to console and log selection
    cout << "Selected attack: " << selectedAttack << endl;
    logSelection(selectedAttack, cooldownPeriod);

    // Return encrypted data structure containing attack details
    return selectedAttack;
}

// Log selection in a file for analytics
void logSelection(int selectedAttack, int cooldownPeriod) {
