// Define the structure for the CRC indication PDU
typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the maximum size of the array
#define MAX_ARRAY_SIZE 100

// Function to dynamically allocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_array(size_t n) {
    // Check if the input size is valid
    if (n > MAX_ARRAY_SIZE) {
        printf("Error: Input size exceeds maximum allowed value\n");
        return NULL;
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* arr = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (!arr) {
        printf("Error: Memory allocation failed\n");
        return NULL;
    }

    // Initialize each structure in the array with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (size_t i = 0; i < n; i++) {
        arr[i].RX_UE_INFORMATION_TAG = 1;
        arr[i].RNTI = rand() % 65536;
        arr[i].CRC_INDICATION_REL8_TAG = 2;
        arr[i].CRCFLAG = (rand() % 2) ? true : false;
    }

    // Return the pointer to the allocated array
    return arr;
}

// Function to free the memory allocated by allocate_crc_indication_array
void free_crc_indication_array(NFAPI_CRC_INDICATION_PDU_T* arr) {
    if (arr) {
        free(arr);
    }
}
