NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_list(int n) {
    // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list == NULL) {
        printf("Error: Failed to allocate memory for CRC indication PDU list\n");
        return NULL;
    }

    // Initialize the RNTI values and CRCFLAGs randomly
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        list[i].rx_ue_information_tag = rand() % MAX_RNTI_VALUES + 1;
        list[i].crc_indication_rel8_tag = rand() % 256;
        list[i].crcflag = (rand() % 2) == 0;
    }

    // Ensure that no two structures in the list have the same RNTI value
    for (int i = 0; i < n - 1; i++) {
        for (int j = i + 1; j < n; j++) {
            if (list[i].rnti == list[j].rnti) {
                // If two structures have the same RNTI value, regenerate the CRCFLAGs randomly
                list[i].crcflag = (rand() % 2) == 0;
                list[j].crcflag = (rand() % 2) == 0;
            }
        }
    }

    // Ensure that the total number of unique RNTI values does not exceed the predefined limit
    int num_unique_rnti_values = 0;
    for (int i = 0; i < n; i++) {
        bool found = false;
        for (int j = 0; j < i; j++) {
            if (list[i].rnti == list[j].rnti) {
                found = true;
                break;
            }
        }
        if (!found) {
            num_unique_rnti_values++;
        }
    }
    if (num_unique_rnti_values > MAX_RNTI_VALUES) {
        // If the total number of unique RNTI values exceeds the predefined limit, retry with a different range of RNTI values after a configurable delay
        printf("Warning: Total number of unique RNTI values exceeds predefined limit. Retrying with a different range of RNTI values.\n");
        sleep(RETRY_DELAY_MS / 1000);
        return create_crc_indication_pdu_list(n);
    }

    // Serialize the list into a binary format for later retrieval
    size_t serialized_size = n * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    void *serialized_data = malloc(serialized_size);
    if (serialized_data == NULL) {
        printf("Error: Failed to allocate memory for serialized CRC indication PDU list\n");
        free(list);
        return NULL;
    }
    memcpy(serialized_data, list, serialized_size);

    // Free the original list of NFAPI_CRC_INDICATION_PDU_T structures
    free(list);

