#include <pthread.h>

// Structure to hold a MAC entity descriptor
typedef struct {
    uint16_t id; // Unique ID for the MAC entity
    size_t frame_count; // Number of frames in the descriptor
    L2Frame *frames; // Array of L2 frames
} MacEntityDescriptor;

// Structure to hold a dynamic array of MAC entity descriptors
typedef struct {
    size_t capacity; // Maximum number of elements in the array
    size_t count; // Current number of elements in the array
    MacEntityDescriptor *descriptors; // Array of MAC entity descriptors
} MacEntityArray;

// Function to initialize a new dynamic array of MAC entity descriptors
MacEntityArray* mac_entity_array_init(size_t capacity) {
    MacEntityArray *arr = malloc(sizeof(MacEntityArray));
    if (!arr) {
        return NULL;
    }
    arr->capacity = capacity;
    arr->count = 0;
    arr->descriptors = calloc(capacity, sizeof(MacEntityDescriptor));
    if (!arr->descriptors) {
        free(arr);
        return NULL;
    }
    return arr;
}

// Function to add a new MAC entity descriptor to the array
int mac_entity_array_add(MacEntityArray *arr, uint16_t id, L2Frame *frames, size_t frame_count) {
    if (arr->count == arr->capacity) {
        // Array is full, cannot add new descriptor
        return -1;
    }
    MacEntityDescriptor *desc = &(arr->descriptors[arr->count]);
    desc->id = id;
    desc->frame_count = frame_count;
    desc->frames = frames;
    arr->count++;
    return 0;
}

// Function to remove a MAC entity descriptor from the array by its ID
int mac_entity_array_remove(MacEntityArray *arr, uint16_t id) {
    for (size_t i = 0; i < arr->count; i++) {
        if (arr->descriptors[i].id == id) {
            // Found the descriptor to remove, shift all subsequent descriptors back one index
            for (size_t j = i; j < arr->count - 1; j++) {
                arr->descriptors[j] = arr->descriptors[j + 1];
            }
            // Decrement the count of descriptors
            arr->count--;
            return 0;
        }
    }
    // Descriptor not found, cannot remove it
    return -1;
}

// Function to iterate over all MAC entity descriptors in the array and process their frames
void mac_entity_array_process(MacEntityArray *arr, void (*process_frame)(L2Frame *)) {
    for (size_t i = 0; i < arr->count; i++) {
        MacEntityDescriptor *desc = &(arr->descriptors[i]);
        for (size_t j = 0; j < desc->frame_count; j++) {
            process_frame(&(desc->frames[j]));
        }
    }
}

// Function to free the memory allocated by the dynamic array of MAC entity descriptors
void mac_entity_array_free(MacEntityArray *arr) {
    if (arr) {
        for (size_t i = 0; i < arr->count; i++) {
            MacEntityDescriptor *desc = &(arr->descriptors[i]);
            free(desc->frames);
        }
        free(arr->descriptors);
        free(arr);
    }
}
```
This code defines a `MacEntityArray` structure to hold a dynamic array of `MacEntityDescriptor` structures, each containing a unique ID and an array of L2 frames. The `mac_entity_array_init()` function initializes a new `MacEntityArray` with the given capacity, allocating memory for the array of descriptors and setting the count to 0. The `mac_entity_array_add()` function adds a new descriptor to the array, checking if the array is full before adding the new descriptor. The `mac_entity_array_remove()` function removes a descriptor from the array by its ID, shifting all subsequent descriptors back one index and decrementing the count of descriptors. The `mac_entity_array_process()` function iterates over all MAC entity descriptors in the array and processes their frames using the given callback function. Finally, the `mac_entity_array_free()` function frees the memory allocated by the dynamic array of MAC entity descriptors.

This code also includes a few error checks to handle potential memory allocation failures gracefully, such as returning NULL if the allocation fails or freeing the memory if the `MacEntityArray` is being freed. Additionally, this code uses pthreads to maintain thread safety when accessing the dynamic array of MAC entity descriptors simultaneously by multiple threads.']

