        int filteredCount = 0;
        for (int i = 0; i < temperatures.length; i++) {
            if (temperatures[i] >= minTemperature && temperatures[i] <= maxTemperature && timestamps[i] >= minTimestamp && timestamps[i] <= maxTimestamp) {
                sensorData[filteredCount++] = new SensorData(temperatures[i], sensorIdentifiers[i], timestamps[i]);
            }
        }
