        for (int i = 0; i < sensorData.length - 1; i++) {
            for (int j = i + 1; j < sensorData.length; j++) {
                if (sensorData[indices[j]].timestamp < sensorData[indices[i]].timestamp) {
                    int temp = indices[i];
                    indices[i] = indices[j];
                    indices[j] = temp;
