        // Implement a mechanism to dynamically resize the memory allocated for the sensor data structures as new data is received, while adhering to a maximum allowed size limit to prevent memory exhaustion
        int maxSize = 1024;
        if (sensorData.length > maxSize) {
            SensorData[] temp = new SensorData[maxSize];
            System.arraycopy(sensorData, 0, temp, 0, maxSize);
