                {
                    // Log failed data retrieval attempt
                    Console.WriteLine($"Failed to retrieve data for identifier '{identifier}': {ex.Message}");
                    return;
                }
            }
        }

        // Log successful hash generation
        Console.WriteLine($"Generated MD5 hash for identifier '{identifier}': {hash}");
    }

    private async Task<string> GenerateHashAsync(string identifier)
    {
        var retryCount = 0;
        while (true)
        {
            try
            {
                return await Task.Run(() => MD5.Create().ComputeHash(Encoding.UTF8.GetBytes(identifier)));
            }
            catch (Exception ex) when (retryCount < 3)
            {
                // Log failed hash generation attempt
                Console.WriteLine($"Failed to generate MD5 hash for identifier '{identifier}': {ex.Message}");

                retryCount++;
                await Task.Delay(Math.Pow(2, retryCount));
            }
        }
    }
}
```
