use std::fs;
use std::path::Path;
use std::process::Command;
use std::thread;
use std::time::Duration;
use tokio::runtime::Runtime;
use tokio::task::block_in_place;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 3 {
        println!("Usage: {} <directory> <output_format>", args[0]);
        return;
    }

    let directory = &args[1];
    let output_format = &args[2];

    // Check if the directory exists and is a directory
    if !Path::new(directory).exists() || !Path::new(directory).is_dir() {
        println!("Error: {} is not a valid directory", directory);
        return;
    }

    let mut files = fs::read_dir(directory).unwrap();
    let mut file_count = 0;
    let mut categorized_files = Vec::new();

    // Iterate over the files in the directory and categorize them based on their MIME type, size, and metadata
    while let Some(file) = files.next() {
        let file_path = file.unwrap().path();
        let file_name = file_path.file_name().unwrap().to_str().unwrap();
        let file_size = fs::metadata(&file_path).unwrap().len();

        // Check the MIME type of the file using the "file" command
        let mime_type = Command::new("file")
            .arg("-b")
            .arg(file_name)
            .output()
            .unwrap()
            .stdout;

        // Check if the file is text or binary based on its MIME type and size
        let content_type = match mime_type {
            "text/plain" => "text",
            _ => {
                if file_size > 50 {
                    "binary"
                } else {
                    "unknown"
                }
            }
        };

        // Check the metadata of the file using the "exiftool" command
        let metadata = Command::new("exiftool")
            .arg(file_name)
            .output()
            .unwrap();

        // If the file has metadata, check if it contains a MIME type and use that instead of the heuristic
        if !metadata.is_empty() {
            let mime_type = String::from_utf8(metadata).unwrap().split(":").collect::<Vec<&str>>()[1];
            content_type = match mime_type {
                "text/plain" => "text",
                _ => "binary",
            };
        }

        // If the file has no extension, use the default MIME type of "application/octet-stream"
        if !file_name.contains(".") {
            content_type = "application/octet-stream";
        }

        // Append a numeric counter to the filename if necessary to ensure uniqueness
        let mut new_filename = file_name.to_string();
        if categorized_files.iter().any(|f| f == &new_filename) {
            let mut counter = 1;
            while categorized_files.iter().any(|f| format!("{}{}", new_filename, counter) == f) {
                counter += 1;
            }
            new_filename = format!("{}{}", new_filename, counter);
        }

        // Add the file to the list of categorized files
        categorized_files.push((file_name, content_type));

        // Print feedback to the user about the progress and status of the operation
        println!(
            "{} - {} ({} bytes) - {}",
            file_name,
            content_type,
            file_size,
            if metadata.is_empty() {
                "No metadata found"
            } else {
                String::from_utf8(metadata).unwrap()
            }
        );

        // Increment the file count
        file_count += 1;
    }

    // Print a summary of the categorized files and their content types
    println!("Categorized {} files:", file_count);
    for (file, content_type) in &categorized_files {
        println!("{} - {}", file, content_type);
    }

    // Write the categorized files to a CSV or JSON file based on the output format specified by the user
    if output_format == "csv" {
        let mut csv = String::new();
        for (file, content_type) in &categorized_files {
            csv.push_str(file);
            csv.push(',');
            csv.push_str(content_type);
            csv.push('\n');
        }
        fs::write("categorized_files.csv", csv).unwrap();
    } else if output_format == "json" {
        let mut json = String::new();
        for (file, content_type) in &categorized_files {
            json.push('{');
            json.push_str("\"");
            json.push_str(file);
            json.push_str("\": \"");
            json.push_str(content_type);
            json.push_str("\"");
            json.push('}');
        }
        fs::write("categorized_files.json", json).unwrap();
    } else {
        println!("Error: {} is not a valid output format", output_format);
    }
}
