use std::env;
use std::fs;
use std::path::PathBuf;
use std::sync::Mutex;

struct DynamicDirectory {
    path: PathBuf,
    env_var: String,
}

impl DynamicDirectory {
    fn new(path: &str) -> Self {
        let mut path = PathBuf::from(path);
        if !path.is_absolute() {
            path = env::current_dir().join(path);
        }
        DynamicDirectory {
            path,
            env_var: "DYNAMIC_DIR".to_string(),
        }
    }

    fn create(&mut self) -> Result<(), String> {
        let mut lock = Mutex::new(());
        let guard = lock.lock().unwrap();
        if !self.path.exists() {
            fs::create_dir_all(&self.path).map_err(|e| e.to_string())?;
        }
        Ok(())
    }

    fn delete(&mut self) -> Result<(), String> {
        let mut lock = Mutex::new(());
        let guard = lock.lock().unwrap();
        if self.path.exists() {
            fs::remove_dir_all(&self.path).map_err(|e| e.to_string())?;
        }
        Ok(())
    }

    fn set_env_var(&mut self) -> Result<(), String> {
        let mut lock = Mutex::new(());
        let guard = lock.lock().unwrap();
        if !self.path.exists() {
            return Err("Path does not exist".to_string());
        }
        env::set_var(&self.env_var, self.path.display().to_string());
        Ok(())
    }

    fn get_env_var(&mut self) -> Result<String, String> {
        let mut lock = Mutex::new(());
        let guard = lock.lock().unwrap();
        env::get_var(&self.env_var).map_err(|e| e.to_string())
    }
}
