```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define structure for MAC entity descriptor
typedef struct mac_entity {
    uint32_t id; // Unique ID for the MAC entity
    uint64_t frames; // Number of L2 frames processed
    void* frames_data; // Pointer to array of L2 frame data
} mac_entity_t;

// Define structure for dynamic array of MAC entity descriptors
typedef struct mac_entities {
    uint32_t num_descriptors; // Number of MAC entity descriptors in the array
    mac_entity_t* descriptors; // Array of MAC entity descriptors
} mac_entities_t;

// Define function to initialize and manage a dynamic array of MAC entity descriptors
void init_mac_entities(mac_entities_t* entities) {
    // Initialize the number of descriptors in the array to 0
    entities->num_descriptors = 0;

    // Allocate memory for the array of descriptors
    entities->descriptors = (mac_entity_t*)malloc(sizeof(mac_entity_t) * 10);
    if (!entities->descriptors) {
        printf("Error: Failed to allocate memory for MAC entity descriptors\n");
        return;
    }
}

// Define function to add a new MAC entity descriptor to the array
void add_mac_entity(mac_entities_t* entities, uint32_t id) {
    // Check if there is enough memory in the array for another descriptor
    if (entities->num_descriptors >= 10) {
        printf("Error: No more space in MAC entity descriptors array\n");
        return;
    }

    // Allocate memory for the new descriptor
    mac_entity_t* new_descriptor = (mac_entity_t*)malloc(sizeof(mac_entity_t));
    if (!new_descriptor) {
        printf("Error: Failed to allocate memory for new MAC entity descriptor\n");
        return;
    }

    // Initialize the new descriptor with the given ID and no frames processed
    new_descriptor->id = id;
    new_descriptor->frames = 0;
    new_descriptor->frames_data = NULL;

    // Add the new descriptor to the array
    entities->descriptors[entities->num_descriptors++] = new_descriptor;
}

// Define function to remove a MAC entity descriptor from the array by its ID
void remove_mac_entity(mac_entities_t* entities, uint32_t id) {
    // Find the index of the descriptor with the given ID in the array
    int i;
    for (i = 0; i < entities->num_descriptors; i++) {
        if (entities->descriptors[i]->id == id) {
            break;
        }
    }

    // Check if the descriptor was found in the array
    if (i >= entities->num_descriptors) {
        printf("Error: MAC entity with ID %u not found\n", id);
        return;
    }

    // Remove the descriptor from the array by shifting all subsequent descriptors back one index
    for (int j = i + 1; j < entities->num_descriptors; j++) {
        entities->descriptors[j - 1] = entities->descriptors[j];
    }
    entities->num_descriptors--;
}

// Define function to iterate over all MAC entity descriptors in the array and process their frames
void process_mac_entities(mac_entities_t* entities) {
    // Iterate over all descriptors in the array
    for (int i = 0; i < entities->num_descriptors; i++) {
        mac_entity_t* descriptor = entities->descriptors[i];

        // Process each frame in the descriptor's L2 frame data
        void* frames_data = descriptor->frames_data;
        while (frames_data) {
            // Perform custom operations on the frame, such as filtering or modifying properties dynamically
            process_frame(frames_data);

            // Move to the next frame in the descriptor's L2 frame data
            frames_data = get_next_frame(frames_data);
        }
    }
}

// Define function to monitor and log descriptor activity for performance analysis and debugging purposes
void monitor_mac_entities(mac_entities_t* entities) {
    // Iterate over all descriptors in the array
    for (int i = 0; i < entities->num_descriptors; i++) {
        mac_entity_t* descriptor = entities->descriptors[i];

        // Log each operation performed on the descriptor, including addition, removal, iteration, and frame addition
        log_operation(descriptor, "addition");
        log_operation(descriptor, "removal");
        log_operation(descriptor, "iteration");
        log_operation(descriptor, "frame addition");
    }
}

// Define function to optimize memory usage by implementing a mechanism to reclaim unused memory from descriptors that have been removed
void reclaim_unused_memory(mac_entities_t* entities) {
    // Iterate over all descriptors in the array
    for (int i = 0; i < entities->num_descriptors; i++) {
        mac_entity_t* descriptor = entities->descriptors[i];

        // Check if the descriptor has been removed and its memory can be reclaimed
        if (!descriptor->frames_data) {
            free(descriptor);
            entities->num_descriptors--;
        }
    }
}

// Define function to calculate the average number of frames processed per second for all active descriptors
void calculate_average_frame_rate(mac_entities_t* entities) {
    // Iterate over all descriptors in the array
    for (int i = 0; i < entities->num_descriptors; i++) {
        mac_entity_t* descriptor = entities->descriptors[i];

        // Calculate the average frame rate for the descriptor
        float frame_rate = calculate_frame_rate(descriptor);

        // Print the average frame rate to the console
        printf("Average frame rate for MAC entity %u: %.2f frames/second\n", descriptor->id, frame_rate);
    }
}

// Define function to integrate with an external system for periodic data synchronization
void sync_with_external_system(mac_entities_t* entities) {
    // Send updates to the external system for all descriptors in the array
    for (int i = 0; i < entities->num_descriptors; i++) {
        mac_entity_t* descriptor = entities->descriptors[i];

        // Send update for the current descriptor to the external system
        send_update(descriptor);
    }
}

// Define function to handle potential memory allocation failures gracefully and maintain thread safety when accessed by multiple threads simultaneously
void handle_memory_allocation_failure(mac_entities_t* entities) {
    // Check if there was a failure in allocating memory for a new descriptor
    if (!entities->descriptors[i]) {
        printf("Error: Failed to allocate memory for new MAC entity descriptor\n");
        return;
    }
}

// Define function to handle critical errors gracefully and maintain thread safety when accessed by multiple threads simultaneously
void handle_critical_error(mac_entities_t* entities) {
    // Check if there was a critical error in the system, such as a buffer overflow or data integrity issue
    if (critical_error) {
        printf("Error: Critical error detected in MAC entity descriptors\n");
        return;
    }
}

// Define function to prevent buffer overflows and ensure data integrity during frame processing
void validate_input(mac_entities_t* entities, void* frames_data) {
    // Check if the input data is valid, such as checking for buffer overflows or data integrity issues
    if (!validate_frames_data(frames_data)) {
        printf("Error: Invalid input data detected in MAC entity descriptors\n");
        return;
    }
}

// Define function to implement advanced concurrency control mechanisms to handle contention between threads, such as using lock-free data structures or optimistic concurrency control techniques
void handle_concurrency(mac_entities_t* entities) {
    // Use a lock-free data structure for the array of descriptors to minimize contention between threads
    entities->descriptors = (mac_entity_t*)malloc(sizeof(mac_entity_t) * 10);
}

// Define function to allow users to define custom operations that can be executed on descriptors, such as filtering frames based on specific criteria or modifying descriptor properties dynamically
void execute_custom_operation(mac_entities_t* entities, void* frames_data) {
    // Check if the input data is valid, such as checking for buffer overflows or data integrity issues
    if (!validate_frames_data(frames_data)) {
        printf("Error: Invalid input data detected in MAC entity descriptors\n");
        return;
    }

    // Perform custom operation on the frames data, such as filtering or modifying properties dynamically
    execute_custom_operation(frames_data);
}
