#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <tiffio.h>

// Define a struct to store the extracted metadata
struct Metadata {
    int bitsPerSample;
    int samplesPerPixel;
    int extraSamplesCount;
};

// Define a function to process an image file and encrypt its data
void processImageAndEncrypt(const char* filename, const char* encryptionOption) {
    // Initialize an OpenSSL cipher object
    EVP_CIPHER_CTX *cipherCtx = EVP_CIPHER_CTX_new();

    // Parse the input file using TIFF library functions
    TIFF *tiff = TIFFOpen(filename, "r");
    if (!tiff) {
        fprintf(stderr, "Error: unable to open %s\n", filename);
        return;
    }

    // Extract metadata from the input file
    struct Metadata metadata;
    TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &metadata.bitsPerSample);
    TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &metadata.samplesPerPixel);
    TIFFGetField(tiff, TIFFTAG_EXTRASAMPLES, &metadata.extraSamplesCount);

    // Check if the input file has unsupported configuration
    if (metadata.bitsPerSample != 1 && metadata.bitsPerSample != 2 && metadata.bitsPerSample != 4 && metadata.bitsPerSample != 8 && metadata.bitsPerSample != 16) {
        fprintf(stderr, "Error: unsupported bits per sample value (%d)\n", metadata.bitsPerSample);
        return;
    }

    // Encrypt the extracted data using OpenSSL library functions
    int encryptionOptionIndex = -1;
    for (int i = 0; i < EVP_get_cipherbyname(encryptionOption); i++) {
        if (EVP_CIPHER_CTX_init(cipherCtx, EVP_get_cipherbyname(encryptionOption), NULL, NULL, -1)) {
            encryptionOptionIndex = i;
            break;
        }
    }
    if (encryptionOptionIndex == -1) {
        fprintf(stderr, "Error: unable to initialize OpenSSL cipher object with %s\n", encryptionOption);
        return;
    }

    // Handle extra samples in the input file
    if (metadata.extraSamplesCount > 0) {
        fprintf(stderr, "Warning: ignoring %d extra samples in %s\n", metadata.extraSamplesCount, filename);
    }

    // Process the input file and encrypt its data
    TIFFReadDirectory(tiff);
    for (int i = 0; i < TIFFNumberOfStrips(tiff); i++) {
        uint32 stripSize = TIFFStripSize(tiff);
        void *stripBuffer = _TIFFmalloc(stripSize);
        if (!stripBuffer) {
            fprintf(stderr, "Error: unable to allocate memory for strip buffer\n");
            return;
        }
        TIFFReadEncodedStrip(tiff, i, stripBuffer, stripSize);
        EVP_CipherUpdate(cipherCtx, stripBuffer, stripSize, NULL, 0);
        _TIFFfree(stripBuffer);
    }

    // Summarize the processed images and encryption results
    printf("Processed image %s with %d bits per sample and %d samples per pixel\n", filename, metadata.bitsPerSample, metadata.samplesPerPixel);
    if (encryptionOptionIndex != -1) {
        printf("Encrypted data using %s with key size %d\n", encryptionOption, EVP_CIPHER_CTX_key_length(cipherCtx));
    } else {
        printf("No encryption option specified\n");
    }
}

// Define a function to handle multiple input files and provide a summary report
void processImagesAndEncrypt(const char* filenames[], int numFiles, const char* encryptionOption) {
    // Initialize an OpenSSL cipher object
    EVP_CIPHER_CTX *cipherCtx = EVP_CIPHER_CTX_new();

    // Process each input file and encrypt its data
    for (int i = 0; i < numFiles; i++) {
        processImageAndEncrypt(filenames[i], encryptionOption);
    }

    // Summarize the processed images and encryption results
    printf("Processed %d image%s with encryption option %s\n", numFiles, (numFiles > 1) ? "s" : "", encryptionOption);
}
