    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &list[i];
        pdu->rxUeInformationTag = rand() % 10000;
        pdu->rnti = rand() % 10000;
        pdu->crcIndicationRel8Tag = rand() % 10000;
