            entities[i]->frames[num_entities] = frame;
            num_entities++;
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    // If the ID doesn't exist, create a new descriptor and add it to the array
    mac_entity_t* new_entity = malloc(sizeof(mac_entity_t));
    new_entity->id = id;
