size_t nics_cap = 0;
pthread_mutex_t nics_lock = PTHREAD_MUTEX_INITIALIZER;

// Define the function to add a new NIC entity
int add_nic(int id, char* packets) {
    // Check if the ID is already in use
    for (size_t i = 0; i < nics_len; i++) {
        if (nics[i]->id == id) {
            return -1;
        }
    }

    // Allocate memory for the new NIC entity
    nic_entity_t* new_nic = malloc(sizeof(nic_entity_t));
    if (!new_nic) {
        return -2;
    }

    // Initialize the new NIC entity
    new_nic->id = id;
    new_nic->packets = packets;

    // Add the new NIC entity to the dynamic array
    pthread_mutex_lock(&nics_lock);
    if (nics_len == nics_cap) {
        // Resize the dynamic array if necessary
        size_t new_cap = nics_cap * 2;
        nic_entity_t** new_nics = realloc(nics, new_cap * sizeof(nic_entity_t*));
        if (!new_nics) {
            free(new_nic);
            return -3;
        }
        nics = new_nics;
        nics_cap = new_cap;
    }
    nics[nics_len++] = new_nic;
    pthread_mutex_unlock(&nics_lock);

    return 0;
}

// Define the function to remove a NIC entity by its ID
