    nic_entity_t* removed_nic = nics[i];
    for (size_t j = i; j < nics_len - 1; j++) {
        nics[j] = nics[j + 1];
    }
    nics_len--;
    pthread_mutex_unlock(&nics_lock);

    // Free the memory of the removed NIC entity
    free(removed_nic->packets);
    free(removed_nic);

    return 0;
}

