// Define a struct to store the extracted metadata
struct Metadata {
    int bitsPerSample;
    int samplesPerPixel;
    int extraSamplesCount;
};

// Define a function to process an image file and encrypt its data
void processImageAndEncrypt(const char* filename, const char* encryptionOption) {
    // Initialize an OpenSSL cipher object
    EVP_CIPHER_CTX *cipherCtx = EVP_CIPHER_CTX_new();

    // Parse the input file using TIFF library functions
    TIFF *tiff = TIFFOpen(filename, "r");
    if (tiff == NULL) {
        fprintf(stderr, "Error: failed to open %s\n", filename);
        return;
    }

    // Extract metadata from the input file
    struct Metadata metadata = {0};
    TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &metadata.bitsPerSample);
    TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &metadata.samplesPerPixel);
    TIFFGetField(tiff, TIFFTAG_EXTRASAMPLES, &metadata.extraSamplesCount);

    // Check if the input file has unsupported configuration
    if (metadata.bitsPerSample != 1 && metadata.bitsPerSample != 2 && metadata.bitsPerSample != 4 && metadata.bitsPerSample != 8 && metadata.bitsPerSample != 16) {
        fprintf(stderr, "Error: unsupported bits per sample value (%d)\n", metadata.bitsPerSample);
        return;
    }

    // Encrypt the extracted data using OpenSSL library functions
    int encryptionResult = EVP_EncryptInit_ex(cipherCtx, EVP_aes_256_cbc(), NULL, NULL, NULL);
    if (encryptionResult != 1) {
        fprintf(stderr, "Error: failed to initialize OpenSSL cipher object\n");
        return;
    }

    // Handle extra samples in the input file
    if (metadata.extraSamplesCount > 0) {
        fprintf(stdout, "Warning: %d extra samples detected in %s\n", metadata.extraSamplesCount, filename);
        fprintf(stdout, "Detailed information:\n");
        for (int i = 0; i < metadata.extraSamplesCount; i++) {
            int sampleType = 0;
            TIFFGetField(tiff, TIFFTAG_EXTRASAMPLES + i, &sampleType);
            fprintf(stdout, "    Sample %d: type=%d\n", i+1, sampleType);
        }
    }

    // Process the input file and encrypt its data
    uint8_t* buffer = NULL;
    size_t bufferSize = 0;
    TIFFReadEncodedStrip(tiff, 0, buffer, &bufferSize);
    encryptionResult = EVP_EncryptUpdate(cipherCtx, buffer, bufferSize);
    if (encryptionResult != 1) {
        fprintf(stderr, "Error: failed to encrypt data from %s\n", filename);
        return;
    }

    // Clean up resources and return
    TIFFClose(tiff);
    EVP_CIPHER_CTX_free(cipherCtx);
}

// Define a function to handle multiple input files and provide a summary report
void processImagesAndEncrypt(const char* encryptionOption, const char** filenames, int numFiles) {
    // Initialize an OpenSSL cipher object
    EVP_CIPHER_CTX *cipherCtx = EVP_CIPHER_CTX_new();

    // Process each input file and encrypt its data
    for (int i = 0; i < numFiles; i++) {
        processImageAndEncrypt(filenames[i], encryptionOption);
    }

    // Clean up resources and return
    EVP_CIPHER_CTX_free(cipherCtx);
}
