// Define the structure to hold the image metadata
typedef struct {
    int bit_depth;
    int samples_per_pixel;
    int extra_samples;
    char* extra_sample_info[16];
} tiff_metadata;

// Function to parse a TIFF image file and extract metadata
void parse_tiff(const char* filename, tiff_metadata* metadata) {
    // Open the TIFF file for reading
    TIFF* tif = TIFFOpen(filename, "r");
    if (!tif) {
        printf("Error: unable to open TIFF file %s\n", filename);
        return;
    }

    // Read the image header and validate its format
    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &metadata->bit_depth);
    if (metadata->bit_depth != 1 && metadata->bit_depth != 2 && metadata->bit_depth != 4 && metadata->bit_depth != 8 && metadata->bit_depth != 16) {
        printf("Error: invalid bit depth %d\n", metadata->bit_depth);
        TIFFClose(tif);
        return;
    }
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &metadata->samples_per_pixel);
    if (metadata->samples_per_pixel < 1 || metadata->samples_per_pixel > 16) {
        printf("Error: invalid number of samples per pixel %d\n", metadata->samples_per_pixel);
        TIFFClose(tif);
        return;
    }

    // Read the extra sample information, if any
    int extra_samples = 0;
    for (int i = 1; i <= metadata->samples_per_pixel; i++) {
        char* sample_info = TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &extra_samples);
        if (sample_info) {
            metadata->extra_samples++;
            strcpy(metadata->extra_sample_info[i], sample_info);
        }
    }

    // Close the TIFF file and return the metadata
    TIFFClose(tif);
}

