import java.util.HashMap;
import java.util.Map;
import java.security.MessageDigest;

public class StringHashService {
    public static Map<String, String> computeHashes(List<String> strings) {
        // Initialize the hash map to store the string-hash mappings
        Map<String, String> hashMap = new HashMap<>();

        // Loop over the list of strings and compute their MD5 hashes
        for (String string : strings) {
            try {
                // Compute the MD5 hash of the string
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] bytes = md.digest(string.getBytes());

                // Convert the hash to a hexadecimal string and add it to the hash map
                String hash = bytesToHex(bytes);
                hashMap.put(string, hash);
            } catch (NoSuchAlgorithmException e) {
                // Handle exception
            }
        }

        // Return the hash map
        return hashMap;
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < bytes.length; i++) {
            sb.append(String.format("%02x", bytes[i]));
        }
        return sb.toString();
    }
}
