```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the structure for a MAC entity descriptor
typedef struct mac_entity_descriptor {
    uint32_t id; // Unique ID for the MAC entity
    size_t frame_count; // Number of frames in the descriptor
    Layer2Frame *frames[]; // Array of Layer 2 frames
} MacEntityDescriptor;

// Define the structure for a dynamic array of MAC entity descriptors
typedef struct mac_entity_descriptors {
    size_t capacity; // Capacity of the array
    size_t count; // Number of elements in the array
    MacEntityDescriptor *descriptors[]; // Array of MAC entity descriptors
} MacEntityDescriptors;

// Define the function to initialize and manage a dynamic array of MAC entity descriptors
MacEntityDescriptors* mac_entity_descriptors_init(size_t capacity) {
    MacEntityDescriptors *descriptors = malloc(sizeof(MacEntityDescriptors));
    if (descriptors == NULL) {
        fprintf(stderr, "Failed to allocate memory for MAC entity descriptors\n");
        return NULL;
    }
    descriptors->capacity = capacity;
    descriptors->count = 0;
    descriptors->descriptors = malloc(sizeof(MacEntityDescriptor) * capacity);
    if (descriptors->descriptors == NULL) {
        fprintf(stderr, "Failed to allocate memory for MAC entity descriptor array\n");
        free(descriptors);
        return NULL;
    }
    return descriptors;
}

// Define the function to add a new MAC entity descriptor to the dynamic array
int mac_entity_descriptors_add(MacEntityDescriptors *descriptors, uint32_t id) {
    if (descriptors == NULL || id < 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return -1;
    }
    // Check if the array is full
    if (descriptors->count >= descriptors->capacity) {
        fprintf(stderr, "The array is full\n");
        return -2;
    }
    // Create a new descriptor and add it to the array
    MacEntityDescriptor *new_descriptor = malloc(sizeof(MacEntityDescriptor));
    if (new_descriptor == NULL) {
        fprintf(stderr, "Failed to allocate memory for MAC entity descriptor\n");
        return -3;
    }
    new_descriptor->id = id;
    new_descriptor->frame_count = 0;
    new_descriptor->frames = NULL;
    descriptors->descriptors[descriptors->count++] = new_descriptor;
    return 0;
}

// Define the function to remove a MAC entity descriptor from the dynamic array by its ID
int mac_entity_descriptors_remove(MacEntityDescriptors *descriptors, uint32_t id) {
    if (descriptors == NULL || id < 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return -1;
    }
    // Find the descriptor with the specified ID
    MacEntityDescriptor *descriptor = mac_entity_descriptors_find(descriptors, id);
    if (descriptor == NULL) {
        fprintf(stderr, "The descriptor with ID %d does not exist\n", id);
        return -2;
    }
    // Remove the descriptor from the array
    for (size_t i = 0; i < descriptors->count; i++) {
        if (descriptors->descriptors[i] == descriptor) {
            free(descriptor);
            memmove(&descriptors->descriptors[i], &descriptors->descriptors[i + 1], sizeof(MacEntityDescriptor *) * (descriptors->count - i));
            descriptors->count--;
            return 0;
        }
    }
    fprintf(stderr, "The descriptor with ID %d does not exist\n", id);
    return -3;
}

// Define the function to iterate over all MAC entity descriptors and process their frames
int mac_entity_descriptors_iterate(MacEntityDescriptors *descriptors, void (*process_frame)(Layer2Frame *)) {
    if (descriptors == NULL || process_frame == NULL) {
        fprintf(stderr, "Invalid input parameters\n");
        return -1;
    }
    // Iterate over all descriptors and process their frames
    for (size_t i = 0; i < descriptors->count; i++) {
        MacEntityDescriptor *descriptor = descriptors->descriptors[i];
        for (size_t j = 0; j < descriptor->frame_count; j++) {
            Layer2Frame *frame = &descriptor->frames[j];
            process_frame(frame);
        }
    }
    return 0;
}

// Define the function to monitor and log descriptor activity for performance analysis and debugging purposes
void mac_entity_descriptors_monitor(MacEntityDescriptors *descriptors, FILE *log) {
    if (descriptors == NULL || log == NULL) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }
    // Monitor and log descriptor activity for performance analysis and debugging purposes
    for (size_t i = 0; i < descriptors->count; i++) {
        MacEntityDescriptor *descriptor = descriptors->descriptors[i];
        fprintf(log, "Descriptor %d: ID=%u, Frame Count=%zu\n", i, descriptor->id, descriptor->frame_count);
    }
}

// Define the function to optimize memory usage by implementing a mechanism to reclaim unused memory from descriptors that have been removed
void mac_entity_descriptors_reclaim(MacEntityDescriptors *descriptors) {
    if (descriptors == NULL) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }
    // Reclaim unused memory from descriptors that have been removed
    for (size_t i = 0; i < descriptors->count; i++) {
        MacEntityDescriptor *descriptor = descriptors->descriptors[i];
        if (descriptor->frame_count == 0) {
            free(descriptor);
            memmove(&descriptors->descriptors[i], &descriptors->descriptors[i + 1], sizeof(MacEntityDescriptor *) * (descriptors->count - i));
            descriptors->count--;
        }
    }
}

// Define the function to calculate the average number of frames processed per second for all active descriptors
double mac_entity_descriptors_average_frames_per_second(MacEntityDescriptors *descriptors) {
    if (descriptors == NULL) {
        fprintf(stderr, "Invalid input parameters\n");
        return -1;
    }
    // Calculate the average number of frames processed per second for all active descriptors
    double total_frames = 0;
    double total_time = 0;
    for (size_t i = 0; i < descriptors->count; i++) {
        MacEntityDescriptor *descriptor = descriptors->descriptors[i];
        total_frames += descriptor->frame_count;
        total_time += descriptor->frame_count / descriptor->id;
    }
    return total_frames / total_time;
}

// Define the function to integrate with an external system for periodic data synchronization
void mac_entity_descriptors_sync(MacEntityDescriptors *descriptors, ExternalSystem *external_system) {
    if (descriptors == NULL || external_system == NULL) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }
    // Integrate with an external system for periodic data synchronization
    for (size_t i = 0; i < descriptors->count; i++) {
        MacEntityDescriptor *descriptor = descriptors->descriptors[i];
        ExternalSystemUpdate update = external_system_update(external_system, descriptor->id);
        if (update.status == EXTERNAL_SYSTEM_UPDATE_SUCCESS) {
            // Update the descriptor with the latest data from the external system
            memcpy(&descriptor->frames[0], update.data, sizeof(Layer2Frame) * update.frame_count);
            descriptor->frame_count = update.frame_count;
        } else if (update.status == EXTERNAL_SYSTEM_UPDATE_FAILURE) {
            // Handle the failure to retrieve data from the external system
            fprintf(stderr, "Failed to retrieve data from the external system\n");
        }
    }
}
