// Define the structure to hold the image metadata
typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
    char* compressionType;
    float resolutionX;
    float resolutionY;
    int extraSamples;
} ImageMetadata;

// Function to parse a TIFF image file and extract metadata
ImageMetadata parseTIFF(const char* filename) {
    // Initialize the metadata structure
    ImageMetadata metadata = {0};

    // Open the TIFF file for reading
    TIFF* tiff = TIFFOpen(filename, "r");
    if (!tiff) {
        fprintf(stderr, "Error: unable to open TIFF file %s\n", filename);
        return metadata;
    }

    // Read the image header and extract the bits per sample
    TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &metadata.bitsPerSample);

    // Check if the bits per sample is supported
    if (metadata.bitsPerSample != 1 && metadata.bitsPerSample != 2 &&
        metadata.bitsPerSample != 4 && metadata.bitsPerSample != 8 &&
        metadata.bitsPerSample != 16) {
        fprintf(stderr, "Error: unsupported bits per sample (%d)\n",
                metadata.bitsPerSample);
        TIFFClose(tiff);
        return metadata;
    }

    // Read the image header and extract the samples per pixel
    TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &metadata.samplesPerPixel);

    // Check if the number of extra samples is greater than 0
    int extraSamples = 0;
    TIFFGetField(tiff, TIFFTAG_EXTRASAMPLES, &extraSamples);
    metadata.extraSamples = extraSamples;

    // Read the image header and extract the compression type
    char* compressionType = NULL;
    TIFFGetField(tiff, TIFFTAG_COMPRESSION, &compressionType);
    metadata.compressionType = compressionType;

    // Read the image header and extract the resolution
    float resolutionX = 0.0f;
    float resolutionY = 0.0f;
    TIFFGetField(tiff, TIFFTAG_RESOLUTIONUNIT, &resolutionX, &resolutionY);
    metadata.resolutionX = resolutionX;
    metadata.resolutionY = resolutionY;

    // Close the TIFF file
    TIFFClose(tiff);

    return metadata;
}

// Function to handle errors during parsing of a TIFF image file
void parseTIFFErrorHandler(const char* filename, const char* message) {
    fprintf(stderr, "Error: unable to parse TIFF file %s (%s)\n", filename, message);
}

// Function to clean up resources after parsing a TIFF image file
void parseTIFFCleanup(const char* filename, TIFF* tiff) {
    if (tiff) {
        TIFFClose(tiff);
    }
}

// Unit tests for the parseTIFF function
void testParseTIFF() {
    // Test case 1: Parse a valid TIFF file with 8 bits per sample and 3 samples per pixel
