    assert(metadata.samplesPerPixel == 3);
    assert(strcmp(metadata.compressionType, "LZW") == 0);
    assert(metadata.resolutionX == 72.0f);
    assert(metadata.resolutionY == 72.0f);
    assert(metadata.extraSamples == 0);

    // Test case 2: Parse a valid TIFF file with 16 bits per sample and 4 samples per pixel
