    assert(metadata.bitsPerSample == 16);
    assert(metadata.samplesPerPixel == 4);
    assert(strcmp(metadata.compressionType, "LZW") == 0);
    assert(metadata.resolutionX == 72.0f);
    assert(metadata.resolutionY == 72.0f);
    assert(metadata.extraSamples == 0);

    // Test case 3: Parse a valid TIFF file with 8 bits per sample and 5 samples per pixel
    metadata = parseTIFF("test.tif");
    assert(metadata.bitsPerSample == 8);
    assert(metadata.samplesPerPixel == 5);
    assert(strcmp(metadata.compressionType, "LZW") == 0);
    assert(metadata.resolutionX == 72.0f);
    assert(metadata.resolutionY == 72.0f);
    assert(metadata.extraSamples == 1);

    // Test case 4: Parse a valid TIFF file with 8 bits per sample and 6 samples per pixel
