void retryWithExponentialBackoff(int* retries, int max_retries, int sleep_time) {
    // Increment the number of retries and check if it exceeds the maximum number of retries
    (*retries)++;
    if (*retries > max_retries) {
        return;
    }

    // Calculate the sleep time for the current retry attempt
