            printf("\t--help\t\t\tDisplays usage information.\n");
            printf("\t--version\t\tPrints the version information.\n");
            exit(0);
        } else if (strcmp(argv[i], OPTION_VERSION) == 0) {
            // Print the version information and exit
            printf("Version: %s\n", "1.0");
            exit(0);
        } else if (strncmp(argv[i], OPTION_INPUT_DIRECTORY, strlen(OPTION_INPUT_DIRECTORY)) == 0) {
            // Set the input directory
            config.input_directory = argv[i] + strlen(OPTION_INPUT_DIRECTORY);
        } else if (strncmp(argv[i], OPTION_OUTPUT_FILE, strlen(OPTION_OUTPUT_FILE)) == 0) {
            // Set the output file
            config.output_file = argv[i] + strlen(OPTION_OUTPUT_FILE);
        } else {
            // Print an error message and exit if an invalid option is specified
            printf("Error: Invalid option '%s'\n", argv[i]);
            exit(1);
        }
    }

    // Check that at least one input directory was specified
    if (config.input_directory == NULL) {
        printf("Error: No input directories specified\n");
        exit(1);
    }

    return config;
