// Define a function to process all log files in an input directory and return the total number of lines processed
int process_input_directory(char *input_directory, struct config *config) {
    // Open the input directory for reading
    DIR *dir = opendir(input_directory);
    if (dir == NULL) {
        printf("Error: Could not open directory '%s': %s\n", input_directory, strerror(errno));
        return 0;
    }

    // Initialize the number of lines processed to 0
    int num_lines = 0;

    // Iterate over each file in the input directory and process it
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        // Process the log file and increment the number of lines processed
        num_lines += process_log_file(input_directory, config);
