    if (ret < 0) {
        return -4;
    }

    // Encrypt the plaintext
    ret = EVP_EncryptUpdate(ctx, ciphertext, &plaintext_len, plaintext, plaintext_len);
    if (ret < 0) {
        return -5;
    }

    // Finalize the encryption
    ret = EVP_EncryptFinal(ctx, ciphertext + plaintext_len, &ciphertext_len);
    if (ret < 0) {
        return -6;
    }

    // Clean up the encryption context
    EVP_CIPHER_CTX_free(ctx);

    return ciphertext_len;
}

// Define the decryption function
int decrypt(struct EncryptionContext* ctx, const unsigned char* ciphertext, size_t ciphertext_len, unsigned char* plaintext) {
    // Check if the input is valid
    if (!ctx || !ciphertext || !plaintext) {
        return -1;
    }

    // Get the key from the KMS service
