    int ret = EVP_DecryptInit(ctx, ctx->cipher_suite, NULL, key);
    if (ret < 0) {
        return -4;
    }

    // Decrypt the ciphertext
    ret = EVP_DecryptUpdate(ctx, plaintext, &plaintext_len, ciphertext, ciphertext_len);
    if (ret < 0) {
