    if (!ctx) {
        return -1;
    }

    // Set the cipher suite and key size
    int ret = EVP_EncryptInit(ctx, ctx.cipher_suite, NULL, kms.get_key(ctx.key_id));
    if (ret < 0) {
        return -2;
    }

    // Encrypt the plaintext
    unsigned char* plaintext = "Hello, World!";
    size_t plaintext_len = strlen((char*)plaintext);
