    if (strcmp(config->load_balancing_algorithm, "Round Robin") != 0 && strcmp(config->load_balancing_algorithm, "Least Connected") != 0) {
        printf("Invalid load balancing algorithm: %s\n", config->load_balancing_algorithm);
        return;
    }

    // Set the configuration parameters for the DBMS client
