    // Send a cancel request to the DBMS server and log an error message
    send(socket, "CANCEL", 6, 0);
    printf("Query timed out: %d\n", query_timeout);
}

// Define the function to optimize for both speed and resource usage when processing large datasets and handling multiple concurrent queries
void optimize_for_speed_and_resource_usage(int socket) {
    // Set the socket options to optimize for speed and resource usage
    int optval = 1;
    setsockopt(socket, SOL_SOCKET, SO_REUSEADDR, &optval, sizeof(optval));
    setsockopt(socket, SOL_SOCKET, SO_KEEPALIVE, &optval, sizeof(optval));
}
