    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
    int crcflag;
} nfapi_crc_indication_pdu_t;

// Define the function to initialize the configuration structure
void init_config(config_t *config) {
    // Validate the modulation type and set it to a default value if invalid
    config->modulation_type = validate_modulation_type(config->modulation_type);

    // Validate the bandwidth and set it to a default value if invalid
    config->bandwidth = validate_bandwidth(config->bandwidth);

    // Validate the cell identity and set it to a default value if invalid
    config->cell_identity = validate_cell_identity(config->cell_identity);
}

// Define the function to initialize the sensor data structure
void init_sensor_data(sensor_data_t *sensor_data) {
    // Validate the temperature reading and set it to a default value if invalid
    sensor_data->temperature = validate_temperature(sensor_data->temperature);

    // Validate the sensor identifier and set it to a default value if invalid
    sensor_data->sensor_id = validate_sensor_id(sensor_data->sensor_id);

    // Validate the timestamp and set it to the current time if invalid
    sensor_data->timestamp = validate_timestamp(sensor_data->timestamp);
}

// Define the function to initialize the NFAPI_CRC_INDICATION_PDU_T structure
void init_nfapi_crc_indication_pdu(nfapi_crc_indication_pdu_t *nfapi_crc_indication_pdu) {
