#include <fcntl.h>
#include <zlib.h>
#include <openssl/sha.h>

void process_and_log_errors(int log_fd, int error_code, char *format, va_list args, const char *input_file, const char *output_file, const char *rules, bool verbose, const char *hash_function, const char *processing_params, int max_threads, const char *thread_scheduling) {
    // Open the input log file for reading
    FILE *input = fopen(input_file, "r");
    if (input == NULL) {
        perror("Error opening input log file");
        return;
    }

    // Open the output report file for writing
    FILE *output = fopen(output_file, "w");
    if (output == NULL) {
        perror("Error opening output report file");
        fclose(input);
        return;
    }

    // Initialize a hash function based on the provided identifier
    void *hash_function_ptr = NULL;
    if (strcmp(hash_function, "SHA256") == 0) {
        hash_function_ptr = SHA256();
    } else if (strcmp(hash_function, "SHA384") == 0) {
