    int data_sampling_rate; // Data sampling rate in percent (0-100)
    char *network_interface; // Network interface name
    int latency_threshold; // Latency threshold in milliseconds
    int packet_loss_threshold; // Packet loss threshold in percent (0-100)
} network_monitoring_config_t;

// Define the error codes for the function
#define ERROR_INVALID_INTERVAL 1
#define ERROR_INVALID_SAMPLING_RATE 2
#define ERROR_INVALID_NETWORK_INTERFACE 3
#define ERROR_INVALID_THRESHOLD 4
#define ERROR_MEMORY_ALLOCATION 5
#define ERROR_SYSTEM_CALL 6

// Define the function to initialize the network monitoring configuration structure
int init_network_monitoring_config(network_monitoring_config_t *config, int monitoring_interval, int data_sampling_rate, char *network_interface, int latency_threshold, int packet_loss_threshold) {
    // Validate the input parameters against predefined constraints
    if (monitoring_interval < 1 || monitoring_interval > 3600) {
        printf("Error: Invalid monitoring interval specified. Must be between 1 and 3600 seconds.\n");
        return ERROR_INVALID_INTERVAL;
    }
    if (data_sampling_rate < 0 || data_sampling_rate > 100) {
        printf("Error: Invalid data sampling rate specified. Must be between 0 and 100 percent.\n");
        return ERROR_INVALID_SAMPLING_RATE;
    }
    if (network_interface == NULL || strlen(network_interface) == 0) {
        printf("Error: Invalid network interface specified. Must be a valid network interface name.\n");
        return ERROR_INVALID_NETWORK_INTERFACE;
    }
    if (latency_threshold < 1 || latency_threshold > 1000) {
        printf("Error: Invalid latency threshold specified. Must be between 1 and 1000 milliseconds.\n");
        return ERROR_INVALID_THRESHOLD;
    }
    if (packet_loss_threshold < 0 || packet_loss_threshold > 100) {
        printf("Error: Invalid packet loss threshold specified. Must be between 0 and 100 percent.\n");
        return ERROR_INVALID_THRESHOLD;
    }

    // Initialize the configuration structure with the input parameters
    config->monitoring_interval = monitoring_interval;
    config->data_sampling_rate = data_sampling_rate;
    config->network_interface = network_interface;
    config->latency_threshold = latency_threshold;
    config->packet_loss_threshold = packet_loss_threshold;

    // Log the final configuration state for debugging and monitoring purposes
    printf("Final network monitoring configuration:\n");
    printf("Monitoring interval: %d seconds\n", config->monitoring_interval);
    printf("Data sampling rate: %d percent\n", config->data_sampling_rate);
    printf("Network interface: %s\n", config->network_interface);
    printf("Latency threshold: %d milliseconds\n", config->latency_threshold);
    printf("Packet loss threshold: %d percent\n", config->packet_loss_threshold);

    // Return success
    return 0;
}

// Define the function to update the network monitoring configuration structure with new parameters
int update_network_monitoring_config(network_monitoring_config_t *config, int monitoring_interval, int data_sampling_rate, char *network_interface, int latency_threshold, int packet_loss_threshold) {
    // Validate the input parameters against predefined constraints
    if (monitoring_interval < 1 || monitoring_interval > 3600) {
        printf("Error: Invalid monitoring interval specified. Must be between 1 and 3600 seconds.\n");
        return ERROR_INVALID_INTERVAL;
    }
    if (data_sampling_rate < 0 || data_sampling_rate > 100) {
        printf("Error: Invalid data sampling rate specified. Must be between 0 and 100 percent.\n");
        return ERROR_INVALID_SAMPLING_RATE;
    }
    if (network_interface == NULL || strlen(network_interface) == 0) {
        printf("Error: Invalid network interface specified. Must be a valid network interface name.\n");
        return ERROR_INVALID_NETWORK_INTERFACE;
    }
    if (latency_threshold < 1 || latency_threshold > 1000) {
        printf("Error: Invalid latency threshold specified. Must be between 1 and 1000 milliseconds.\n");
        return ERROR_INVALID_THRESHOLD;
    }
    if (packet_loss_threshold < 0 || packet_loss_threshold > 100) {
        printf("Error: Invalid packet loss threshold specified. Must be between 0 and 100 percent.\n");
        return ERROR_INVALID_THRESHOLD;
    }

    // Update the configuration structure with the new parameters
    config->monitoring_interval = monitoring_interval;
    config->data_sampling_rate = data_sampling_rate;
    config->network_interface = network_interface;
    config->latency_threshold = latency_threshold;
    config->packet_loss_threshold = packet_loss_threshold;

    // Log the updated configuration state for debugging and monitoring purposes
    printf("Updated network monitoring configuration:\n");
    printf("Monitoring interval: %d seconds\n", config->monitoring_interval);
    printf("Data sampling rate: %d percent\n", config->data_sampling_rate);
    printf("Network interface: %s\n", config->network_interface);
    printf("Latency threshold: %d milliseconds\n", config->latency_threshold);
    printf("Packet loss threshold: %d percent\n", config->packet_loss_threshold);

    // Return success
    return 0;
}

// Define the function to handle potential race conditions if the configuration structure is accessed concurrently by multiple threads
void synchronize_config(network_monitoring_config_t *config) {
    pthread_mutex_lock(&config->mutex);
    // Perform any necessary synchronization or data integrity checks here
    pthread_mutex_unlock(&config->mutex);
}

// Define the function to detect and handle potential network disruptions
void handle_network_disruption(network_monitoring_config_t *config) {
    // Implement a fallback strategy that uses alternative network interfaces or reduces data sampling rates in case of disruptions
    printf("Network disruption detected. Using alternative network interface and reducing data sampling rate.\n");
}
