import os
import json
from datetime import datetime

class Book:
    def __init__(self, title, author, series=None, series_num=None):
        self.title = title
        self.author = author
        self.series = series
        self.series_num = series_num
        self.last_read = None
        self.reading_progress = 0

    def generate_id(self):
        return f"{self.title} by {self.author}" + (f" ({self.series}, {self.series_num})" if self.series else "")

class BookLibrary:
    def __init__(self, storage_path=None):
        self.storage_path = storage_path
        self.books = {}

    def add_book(self, book):
        self.books[book.generate_id()] = book

    def get_book(self, id):
        return self.books[id]

    def update_reading_progress(self, id, progress):
        self.books[id].reading_progress = progress

    def save(self):
        with open(os.path.join(self.storage_path, "library.json"), "w") as f:
            json.dump(self.books, f)

class BookReader:
    def __init__(self, library):
        self.library = library

    def read_book(self, id):
        book = self.library.get_book(id)
        if not book:
            raise ValueError("Book not found")
        book.last_read = datetime.now()
        self.library.update_reading_progress(id, 0)

    def update_reading_progress(self, id, progress):
        book = self.library.get_book(id)
        if not book:
            raise ValueError("Book not found")
        book.reading_progress = progress

class BookMetadataService:
    def __init__(self, api_url=None):
        self.api_url = api_url

    def get_metadata(self, id):
        # Implement API call to retrieve metadata for the given ID
        pass

class BookProcessor:
    def __init__(self, library, reader, metadata_service):
        self.library = library
        self.reader = reader
        self.metadata_service = metadata_service

    def process_book(self, id):
        book = self.library.get_book(id)
        if not book:
            raise ValueError("Book not found")
        # Handle system-specific limitations and network failures
        try:
            metadata = self.metadata_service.get_metadata(id)
            book.series = metadata["series"]
            book.series_num = metadata["series_num"]
        except Exception as e:
            print(f"Error retrieving metadata for {id}: {e}")
        self.reader.read_book(id)
        self.library.save()

class BookManager:
    def __init__(self, library, reader, processor):
        self.library = library
        self.reader = reader
        self.processor = processor

    def add_book(self, title, author, series=None, series_num=None):
        book = Book(title, author, series, series_num)
        self.library.add_book(book)
        self.processor.process_book(book.generate_id())

    def get_book(self, id):
        return self.library.get_book(id)

    def update_reading_progress(self, id, progress):
        self.reader.update_reading_progress(id, progress)

# Usage example:

# Initialize the library and reader
library = BookLibrary()
reader = BookReader(library)

# Add some books to the library
library.add_book("The Hitchhiker's Guide to the Galaxy", "Douglas Adams")
library.add_book("1984", "George Orwell")
library.add_book("The Lord of the Rings", "J.R.R. Tolkien")

# Process the books and update their metadata
processor = BookProcessor(library, reader, BookMetadataService())
processor.process_book("The Hitchhiker's Guide to the Galaxy")
processor.process_book("1984")
processor.process_book("The Lord of the Rings")

# Update reading progress for a book
reader.update_reading_progress("The Hitchhiker's Guide to the Galaxy", 0.5)

# Save the library and export it as JSON
library.save()
with open("library.json", "w") as f:
    json.dump(library.books, f)']

