#include <string.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>
#include "configuration.h"
#include "logging.h"

// Configuration structure for wireless communication system and network management system (NMS)
struct configuration {
    char modulation_type[16]; // Modulation type (e.g., OFDM, QPSK, etc.)
    int bandwidth; // Bandwidth in MHz
    int cell_identity; // Cell identity
    int transmission_power; // Transmission power in dBm
    char channel_selection[16]; // Channel selection method (e.g., automatic, manual)
    char network_protocol[16]; // Network protocol (e.g., TCP, UDP, etc.)
    int maximum_bandwidth; // Maximum bandwidth in Mbps
    struct sockaddr_in gateway_ip; // Gateway IP address
    struct in_addr subnet_mask; // Subnet mask
    char dns_server_list[128]; // DNS server list (comma-separated)
    char mac_address_filtering_rules[512]; // MAC address filtering rules (e.g., allow, deny)
};

// Initialize configuration structure with default values
void initialize_configuration(struct configuration *config) {
    strcpy(config->modulation_type, "OFDM");
    config->bandwidth = 20;
    config->cell_identity = 1;
    config->transmission_power = -30;
    strcpy(config->channel_selection, "automatic");
    strcpy(config->network_protocol, "TCP");
    config->maximum_bandwidth = 100;
    config->gateway_ip.sin_family = AF_INET;
    config->subnet_mask.s_addr = htonl(0xffffff00);
    strcpy(config->dns_server_list, "8.8.8.8");
    strcpy(config->mac_address_filtering_rules, "allow all");
}

// Validate configuration parameters against predefined constraints
void validate_configuration(struct configuration *config) {
    // Modulation type
    if (strcmp(config->modulation_type, "OFDM") && strcmp(config->modulation_type, "QPSK")) {
        log_error("Invalid modulation type: %s", config->modulation_type);
        return;
    }

    // Bandwidth
    if (config->bandwidth < 10 || config->bandwidth > 80) {
        log_error("Bandwidth out of range: %d MHz", config->bandwidth);
        return;
    }

    // Cell identity
    if (config->cell_identity < 1 || config->cell_identity > 64) {
        log_error("Cell identity out of range: %d", config->cell_identity);
        return;
    }

    // Transmission power
    if (config->transmission_power < -30 || config->transmission_power > 15) {
        log_error("Transmission power out of range: %d dBm", config->transmission_power);
        return;
    }

    // Channel selection method
    if (strcmp(config->channel_selection, "automatic") && strcmp(config->channel_selection, "manual")) {
        log_error("Invalid channel selection method: %s", config->channel_selection);
        return;
    }

    // Network protocol
    if (strcmp(config->network_protocol, "TCP") && strcmp(config->network_protocol, "UDP")) {
        log_error("Invalid network protocol: %s", config->network_protocol);
        return;
    }

    // Maximum bandwidth
    if (config->maximum_bandwidth < 10 || config->maximum_bandwidth > 1000) {
        log_error("Maximum bandwidth out of range: %d Mbps", config->maximum_bandwidth);
        return;
    }

    // Gateway IP address
    if (config->gateway_ip.sin_family != AF_INET) {
        log_error("Invalid gateway IP address: %s", inet_ntoa(config->gateway_ip));
        return;
    }

    // Subnet mask
    if (config->subnet_mask.s_addr == htonl(0xffffff00)) {
        log_error("Invalid subnet mask: %s", inet_ntoa(config->subnet_mask));
        return;
    }

    // DNS server list
    if (strlen(config->dns_server_list) > 128) {
