// Update configuration structure with new values from user input
void update_configuration(struct configuration *config, char *modulation_type, int bandwidth, int cell_identity, int transmission_power, char *channel_selection, char *network_protocol, int maximum_bandwidth, struct sockaddr_in gateway_ip, struct in_addr subnet_mask, char *dns_server_list, char *mac_address_filtering_rules) {
