    // Network protocol
    if (network_protocol != NULL && strcmp(config->network_protocol, "TCP") && strcmp(config->network_protocol, "UDP")) {
        strcpy(config->network_protocol, network_protocol);
    }

    // Maximum bandwidth
    if (maximum_bandwidth != 0) {
        config->maximum_bandwidth = maximum_bandwidth;
    }

    // Gateway IP address
    if (gateway_ip.sin_family == AF_INET) {
        config->gateway_ip = gateway_ip;
    }

    // Subnet mask
    if (subnet_mask.s_addr != htonl(0xffffff00)) {
        config->subnet_mask = subnet_mask;
    }

    // DNS server list
    if (dns_server_list != NULL && strlen(config->dns_server_list) > 128) {
        strcpy(config->dns_server_list, dns_server_list);
    }

    // MAC address filtering rules
    if (mac_address_filtering_rules != NULL && strlen(config->mac_address_filtering_rules) > 512) {
        strcpy(config->mac_address_filtering_rules, mac_address_filtering_rules);
    }
}

