#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define structure for record
typedef struct {
    int key;
} Record;

// Function to read and validate configuration file
void read_config(const char* filename, int* offset_size, int* key_size) {
    // Open configuration file
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open configuration file\n");
        exit(1);
    }

    // Read and validate offset size
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        if (strncmp(line, "offset_size", 11) == 0) {
            char* endptr;
            *offset_size = strtol(line + 12, &endptr, 10);
            if (*offset_size <= 0 || *endptr != '\n') {
                printf("Error: invalid offset size\n");
                exit(1);
            }
        } else if (strncmp(line, "key_size", 8) == 0) {
            char* endptr;
            *key_size = strtol(line + 9, &endptr, 10);
            if (*key_size <= 0 || *endptr != '\n') {
                printf("Error: invalid key size\n");
                exit(1);
            }
        }
    }

    // Close configuration file
    fclose(fp);
}

// Function to allocate memory for arrays and initialize records
void allocate_memory(int offset_size, int key_size) {
    // Allocate memory for offset array
    long* offsets = malloc(offset_size * sizeof(long));
    if (offsets == NULL) {
        printf("Error: unable to allocate memory for offset array\n");
        exit(1);
    }

    // Initialize offset array with random values within specified range
    srand(time(NULL));
    for (int i = 0; i < offset_size; i++) {
        offsets[i] = rand() % key_size + 1;
    }

    // Allocate memory for key array
    int* keys = malloc(key_size * sizeof(int));
    if (keys == NULL) {
        printf("Error: unable to allocate memory for key array\n");
        exit(1);
    }

    // Initialize key array with random values within specified range
    srand(time(NULL));
    for (int i = 0; i < key_size; i++) {
        keys[i] = rand() % offset_size + 1;
    }

    // Allocate memory for record structures
    Record* records = malloc(offset_size * sizeof(Record));
    if (records == NULL) {
        printf("Error: unable to allocate memory for record structures\n");
        exit(1);
    }

    // Initialize record structures with random values within specified range
    srand(time(NULL));
    for (int i = 0; i < offset_size; i++) {
        records[i].key = rand() % key_size + 1;
    }
}

// Function to print contents of arrays and record structures in a formatted manner
void print_contents(long* offsets, int* keys, Record* records) {
    printf("Offset array:\n");
    for (int i = 0; i < offset_size; i++) {
        printf("%ld ", offsets[i]);
    }
    printf("\n\nKey array:\n");
    for (int i = 0; i < key_size; i++) {
        printf("%d ", keys[i]);
    }
    printf("\n\nRecord structures:\n");
    for (int i = 0; i < offset_size; i++) {
        printf("{%d} ", records[i].key);
    }
    printf("\n");
}

// Main function to demonstrate usage of allocate_memory and print_contents functions
int main() {
    // Read configuration file and validate input
    int offset_size, key_size;
    read_config("configuration.txt", &offset_size, &key_size);

    // Allocate memory for arrays and initialize records
    allocate_memory(offset_size, key_size);

    // Print contents of arrays and record structures in a formatted manner
    print_contents(offsets, keys, records);

    // Free allocated memory before exiting
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
