int fetch_config(const char *url, json_object **config) {
    CURL *curl;
    CURLcode res;
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_data);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, config);
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "Failed to fetch configuration: %s\n", curl_easy_strerror(res));
            return -1;
        }
    } else {
        fprintf(stderr, "Failed to initialize cURL handle\n");
        return -1;
    }
    curl_easy_cleanup(curl);
    return 0;
}

// Function to validate JSON configuration file
int validate_config(json_object *config) {
    // Check if the config object is valid
    if (!json_object_is_type(config, json_type_object)) {
        fprintf(stderr, "Invalid configuration: not an object\n");
        return -1;
    }
    // Check if the 'offset' and 'key' sections are present
    json_object *offset = json_object_object_get(config, "offset");
    json_object *key = json_object_object_get(config, "key");
    if (!offset || !key) {
        fprintf(stderr, "Invalid configuration: missing 'offset' or 'key' section\n");
        return -1;
    }
    // Check if the 'offset' and 'key' sections are arrays
    if (!json_object_is_type(offset, json_type_array) || !json_object_is_type(key, json_type_array)) {
        fprintf(stderr, "Invalid configuration: 'offset' or 'key' section is not an array\n");
        return -1;
    }
    // Check if the 'offset' and 'key' sections have the same length
    size_t offset_len = json_object_array_length(offset);
    size_t key_len = json_object_array_length(key);
    if (offset_len != key_len) {
        fprintf(stderr, "Invalid configuration: 'offset' and 'key' sections have different lengths\n");
        return -1;
    }
    // Check if the 'record' section is present
    json_object *record = json_object_object_get(config, "record");
    if (!record) {
        fprintf(stderr, "Invalid configuration: missing 'record' section\n");
        return -1;
    }
    // Check if the 'record' section is an array
    if (!json_object_is_type(record, json_type_array)) {
        fprintf(stderr, "Invalid configuration: 'record' section is not an array\n");
        return -1;
    }
    // Check if the 'record' section has a valid length
    size_t record_len = json_object_array_length(record);
    if (record_len == 0) {
        fprintf(stderr, "Invalid configuration: 'record' section is empty\n");
        return -1;
    }
    // Check if the 'record' section has a valid value range
    json_object *value = json_object_array_get_idx(record, 0);
    int min_value = json_object_get_int(json_object_object_get(config, "min_value"));
    int max_value = json_object_get_int(json_object_object_get(config, "max_value"));
    if (json_object_get_int(value) < min_value || json_object_get_int(value) > max_value) {
        fprintf(stderr, "Invalid configuration: 'record' section has an invalid value range\n");
        return -1;
    }
    return 0;
}

// Function to allocate memory for arrays and initialize record structures
int alloc_memory(json_object *config) {
    // Validate the configuration file
    if (validate_config(config) < 0) {
        fprintf(stderr, "Invalid configuration\n");
        return -1;
    }
    // Get the number of records from the 'record' section
    size_t record_len = json_object_array_length(json_object_object_get(config, "record"));
    // Allocate memory for the offset and key arrays
    long *offset = malloc(sizeof(long) * record_len);
    int *key = malloc(sizeof(int) * record_len);
    if (!offset || !key) {
        fprintf(stderr, "Failed to allocate memory for arrays\n");
        return -1;
    }
    // Initialize the offset and key arrays with random values within the specified range
    srand(time(NULL));
    for (size_t i = 0; i < record_len; i++) {
        offset[i] = rand() % json_object_get_int(json_object_object_get(config, "max_offset"));
        key[i] = rand() % json_object_get_int(json_object_object_get(config, "max_key"));
    }
    // Allocate memory for the record structures and initialize them with random values within the specified range
    Record *records = malloc(sizeof(Record) * record_len);
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        return -1;
    }
    for (size_t i = 0; i < record_len; i++) {
        records[i].value = rand() % json_object_get_int(json_object_object_get(config, "max_value"));
    }
    return 0;
}

// Function to free memory allocated by alloc_memory()
void free_memory(long *offset, int *key, Record *records) {
    // Free the offset and key arrays
    if (offset) {
        free(offset);
    }
    if (key) {
        free(key);
    }
    // Free the record structures
    if (records) {
        free(records);
    }
}

