// Function to manage dynamic file operations for configuration files
void manage_file_operations(wireless_config_t* config, char* filename) {
    // Generate unique numeric identifier for filename
    int id = rand() % 1000000 + 1;
    char new_filename[256];
    sprintf(new_filename, "%s%d.conf", filename, id);

    // Open file in read-write mode
    FILE* fp = fopen(new_filename, "r+");
    if (fp == NULL) {
        printf("Error opening file: %s\n", new_filename);
        return;
    }

    // Read configuration parameters from file
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "trace_id=", 8) == 0) {
            config->trace_id = atoi(line + 8);
        } else if (strncmp(line, "span_name=", 9) == 0) {
            strcpy(config->span_name, line + 9);
        } else if (strncmp(line, "service_version=", 15) == 0) {
            strcpy(config->service_version, line + 15);
        } else if (strncmp(line, "modulation_type=", 15) == 0) {
            strcpy(config->modulation_type, line + 15);
        } else if (strncmp(line, "bandwidth=", 9) == 0) {
            config->bandwidth = atoi(line + 9);
        } else if (strncmp(line, "cell_identity=", 12) == 0) {
            config->cell_identity = atoi(line + 12);
        } else if (strncmp(line, "transmission_power=", 17) == 0) {
            config->transmission_power = atoi(line + 17);
        } else if (strncmp(line, "snr=", 4) == 0) {
            config->snr = atof(line + 4);
        } else if (strncmp(line, "channel_frequency=", 16) == 0) {
            config->channel_frequency = atof(line + 16);
        }
    }

    // Close file
    fclose(fp);
}

