#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <json-c/json.h>

// Define the structure for a UE context
typedef struct {
    int ue_id;
    char *active_radio_bearers;
    char *handover_parameters;
} ue_context_t;

// Define the structure for a record in the offset array
typedef struct {
    long offset;
} offset_record_t;

// Define the structure for a record in the key array
typedef struct {
    int key;
} key_record_t;

// Define the structure for a record in the record array
typedef struct {
    int value;
} record_t;

// Define the hash table for UE contexts
static ue_context_t *ue_context_hash = NULL;

// Define the doubly linked list for UE contexts
static ue_context_t *ue_context_list = NULL;

// Define the custom memory allocator for UE contexts
static void *ue_context_alloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Define the custom memory deallocator for UE contexts
static void ue_context_free(void *ptr) {
    free(ptr);
}

// Define the function to add a new UE context
int add_ue_context(int ue_id, char *active_radio_bearers, char *handover_parameters) {
    // Create a new UE context
    ue_context_t *new_context = (ue_context_t *)ue_context_alloc(sizeof(ue_context_t));
    new_context->ue_id = ue_id;
    new_context->active_radio_bearers = active_radio_bearers;
    new_context->handover_parameters = handover_parameters;

    // Add the new UE context to the hash table and doubly linked list
    pthread_mutex_lock(&ue_context_hash);
    ue_context_hash[ue_id] = new_context;
    if (ue_context_list == NULL) {
        ue_context_list = new_context;
    } else {
        ue_context_t *last_context = ue_context_list;
        while (last_context->next != NULL) {
            last_context = last_context->next;
        }
        last_context->next = new_context;
    }
    pthread_mutex_unlock(&ue_context_hash);

    return 0;
}

// Define the function to update an existing UE context
int update_ue_context(int ue_id, char *active_radio_bearers, char *handover_parameters) {
    // Check if the UE context exists in the hash table
    pthread_mutex_lock(&ue_context_hash);
    if (ue_context_hash[ue_id] == NULL) {
        pthread_mutex_unlock(&ue_context_hash);
        return -1;
    }
    ue_context_t *context = ue_context_hash[ue_id];
    pthread_mutex_unlock(&ue_context_hash);

    // Update the UE context in the hash table and doubly linked list
    context->active_radio_bearers = active_radio_bearers;
    context->handover_parameters = handover_parameters;

    return 0;
}

// Define the function to retrieve a specific UE context by ID
ue_context_t *get_ue_context(int ue_id) {
    // Check if the UE context exists in the hash table
    pthread_mutex_lock(&ue_context_hash);
    if (ue_context_hash[ue_id] == NULL) {
        pthread_mutex_unlock(&ue_context_hash);
        return NULL;
    }
    ue_context_t *context = ue_context_hash[ue_id];
    pthread_mutex_unlock(&ue_context_hash);

    return context;
}

// Define the function to delete a specific UE context by ID
int delete_ue_context(int ue_id) {
    // Check if the UE context exists in the hash table
    pthread_mutex_lock(&ue_context_hash);
    if (ue_context_hash[ue_id] == NULL) {
        pthread_mutex_unlock(&ue_context_hash);
        return -1;
    }
    ue_context_t *context = ue_context_hash[ue_id];
    pthread_mutex_unlock(&ue_context_hash);

    // Remove the UE context from the hash table and doubly linked list
    pthread_mutex_lock(&ue_context_hash);
    if (context == ue_context_list) {
        ue_context_list = context->next;
    } else {
        ue_context_t *prev_context = ue_context_list;
        while (prev_context->next != context) {
            prev_context = prev_context->next;
        }
        prev_context->next = context->next;
    }
    pthread_mutex_unlock(&ue_context_hash);

    // Free the memory allocated for the UE context
    ue_context_free(context);

    return 0;
}

// Define the function to handle deactivation of a UE and delete its context
int handle_deactivation(int ue_id) {
    // Check if the UE context exists in the hash table
    pthread_mutex_lock(&ue_context_hash);
    if (ue_context_hash[ue_id] == NULL) {
        pthread_mutex_unlock(&ue_context_hash);
        return -1;
    }
    ue_context_t *context = ue_context_hash[ue_id];
    pthread_mutex_unlock(&ue_context_hash);

    // Delete the UE context from the hash table and doubly linked list
    delete_ue_context(ue_id);

    return 0;
}

// Define the function to periodically prune inactive UE contexts
void prune_inactive_contexts() {
    // Check if there are any inactive UE contexts
    pthread_mutex_lock(&ue_context_hash);
    if (ue_context_list == NULL) {
        pthread_mutex_unlock(&ue_context_hash);
        return;
    }
    ue_context_t *inactive_context = ue_context_list;
    while (inactive_context->next != NULL) {
        inactive_context = inactive_context->next;
        if (inactive_context->ue_id == 0) {
            break;
        }
    }
    pthread_mutex_unlock(&ue_context_hash);

    // If there are any inactive UE contexts, delete them
    if (inactive_context != NULL && inactive_context->next == NULL) {
        delete_ue_context(inactive_context->ue_id);
    }
}

// Define the function to parse a JSON configuration file and validate its integrity
int parse_configuration(char *filename) {
    // Open the JSON configuration file
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("fopen");
        return -1;
    }

    // Parse the JSON configuration file and validate its integrity
    json_object *root = json_object_from_file(filename);
    if (root == NULL) {
        fclose(file);
        return -1;
    }
    json_object *config = json_object_get_object(root, "configuration");
    if (config == NULL) {
        json_object_put(root);
        fclose(file);
        return -1;
    }

    // Close the JSON configuration file
    json_object_put(root);
    fclose(file);

    return 0;
}

// Define the function to initialize an array of 'record' structures
int init_records(char *filename) {
    // Parse the JSON configuration file and validate its integrity
    if (parse_configuration(filename) < 0) {
        return -1;
    }

    // Initialize an array of 'record' structures
    int record_count = json_object_array_length(config);
    record_t *records = (record_t *)ue_context_alloc(sizeof(record_t) * record_count);
    for (int i = 0; i < record_count; i++) {
        json_object *record = json_object_array_get_idx(config, i);
        records[i].value = json_object_get_int(record);
    }

    return 0;
}

// Define the function to print the contents of both the offset and key arrays, as well as the record structures, in a formatted and readable manner
void print_records() {
    // Print the contents of the offset array
    printf("Offset Array:\n");
    for (int i = 0; i < record_count; i++) {
        printf("%d: %ld\n", i, records[i].offset);
    }

    // Print the contents of the key array
    printf("Key Array:\n");
    for (int i = 0; i < record_count; i++) {
        printf("%d: %d\n", i, records[i].key);
    }

    // Print the contents of the record structures
    printf("Record Structures:\n");
    for (int i = 0; i < record_count; i++) {
        printf("%d: %d\n", i, records[i].value);
    }
}
