#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

// Define a structure to represent a NIC entity
typedef struct {
    int id;
    char* packets;
} nic_entity_t;

// Define a dynamic array to store the NIC entities
typedef struct {
    nic_entity_t** data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} nic_array_t;

// Initialize the dynamic array with a given initial capacity
void init_nic_array(nic_array_t* arr, size_t initial_capacity) {
    arr->data = (nic_entity_t**)malloc(initial_capacity * sizeof(nic_entity_t*));
    arr->capacity = initial_capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->mutex, NULL);
}

// Add a new NIC entity to the dynamic array
void add_nic(nic_array_t* arr, int id, char* packets) {
    // Check if the ID already exists in the array
    for (size_t i = 0; i < arr->size; i++) {
        if (arr->data[i]->id == id) {
            printf("Duplicate NIC ID detected. Skipping addition.\n");
            return;
        }
    }

    // Reallocate the array if necessary
    if (arr->size >= arr->capacity) {
        arr->data = (nic_entity_t**)realloc(arr->data, 2 * arr->capacity * sizeof(nic_entity_t*));
        arr->capacity *= 2;
    }

    // Add the new NIC entity to the array
    nic_entity_t* new_nic = (nic_entity_t*)malloc(sizeof(nic_entity_t));
    new_nic->id = id;
    new_nic->packets = packets;
    arr->data[arr->size++] = new_nic;
}

// Remove a NIC entity from the dynamic array by its ID
void remove_nic(nic_array_t* arr, int id) {
    // Find the index of the NIC entity to be removed
    size_t i;
    for (i = 0; i < arr->size; i++) {
        if (arr->data[i]->id == id) {
            break;
        }
    }

    // If the ID is not found, return
    if (i >= arr->size) {
        printf("NIC ID %d not found. Skipping removal.\n", id);
        return;
    }

    // Remove the NIC entity from the array
    free(arr->data[i]);
    for (size_t j = i; j < arr->size - 1; j++) {
        arr->data[j] = arr->data[j + 1];
    }
    arr->size--;
}

// Iterate over all NIC entities in the dynamic array and process their packets
void iterate_nics(nic_array_t* arr, void (*process_packet)(char*)) {
    for (size_t i = 0; i < arr->size; i++) {
        // Process each packet in the NIC entity's packet array
        char** packets = arr->data[i]->packets;
        size_t num_packets = strlen(packets);
        for (size_t j = 0; j < num_packets; j++) {
            process_packet(packets[j]);
        }
    }
}

// Smart resizing strategy for the dynamic array based on load factors and peak usage statistics
void resize_nic_array(nic_array_t* arr) {
    // Calculate the current load factor and peak usage of the array
    float load_factor = (float)arr->size / arr->capacity;
    size_t peak_usage = 0;
    for (size_t i = 0; i < arr->size; i++) {
        if (peak_usage < strlen(arr->data[i]->packets)) {
            peak_usage = strlen(arr->data[i]->packets);
        }
    }

    // Adjust the capacity of the array based on the load factor and peak usage
    if (load_factor > 0.75 && peak_usage > arr->capacity / 2) {
        arr->data = (nic_entity_t**)realloc(arr->data, 2 * arr->capacity * sizeof(nic_entity_t*));
        arr->capacity *= 2;
    } else if (load_factor < 0.25 && peak_usage < arr->capacity / 4) {
        arr->data = (nic_entity_t**)realloc(arr->data, arr->capacity / 2 * sizeof(nic_entity_t*));
        arr->capacity /= 2;
    }
}

// Segmented memory allocation scheme for the dynamic array based on usage patterns
void allocate_segment(nic_array_t* arr, size_t segment_size) {
    // Allocate a new segment of the given size
    nic_entity_t** segment = (nic_entity_t**)malloc(segment_size * sizeof(nic_entity_t*));

    // Add the new segment to the array
    arr->data = (nic_entity_t**)realloc(arr->data, (arr->size + segment_size) * sizeof(nic_entity_t*));
    for (size_t i = 0; i < segment_size; i++) {
        arr->data[arr->size++] = segment[i];
    }
}

// Detailed logging for all operations, including successful additions, removals, and packet processing events
void log_operation(nic_array_t* arr, char* operation) {
    printf("%s: %zu\n", operation, arr->size);
}

// Handle potential out-of-memory conditions gracefully by degrading gracefully rather than crashing
void handle_oom(nic_array_t* arr) {
    // Reallocate the array with a smaller capacity if necessary
    if (arr->capacity > 1024) {
        arr->data = (nic_entity_t**)realloc(arr->data, 512 * sizeof(nic_entity_t*));
        arr->capacity /= 2;
    } else {
        printf("Out of memory. Degrading gracefully.\n");
    }
}

// Handle intermittent network connectivity and recover without losing state
void handle_network_connectivity(nic_array_t* arr) {
    // Check if the network is connected
    if (!is_network_connected()) {
        printf("Network disconnected. Recovering...\n");

        // Reallocate the array with a smaller capacity if necessary
        if (arr->capacity > 1024) {
            arr->data = (nic_entity_t**)realloc(arr->data, 512 * sizeof(nic_entity_t*));
            arr->capacity /= 2;
        } else {
            printf("Network disconnected. Degrading gracefully.\n");
        }
    }
}
