// Define a struct to store extracted metadata
struct Metadata {
    int bitsPerSample;
    int samplesPerPixel;
    int extraSamplesCount;
};

// Define a function to process an image file and encrypt the data
void processImageAndEncrypt(const char* filename, const char* encryptionOption) {
    // Initialize an OpenSSL cipher object
    EVP_CIPHER_CTX *cipherCtx = EVP_CIPHER_CTX_new();

    // Load the TIFF image file and parse its metadata
    TIFF *tiff = TIFFOpen(filename, "r");
    if (tiff == NULL) {
        fprintf(stderr, "Error: failed to open TIFF file %s\n", filename);
        return;
    }

    // Extract metadata from the image
    struct Metadata metadata = {0};
    metadata.bitsPerSample = TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE);
    metadata.samplesPerPixel = TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL);
    metadata.extraSamplesCount = TIFFGetField(tiff, TIFFTAG_EXTRASAMPLES);

    // Check if the image has unsupported configuration
    if (metadata.bitsPerSample != 1 && metadata.bitsPerSample != 2 && metadata.bitsPerSample != 4 && metadata.bitsPerSample != 8 && metadata.bitsPerSample != 16) {
        fprintf(stderr, "Error: unsupported bits per sample value %d\n", metadata.bitsPerSample);
        return;
    }

    // Encrypt the extracted data using the specified encryption option
    int cipherType = EVP_get_cipherbyname(encryptionOption);
    if (cipherType == NID_undef) {
        fprintf(stderr, "Error: unknown encryption option %s\n", encryptionOption);
        return;
    }

    // Initialize the cipher object with the specified algorithm and key size
    EVP_CIPHER_CTX_init(cipherCtx);
    EVP_EncryptInit_ex(cipherCtx, cipherType, NULL, NULL, NULL);

    // Encrypt the data in chunks
    int chunkSize = 1024;
    unsigned char *dataChunk = malloc(chunkSize);
    while (TIFFReadEncodedStrip(tiff, -1, dataChunk, chunkSize) > 0) {
        EVP_EncryptUpdate(cipherCtx, NULL, &chunkSize, dataChunk, chunkSize);
    }

    // Clean up resources
    free(dataChunk);
    TIFFClose(tiff);
    EVP_CIPHER_CTX_cleanup(cipherCtx);
}

// Define a function to handle multiple input files and provide a summary report
void processImagesAndEncrypt(const char* encryptionOption, const char** filenames, int numFiles) {
    // Initialize an OpenSSL cipher object
    EVP_CIPHER_CTX *cipherCtx = EVP_CIPHER_CTX_new();

    // Load the TIFF image files and parse their metadata
    struct Metadata *metadataList = malloc(numFiles * sizeof(struct Metadata));
    for (int i = 0; i < numFiles; i++) {
        TIFF *tiff = TIFFOpen(filenames[i], "r");
        if (tiff == NULL) {
            fprintf(stderr, "Error: failed to open TIFF file %s\n", filenames[i]);
            continue;
        }

        // Extract metadata from the image
        struct Metadata metadata = {0};
        metadata.bitsPerSample = TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE);
        metadata.samplesPerPixel = TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL);
        metadata.extraSamplesCount = TIFFGetField(tiff, TIFFTAG_EXTRASAMPLES);

        // Check if the image has unsupported configuration
        if (metadata.bitsPerSample != 1 && metadata.bitsPerSample != 2 && metadata.bitsPerSample != 4 && metadata.bitsPerSample != 8 && metadata.bitsPerSample != 16) {
            fprintf(stderr, "Error: unsupported bits per sample value %d\n", metadata.bitsPerSample);
            continue;
        }

        // Encrypt the extracted data using the specified encryption option
        int cipherType = EVP_get_cipherbyname(encryptionOption);
        if (cipherType == NID_undef) {
            fprintf(stderr, "Error: unknown encryption option %s\n", encryptionOption);
            continue;
        }

        // Initialize the cipher object with the specified algorithm and key size
        EVP_CIPHER_CTX_init(cipherCtx);
        EVP_EncryptInit_ex(cipherCtx, cipherType, NULL, NULL, NULL);

        // Encrypt the data in chunks
        int chunkSize = 1024;
        unsigned char *dataChunk = malloc(chunkSize);
        while (TIFFReadEncodedStrip(tiff, -1, dataChunk, chunkSize) > 0) {
            EVP_EncryptUpdate(cipherCtx, NULL, &chunkSize, dataChunk, chunkSize);
        }

        // Clean up resources
        free(dataChunk);
        TIFFClose(tiff);
        EVP_CIPHER_CTX_cleanup(cipherCtx);

        // Store the metadata in a list for later use
        metadataList[i] = metadata;
    }

    // Print a summary report of all processed images
    printf("Summary Report\n");
    printf("-------------\n");
    printf("Total number of images: %d\n", numFiles);
    printf("Number of successful encryption attempts: %d\n", numFiles - countFailedEncryptionAttempts(metadataList, numFiles));
    printf("Number of failed encryption attempts: %d\n", countFailedEncryptionAttempts(metadataList, numFiles));
}

// Define a function to count the number of failed encryption attempts
int countFailedEncryptionAttempts(struct Metadata *metadataList, int numFiles) {
    int failedEncryptionAttempts = 0;
    for (int i = 0; i < numFiles; i++) {
        if (metadataList[i].bitsPerSample == NID_undef || metadataList[i].samplesPerPixel == NID_undef) {
            failedEncryptionAttempts++;
        }
    }
    return failedEncryptionAttempts;
}
