#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <tiffio.h>

// Define a struct to store the metadata for each image
typedef struct {
    int bits_per_sample;
    int samples_per_pixel;
    int extra_samples;
} image_metadata_t;

// Define a struct to store the encryption parameters
typedef struct {
    const EVP_CIPHER *cipher;
    int key_size;
    int iv_size;
    int block_size;
    int mode;
} encryption_params_t;

// Define a function to extract metadata from a TIFF image file
image_metadata_t extract_metadata(const char *filename) {
    TIFF *tif = TIFFOpen(filename, "r");
    if (!tif) {
        fprintf(stderr, "Error opening TIFF file: %s\n", filename);
        exit(1);
    }

    image_metadata_t metadata;
    metadata.bits_per_sample = TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE);
    metadata.samples_per_pixel = TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL);
    metadata.extra_samples = TIFFGetField(tif, TIFFTAG_EXTRASAMPLES);

    TIFFClose(tif);
    return metadata;
}

// Define a function to encrypt data using OpenSSL
void encrypt(const unsigned char *data, size_t length, const encryption_params_t *params) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit_ex(ctx, params->cipher, NULL, params->key, params->iv)) {
        fprintf(stderr, "Error initializing encryption context\n");
        exit(1);
    }

    EVP_CIPHER_CTX_set_padding(ctx, 0);
    EVP_CIPHER_CTX_set_key_length(ctx, params->key_size);
    EVP_CIPHER_CTX_set_iv_length(ctx, params->iv_size);
    EVP_CIPHER_CTX_set_block_size(ctx, params->block_size);
    EVP_CIPHER_CTX_set_flags(ctx, params->mode);

    unsigned char *encrypted = malloc(length + EVP_CIPHER_CTX_block_size(ctx));
    int encrypted_len;
    if (!EVP_EncryptUpdate(ctx, encrypted, &encrypted_len, data, length)) {
        fprintf(stderr, "Error encrypting data\n");
        exit(1);
    }

    free(data);
    EVP_CIPHER_CTX_free(ctx);
}

// Define a function to process a batch of TIFF image files
void process_images(const char *input_dir, const encryption_params_t *params) {
    DIR *dir = opendir(input_dir);
    if (!dir) {
        fprintf(stderr, "Error opening input directory: %s\n", input_dir);
        exit(1);
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char filename[PATH_MAX];
        snprintf(filename, PATH_MAX, "%s/%s", input_dir, entry->d_name);

        image_metadata_t metadata = extract_metadata(filename);
        if (metadata.bits_per_sample != 1 && metadata.bits_per_sample != 2 &&
            metadata.bits_per_sample != 4 && metadata.bits_per_sample != 8 &&
            metadata.bits_per_sample != 16) {
            fprintf(stderr, "Unsupported bits per sample: %d\n", metadata.bits_per_sample);
            continue;
        }

        if (metadata.samples_per_pixel > 4) {
            fprintf(stderr, "Unsupported samples per pixel: %d\n", metadata.samples_per_pixel);
            continue;
        }

        unsigned char *data = malloc(metadata.bits_per_sample / 8 * metadata.samples_per_pixel *
                                    metadata.extra_samples);
        size_t data_len;
        if (!TIFFReadRawStrip(filename, 0, data, &data_len)) {
            fprintf(stderr, "Error reading TIFF file: %s\n", filename);
            continue;
        }

        encrypt(data, data_len, params);
    }
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <input directory> <encryption parameters>\n", argv[0]);
        exit(1);
    }

    const char *input_dir = argv[1];
    encryption_params_t params;
    if (sscanf(argv[2], "%d:%d:%d:%d:%d", &params.cipher, &params.key_size, &params.iv_size,
               &params.block_size, &params.mode) != 5) {
        fprintf(stderr, "Invalid encryption parameters\n");
        exit(1);
    }

    process_images(input_dir, &params);
}
