        char* jsonData = malloc(1024);
        sprintf(jsonData, "{\"hostname\":\"%s\", \"ip\":\"%d.%d.%d.%d\"}", hostname, ip[0], ip[1], ip[2], ip[3]);
        curl_easy_setopt(curl, CURLOPT_URL, LOGGING_SERVICE_ENDPOINT);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, jsonData);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_perform(curl);
        free(jsonData);
        curl_slist_free_all(headers);
    }
}
