// Define the supported sample rates and bit depths
const int SUPPORTED_SAMPLE_RATES[] = {8000, 16000, 44100, 48000};
const int SUPPORTED_BIT_DEPTHS[] = {8, 16, 24};

// Define the supported number of channels
const int MAX_CHANNELS = 2;

// Define the maximum packet size for Opus encoding
const int MAX_PACKET_SIZE = 1276;

// Define the minimum buffer size for WAV parsing
