// Define the function to process an audio file and stream it over a network connection
void processAudioAndStream(char* inputFile, char* outputFile) {
    // Initialize variables for parsing the WAV header
    int sampleRate = 0;
    int numChannels = 0;
    int bitDepth = 0;
    int bufferSize = 0;

    // Open the input file and parse the WAV header
    FILE* wavFile = fopen(inputFile, "rb");
    if (wavFile == NULL) {
        printf("Error: Could not open input file %s\n", inputFile);
        return;
    }
    bufferSize = fread(&sampleRate, sizeof(int), 1, wavFile);
    if (bufferSize != 1) {
        printf("Error: Could not read sample rate from WAV header\n");
        fclose(wavFile);
        return;
    }
    bufferSize = fread(&numChannels, sizeof(int), 1, wavFile);
    if (bufferSize != 1) {
        printf("Error: Could not read number of channels from WAV header\n");
        fclose(wavFile);
        return;
    }
    bufferSize = fread(&bitDepth, sizeof(int), 1, wavFile);
    if (bufferSize != 1) {
        printf("Error: Could not read bit depth from WAV header\n");
        fclose(wavFile);
        return;
    }

    // Check that the sample rate and bit depth are supported
    int i = 0;
    for (i = 0; i < sizeof(SUPPORTED_SAMPLE_RATES) / sizeof(int); i++) {
        if (sampleRate == SUPPORTED_SAMPLE_RATES[i]) {
            break;
        }
    }
    if (i >= sizeof(SUPPORTED_SAMPLE_RATES) / sizeof(int)) {
        printf("Error: Sample rate %d is not supported\n", sampleRate);
        fclose(wavFile);
        return;
    }
    for (i = 0; i < sizeof(SUPPORTED_BIT_DEPTHS) / sizeof(int); i++) {
        if (bitDepth == SUPPORTED_BIT_DEPTHS[i]) {
            break;
        }
    }
    if (i >= sizeof(SUPPORTED_BIT_DEPTHS) / sizeof(int)) {
        printf("Error: Bit depth %d is not supported\n", bitDepth);
        fclose(wavFile);
        return;
    }

    // Check that the number of channels is supported
    if (numChannels > MAX_CHANNELS) {
        printf("Error: Number of channels %d is not supported\n", numChannels);
        fclose(wavFile);
        return;
    }

    // Initialize the Opus encoder and stream the encoded audio data over a TCP socket connection
    int opusEncoder = opus_encoder_create(sampleRate, numChannels, OPUS_APPLICATION_AUDIO, NULL);
    if (opusEncoder == NULL) {
        printf("Error: Could not create Opus encoder\n");
        fclose(wavFile);
        return;
    }
    int packetSize = opus_encoder_ctl(opusEncoder, OPUS_GET_PACKET_SIZE());
    if (packetSize < 0) {
        printf("Error: Could not get Opus packet size\n");
        fclose(wavFile);
        return;
    }
    int tcpSocket = socket(AF_INET, SOCK_STREAM, 0);
    if (tcpSocket < 0) {
        printf("Error: Could not create TCP socket\n");
        fclose(wavFile);
        return;
    }
    struct sockaddr_in serverAddr = {
        .sin_family = AF_INET,
        .sin_port = htons(8080),
        .sin_addr.s_addr = INADDR_ANY
    };
    if (bind(tcpSocket, (struct sockaddr*)&serverAddr, sizeof(serverAddr)) < 0) {
        printf("Error: Could not bind TCP socket\n");
        fclose(wavFile);
        return;
    }
    if (listen(tcpSocket, 1) < 0) {
        printf("Error: Could not listen on TCP socket\n");
        fclose(wavFile);
        return;
    }
    int clientSocket = accept(tcpSocket, NULL, NULL);
    if (clientSocket < 0) {
        printf("Error: Could not accept connection on TCP socket\n");
        fclose(wavFile);
        return;
    }
    char* buffer = malloc(packetSize * sizeof(char));
    if (buffer == NULL) {
        printf("Error: Could not allocate memory for Opus packet\n");
        fclose(wavFile);
        return;
    }
    int bytesRead = 0;
    while ((bytesRead = fread(buffer, sizeof(char), packetSize, wavFile)) > 0) {
        if (send(clientSocket, buffer, bytesRead, 0) < 0) {
            printf("Error: Could not send Opus packet over TCP socket\n");
            break;
        }
    }
    free(buffer);
    fclose(wavFile);
}
