    mac_entity_t** buckets;
    int num_buckets;
    pthread_mutex_t* mutexes; // array of mutexes for each bucket
} hash_table_t;

// Define the structure for a red-black tree to maintain the order of descriptors based on their creation time
typedef struct rb_tree {
    mac_entity_t** nodes;
    int num_nodes;
    pthread_mutex_t* mutexes; // array of mutexes for each node
} rb_tree_t;

// Define the structure for statistics on the number of frames processed and any errors encountered during operations
typedef struct stats {
    int num_frames_processed;
    int num_errors;
} stats_t;

// Function to initialize and manage a dynamic array of MAC entity descriptors
void mac_entity_manager(hash_table_t* hash_table, rb_tree_t* rb_tree, stats_t* stats) {
    // Initialize the hash table and red-black tree with default values
    hash_table->buckets = NULL;
    hash_table->num_buckets = 0;
    rb_tree->nodes = NULL;
    rb_tree->num_nodes = 0;
    stats->num_frames_processed = 0;
    stats->num_errors = 0;

    // Define the mutexes for each bucket and node in the hash table and red-black tree
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    hash_table->mutexes = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t) * hash_table->num_buckets);
    rb_tree->mutexes = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t) * rb_tree->num_nodes);
