int parseWAVHeader(FILE* wav_file, AudioMetadata* metadata) {
    // Read WAV header and extract audio metadata
    char chunk_id[4];
    fread(&chunk_id, sizeof(char), 4, wav_file);
    if (strncmp(chunk_id, "RIFF", 4) != 0) {
        printf("Error: Invalid WAV file format\n");
        return -1;
    }
    fread(&metadata->sample_rate, sizeof(int), 1, wav_file);
    fread(&metadata->channels, sizeof(int), 1, wav_file);
    fread(&metadata->bit_depth, sizeof(int), 1, wav_file);
    return 0;
}

int encodeOpus(opus_encoder* encoder, short* audio_data, int frame_size, int bitrate, int channels, int sample_rate, int bit_depth) {
    // Encode audio data into Opus format
    char* buffer = (char*)malloc(sizeof(char) * STREAMING_BUFFER_SIZE);
    int buffer_size = opus_encode(encoder, audio_data, frame_size, buffer, STREAMING_BUFFER_SIZE);
    return buffer_size;
}

void streamAudioOverTCP(char* hostname, int port, char* buffer, int buffer_size) {
    // Stream audio data over TCP socket connection
    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(port);
    inet_pton(AF_INET, hostname, &server_address.sin_addr);
    connect(sock, (struct sockaddr*)&server_address, sizeof(server_address));
    send(sock, buffer, buffer_size, 0);
}

int handlePacketLoss(char* buffer, int buffer_size, int packet_loss_percentage) {
    // Handle packet loss and retransmission
    srand(time(NULL));
    for (int i = 0; i < buffer_size; i++) {
        if (rand() % 100 <= packet_loss_percentage) {
            buffer[i] = 0xFF; // Set to invalid Opus frame
        }
    }
    return buffer_size;
}

void* processAudioThread(void* args) {
    // Process audio data in real-time using a separate thread
    while (1) {
        // Read audio data from file and encode it into Opus format
        short* audio_data = (short*)malloc(sizeof(short) * metadata.channels * OPUS_FRAME_SIZE);
        int frame_size = metadata.channels * OPUS_FRAME_SIZE;
        int bitrate = OPUS_BITRATE_MIN;
        char* buffer = (char*)malloc(sizeof(char) * STREAMING_BUFFER_SIZE);
        int buffer_size = encodeOpus(encoder, audio_data, frame_size, bitrate, metadata.channels, metadata.sample_rate, metadata.bit_depth);

        // Handle packet loss and retransmission
        handlePacketLoss(buffer, buffer_size, OPUS_PACKET_LOSS_PERCENTAGE);

        // Stream audio data over TCP socket connection
        streamAudioOverTCP(hostname, port, buffer, buffer_size);
    }
}
