void dynamicallySelectAndExecuteAttack(Character& character) {
  // Check if the character is in cooldown period for any attack type
  bool inCooldown = false;
  for (int i = 0; i < ATTACK_HISTORY.size(); i++) {
    if (ATTACK_HISTORY[i] > 0) {
      inCooldown = true;
      break;
    }
  }

  // Select an attack based on character state and cooldown status
  int attackType = -1;
  if (!inCooldown) {
    // Check if the character has enough health to perform attack 1
    if (character.getHealth() >= ATTACK_1) {
      attackType = 0;
    } else {
      // Check if the character has enough mana to perform attack 2
      if (character.getMana() >= ATTACK_2) {
        attackType = 1;
      }
    }
