// Define a structure to represent a MAC entity descriptor
typedef struct mac_entity {
    uint64_t id; // Unique identifier for the MAC entity
    char* frames; // Pointer to an array of L2 frames
    size_t frame_count; // Number of frames in the array
} mac_entity_t;

// Define a hash table to store the MAC entity descriptors
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static mac_entity_t* entities = NULL;

// Function to initialize and manage the dynamic collection of MAC entity descriptors
void init_mac_entities() {
    // Allocate memory for the hash table
    entities = (mac_entity_t*)malloc(sizeof(mac_entity_t) * 1024);
    if (!entities) {
        perror("Failed to allocate memory for MAC entity descriptors");
        exit(EXIT_FAILURE);
    }
}

// Function to add a new frame to the descriptor with the given ID
void add_frame(uint64_t id, char* frame) {
    // Acquire the mutex lock to prevent race conditions
    pthread_mutex_lock(&mutex);

    // Find the descriptor with the given ID
    mac_entity_t* entity = find_entity(id);
    if (!entity) {
        perror("Failed to find MAC entity");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the new frame and copy it into the descriptor
    char* new_frame = (char*)malloc(sizeof(char) * 1024);
    if (!new_frame) {
        perror("Failed to allocate memory for new frame");
        exit(EXIT_FAILURE);
    }
    memcpy(new_frame, frame, sizeof(char) * 1024);

    // Add the new frame to the descriptor's array of frames
    entity->frames = (char**)realloc(entity->frames, sizeof(char*) * (entity->frame_count + 1));
    if (!entity->frames) {
        perror("Failed to reallocate memory for MAC entity frames");
        exit(EXIT_FAILURE);
    }
    entity->frames[entity->frame_count++] = new_frame;

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

// Function to remove a descriptor by its ID
void remove_entity(uint64_t id) {
    // Acquire the mutex lock to prevent race conditions
    pthread_mutex_lock(&mutex);

    // Find the descriptor with the given ID
    mac_entity_t* entity = find_entity(id);
    if (!entity) {
        perror("Failed to find MAC entity");
        exit(EXIT_FAILURE);
    }

    // Free the memory for the descriptor's frames
    free(entity->frames);

    // Remove the descriptor from the hash table
    entities = (mac_entity_t*)realloc(entities, sizeof(mac_entity_t) * (num_entities - 1));
    if (!entities) {
        perror("Failed to reallocate memory for MAC entity descriptors");
        exit(EXIT_FAILURE);
    }

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

// Function to iterate over all descriptors and process their frames
void process_frames() {
    // Acquire the mutex lock to prevent race conditions
    pthread_mutex_lock(&mutex);

    // Iterate over all descriptors and process their frames
    for (int i = 0; i < num_entities; i++) {
        mac_entity_t* entity = &entities[i];
        for (int j = 0; j < entity->frame_count; j++) {
            // Process the frame using the third-party library
            process_frame(entity->frames[j]);
        }
    }

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

// Function to find a descriptor by its ID
mac_entity_t* find_entity(uint64_t id) {
    for (int i = 0; i < num_entities; i++) {
        mac_entity_t* entity = &entities[i];
        if (entity->id == id) {
            return entity;
        }
    }
    return NULL;
}
