// Define the DNS cache cleanup thread function
void *dns_cache_cleanup(void *arg) {
    while (1) {
        // Wait for the next cleanup interval
        sleep(DNS_CACHE_CLEANUP_INTERVAL);

        // Lock the mutex
        pthread_mutex_lock(&dns_cache_cleanup_mutex);

        // Clean up the DNS cache
        hdestroy_r(&dns_cache_ht);

