// Define the DNS resolution function
int dns_resolve(const char *hostname, struct in_addr *ip_address) {
    // Check if the hostname is null or empty
    if (hostname == NULL || strlen(hostname) == 0) {
        return -1;
    }

    // Check if the DNS cache is initialized
    if (!dns_cache_ht.htab) {
        // Initialize the DNS cache hash table
        hcreate_r(MAX_CACHE_ENTRIES, &dns_cache_ht);
    }

    // Lock the mutex
    pthread_mutex_lock(&dns_cache_cleanup_mutex);

    // Check if the hostname is in the DNS cache
    struct dns_cache *cache = hsearch_r(hostname, FIND, &dns_cache_ht);

    // Unlock the mutex
    pthread_mutex_unlock(&dns_cache_cleanup_mutex);

    // Check if the hostname is in the DNS cache and has not expired
    if (cache != NULL && time(NULL) < cache->expiration_time) {
        // Return the IP address from the DNS cache
        *ip_address = cache->ip_address;
        return 0;
    }

    // Create a new DNS query
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_DGRAM;
    hints.ai_protocol = IPPROTO_UDP;

    // Get the DNS server address
    struct in_addr dns_server_address;
    if (inet_pton(AF_INET, DNS_SERVER, &dns_server_address) != 1) {
        return -1;
    }

    // Perform the DNS query
    int error = getaddrinfo(hostname, NULL, &hints, &res);
    if (error != 0) {
        return -1;
    }

    // Get the IP address from the DNS response
    struct in_addr *ip_address_ptr = &((struct sockaddr_in *) res->ai_addr)->sin_addr;

    // Create a new DNS cache entry
    struct dns_cache *new_cache = malloc(sizeof(struct dns_cache));
    if (new_cache == NULL) {
        return -1;
    }

    // Set the hostname, IP address, and expiration time for the DNS cache entry
    new_cache->hostname = strdup(hostname);
    new_cache->ip_address = *ip_address_ptr;
    new_cache->expiration_time = time(NULL) + DNS_CACHE_EXPIRATION;

    // Lock the mutex
    pthread_mutex_lock(&dns_cache_cleanup_mutex);

    // Add the DNS cache entry to the hash table
    hsearch_r(new_cache, ENTER, &dns_cache_ht);

    // Unlock the mutex
    pthread_mutex_unlock(&dns_cache_cleanup_mutex);

    // Return the IP address from the DNS cache
    *ip_address = new_cache->ip_address;
    return 0;
}

// Define the main function
int main(int argc, char **argv) {
    // Check if the hostname is null or empty
    if (argc < 2 || strlen(argv[1]) == 0) {
        printf("Usage: %s <hostname>\n", argv[0]);
        return -1;
    }

    // Initialize the DNS cache hash table
    hcreate_r(MAX_CACHE_ENTRIES, &dns_cache_ht);

    // Create a new thread for the DNS cache cleanup
    pthread_attr_init(&dns_cache_cleanup_attr);
    pthread_attr_setdetachstate(&dns_cache_cleanup_attr, PTHREAD_CREATE_DETACHED);
    pthread_attr_setstacksize(&dns_cache_cleanup_attr, DNS_CACHE_CLEANUP_STACK_SIZE);
    pthread_attr_setscope(&dns_cache_cleanup_attr, DNS_CACHE_CLEANUP_AFFINITY_MASK);
    pthread_create(&dns_cache_cleanup_thread, &dns_cache_cleanup_attr, dns_cache_cleanup, NULL);

    // Perform the DNS resolution
    struct in_addr ip_address;
    int error = dns_resolve(argv[1], &ip_address);
    if (error != 0) {
        printf("Error: %s\n", strerror(errno));
        return -1;
    }

    // Print the IP address
    char ip_address_str[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &ip_address, ip_address_str, INET_ADDRSTRLEN);
    printf("IP Address: %s\n", ip_address_str);

    // Clean up the DNS cache hash table
    hdestroy_r(&dns_cache_ht);

    return 0;
}
