#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <pthread.h>

// Define the maximum number of transaction IDs to handle simultaneously
#define MAX_TRANSACTION_IDS 1000

// Define the size of the rolling buffer for each transaction ID
#define ROLLING_BUFFER_SIZE 10

// Define the decay rate for the weight factor
#define DECAY_RATE 0.95

// Define the maximum number of transactions to track within a 3-second window
#define MAX_TRANSACTIONS_PER_ID 20

// Define the structure for storing metrics
typedef struct {
    int transaction_id;
    double weighted_sum;
    int count;
} Metric;

// Define the structure for storing the rolling buffer
typedef struct {
    int transaction_id;
    double data[ROLLING_BUFFER_SIZE];
} RollingBuffer;

// Define the function to handle incoming transactions
void handleTransaction(int transaction_id, double amount) {
    // Calculate the weight factor for the current transaction
    double weight = 1.0 / pow(DECAY_RATE, (double)transaction_id);

    // Update the rolling buffer for the current transaction ID
    RollingBuffer *buffer = getRollingBuffer(transaction_id);
    buffer->data[buffer->count % ROLLING_BUFFER_SIZE] = amount * weight;
    buffer->count++;

    // Calculate the weighted sum for the current transaction ID
    double weighted_sum = 0.0;
    for (int i = 0; i < ROLLING_BUFFER_SIZE; i++) {
        weighted_sum += buffer->data[i];
    }

    // Update the metrics for the current transaction ID
    Metric *metric = getMetric(transaction_id);
    metric->weighted_sum = weighted_sum;
    metric->count++;

    // Check if the number of transactions exceeds the limit
    if (metric->count > MAX_TRANSACTIONS_PER_ID) {
        printf("Transaction ID %d has exceeded the maximum number of transactions per 3-second window\n", transaction_id);
    }
}

// Define the function to generate an aggregated report file based on configurable rules
void generateReport(char *input_file, char *output_file, char *rules, bool verbose) {
    // Initialize the metrics and rolling buffers for each transaction ID
    Metric metrics[MAX_TRANSACTION_IDS];
    RollingBuffer buffers[MAX_TRANSACTION_IDS];
    for (int i = 0; i < MAX_TRANSACTION_IDS; i++) {
        metrics[i].transaction_id = -1;
        buffers[i].transaction_id = -1;
    }

    // Read the input log file and process each transaction
    FILE *input = fopen(input_file, "r");
    while (!feof(input)) {
        int transaction_id;
        double amount;
        fscanf(input, "%d %lf", &transaction_id, &amount);
        handleTransaction(transaction_id, amount);
    }
    fclose(input);

    // Generate the aggregated report file based on the given rules
    FILE *output = fopen(output_file, "w");
    for (int i = 0; i < MAX_TRANSACTION_IDS; i++) {
        if (metrics[i].transaction_id != -1) {
            // Calculate the weighted sum and count for the current transaction ID
            double weighted_sum = metrics[i].weighted_sum;
            int count = metrics[i].count;

            // Apply the given rules to the weighted sum and count
            if (strcmp(rules, "max") == 0) {
                fprintf(output, "%d %lf\n", metrics[i].transaction_id, weighted_sum);
            } else if (strcmp(rules, "avg") == 0) {
                fprintf(output, "%d %lf\n", metrics[i].transaction_id, weighted_sum / count);
            } else if (strcmp(rules, "count") == 0) {
                fprintf(output, "%d %d\n", metrics[i].transaction_id, count);
            }
        }
    }
    fclose(output);
}

// Define the function to get the rolling buffer for a given transaction ID
RollingBuffer *getRollingBuffer(int transaction_id) {
    // Initialize the rolling buffer if it does not exist yet
    if (buffers[transaction_id].transaction_id == -1) {
        buffers[transaction_id].transaction_id = transaction_id;
        for (int i = 0; i < ROLLING_BUFFER_SIZE; i++) {
            buffers[transaction_id].data[i] = 0.0;
        }
    }
    return &buffers[transaction_id];
}

// Define the function to get the metric for a given transaction ID
Metric *getMetric(int transaction_id) {
    // Initialize the metric if it does not exist yet
    if (metrics[transaction_id].transaction_id == -1) {
        metrics[transaction_id].transaction_id = transaction_id;
        metrics[transaction_id].weighted_sum = 0.0;
        metrics[transaction_id].count = 0;
    }
    return &metrics[transaction_id];
}
```
