            log_validation_step("Location Data Unavailable");
            return ERROR_LOCATION_DATA_UNAVAILABLE;
        }
        if (fetch_bandwidth(bandwidth, &cached_bandwidth) != 0) {
            log_validation_step("Bandwidth Data Unavailable");
            return ERROR_BANDWIDTH_DATA_UNAVAILABLE;
        }
        // Cache the fetched data for future use
        config->location = cached_location;
        config->bandwidth = cached_bandwidth;
    }

