#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

// Custom memory pool for improved performance in high-throughput environments
struct MemoryPool {
    size_t capacity;
    size_t size;
    void** buffer;
};

// Least-recently-used (LRU) cache mechanism to reclaim memory from infrequently accessed messages
struct LRUCache {
    struct Node* head;
    struct Node* tail;
    size_t capacity;
    size_t size;
};

// Node structure for the LRU cache
struct Node {
    void* data;
    struct Node* next;
    struct Node* prev;
};

// Function to add a new message to the dynamic array
void addMessage(struct MemoryPool* pool, struct LRUCache* cache, NFAPI_RRC_MESSAGE_T* msg) {
    // Check if the memory pool is full
    if (pool->size == pool->capacity) {
        // Evict the least recently used message from the cache
        void* data = lruCachePop(cache);
        free(data);
    }

    // Allocate memory for the new message
