    // Update the message in the memory pool
    size_t msgSize = sizeof(NFAPI_RRC_MESSAGE_T) + msg->msgLen;
    void* newMsg = realloc(pool->buffer[idx], msgSize);
    memcpy(newMsg, msg, msgSize);
