#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <getopt.h>

#define BUFFER_SIZE 4096
#define MAX_LINES 1000000

void printUsage() {
    printf("Usage: ./program [options] input_file\n");
    printf("\t--manpage\tDisplay detailed usage instructions.\n");
    printf("\t-cs\tPrint the content of each line in lowercase.\n");
    printf("\t-o <output_file>\tRedirect all output to a specified file instead of standard output.\n");
    printf("\t-m <max_lines>\tLimit the number of lines processed per file to a specified maximum.\n");
}

void printError(char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

int main(int argc, char** argv) {
    // Check for invalid input
    if (argc < 2) {
        printUsage();
        return 1;
    }

    // Parse command line options
    int option_index = 0;
    static struct option long_options[] = {
        {"manpage", no_argument, 0, 'm'},
        {"lowercase", no_argument, 0, 'c'},
        {"output", required_argument, 0, 'o'},
        {"max-lines", required_argument, 0, 'M'},
        {0, 0, 0, 0}
    };
    int c;
    while ((c = getopt_long(argc, argv, "m:c:o:M:", long_options, &option_index)) != -1) {
        switch (c) {
            case 'm':
                // Check if max lines is a valid integer
                char* end;
                errno = 0;
                long max_lines = strtol(optarg, &end, 10);
                if (errno != 0 || *end != '\0' || max_lines < 0) {
                    printError("Invalid value for option -m");
                    return 1;
                }
                break;
            case 'c':
                // Check if lowercase is a valid argument
                if (strcmp(optarg, "lowercase") != 0) {
                    printError("Invalid argument for option -c");
                    return 1;
                }
                break;
            case 'o':
                // Check if output file is specified
                if (strlen(optarg) == 0) {
                    printError("Output file not specified");
                    return 1;
                }
                break;
            case 'M':
                // Check if max lines is a valid integer
                char* end;
                errno = 0;
                long max_lines = strtol(optarg, &end, 10);
                if (errno != 0 || *end != '\0' || max_lines < 0) {
                    printError("Invalid value for option -M");
                    return 1;
                }
                break;
            case '?':
                // Print usage information and exit
                printUsage();
                return 1;
        }
    }

    // Check if input file is specified
    if (optind >= argc) {
        printError("Input file not specified");
        return 1;
    }

    // Open input file and check for errors
    FILE* input_file = fopen(argv[optind], "r");
    if (input_file == NULL) {
        printError("Failed to open input file");
        return 1;
    }

    // Initialize variables
    long line_count = 0;
    long word_count = 0;
    char buffer[BUFFER_SIZE];
    int max_lines = MAX_LINES;
    if (option_index == 4) {
        max_lines = atoi(optarg);
    }

    // Read input file in chunks and process lines
    while (fgets(buffer, BUFFER_SIZE, input_file)) {
        line_count++;
        word_count += strlen(buffer);
        if (line_count > max_lines) {
            break;
        }
        // Print lowercase version of each line if option -c is specified
        if (option_index == 2) {
            for (int i = 0; i < strlen(buffer); i++) {
                buffer[i] = tolower(buffer[i]);
            }
        }
        // Redirect output to file if option -o is specified
        if (option_index == 3) {
            FILE* output_file = fopen(optarg, "w");
            if (output_file == NULL) {
                printError("Failed to open output file");
                return 1;
            }
            fprintf(output_file, "%s", buffer);
        } else {
            printf("%s", buffer);
        }
    }

    // Print usage information and exit if option --manpage is specified
    if (option_index == 0) {
        printUsage();
        return 1;
    }

    // Print progress updates every 10% of the total file size processed
    long total_size = ftell(input_file);
    long current_position = ftell(input_file);
    while (current_position < total_size) {
        if (current_position % (total_size / 10) == 0) {
            printf("Processed %ld%% of the file\n", current_position * 100 / total_size);
        }
        fgets(buffer, BUFFER_SIZE, input_file);
        current_position = ftell(input_file);
    }

    // Print final results
    printf("Number of lines: %ld\n", line_count);
    printf("Total word count: %ld\n", word_count);

    // Close input file and return success
    fclose(input_file);
    return 0;
}']

