    printf("Subnet mask: %s\n", config->subnet_mask);
    printf("Gateway: %s\n", config->gateway);
    for (int i = 0; i < config->dns_servers_count; i++) {
        printf("DNS server %d: %s\n", i + 1, config->dns_servers[i]);
    }
}

// Validate the IP address
bool validate_ip(const char *ip) {
    // Check if the input is a valid IPv4 address
    struct sockaddr_in sa;
    return inet_pton(AF_INET, ip, &sa.sin_addr) == 1;
}

// Validate the subnet mask
bool validate_subnet_mask(const char *subnet_mask) {
    // Check if the input is a valid IPv4 address
    struct sockaddr_in sa;
    return inet_pton(AF_INET, subnet_mask, &sa.sin_addr) == 1;
}

// Validate the gateway address
bool validate_gateway(const char *gateway) {
    // Check if the input is a valid IPv4 address
    struct sockaddr_in sa;
    return inet_pton(AF_INET, gateway, &sa.sin_addr) == 1;
}
