#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <errno.h>

#define MAX_QUERIES 10
#define TIMEOUT 5 // seconds
#define MAX_ATTEMPTS 3

int dns_resolve(const char *hostname, struct in_addr *ip) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    // Set timeout for DNS query
    struct timeval tv;
    tv.tv_sec = TIMEOUT;
    tv.tv_usec = 0;
    if (setsockopt(sockfd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv)) < 0) {
        perror("setsockopt");
        close(sockfd);
        return -1;
    }

    // Set maximum number of attempts before giving up
    int attempts = 0;

    while (attempts < MAX_ATTEMPTS) {
        struct addrinfo hints, *res;
        memset(&hints, 0, sizeof(hints));
        hints.ai_family = AF_INET;
        hints.ai_socktype = SOCK_DGRAM;

        int status = getaddrinfo(hostname, NULL, &hints, &res);
        if (status != 0) {
            perror("getaddrinfo");
            close(sockfd);
            return -1;
        }

        struct sockaddr_in *sa = (struct sockaddr_in *) res->ai_addr;
        memcpy(ip, &sa->sin_addr, sizeof(struct in_addr));

        freeaddrinfo(res);

        // Check if the DNS query was successful
        if (inet_ntop(AF_INET, ip, hostname, INET_ADDRSTRLEN) == NULL) {
            perror("inet_ntop");
            close(sockfd);
            return -1;
        }

        // Log successful resolution
        log_resolution(hostname, ip);

        break;
    }

    close(sockfd);

    if (attempts == MAX_ATTEMPTS) {
        fprintf(stderr, "Maximum number of attempts reached\n");
        return -1;
    }

    return 0;
}

void log_resolution(const char *hostname, struct in_addr *ip) {
    // Integrate with external logging service
    // ...
}
```
