// Function to initialize the list of TCP connections
void init_tcp_connections(int num_connections) {
    // Allocate memory for the array of TCP connection metadata structures
    tcp_connection_metadata_t *connections = (tcp_connection_metadata_t *)malloc(num_connections * sizeof(tcp_connection_metadata_t));

    // Initialize each structure in the array with a valid IP address, port number, and timestamp
    for (int i = 0; i < num_connections; i++) {
        connections[i].ip_address = malloc(16);
        connections[i].port = 0;
        connections[i].state = 0;
        connections[i].timestamp = time(NULL);
    }
}

// Function to read a list of IP addresses and port numbers from standard input, storing them in an array
void read_tcp_connections(int num_connections) {
    // Allocate memory for the array of TCP connection metadata structures
    tcp_connection_metadata_t *connections = (tcp_connection_metadata_t *)malloc(num_connections * sizeof(tcp_connection_metadata_t));

    // Read each IP address and port number from standard input, storing them in the appropriate structure
    for (int i = 0; i < num_connections; i++) {
        char ip_address[16];
        int port;
        scanf("%s %d", &ip_address, &port);
        connections[i].ip_address = malloc(strlen(ip_address) + 1);
        strcpy(connections[i].ip_address, ip_address);
        connections[i].port = port;
    }
}

// Function to find and print the oldest connection based on the timestamp
void print_oldest_connection() {
    // Find the oldest connection by comparing the timestamps of each structure in the array
    int oldest_index = 0;
    for (int i = 1; i < num_connections; i++) {
        if (connections[i].timestamp < connections[oldest_index].timestamp) {
            oldest_index = i;
        }
    }

    // Print the IP address, port number, and timestamp of the oldest connection
    printf("Oldest connection: %s:%d (%ld)\n", connections[oldest_index].ip_address, connections[oldest_index].port, connections[oldest_index].timestamp);
}

// Function to free resources allocated by the program
void cleanup() {
    // Free memory for each structure in the array
    for (int i = 0; i < num_connections; i++) {
        free(connections[i].ip_address);
    }

    // Free memory for the array of structures
    free(connections);
}
