// Function to initialize and read a list of IP addresses, port numbers, and packet data from standard input
void initAndReadList(ConnectionMetadata **metadata, DataPacket **packets) {
    // Initialize the metadata array
    *metadata = malloc(sizeof(ConnectionMetadata));
    (*metadata)[0].ip_address = NULL;
    (*metadata)[0].port_number = 0;
    (*metadata)[0].state = 0;
    (*metadata)[0].timestamp = 0;

    // Initialize the packets array
    *packets = malloc(sizeof(DataPacket));
    (*packets)[0].timestamp = 0;
    (*packets)[0].packet_size = 0;
    (*packets)[0].packet_data = NULL;

    // Read the list of IP addresses, port numbers, and packet data from standard input
    while (1) {
        char *ip_address = malloc(sizeof(char));
        int port_number = 0;
        int state = 0;
        time_t timestamp = 0;
        size_t packet_size = 0;
        unsigned char *packet_data = NULL;

        // Read the IP address, port number, and state from standard input
        scanf("%s %d %d", &ip_address, &port_number, &state);

        // Check if the IP address is valid
        if (inet_pton(AF_INET, ip_address, NULL) != 1) {
            free(ip_address);
            continue;
        }

        // Read the timestamp from standard input
        scanf("%ld", &timestamp);

        // Read the packet size and data from standard input
        scanf("%zu", &packet_size);
        packet_data = malloc(sizeof(unsigned char) * packet_size);
        for (int i = 0; i < packet_size; i++) {
            scanf("%c", &packet_data[i]);
