        // Add the new connection and packet to the arrays
        (*metadata)[(*metadata)[0].ip_address] = malloc(sizeof(ConnectionMetadata));
        (*metadata)[(*metadata)[0].port_number] = malloc(sizeof(ConnectionMetadata));
        (*packets)[(*packets)[0].timestamp] = malloc(sizeof(DataPacket));

        // Update the metadata and packets arrays
        (*metadata)[(*metadata)[0].ip_address].ip_address = ip_address;
        (*metadata)[(*metadata)[0].port_number].port_number = port_number;
        (*metadata)[(*metadata)[0].state].state = state;
        (*metadata)[(*metadata)[0].timestamp].timestamp = timestamp;
        (*packets)[(*packets)[0].timestamp].timestamp = timestamp;
        (*packets)[(*packets)[0].packet_size].packet_size = packet_size;
        (*packets)[(*packets)[0].packet_data].packet_data = packet_data;
    }
}

