    ConnectionMetadata *oldest_connection = (*metadata)[0];

    // Iterate over the connections and find the one with the oldest timestamp
    for (int i = 1; i < (*metadata)[0].ip_address; i++) {
        if ((*metadata)[i].timestamp < oldest_connection.timestamp) {
            oldest_connection = (*metadata)[i];
