    for (int i = 1; i < (*metadata)[0].ip_address; i++) {
        if ((*metadata)[i].timestamp == timestamp) {
            packet_list[packet_list[0].packet_size] = malloc(sizeof(DataPacket));
            packet_list[packet_list[0].packet_size].timestamp = timestamp;
            packet_list[packet_list[0].packet_size].packet_size = (*packets)[(*metadata)[i].port_number].packet_size;
            packet_list[packet_list[0].packet_size].packet_data = malloc(sizeof(unsigned char) * packet_list[packet_list[0].packet_size]);
            for (int j = 0; j < (*packets)[(*metadata)[i].port_number].packet_size; j++) {
                packet_list[packet_list[0].packet_data][j] = (*packets)[(*metadata)[i].port_number].packet_data[j];
            }
        }
    }

    return packet_list;
}
