        printf("  Size: %ld bytes\n", file_stats.st_size);
        printf("  Creation time: %s", ctime(&file_stats.st_ctime));
        printf("  Modification time: %s", ctime(&file_stats.st_mtime));

        // Compute and return the MD5 hash of a provided string parameter using a standard library function
