        if (new_filename == NULL) {
            perror("Error constructing new filename");
            continue;
        }
        printf("  New filename: %s\n", new_filename);
        free(new_filename);
    }
}

// Subroutine to compute and return the MD5 hash of a provided string parameter using a standard library function
char* computeMD5Hash(const char* str) {
    // Initialize the MD5 context
    MD5_CTX ctx;
    MD5_Init(&ctx);

    // Update the MD5 context with the input string
    MD5_Update(&ctx, str, strlen(str));

    // Finalize the MD5 hash and return it as a hexadecimal string
    unsigned char md5_hash[MD5_DIGEST_LENGTH];
    MD5_Final(md5_hash, &ctx);
    char* hex_string = malloc(2 * MD5_DIGEST_LENGTH + 1);
    if (hex_string == NULL) {
        perror("Error allocating memory for hex string");
        return NULL;
    }
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(hex_string + 2 * i, "%02x", md5_hash[i]);
    }
    hex_string[2 * MD5_DIGEST_LENGTH] = '\0';
    return hex_string;
}

// Subroutine to construct a new filename based on the original filename's characteristics
char* constructNewFilename(const char* filename) {
    // Allocate memory for the new filename
    int len = strlen(filename);
    char* new_filename = malloc(256);
    if (new_filename == NULL) {
        perror("Error allocating memory for new filename");
        return NULL;
    }

    // Build the new filename using sprintf and strcat
    int num_digits = len / 2;
    sprintf(new_filename, "%s-%d", filename, num_digits);
    char* file_type = strrchr(filename, '.');
    if (file_type != NULL) {
        strcat(new_filename, file_type);
    } else {
        strcat(new_filename, ".txt");
    }

    // Return the new filename
    return new_filename;
}
