// Define the maximum size of the array of NFAPI_CRC_INDICATION_PDU_T structures
#define MAX_STRUCTURES 1000000

// Define the structure for holding the transaction data
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to process the transaction data and generate the financial report
void process_transactions(char* input_file, char* output_file, char* metrics, bool verbose, int threshold, char* config_profile) {
    // Initialize variables for tracking the transactions and financial metrics
    int num_transactions = 0;
    double total_amount = 0.0;
    double average_amount = 0.0;
    double median_amount = 0.0;
    double max_amount = 0.0;
    double min_amount = 0.0;
    int num_filtered_transactions = 0;
    char* currency = "USD";

    // Open the input file and read in the transaction data
    FILE* fp = fopen(input_file, "r");
    if (fp == NULL) {
        printf("Error: unable to open input file %s\n", input_file);
        return;
    }

    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* transactions = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (transactions == NULL) {
        printf("Error: unable to allocate memory for transactions\n");
        fclose(fp);
        return;
    }

    // Initialize the array of NFAPI_CRC_INDICATION_PDU_T structures with random values
    srand(time(NULL));
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        transactions[i].rx_ue_information_tag = rand() % 10000;
        transactions[i].rnti = rand() % 10000;
        transactions[i].crc_indication_rel8_tag.crflag = rand() % 2;
    }

    // Loop through the array of NFAPI_CRC_INDICATION_PDU_T structures and calculate the financial metrics
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        if (transactions[i].crc_indication_rel8_tag.crflag == 1) {
            num_transactions++;
            total_amount += transactions[i].rx_ue_information_tag;
            average_amount = total_amount / num_transactions;
            if (num_transactions % 2 == 0) {
                median_amount = (transactions[i - 1].rx_ue_information_tag + transactions[i].rx_ue_information_tag) / 2.0;
            } else {
                median_amount = transactions[i].rx_ue_information_tag;
            }
            if (max_amount < transactions[i].rx_ue_information_tag) {
                max_amount = transactions[i].rx_ue_information_tag;
            }
            if (min_amount > transactions[i].rx_ue_information_tag || min_amount == 0.0) {
                min_amount = transactions[i].rx_ue_information_tag;
            }
        } else {
            num_filtered_transactions++;
        }
    }

    // Close the input file and open the output file for writing
    fclose(fp);
    FILE* fp2 = fopen(output_file, "w");
    if (fp2 == NULL) {
        printf("Error: unable to open output file %s\n", output_file);
        return;
    }

    // Write the financial metrics to the output file
    fprintf(fp2, "Financial Metrics:\n");
    fprintf(fp2, "Number of Transactions: %d\n", num_transactions);
    fprintf(fp2, "Total Amount: $%.2f\n", total_amount);
    fprintf(fp2, "Average Amount: $%.2f\n", average_amount);
    fprintf(fp2, "Median Amount: $%.2f\n", median_amount);
    fprintf(fp2, "Maximum Amount: $%.2f\n", max_amount);
    fprintf(fp2, "Minimum Amount: $%.2f\n", min_amount);
    fprintf(fp2, "Number of Filtered Transactions: %d\n", num_filtered_transactions);
    fprintf(fp2, "Currency: %s\n", currency);

    // Close the output file and free up memory
    fclose(fp2);
    free(transactions);
}

