};

// Define the cache management functions
void cache_init(struct cache **cache) {
    // Initialize the cache with a maximum size of CACHE_SIZE and a maximum number of entries of MAX_ENTRIES
    *cache = malloc(sizeof(struct cache) * CACHE_SIZE);
}

