// Define the function to process file metadata asynchronously using POSIX threads
void process_file_metadata(char *path, struct stat metadata) {
    // Create a new thread to process the file metadata
    pthread_t thread;
    pthread_create(&thread, NULL, (void *)process_file_metadata_helper, path);
}

// Define the function to process file metadata asynchronously using POSIX threads (helper function)
void *process_file_metadata_helper(char *path) {
    // Check if the file exists and is accessible
    struct stat metadata;
    if (stat(path, &metadata) == -1) {
        log_error("Error accessing file");
        return NULL;
    }

    // Check if the file is a regular file
    if (!S_ISREG(metadata.st_mode)) {
        log_warning("File is not a regular file");
        return NULL;
    }

    // Add the path and metadata to the cache
    struct cache *cache = malloc(sizeof(struct cache));
    cache->path = path;
    cache->metadata = metadata;

    // Check if the cache is full
    if (cache_size(cache) == CACHE_SIZE) {
        log_warning("Cache is full");
        return NULL;
    }

    // Add the path and metadata to the cache
    cache_add(cache, path, metadata);

    // Check if the file has been accessed recently
    struct stat recent_metadata;
    if (stat(path, &recent_metadata) == -1) {
        log_error("Error accessing file");
        return NULL;
    }

    // Check if the file is a regular file
    if (!S_ISREG(recent_metadata.st_mode)) {
        log_warning("File is not a regular file");
        return NULL;
    }

