        return NULL;
    }

    // Check if the file has been accessed recently
    if (recent_metadata.st_atime < metadata.st_atime) {
        log_info("File has been accessed recently");
        return NULL;
    }

    // Check if the file has been modified or accessed recently
    if (recent_metadata.st_mtime > metadata.st_mtime && recent_metadata.st_atime > metadata.st_atime) {
