    if (stat(path, &sb) == 0) {
        struct file_metadata *entry = malloc(sizeof(struct file_metadata));
        entry->path = path;
        entry->size = sb.st_size;
        entry->permissions = sb.st_mode;
        entry->modification_time = sb.st_mtime;
        return entry;
    } else {
        log("error", "Failed to process file: %s", path);
        return NULL;
    }
}

// Define the asynchronous processing function
void *process_file_async(void *arg) {
