};

struct PacketReport {
    vector<PacketMetadata> packets;
    map<string, int> ipCounts;
    map<uint16_t, int> portCounts;
    chrono::time_point<chrono::system_clock> startTime;
    chrono::time_point<chrono::system_clock> endTime;
};

class PacketProcessor {
public:
    PacketProcessor(int socket, int bufferSize) : socket_(socket), bufferSize_(bufferSize) {}

    void processPackets() {
        while (true) {
            // Read packet data from the socket
            char* buffer = new char[bufferSize_];
            ssize_t bytesRead = recv(socket_, buffer, bufferSize_, 0);
            if (bytesRead < 0) {
                cout << "Error reading from socket: " << strerror(errno) << endl;
                break;
            } else if (bytesRead == 0) {
                // Socket has been closed by the other end
                break;
            }

            // Parse packet metadata and add to report
            PacketMetadata metadata;
            metadata.size = bytesRead;
            struct sockaddr_in* sourceAddr = (struct sockaddr_in*)&metadata.sourceIP;
            struct sockaddr_in* destAddr = (struct sockaddr_in*)&metadata.destinationIP;
            if (getsockname(socket_, sourceAddr, sizeof(struct sockaddr_in)) < 0) {
                cout << "Error getting socket name: " << strerror(errno) << endl;
                break;
            }
            if (getpeername(socket_, destAddr, sizeof(struct sockaddr_in)) < 0) {
                cout << "Error getting peer name: " << strerror(errno) << endl;
                break;
            }
            metadata.sourcePort = ntohs(sourceAddr->sin_port);
            metadata.destinationPort = ntohs(destAddr->sin_port);
            metadata.timestamp = chrono::system_clock::now();
            report_.packets.push_back(metadata);

            // Update IP and port counts in the report
            string sourceIP = inet_ntoa(sourceAddr->sin_addr);
            string destinationIP = inet_ntoa(destAddr->sin_addr);
            report_.ipCounts[sourceIP]++;
            report_.ipCounts[destinationIP]++;
            report_.portCounts[metadata.sourcePort]++;
            report_.portCounts[metadata.destinationPort]++;

            // Update the cache with the new packet metadata
            cacheMutex_.lock();
            cache_[metadata.sourceIP + ":" + to_string(metadata.sourcePort)] = metadata;
            cache_[metadata.destinationIP + ":" + to_string(metadata.destinationPort)] = metadata;
            cacheMutex_.unlock();
        }
    }

    PacketReport getReport() {
        return report_;
    }

private:
    int socket_;
    int bufferSize_;
    PacketReport report_;
    map<string, PacketMetadata> cache_;
    mutex cacheMutex_;
};

class CachingPacketProcessor : public PacketProcessor {
public:
    CachingPacketProcessor(int socket, int bufferSize) : PacketProcessor(socket, bufferSize), cache_(10000) {}

    void processPackets() {
        while (true) {
            // Read packet data from the socket
            char* buffer = new char[bufferSize_];
            ssize_t bytesRead = recv(socket_, buffer, bufferSize_, 0);
            if (bytesRead < 0) {
