// Define encryption modes
enum EncryptionMode { ECB, EDE, EDE3, CFB };

// Define key management service (KMS)
struct KMS {
    char* key;
    int key_size;
};

// Define communication project structure
struct CommunicationProject {
    char* name;
    int priority;
    char* status;
    time_t start_date;
};

// Define logging mechanism
