// Subroutine to compute and return the MD5 hash of a provided string parameter using a standard library function
char* computeMD5Hash(const char* filename) {
    // Handle exceptions and logging issues
    try {
        unsigned char md5_hash[MD5_DIGEST_LENGTH];
        MD5((unsigned char*)filename, strlen(filename), md5_hash);
        return (char*)md5_hash;
    } catch (const std::exception& e) {
        printf("Error computing MD5 hash: %s\n", e.what());
        return NULL;
    }
}

