// Define the maximum block size and metadata cache size
#define MAX_BLOCK_SIZE 1024
#define METADATA_CACHE_SIZE 1024

// Define the minimum and maximum replication factor
#define MIN_REPLICATION_FACTOR 3
#define MAX_REPLICATION_FACTOR 5

// Define the minimum and maximum redundancy level
#define MIN_REDUNDANCY_LEVEL 1
#define MAX_REDUNDANCY_LEVEL 2

// Define the default block size, replication factor, metadata cache size, and redundancy level
#define DEFAULT_BLOCK_SIZE 512
#define DEFAULT_REPLICATION_FACTOR 4
#define DEFAULT_METADATA_CACHE_SIZE 512
#define DEFAULT_REDUNDANCY_LEVEL 1

// Define the maximum number of retries for hashing a file
#define MAX_HASHING_RETRIES 3

// Define the error codes for the configureStorageSystem function
#define ERROR_INVALID_BLOCK_SIZE -1
#define ERROR_INVALID_METADATA_CACHE_SIZE -2
#define ERROR_INVALID_REPLICATION_FACTOR -3
#define ERROR_INVALID_REDUNDANCY_LEVEL -4
#define ERROR_HASHING_FAILED -5

// Define the function to compute and return the SHA-256 hash of a file path
unsigned char* computeHash(const char* filePath) {
    // Initialize the SHA-256 context
    SHA256_CTX ctx;
    SHA256_Init(&ctx);

    // Open the file for reading
    FILE* fp = fopen(filePath, "rb");
    if (fp == NULL) {
        printf("Error: Failed to open file %s\n", filePath);
        return NULL;
    }

    // Read the file in chunks and update the hash
    char buffer[1024];
    size_t bytesRead = 0;
    while ((bytesRead = fread(buffer, 1, sizeof(buffer), fp)) > 0) {
        SHA256_Update(&ctx, buffer, bytesRead);
    }

    // Close the file
    fclose(fp);

    // Finalize the hash and return it
    unsigned char* hash = (unsigned char*)malloc(SHA256_DIGEST_LENGTH);
    SHA256_Final(hash, &ctx);
    return hash;
}

// Define the configureStorageSystem function
int configureStorageSystem(const char* blockSize, const char* metadataCacheSize, const char* replicationFactor, const char* redundancyLevel) {
    // Initialize the configuration parameters
    int configuredBlockSize = DEFAULT_BLOCK_SIZE;
    int configuredMetadataCacheSize = DEFAULT_METADATA_CACHE_SIZE;
    int configuredReplicationFactor = DEFAULT_REPLICATION_FACTOR;
    int configuredRedundancyLevel = DEFAULT_REDUNDANCY_LEVEL;

    // Validate the block size parameter
    if (blockSize != NULL) {
        int blockSizeValue = atoi(blockSize);
        if (blockSizeValue < MIN_BLOCK_SIZE || blockSizeValue > MAX_BLOCK_SIZE) {
            printf("Error: Invalid block size %d\n", blockSizeValue);
            return ERROR_INVALID_BLOCK_SIZE;
        }
        configuredBlockSize = blockSizeValue;
    }

    // Validate the metadata cache size parameter
    if (metadataCacheSize != NULL) {
        int metadataCacheSizeValue = atoi(metadataCacheSize);
        if (metadataCacheSizeValue < MIN_METADATA_CACHE_SIZE || metadataCacheSizeValue > MAX_METADATA_CACHE_SIZE) {
            printf("Error: Invalid metadata cache size %d\n", metadataCacheSizeValue);
            return ERROR_INVALID_METADATA_CACHE_SIZE;
        }
        configuredMetadataCacheSize = metadataCacheSizeValue;
    }

    // Validate the replication factor parameter
    if (replicationFactor != NULL) {
        int replicationFactorValue = atoi(replicationFactor);
        if (replicationFactorValue < MIN_REPLICATION_FACTOR || replicationFactorValue > MAX_REPLICATION_FACTOR) {
            printf("Error: Invalid replication factor %d\n", replicationFactorValue);
            return ERROR_INVALID_REPLICATION_FACTOR;
        }
        configuredReplicationFactor = replicationFactorValue;
    }

    // Validate the redundancy level parameter
    if (redundancyLevel != NULL) {
        int redundancyLevelValue = atoi(redundancyLevel);
        if (redundancyLevelValue < MIN_REDUNDANCY_LEVEL || redundancyLevelValue > MAX_REDUNDANCY_LEVEL) {
            printf("Error: Invalid redundancy level %d\n", redundancyLevelValue);
            return ERROR_INVALID_REDUNDANCY_LEVEL;
        }
        configuredRedundancyLevel = redundancyLevelValue;
    }

    // Compute the hash of the file path
    unsigned char* hash = computeHash(filePath);
    if (hash == NULL) {
        printf("Error: Failed to compute hash for file %s\n", filePath);
        return ERROR_HASHING_FAILED;
    }

    // Log the validation steps and final configuration states
    printf("Validated block size: %d\n", configuredBlockSize);
    printf("Validated metadata cache size: %d\n", configuredMetadataCacheSize);
    printf("Validated replication factor: %d\n", configuredReplicationFactor);
    printf("Validated redundancy level: %d\n", configuredRedundancyLevel);
    printf("Computed hash for file path: %s\n", filePath);

    // Return the configuration parameters
    return 0;
}
