}

// Rate limiting functions
int check_rate_limit(char* tenant_id) {
    // Check if the tenant has exceeded its query rate limit
    int queries_per_minute = 0;
    time_t current_time = time(NULL);
    for (int i = 0; i < MAX_QUERIES_PER_MINUTE; i++) {
