}

// Fallback mechanism functions
void use_local_cache(char* tenant_id, char* key, char** value) {
    // Use the local cache for configuration retrieval when remote retrieval fails temporarily
    config_entry_t* entry = NULL;
    if (cache_contains(tenant_id, key, &entry)) {
