#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define BUFFER_SIZE 4096
#define MAX_LINES 1000000
#define MAX_WORDS 1000000

struct file_info {
    char *filename;
    int fd;
    off_t size;
};

struct counter {
    long lines;
    long words;
};

void print_usage() {
    printf("Usage: ./program [options] <input files>\n");
    printf("\nOptions:\n");
    printf("  -cs\tPrint content of each line in lowercase.\n");
    printf("  -o <output file>\tRedirect all output to a specified file instead of standard output.\n");
    printf("  -m <max lines>\tLimit the number of lines processed per file to a specified maximum.\n");
    printf("  -f <max words>\tLimit the number of words printed for each line to a specified maximum.\n");
    printf("\nExamples:\n");
    printf("  ./program input.txt\n");
    printf("  ./program -cs input1.txt input2.txt > output.txt\n");
    printf("  ./program -m 50000 -f 10000 input.txt\n");
}

void* process_file(void *arg) {
    struct file_info *fi = (struct file_info *) arg;
    char buffer[BUFFER_SIZE];
    int bytes_read, i;
    long lines = 0, words = 0;
    off_t offset = 0;

    while ((bytes_read = read(fi->fd, buffer, BUFFER_SIZE)) > 0) {
        for (i = 0; i < bytes_read; i++) {
            if (buffer[i] == '\n') {
                lines++;
            } else if (buffer[i] != ' ') {
                words++;
            }
        }
    }

    pthread_mutex_lock(&counter_mutex);
    fi->lines += lines;
    fi->words += words;
    pthread_mutex_unlock(&counter_mutex);

    return NULL;
}

int main(int argc, char *argv[]) {
    int i, j;
    struct file_info *files = NULL;
    long lines = 0, words = 0;
    pthread_t threads[argc - 1];
    pthread_mutex_t counter_mutex;
    pthread_mutex_init(&counter_mutex, NULL);

    if (argc == 1) {
        print_usage();
        return 0;
    }

    for (i = 1; i < argc; i++) {
        struct file_info *fi = malloc(sizeof(struct file_info));
        fi->filename = argv[i];
        if ((fi->fd = open(argv[i], O_RDONLY)) == -1) {
            perror("open");
            return 1;
        }
        struct stat st;
        fstat(fi->fd, &st);
        fi->size = st.st_size;
        files = realloc(files, (i + 1) * sizeof(struct file_info));
        files[i - 1] = *fi;
    }

    for (i = 0; i < argc - 1; i++) {
        pthread_create(&threads[i], NULL, process_file, &files[i]);
    }

    for (i = 0; i < argc - 1; i++) {
        pthread_join(threads[i], NULL);
    }

    for (i = 1; i < argc; i++) {
        lines += files[i - 1].lines;
        words += files[i - 1].words;
    }

    if (strcmp(argv[argc - 1], "-cs") == 0) {
        for (i = 1; i < argc; i++) {
            char buffer[BUFFER_SIZE];
            int bytes_read, j;
            long lines = 0, words = 0;
            off_t offset = 0;

            while ((bytes_read = read(files[i - 1].fd, buffer, BUFFER_SIZE)) > 0) {
                for (j = 0; j < bytes_read; j++) {
                    if (buffer[j] == '\n') {
                        lines++;
                    } else if (buffer[j] != ' ') {
                        words++;
                    }
                }
            }

            pthread_mutex_lock(&counter_mutex);
            files[i - 1].lines += lines;
            files[i - 1].words += words;
            pthread_mutex_unlock(&counter_mutex);
        }
    }

    if (strcmp(argv[argc - 1], "-o") == 0) {
        char *output_file = argv[argc];
        FILE *fp;
        if ((fp = fopen(output_file, "w")) == NULL) {
            perror("fopen");
            return 1;
        }
        for (i = 1; i < argc; i++) {
            char buffer[BUFFER_SIZE];
            int bytes_read, j;
