#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure to hold the media processing pipeline configuration
typedef struct {
    int codec_type; // 0: H264, 1: VP9, 2: AV1
    int resolution; // 720p (1280x720), 1080p (1920x1080), etc.
    float frame_rate; // 30 fps, 60 fps, etc.
    int audio_sample_rate; // 44100 Hz, 48000 Hz, etc.
} pipeline_config_t;

// Define a function to initialize the media processing pipeline configuration structure
void init_pipeline_config(pipeline_config_t *config) {
    // Set default values for each parameter
    config->codec_type = 0;
    config->resolution = 720;
    config->frame_rate = 30.0f;
    config->audio_sample_rate = 44100;

    // Validate each parameter against predefined constraints
    if (config->codec_type < 0 || config->codec_type > 2) {
        printf("Invalid codec type: %d\n", config->codec_type);
        return;
    }
    if (config->resolution < 480 || config->resolution > 1920) {
        printf("Invalid resolution: %d\n", config->resolution);
        return;
    }
    if (config->frame_rate < 15.0f || config->frame_rate > 60.0f) {
        printf("Invalid frame rate: %f\n", config->frame_rate);
        return;
    }
    if (config->audio_sample_rate < 8000 || config->audio_sample_rate > 192000) {
        printf("Invalid audio sample rate: %d\n", config->audio_sample_rate);
        return;
    }

    // Log detailed information about each validation step and the final configuration state for debugging and monitoring purposes
    printf("Codec type: %s\n", (config->codec_type == 0) ? "H264" : ((config->codec_type == 1) ? "VP9" : "AV1"));
    printf("Resolution: %dx%d\n", config->resolution, config->resolution);
    printf("Frame rate: %.1f fps\n", config->frame_rate);
    printf("Audio sample rate: %d Hz\n", config->audio_sample_rate);
}

// Define a function to update the media processing pipeline configuration structure dynamically without restarting the entire pipeline
void update_pipeline_config(pipeline_config_t *config, int codec_type, int resolution, float frame_rate, int audio_sample_rate) {
    // Validate each parameter against predefined constraints
    if (codec_type < 0 || codec_type > 2) {
        printf("Invalid codec type: %d\n", codec_type);
        return;
    }
    if (resolution < 480 || resolution > 1920) {
        printf("Invalid resolution: %d\n", resolution);
        return;
    }
    if (frame_rate < 15.0f || frame_rate > 60.0f) {
        printf("Invalid frame rate: %f\n", frame_rate);
        return;
    }
    if (audio_sample_rate < 8000 || audio_sample_rate > 192000) {
        printf("Invalid audio sample rate: %d\n", audio_sample_rate);
        return;
    }

    // Update the configuration structure with the new parameters
    config->codec_type = codec_type;
    config->resolution = resolution;
    config->frame_rate = frame_rate;
    config->audio_sample_rate = audio_sample_rate;

    // Log detailed information about each validation step and the final configuration state for debugging and monitoring purposes
    printf("Codec type: %s\n", (config->codec_type == 0) ? "H264" : ((config->codec_type == 1) ? "VP9" : "AV1"));
    printf("Resolution: %dx%d\n", config->resolution, config->resolution);
    printf("Frame rate: %.1f fps\n", config->frame_rate);
    printf("Audio sample rate: %d Hz\n", config->audio_sample_rate);
}
