// Define constants for codec type, resolution, frame rate, and audio sample rate
#define CODEC_TYPE_H264 0
#define RESOLUTION_1920x1080 1
#define FRAME_RATE_30 2
#define AUDIO_SAMPLE_RATE_48K 3

// Define structure for media processing pipeline configuration
typedef struct {
    int codec_type;
    int resolution;
    int frame_rate;
    int audio_sample_rate;
} pipeline_config_t;

// Function to initialize media processing pipeline configuration
void init_pipeline_config(pipeline_config_t *config) {
    // Set default values for codec type, resolution, frame rate, and audio sample rate
    config->codec_type = CODEC_TYPE_H264;
    config->resolution = RESOLUTION_1920x1080;
    config->frame_rate = FRAME_RATE_30;
    config->audio_sample_rate = AUDIO_SAMPLE_RATE_48K;
}

// Function to validate and log media processing pipeline configuration parameters
void validate_pipeline_config(pipeline_config_t *config) {
    // Validate codec type
    if (config->codec_type != CODEC_TYPE_H264 && config->codec_type != CODEC_TYPE_H265) {
        printf("Invalid codec type: %d\n", config->codec_type);
        return;
    }

    // Validate resolution
    if (config->resolution < RESOLUTION_320x180 || config->resolution > RESOLUTION_4K) {
        printf("Invalid resolution: %d\n", config->resolution);
        return;
    }

    // Validate frame rate
    if (config->frame_rate < FRAME_RATE_15 || config->frame_rate > FRAME_RATE_60) {
        printf("Invalid frame rate: %d\n", config->frame_rate);
        return;
    }

    // Validate audio sample rate
    if (config->audio_sample_rate < AUDIO_SAMPLE_RATE_8K || config->audio_sample_rate > AUDIO_SAMPLE_RATE_192K) {
        printf("Invalid audio sample rate: %d\n", config->audio_sample_rate);
        return;
    }

    // Log final configuration state for debugging and monitoring purposes
    printf("Final pipeline configuration:\n");
    printf("Codec type: %d\n", config->codec_type);
    printf("Resolution: %d\n", config->resolution);
    printf("Frame rate: %d\n", config->frame_rate);
    printf("Audio sample rate: %d\n", config->audio_sample_rate);
}

// Function to read a file, sort its lines, and extract a sequence number from the last line
int read_file(const char *filename) {
    // Open file for reading
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error opening file: %s\n", strerror(errno));
        return -1;
    }

    // Read lines from file into an array
    char **lines = malloc(sizeof(char *) * 100);
    int line_count = 0;
    while (fgets(lines[line_count], 1024, fp) != NULL) {
        line_count++;
    }

    // Sort lines in ascending order
    qsort(lines, line_count, sizeof(char *), compare_strings);

    // Extract sequence number from last line
    char *last_line = lines[line_count - 1];
    int sequence_number = atoi(strtok(last_line, " "));

    // Close file and free memory
    fclose(fp);
    free(lines);

    return sequence_number;
}

// Function to update media processing pipeline configuration without restarting the entire pipeline
void update_pipeline_config(pipeline_config_t *config, int codec_type, int resolution, int frame_rate, int audio_sample_rate) {
    // Validate input parameters and log validation steps for debugging and monitoring purposes
    if (codec_type != CODEC_TYPE_H264 && codec_type != CODEC_TYPE_H265) {
        printf("Invalid codec type: %d\n", codec_type);
        return;
    }

    if (resolution < RESOLUTION_320x180 || resolution > RESOLUTION_4K) {
        printf("Invalid resolution: %d\n", resolution);
        return;
    }

    if (frame_rate < FRAME_RATE_15 || frame_rate > FRAME_RATE_60) {
        printf("Invalid frame rate: %d\n", frame_rate);
        return;
    }

    if (audio_sample_rate < AUDIO_SAMPLE_RATE_8K || audio_sample_rate > AUDIO_SAMPLE_RATE_192K) {
        printf("Invalid audio sample rate: %d\n", audio_sample_rate);
        return;
    }

    // Update configuration parameters
    config->codec_type = codec_type;
    config->resolution = resolution;
    config->frame_rate = frame_rate;
    config->audio_sample_rate = audio_sample_rate;

    // Log updated configuration state for debugging and monitoring purposes
    printf("Updated pipeline configuration:\n");
    printf("Codec type: %d\n", config->codec_type);
    printf("Resolution: %d\n", config->resolution);
    printf("Frame rate: %d\n", config->frame_rate);
    printf("Audio sample rate: %d\n", config->audio_sample_rate);
}

// Function to handle exceptions gracefully during media processing pipeline configuration and file reading
void handle_exceptions(const char *filename) {
    // Check if file exists
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error opening file: %s\n", strerror(errno));
        return;
    }

    // Close file and free memory
    fclose(fp);
}
