    // Add hostname to cache
    pthread_mutex_lock(&dns_cache_lock);
    if (dns_cache_size < MAX_ENTRIES) {
        dns_cache[dns_cache_size].hostname = strdup(hostname);
        memcpy(dns_cache[dns_cache_size].ip, ip, 16);
        dns_cache_size++;
