    return ascii_domain;
}

// DNS load balancing function
int dns_load_balancer_select() {
    // Select a DNS server from the list using the specified load balancing mechanism
    int dns_server_index = dns_load_balancer_select(dns_servers, sizeof(dns_servers) / sizeof(char*));
    if (dns_server_index < 0) {
        return -1;
    }

    // Return the selected DNS server index
    return dns_server_index;
}

// DNS resolution function using a specific DNS server
struct sockaddr_in* dns_resolve(char* domain, char* dns_server) {
    // Perform DNS resolution using the specified DNS server
    struct sockaddr_in* addr = dns_resolve(domain, dns_server);
    if (!addr) {
