#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define the structure of a NICP frame
typedef struct {
    MAC_FRAME macFrame;
    MAC_STATUS status;
} NICP_FRAME;

// Define the structure of a MAC_FRAME
typedef struct {
    uint16_t llid;
    L2_HEADER l2Header;
} MAC_FRAME;

// Define the structure of a L2_HEADER
typedef struct {
    uint8_t dstAddr[6];
    uint8_t srcAddr[6];
    uint16_t etherType;
} L2_HEADER;

// Define the structure of a MAC_STATUS
typedef struct {
    uint8_t statusCode;
} MAC_STATUS;

void initNICPFrames(NICP_FRAME **frames, size_t numFrames) {
    // Allocate memory for the array of NICP frames
    *frames = (NICP_FRAME *)malloc(numFrames * sizeof(NICP_FRAME));
    if (*frames == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize each NICP frame with a valid MAC_FRAME and MAC_STATUS structure
    for (size_t i = 0; i < numFrames; i++) {
        (*frames)[i].macFrame.llid = rand() % 65535;
        (*frames)[i].macFrame.l2Header.dstAddr[0] = rand() % 256;
        (*frames)[i].macFrame.l2Header.srcAddr[0] = rand() % 256;
        (*frames)[i].macFrame.l2Header.etherType = rand() % 65535;
        (*frames)[i].status.statusCode = rand() % 256;
    }
}
```']

