#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <errno.h>

#define MAX_FRAMES 1024
#define FRAME_SIZE 1518
#define DEFAULT_BUFFER_SIZE 65536
#define DEFAULT_TIMEOUT 1000
#define QOS_PRIORITY_LOW 0
#define QOS_PRIORITY_HIGH 7

typedef struct {
    uint8_t llid;
    uint8_t l2_header[14];
} MAC_FRAME;

typedef struct {
    uint8_t status_code;
} MAC_STATUS;

typedef struct {
    int socket_fd;
    bool is_open;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int buffer_size;
    int timeout;
    int qos_priority;
} NICP_CONTEXT;

NICP_CONTEXT nicp_context = {
    .socket_fd = -1,
    .is_open = false,
    .mutex = PTHREAD_MUTEX_INITIALIZER,
    .cond = PTHREAD_COND_INITIALIZER,
    .buffer_size = DEFAULT_BUFFER_SIZE,
    .timeout = DEFAULT_TIMEOUT,
    .qos_priority = QOS_PRIORITY_LOW
};

void nicp_init(NICP_CONTEXT *context) {
    context->socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (context->socket_fd < 0) {
        perror("Failed to create socket");
        return;
    }
    context->is_open = true;
}

void nicp_destroy(NICP_CONTEXT *context) {
    if (context->is_open) {
        close(context->socket_fd);
        context->is_open = false;
    }
}

bool nicp_send_frame(NICP_CONTEXT *context, MAC_FRAME *frame) {
    bool success = true;
    if (context->is_open) {
        int ret = sendto(context->socket_fd, frame, FRAME_SIZE, 0, NULL, 0);
        if (ret < 0) {
            perror("Failed to send frame");
            success = false;
        }
    } else {
        success = false;
    }
    return success;
}

bool nicp_receive_frame(NICP_CONTEXT *context, MAC_FRAME **frame) {
    bool success = true;
    if (context->is_open) {
        int ret = recvfrom(context->socket_fd, *frame, FRAME_SIZE, 0, NULL, 0);
        if (ret < 0) {
            perror("Failed to receive frame");
            success = false;
        }
    } else {
        success = false;
    }
    return success;
}

bool nicp_set_buffer_size(NICP_CONTEXT *context, int buffer_size) {
    bool success = true;
    if (context->is_open) {
        context->buffer_size = buffer_size;
    } else {
        success = false;
    }
    return success;
}

bool nicp_set_timeout(NICP_CONTEXT *context, int timeout) {
    bool success = true;
    if (context->is_open) {
        context->timeout = timeout;
    } else {
        success = false;
    }
    return success;
}

bool nicp_set_qos_priority(NICP_CONTEXT *context, int qos_priority) {
    bool success = true;
    if (context->is_open) {
        context->qos_priority = qos_priority;
    } else {
        success = false;
    }
    return success;
}

bool nicp_get_buffer_size(NICP_CONTEXT *context, int *buffer_size) {
    bool success = true;
    if (context->is_open) {
        *buffer_size = context->buffer_size;
    } else {
        success = false;
    }
    return success;
}

bool nicp_get_timeout(NICP_CONTEXT *context, int *timeout) {
    bool success = true;
    if (context->is_open) {
        *timeout = context->timeout;
    } else {
        success = false;
    }
    return success;
}

bool nicp_get_qos_priority(NICP_CONTEXT *context, int *qos_priority) {
    bool success = true;
    if (context->is_open) {
        *qos_priority = context->qos_priority;
    } else {
        success = false;
    }
    return success;
}
```
