        if (retry_count >= MAX_RETRY_ATTEMPTS) {
            printf("Error: failed to connect to data source after %d attempts\n", retry_count);
            continue;
        }

        // Extract and report metadata for the current transaction
        printf("Account ID: %s\n", metadata->account_id);
        printf("Transaction Type: %s\n", metadata->transaction_type);
        printf("Data Source: %s\n", metadata->data_source);
        printf("Timestamp: %ld\n", metadata->timestamp);

        // Handle transaction integrity issues by logging the error and continuing with the next transaction
        if (metadata->timestamp < time(NULL)) {
            printf("Error: delayed or rejected transaction detected\n");
            continue;
        }

        // Generate a detailed report for the current transaction
        printf("Original Account ID: %s\n", metadata->account_id);
        printf("Category: %s\n", get_category(metadata));
        printf("Timestamp: %ld\n", metadata->timestamp);
        printf("Transaction Type: %s\n", metadata->transaction_type);

        // Increment the total number of transactions and successful transactions
        total_transactions++;
        if (metadata->timestamp < time(NULL)) {
            successful_transactions++;
        }

        // Handle large-scale deployments with minimal overhead and provide detailed metrics on throughput, latency, and error rates
        int current_time = time(NULL);
        if (current_time - start_time >= 60) {
            printf("Throughput: %d transactions/minute\n", total_transactions / 60);
            printf("Latency: %ld milliseconds\n", current_time - metadata->timestamp);
            printf("Error Rate: %.2f%%\n", (float)error_count / total_transactions * 100);
            start_time = current_time;
            total_transactions = 0;
            successful_transactions = 0;
            error_count = 0;
        }
    }
}

