#define BUFFER_SIZE 1024
#define MAX_FILENAME_LENGTH 256

// Structure to store file information
typedef struct {
    char filename[MAX_FILENAME_LENGTH];
    int filesize;
} FileInfo;

// Function to send a file over the network
int sendFile(int sock, const char* filename) {
    // Open the file for reading
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        perror("fopen");
        return -1;
    }

    // Get the file size
    fseek(file, 0, SEEK_END);
    int filesize = ftell(file);
    rewind(file);

    // Send the file size and filename over the network
    if (send(sock, &filesize, sizeof(int), 0) < 0) {
        perror("send");
        return -1;
    }
    if (send(sock, filename, strlen(filename), 0) < 0) {
        perror("send");
        return -1;
    }

    // Send the file data over the network
    char buffer[BUFFER_SIZE];
    int bytes_read = 0;
    while ((bytes_read = fread(buffer, sizeof(char), BUFFER_SIZE, file)) > 0) {
        if (send(sock, buffer, bytes_read, 0) < 0) {
            perror("send");
            return -1;
        }
    }

    // Close the file and return success
    fclose(file);
    return 0;
}

// Function to receive a file over the network
int recvFile(int sock, const char* filename) {
    // Open the file for writing
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        perror("fopen");
        return -1;
    }

    // Receive the file size and filename from the network
    int filesize;
    char buffer[BUFFER_SIZE];
    if (recv(sock, &filesize, sizeof(int), 0) < 0) {
        perror("recv");
        return -1;
    }
    if (recv(sock, buffer, strlen(buffer), 0) < 0) {
        perror("recv");
        return -1;
    }

    // Receive the file data from the network
    int bytes_read = 0;
    while ((bytes_read = recv(sock, buffer, BUFFER_SIZE, 0)) > 0) {
        if (fwrite(buffer, sizeof(char), bytes_read, file) < 0) {
            perror("fwrite");
            return -1;
        }
    }

    // Close the file and return success
    fclose(file);
    return 0;
}

