#define BITRATE 5000000
#define COMPRESSION_ALGORITHM H264
#define AUDIO_CODEC AAC

// Define constants for performance considerations
#define MEMORY_ALLOCATION_LIMIT 100000000
#define CPU_USAGE_LIMIT 50
#define TIME_FRAME_LIMIT 5

// Define constants for resource management
#define RESOURCE_MANAGEMENT_THREADS 2
#define RESOURCE_MANAGEMENT_INTERVAL 1000

// Define constants for external media server integration
#define MEDIA_SERVER_HOST "localhost"
#define MEDIA_SERVER_PORT 8080

