    fprintf(config_file, "Service Version: %s\n", wireless_config->service_version);
    fprintf(config_file, "Modulation Type: %s\n", wireless_config->modulation_type);
    fprintf(config_file, "Bandwidth: %d\n", wireless_config->bandwidth);
    fprintf(config_file, "Cell Identity: %d\n", wireless_config->cell_identity);
    fprintf(config_file, "Transmission Power: %d\n", wireless_config->transmission_power);
    fprintf(config_file, "SNR: %f\n", wireless_config->snr);
    fprintf(config_file, "Channel Frequency: %f\n", wireless_config->channel_frequency);

