using namespace std;

namespace RandomGenerator {
    class MTGenerator {
    public:
        MTGenerator() : mt(std::random_device{}()) {}
        ~MTGenerator() = default;
        MTGenerator(const MTGenerator& other) : mt(other.mt) {}

        void generateRandomNumbers(vector<int>& numbers, int numThreads) {
            // Initialize the random number generator with a seed
            std::seed_seq seed{std::random_device{}()};
            mt.seed(seed);

            // Generate random numbers for each thread
            vector<future<void>> futures;
            for (int i = 0; i < numThreads; ++i) {
                auto future = std::async([this, &numbers]() {
                    int numRandomNumbers = 10000 / numThreads;
                    vector<int> randomNumbers(numRandomNumbers);
                    for (int i = 0; i < numRandomNumbers; ++i) {
                        randomNumbers[i] = mt();
                    }
                    numbers.insert(numbers.end(), randomNumbers.begin(), randomNumbers.end());
                });
                futures.push_back(std::move(future));
            }

            // Wait for all threads to finish
            for (auto& future : futures) {
                future.wait();
            }
        }

        int getLargestInteger() {
            return *max_element(numbers.begin(), numbers.end());
        }

        double getMean() {
            return accumulate(numbers.begin(), numbers.end(), 0.0) / numbers.size();
        }

        int getMedian() {
            sort(numbers.begin(), numbers.end());
            if (numbers.size() % 2 == 0) {
                return (numbers[numbers.size() / 2 - 1] + numbers[numbers.size() / 2]) / 2;
            } else {
                return numbers[numbers.size() / 2];
            }
        }

        int getMode() {
            unordered_map<int, int> frequencyMap;
            for (auto number : numbers) {
                ++frequencyMap[number];
            }
            auto maxFrequency = max_element(frequencyMap.begin(), frequencyMap.end(), [](const auto& a, const auto& b) { return a.second < b.second; });
            return maxFrequency->first;
        }

    private:
        std::mt19937 mt;
        vector<int> numbers;
    };
}
```
