import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;

public class URLMetadataProcessor {
    private static final int NUM_THREADS = 10; // adjust as needed
    private static final int BUFFER_SIZE = 1024 * 1024; // 1MB

    public static void processURLs(List<String> urls) {
        ExecutorService executor = Executors.newFixedThreadPool(NUM_THREADS);
        List<Future<URLMetadata>> futures = new ArrayList<>();

        for (String url : urls) {
            URLMetadata metadata = new URLMetadata();
            metadata.setUrl(url);
            futures.add(executor.submit(() -> processURL(metadata)));
        }

        executor.shutdown();
        try {
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            // handle exception
        }

        List<URLMetadata> metadataList = futures.stream()
                .map(future -> future.get())
                .collect(Collectors.toList());

        System.out.println("Processed " + urls.size() + " URLs");
    }

    private static URLMetadata processURL(URLMetadata metadata) {
        try {
            URL url = new URL(metadata.getUrl());
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            connection.connect();

            int responseCode = connection.getResponseCode();
            if (responseCode == 200) {
                metadata.setHostname(url.getHost());
                metadata.setPageTitle(connection.getHeaderField("Content-Type"));
                metadata.setContentLength(connection.getContentLengthLong());

                String content = IOUtils.toString(connection.getInputStream(), StandardCharsets.UTF_8);
                metadata.setHash(SHA256.hash(content));
            } else {
                // handle error response code
            }
        } catch (IOException e) {
            // handle exception
        }

        return metadata;
    }
}
