// Define a function to sort an array of sensor data structures using a hybrid sorting algorithm
void sort_sensor_data(sensor_data *data, int num_sensors) {
    // Validate the input parameters
    if (data == NULL || num_sensors <= 0) {
        printf("Error: Invalid input parameter\n");
        return;
    }

    // Use a hybrid sorting algorithm that combines quicksort and mergesort to optimize performance based on dataset characteristics
    int pivot = data[num_sensors / 2].temperature; // Pivot value for the partitioning step
    int left = 0; // Index of the first element in the left subarray
    int right = num_sensors - 1; // Index of the last element in the right subarray

    while (left <= right) {
        // Partition the array around the pivot value
        while (data[left].temperature < pivot) {
            left++;
        }
        while (data[right].temperature > pivot) {
            right--;
        }
        if (left <= right) {
            sensor_data temp = data[left]; // Swap the elements
            data[left] = data[right];
            data[right] = temp;
            left++;
            right--;
        }
    }

    // Recursively sort the subarrays
    if (left < num_sensors) {
        sort_sensor_data(data, left);
    }
    if (right >= 0) {
        sort_sensor_data(data + left, right - left + 1);
    }
}

