#define AUDIO_SAMPLE_RATE 48000
#define AUDIO_BIT_DEPTH 24
#define AUDIO_CHANNELS 2
#define OPUS_ENCODER_QUALITY 10
#define OPUS_ENCODER_COMPLEXITY 10
#define OPUS_ENCODER_BANDWIDTH 3
#define OPUS_PACKET_SIZE 960
#define NETWORK_BUFFER_SIZE 4096
#define PACKET_LOSS_TIMEOUT 5000 // in milliseconds

typedef struct {
    int sample_rate;
    int bit_depth;
    int channels;
} audio_metadata_t;

typedef struct {
    int socket_fd;
    char *ip_address;
    unsigned short port;
} network_connection_t;

typedef struct {
    opus_encoder *encoder;
    audio_metadata_t metadata;
    network_connection_t connection;
} streamer_state_t;

void validateAndStreamTokenResponse(const char *token_response, streamer_state_t *streamer) {
    // Parse the JSON token response and extract the required fields
    json_object *json = json_tokener_parse(token_response);
    if (!json) {
        printf("Error parsing JSON token response\n");
        return;
    }

    const char *access_token = json_object_get_string(json, "access_token");
    int expires_in = json_object_get_int(json, "expires_in");
    const char *token_type = json_object_get_string(json, "token_type");
    const char *refresh_token = json_object_get_string(json, "refresh_token");

    // Verify that the token is valid and has the required fields
    if (!access_token || !expires_in || !token_type) {
        printf("Invalid token response\n");
        return;
    }

    // Initialize an Opus encoder with the appropriate settings
    streamer->encoder = opus_encoder_create(AUDIO_SAMPLE_RATE, AUDIO_CHANNELS, OPUS_ENCODER_QUALITY, OPUS_ENCODER_COMPLEXITY, OPUS_ENCODER_BANDWIDTH);
    if (!streamer->encoder) {
        printf("Error creating Opus encoder\n");
        return;
    }

    // Open a network connection and initialize the streamer state
    streamer->socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (streamer->socket_fd < 0) {
        printf("Error opening network socket\n");
        return;
    }

    struct sockaddr_in server_address;
    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(streamer->port);
    inet_pton(AF_INET, streamer->ip_address, &server_address.sin_addr);

    if (connect(streamer->socket_fd, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        printf("Error connecting to network socket\n");
        return;
    }

    // Start the audio streaming thread
    pthread_t stream_thread;
    if (pthread_create(&stream_thread, NULL, streamer_thread, streamer)) {
        printf("Error creating audio streaming thread\n");
        return;
    }
}

void *streamer_thread(void *arg) {
    streamer_state_t *streamer = (streamer_state_t *)arg;

    // Initialize the Opus encoder and start encoding the audio data
    opus_encoder_ctl(streamer->encoder, OPUS_SET_BITRATE(OPUS_PACKET_SIZE));
    opus_encoder_ctl(streamer->encoder, OPUS_SET_VBR(1));

    while (1) {
        // Read audio data from the network buffer and encode it using Opus
        char *buffer = malloc(NETWORK_BUFFER_SIZE);
        int bytes_read = read(streamer->socket_fd, buffer, NETWORK_BUFFER_SIZE);
        if (bytes_read < 0) {
            printf("Error reading from network socket\n");
            break;
        }

        // Encode the audio data using Opus and send it over the network
        int encoded_size = opus_encode(streamer->encoder, buffer, bytes_read, NULL, 0);
        if (encoded_size < 0) {
            printf("Error encoding audio data\n");
            break;
        }

        // Send the encoded audio data over the network
        int sent_bytes = send(streamer->socket_fd, buffer, encoded_size, 0);
        if (sent_bytes < 0) {
            printf("Error sending encoded audio data\n");
            break;
        }
    }

    // Clean up the Opus encoder and network connection
    opus_encoder_destroy(streamer->encoder);
    close(streamer->socket_fd);

    return NULL;
}

int main() {
    streamer_state_t streamer = {0};
    streamer.ip_address = "127.0.0.1";
    streamer.port = 8080;

    // Initialize the audio metadata and network connection
    audio_metadata_t metadata = {AUDIO_SAMPLE_RATE, AUDIO_BIT_DEPTH, AUDIO_CHANNELS};
    streamer.connection = (network_connection_t) {0};

    // Start the audio streaming thread and wait for it to finish
    pthread_create(&streamer.stream_thread, NULL, streamer_thread, &streamer);
    pthread_join(streamer.stream_thread, NULL);

    return 0;
}
