// Configuration file parsing and validation
void parse_config(const char *filename, json_object *config) {
    // Validate configuration file format
    if (json_object_get_type(config) != json_type_object) {
        fprintf(stderr, "Invalid configuration file format\n");
        exit(1);
    }

    // Parse offset values
    json_object *offsets = json_object_object_get(config, "offsets");
    if (!offsets) {
        fprintf(stderr, "Missing offsets section in configuration file\n");
        exit(1);
    }
    size_t num_offsets = json_object_array_length(offsets);
    long *offset_values = malloc(num_offsets * sizeof(long));
    for (size_t i = 0; i < num_offsets; i++) {
        json_object *offset = json_object_array_get_idx(offsets, i);
        if (!json_object_is_type(offset, json_type_int)) {
            fprintf(stderr, "Invalid offset value in configuration file\n");
            exit(1);
        }
        offset_values[i] = json_object_get_int(offset);
    }

    // Parse key values
    json_object *keys = json_object_object_get(config, "keys");
    if (!keys) {
        fprintf(stderr, "Missing keys section in configuration file\n");
        exit(1);
    }
    size_t num_keys = json_object_array_length(keys);
    int *key_values = malloc(num_keys * sizeof(int));
    for (size_t i = 0; i < num_keys; i++) {
        json_object *key = json_object_array_get_idx(keys, i);
        if (!json_object_is_type(key, json_type_int)) {
            fprintf(stderr, "Invalid key value in configuration file\n");
            exit(1);
        }
        key_values[i] = json_object_get_int(key);
    }

    // Parse timestamp values
    json_object *timestamps = json_object_object_get(config, "timestamps");
    if (!timestamps) {
        fprintf(stderr, "Missing timestamps section in configuration file\n");
        exit(1);
    }
    size_t num_timestamps = json_object_array_length(timestamps);
    double *timestamp_values = malloc(num_timestamps * sizeof(double));
    for (size_t i = 0; i < num_timestamps; i++) {
        json_object *timestamp = json_object_array_get_idx(timestamps, i);
        if (!json_object_is_type(timestamp, json_type_double)) {
            fprintf(stderr, "Invalid timestamp value in configuration file\n");
            exit(1);
        }
        timestamp_values[i] = json_object_get_double(timestamp);
    }

    // Parse record values
    json_object *records = json_object_object_get(config, "records");
    if (!records) {
        fprintf(stderr, "Missing records section in configuration file\n");
        exit(1);
    }
    size_t num_records = json_object_array_length(records);
    struct record *record_values = malloc(num_records * sizeof(struct record));
    for (size_t i = 0; i < num_records; i++) {
        json_object *record = json_object_array_get_idx(records, i);
        if (!json_object_is_type(record, json_type_object)) {
            fprintf(stderr, "Invalid record value in configuration file\n");
            exit(1);
        }
        struct record *r = &record_values[i];
        r->value = json_object_get_int(json_object_object_get(record, "value"));
        r->offset = json_object_get_int(json_object_object_get(record, "offset"));
        r->key = json_object_get_int(json_object_object_get(record, "key"));
        r->timestamp = json_object_get_double(json_object_object_get(record, "timestamp"));
    }

    // Free memory
    free(offset_values);
    free(key_values);
    free(timestamp_values);
    free(record_values);
}

