```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>

// Define the data structures for storing transaction metadata and configuration settings
typedef struct {
    char account_id[16];
    char category[8];
    time_t timestamp;
    int transaction_type;
} transaction_metadata_t;

typedef struct {
    char hostname[256];
    int port;
    char username[32];
    char password[32];
} remote_exchange_config_t;

// Define the function for managing and optimizing transactional data streams
void manage_transactions(transaction_metadata_t *metadata, remote_exchange_config_t *config) {
    // Initialize variables for tracking performance metrics
    int num_transactions = 0;
    int num_errors = 0;
    double latency = 0.0;

    // Connect to the remote financial exchange API
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    if (getaddrinfo(config->hostname, config->port, &hints, &res) != 0) {
        fprintf(stderr, "Failed to resolve hostname: %s\n", config->hostname);
        return;
    }
    int sock = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (connect(sock, res->ai_addr, res->ai_addrlen) != 0) {
        fprintf(stderr, "Failed to connect to remote exchange: %s\n", config->hostname);
        return;
    }

    // Authenticate with the remote financial exchange API
    char *auth_message = "AUTH username=<username> password=<password>\r\n";
    auth_message = str_replace(auth_message, "<username>", config->username);
    auth_message = str_replace(auth_message, "<password>", config->password);
    send(sock, auth_message, strlen(auth_message), 0);
    char *response = recv(sock, buffer, sizeof(buffer), 0);
    if (strcmp(response, "200 OK\r\n") != 0) {
        fprintf(stderr, "Failed to authenticate with remote exchange: %s\n", config->hostname);
        return;
    }

    // Loop over the transaction metadata and process each transaction
    for (int i = 0; i < num_transactions; i++) {
        // Extract the transaction data from the metadata structure
        char *account_id = metadata[i].account_id;
        char *category = metadata[i].category;
        time_t timestamp = metadata[i].timestamp;
        int transaction_type = metadata[i].transaction_type;

        // Send the transaction data to the remote financial exchange API
        char *send_message = "SEND account_id=<account_id> category=<category> timestamp=<timestamp> transaction_type=<transaction_type>\r\n";
        send_message = str_replace(send_message, "<account_id>", account_id);
        send_message = str_replace(send_message, "<category>", category);
        send_message = str_replace(send_message, "<timestamp>", timestamp);
        send_message = str_replace(send_message, "<transaction_type>", transaction_type);
        send(sock, send_message, strlen(send_message), 0);

        // Receive the response from the remote financial exchange API
        char *response = recv(sock, buffer, sizeof(buffer), 0);
        if (strcmp(response, "200 OK\r\n") != 0) {
            fprintf(stderr, "Failed to process transaction: %s\n", account_id);
            num_errors++;
            continue;
        }

        // Update the performance metrics
        latency += (double)(clock() - timestamp) / CLOCKS_PER_SEC;
    }

    // Close the connection to the remote financial exchange API
    close(sock);

    // Print the performance metrics and configuration settings
    printf("Total transactions: %d\n", num_transactions);
    printf("Total errors: %d\n", num_errors);
    printf("Average latency: %.3f ms\n", latency / (double)num_transactions * 1000.0);
    printf("Remote exchange hostname: %s\n", config->hostname);
    printf("Remote exchange port: %d\n", config->port);
    printf("Username: %s\n", config->username);
    printf("Password: %s\n", config->password);
}

// Define the function for handling errors and logging
void handle_error(char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Define the function for managing concurrent data streams
void manage_concurrent_streams(transaction_metadata_t *metadata, remote_exchange_config_t *config) {
    // Initialize variables for tracking performance metrics
    int num_transactions = 0;
    int num_errors = 0;
    double latency = 0.0;

    // Create a thread pool for managing concurrent data streams
    pthread_t *threads = (pthread_t *)malloc(sizeof(pthread_t) * config->num_streams);
    if (threads == NULL) {
        handle_error("Failed to allocate memory for thread pool");
        return;
    }

    // Loop over the transaction metadata and create a new thread for each data stream
    for (int i = 0; i < config->num_streams; i++) {
        pthread_create(&threads[i], NULL, manage_transactions, &metadata[i]);
    }

    // Join the threads and update the performance metrics
    for (int i = 0; i < config->num_streams; i++) {
        pthread_join(threads[i], NULL);
        num_transactions += metadata[i].num_transactions;
        num_errors += metadata[i].num_errors;
        latency += metadata[i].latency;
    }

    // Print the performance metrics and configuration settings
    printf("Total transactions: %d\n", num_transactions);
    printf("Total errors: %d\n", num_errors);
    printf("Average latency: %.3f ms\n", latency / (double)num_transactions * 1000.0);
    printf("Remote exchange hostname: %s\n", config->hostname);
    printf("Remote exchange port: %d\n", config->port);
    printf("Username: %s\n", config->username);
    printf("Password: %s\n", config->password);
}

// Define the main function for managing and optimizing transactional data streams
int main(int argc, char *argv[]) {
    // Check the command-line arguments
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <hostname> <port> <username>\n", argv[0]);
        return 1;
    }

    // Initialize variables for storing transaction metadata and configuration settings
    int num_transactions = 0;
    int num_errors = 0;
    double latency = 0.0;
    char *hostname = argv[1];
    int port = atoi(argv[2]);
    char *username = argv[3];
    remote_exchange_config_t config = { .hostname = hostname, .port = port, .username = username };

    // Read the transaction metadata from a file or database
    FILE *file = fopen("transactions.txt", "r");
    if (file == NULL) {
        handle_error("Failed to open transactions file");
        return 1;
    }
    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        transaction_metadata_t metadata = { .account_id = buffer, .category = "order", .timestamp = time(NULL), .transaction_type = 1 };
        num_transactions++;
        manage_transactions(&metadata, &config);
    }
    fclose(file);

    // Print the performance metrics and configuration settings
    printf("Total transactions: %d\n", num_transactions);
    printf("Total errors: %d\n", num_errors);
    printf("Average latency: %.3f ms\n", latency / (double)num_transactions * 1000.0);
    printf("Remote exchange hostname: %s\n", config.hostname);
    printf("Remote exchange port: %d\n", config.port);
    printf("Username: %s\n", config.username);
    printf("Password: %s\n", config.password);

    // Manage concurrent data streams using a thread pool
    manage_concurrent_streams(metadata, &config);

    return 0;
}
