// Define the caching mechanism
class Cache {
public:
    Cache(int cacheSize, bool useLRUCache, bool useLFUCache) : cacheSize_(cacheSize), useLRUCache_(useLRUCache), useLFUCache_(useLFUCache) {}

    void add(const std::string& key, const SensorData& data) {
        // Check if the cache is full and evict an item if necessary
        if (cache_.size() >= cacheSize_) {
            if (useLRUCache_) {
                // Evict the least recently used item
                auto it = std::find_if(cache_.begin(), cache_.end(), [](const auto& entry) { return entry.second.lastUpdated < std::chrono::system_clock::now(); });
                if (it != cache_.end()) {
                    cache_.erase(it);
                }
            } else if (useLFUCache_) {
                // Evict the least frequently used item
                auto it = std::find_if(cache_.begin(), cache_.end(), [](const auto& entry) { return entry.second.lastUpdated < std::chrono::system_clock::now(); });
                if (it != cache_.end()) {
                    cache_.erase(it);
                }
            }
        }

        // Add the new item to the cache
        cache_.insert({key, data});
    }

    SensorData get(const std::string& key) {
        auto it = cache_.find(key);
        if (it != cache_.end()) {
            return it->second;
        } else {
            return {};
        }
    }

private:
    int cacheSize_;
    bool useLRUCache_;
    bool useLFUCache_;
    std::map<std::string, SensorData> cache_;
};

