            auto it = cache_.find(entry.sensorID);
            if (it != cache_.end()) {
                ++it->second.hitRate;
            } else {
                cache_.insert({entry.sensorID, 1});
            }
        }
    }

    void updateCacheInvalidationPatterns(const std::vector<SensorData>& data) {
        // Update the cache invalidation patterns for each sensor
        for (const auto& entry : data) {
            auto it = cache_.find(entry.sensorID);
            if (it != cache_.end()) {
                ++it->second.cacheInvalidationPattern;
            } else {
                cache_.insert({entry.sensorID, 1});
            }
        }
    }

    void updateFrequencyOfDynamicUpdates(const std::vector<SensorData>& data) {
        // Update the frequency of dynamic updates for each sensor
        for (const auto& entry : data) {
            auto it = cache_.find(entry.sensorID);
            if (it != cache_.end()) {
                ++it->second.frequencyOfDynamicUpdates;
            } else {
                cache_.insert({entry.sensorID, 1});
            }
        }
    }

private:
