// Define the configuration structure for the media and network pipeline
struct MediaAndNetworkPipelineConfig {
  int videoResolution;
  int audioResolution;
  int frameRate;
  int samplingRate;
  int bufferSize;
  int processingTimeout;
};

// Define the cache structure for storing transformed media frames
