    // Validate each parameter against predefined constraints
    if (strlen(config->modulation_type) > MODULATION_TYPE_MAX_LEN) {
        printf("Modulation type exceeds maximum length\n");
        return 0;
    } else if (config->bandwidth < BANDWIDTH_MIN || config->bandwidth > BANDWIDTH_MAX) {
        printf("Bandwidth is out of range\n");
        return 0;
    } else if (config->cell_identity < CELL_IDENTITY_MIN || config->cell_identity > CELL_IDENTITY_MAX) {
        printf("Cell identity is out of range\n");
        return 0;
    } else if (config->transmission_power < TRANSMISSION_POWER_MIN || config->transmission_power > TRANSMISSION_POWER_MAX) {
        printf("Transmission power is out of range\n");
        return 0;
    } else if (config->snr < SNR_MIN || config->snr > SNR_MAX) {
        printf("Signal-to-noise ratio is out of range\n");
        return 0;
    }

    // Log detailed information about validation steps and the final configuration state for debugging and monitoring purposes
    printf("Configuration initialized with modulation type %s, bandwidth %d MHz, cell identity %d, transmission power %d dBm, signal-to-noise ratio %.1f dB\n", config->modulation_type, config->bandwidth, config->cell_identity, config->transmission_power, config->snr);

    // Return 1 if all parameters are validated successfully
    return 1;
}

// Function to run a given command in the background using `fork` and `wait` system calls
int run_command(char *command) {
    pid_t pid = fork();
    if (pid == 0) { // Child process
        execl("/bin/sh", "sh", "-c", command, NULL);
        exit(127);
    } else if (pid < 0) { // Error
        printf("Error forking child process\n");
        return -1;
    }

    // Monitor the resource usage of each command
    struct rusage usage;
    wait4(pid, &usage, WNOHANG, NULL);
    if (usage.ru_maxrss > MAX_MEMORY || usage.ru_utime.tv_sec + usage.ru_stime.tv_sec > MAX_CPU) {
        printf("Resource exceedance detected, terminating command\n");
        kill(pid, SIGKILL);
    }

    // Provide a callback interface for users to be notified of command completion, failure, or resource exceedance
    if (waitpid(pid, NULL, WNOHANG) == pid) {
        command_callback(0);
    } else {
        command_callback(-1);
    }

    // Return 1 if all commands are successfully executed within constraints
    return 1;
}
