int init_telemetry_system(const char* device_id, const time_t timestamp, const char* status, void* sensor_data) {
    // Check if the device ID is empty or NULL
    if (device_id == NULL || strlen(device_id) == 0) {
        return -1;
    }

    // Check if the timestamp is within a valid range
    if (timestamp < 0 || timestamp > time(NULL)) {
        return -2;
