    strcpy(data->device_id, device_id);
    data->timestamp = timestamp;
    strcpy(data->status, status);
    data->sensor_data = sensor_data;

    // Initialize the shared sensor data structure
    shared_sensor_data_t* shared_data = malloc(sizeof(shared_sensor_data_t));
    if (shared_data == NULL) {
        return -5;
    }

    // Set the number of sensors to 0
    shared_data->num_sensors = 0;

    // Initialize the sensor IDs and values arrays
    shared_data->sensor_ids = malloc(sizeof(int) * 16);
    if (shared_data->sensor_ids == NULL) {
        return -6;
    }
    shared_data->sensor_values = malloc(sizeof(float*) * 16);
    if (shared_data->sensor_values == NULL) {
        return -7;
    }

    // Set the communication frequency, data retention period, batch size for aggregation, and network buffer size
    int comm_freq = 10; // Hz
    int data_retention = 3600; // seconds
    int batch_size = 100;
    int net_buffer_size = 1024 * 1024; // bytes

    // Validate the parameters against predefined constraints
    if (comm_freq < 1 || comm_freq > 100) {
        return -8;
    }
    if (data_retention < 60 || data_retention > 3600 * 24) {
        return -9;
    }
    if (batch_size < 1 || batch_size > 1000) {
        return -10;
    }
    if (net_buffer_size < 1024 || net_buffer_size > 1024 * 1024 * 16) {
        return -11;
    }

    // Implement error handling and log detailed information about validation steps and the final configuration state
    printf("Telemetry system initialized with parameters:\n");
    printf("\tCommunication frequency: %d Hz\n", comm_freq);
    printf("\tData retention period: %d seconds\n", data_retention);
    printf("\tBatch size for aggregation: %d\n", batch_size);
    printf("\tNetwork buffer size: %d bytes\n", net_buffer_size);

    // Return success
    return 0;
}

// Define the function to serialize the telemetry data into a CSV format and store it in a compressed archive file
int serialize_telemetry_data(const char* filename, const telemetry_data_t* data) {
    // Check if the device ID is empty or NULL
    if (data->device_id == NULL || strlen(data->device_id) == 0) {
        return -1;
    }

    // Create a unique filename for the archive file
    char* archive_filename = malloc(sizeof(char) * (strlen(filename) + 256));
    if (archive_filename == NULL) {
        return -2;
    }
    sprintf(archive_filename, "%s-%d.csv", filename, time(NULL));

    // Open the archive file for writing
    int fd = open(archive_filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        return -3;
    }

    // Write the header row to the archive file
    char* header = "device_id,timestamp,status,sensor_data\n";
    write(fd, header, strlen(header));

    // Serialize the telemetry data into a CSV format and write it to the archive file
    char* csv_data = malloc(sizeof(char) * (strlen(data->device_id) + 256));
    if (csv_data == NULL) {
        return -4;
    }
    sprintf(csv_data, "%s,%ld,%s,%p\n", data->device_id, data->timestamp, data->status, data->sensor_data);
    write(fd, csv_data, strlen(csv_data));

    // Close the archive file
    close(fd);

    // Compress the archive file using gzip
    char* compressed_filename = malloc(sizeof(char) * (strlen(archive_filename) + 256));
    if (compressed_filename == NULL) {
        return -5;
    }
    sprintf(compressed_filename, "%s.gz", archive_filename);
    int ret = gzip(archive_filename, compressed_filename);
    if (ret != 0) {
        return -6;
    }

    // Remove the original archive file
    remove(archive_filename);

    // Return success
    return 0;
}

// Define the function to check if the device ID is empty or NULL
int is_device_id_empty(const char* device_id) {
    // Check if the device ID is empty or NULL
