    if (modulation_type < 0 || modulation_type > 2) {
        printf("Invalid modulation type. Using default value.\n");
        config->modulation_type = 0;
    } else {
        config->modulation_type = modulation_type;
    }

    // Check if bandwidth is valid
    if (bandwidth < 1 || bandwidth > 80) {
        printf("Invalid bandwidth. Using default value.\n");
        config->bandwidth = 20;
    } else {
        config->bandwidth = bandwidth;
    }

    // Check if cell identity is valid
    if (cell_identity < 1 || cell_identity > 10) {
        printf("Invalid cell identity. Using default value.\n");
        config->cell_identity = 1;
    } else {
        config->cell_identity = cell_identity;
    }

    // Check if transmission power is valid
    if (transmission_power < -40 || transmission_power > -10) {
        printf("Invalid transmission power. Using default value.\n");
        config->transmission_power = -30;
    } else {
        config->transmission_power = transmission_power;
    }

    // Check if SNR is valid
    if (snr < 1 || snr > 20) {
        printf("Invalid SNR. Using default value.\n");
        config->snr = 5.0;
    } else {
        config->snr = snr;
    }
}

// Update configuration structure with values from NMS
