    } else if (strcmp(format, "xml") == 0) {
        xmlDocPtr doc = xmlReadFile(filename, NULL, 0);
        if (doc != NULL) {
            valid = true;
            xmlFreeDoc(doc);
        } else {
            printf("Error parsing XML file %s\n", filename);
        }
    // Validate CSV file format
    } else if (strcmp(format, "csv") == 0) {
        csv_t *csv = csv_loadf(fp, 0, &error);
        if (csv != NULL) {
            valid = true;
            csv_free(csv);
        } else {
            printf("Error parsing CSV file %s: %s\n", filename, error.text);
        }
    } else {
        printf("Unsupported file format %s for file %s\n", format, filename);
    }

    fclose(fp);
    return valid;
}
