    rx_info_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_integers);
    if (!rx_info_array) {
        printf("Error: Failed to allocate memory for the array of RX information structures\n");
        return;
    }

    // Populate the array with the input integers
    for (int i = 0; i < num_integers; i++) {
        int integer = 0;
        scanf("%d", &integer);
        rx_info_array[i].RX_UE_INFORMATION_TAG = 1;
        rx_info_array[i].RNTI = integer;
        rx_info_array[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 0 : 1;
    }

    // Find the largest integer in the array
    int largest_integer = INT_MIN;
    for (int i = 0; i < num_integers; i++) {
        if (rx_info_array[i].RNTI > largest_integer) {
            largest_integer = rx_info_array[i].RNTI;
        }
    }

    // Print the largest integer found in the array
    printf("The largest integer found in the list is %d\n", largest_integer);

    // Safely free the allocated memory when no longer needed
    pthread_mutex_lock(&rx_info_array_mutex);
    free(rx_info_array);
    rx_info_array = NULL;
    pthread_mutex_unlock(&rx_info_array_mutex);
