#include <pthread.h>

// Define the structure for holding CRC indication information
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T crc_indication;
} crc_indication_t;

// Define a list of crc_indication_t structures
typedef struct {
    crc_indication_t *list;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} crc_indication_list_t;

// Initialize the list with a given capacity
void init_crc_indication_list(crc_indication_list_t *list, size_t capacity) {
    list->capacity = capacity;
    list->count = 0;
    list->mutex = PTHREAD_MUTEX_INITIALIZER;
}

// Add a new element to the list
void add_crc_indication(crc_indication_list_t *list, NFAPI_CRC_INDICATION_PDU_T crc_indication) {
    pthread_mutex_lock(&list->mutex);
    if (list->count < list->capacity) {
        // Allocate memory for the new element
        crc_indication_t *new_element = malloc(sizeof(crc_indication_t));
        if (!new_element) {
            perror("Failed to allocate memory for CRC indication");
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        // Initialize the new element with the given crc_indication
        new_element->crc_indication = crc_indication;
        // Add the new element to the list
        list->list[list->count++] = new_element;
    } else {
        fprintf(stderr, "List capacity reached\n");
    }
    pthread_mutex_unlock(&list->mutex);
}

// Remove an element from the list
void remove_crc_indication(crc_indication_list_t *list, size_t index) {
    pthread_mutex_lock(&list->mutex);
    if (index < list->count) {
        // Free the memory allocated for the element
        free(list->list[index]);
        // Shift all elements after the removed element to fill the gap
        memmove(&list->list[index], &list->list[index + 1], (list->count - index - 1) * sizeof(crc_indication_t));
        list->count--;
    } else {
        fprintf(stderr, "Index out of bounds\n");
    }
    pthread_mutex_unlock(&list->mutex);
}

// Get the number of elements in the list
size_t get_crc_indication_count(crc_indication_list_t *list) {
    return list->count;
}

// Update statistics about successful and failed CRC checks
void update_crc_statistics(crc_indication_list_t *list, bool success) {
    if (success) {
        list->successful_crc_checks++;
    } else {
        list->failed_crc_checks++;
    }
}
```
