// Define data structures
typedef struct PCI_SCAN_REQUEST_T {
    SCAN_TYPE scanType;
    CHANNEL_LIST channelList;
    SCAN_PARAMS scanParams;
} PCI_SCAN_REQUEST_T;

typedef struct SCAN_STATS_T {
    int successfulScans;
    int failedScans;
} SCAN_STATS_T;

// Define list data structure
struct LIST_NODE {
    PCI_SCAN_REQUEST_T *data;
    struct LIST_NODE *next;
};

typedef struct LIST_T {
    struct LIST_NODE *head;
    struct LIST_NODE *tail;
    int size;
} LIST_T;

// Define function prototypes
void addScanRequest(PCI_SCAN_REQUEST_T *scanRequest);
void removeScanRequest(int index);
void updateStats(int successful, int failed);

// Global variables
LIST_T scanList;
pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;
SCAN_STATS_T stats;

// Function to add a scan request to the list
void addScanRequest(PCI_SCAN_REQUEST_T *scanRequest) {
    // Check if list is full
    if (scanList.size >= 5000) {
        printf("Error: Scan list is full\n");
        return;
    }

    // Allocate memory for new node
    struct LIST_NODE *newNode = malloc(sizeof(struct LIST_NODE));
    if (newNode == NULL) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Initialize new node data
    newNode->data = scanRequest;
    newNode->next = NULL;

    // Lock list mutex
    pthread_mutex_lock(&listMutex);

    // Add new node to tail of list
    if (scanList.tail == NULL) {
        scanList.head = newNode;
    } else {
        scanList.tail->next = newNode;
    }
    scanList.tail = newNode;
    scanList.size++;

    // Unlock list mutex
    pthread_mutex_unlock(&listMutex);
}

// Function to remove a scan request from the list
void removeScanRequest(int index) {
    // Check if list is empty
    if (scanList.size == 0) {
        printf("Error: Scan list is empty\n");
        return;
    }

    // Lock list mutex
    pthread_mutex_lock(&listMutex);

    // Find node to remove
    struct LIST_NODE *node = scanList.head;
    int i;
    for (i = 0; i < index && node != NULL; i++) {
        node = node->next;
    }

    // Check if node was found
    if (node == NULL) {
        printf("Error: Scan request not found\n");
        return;
    }

    // Remove node from list
    if (node == scanList.head) {
        scanList.head = node->next;
    } else if (node == scanList.tail) {
        scanList.tail = node->prev;
    } else {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }
    free(node);
    scanList.size--;

    // Unlock list mutex
    pthread_mutex_unlock(&listMutex);
}

// Function to update statistics after each operation
void updateStats(int successful, int failed) {
    if (successful) {
        stats.successfulScans++;
    } else {
        stats.failedScans++;
    }
}
